INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9b5847dc52c1', 'en', 'US', 'Chicken Fajitas', 'Recipe video above. The secret ingredient in this Fajita marinade is orange juice. It injects flavour as well as brining, and makes the chicken caramelise beautifully when cooked. It doesn’t taste like oranges at all once cooked. Use any coloured peppers you want – though seeing a kaleidoscope of colours on a platter will bring a smile to anyone’s face!', 'https://www.recipetineats.com/tachyon/2017/04/Chicken-Fajitas_8.jpg', 15, 15, 30, 4, '[{"id": "ing_ime_juice", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1/4 cup / 65 ml lime juice","1/4 cup / 65 ml orange juice (Note 1 for subs)","2 tbsp olive oil","2 garlic cloves (, minced)","1 tsp cumin powder","1 tsp salt","1/2 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["700g / 1.2 lb skinless chicken thighs or 2 large chicken breasts (, halved horizontally (Note 2))","2 tbsp olive oil","3 capsicums / bell peppers (, deseeded and sliced (red, yellow or green))","1 large onion (, halved and sliced thickly (brown, yellow, white or red))"],"purpose":"Fajitas:"},{"ingredients":["8– 12 small tortillas","1 large avocado (, halved and sliced)","Sour cream","Fresh lime wedges"],"purpose":"To Serve:"}]', '[{"description":"Place Marinade ingredients in a large bowl and mix. Add chicken, toss well to coat. Marinade for 1 hour to 24 hours (or freeze immediately then defrost overnight).","images":[],"step":1},{"description":"Use 2 skillets to cook the chicken and vegetables at the same time, if you can.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a heavy based skillet over high heat until smoking. Add vegetables to cover the base of the pan in a single layer without too much overlapping (I cook in 3 batches). Spread out, leave for 45 seconds (to char it).","duration":0.75,"images":[],"step":3},{"description":"Toss quickly then spread out. Sprinkle with salt and pepper. Leave 45 seconds, toss then spread out, then leave 45 seconds. Remove onto platter and repeat with remaining Vegetables.","images":[],"step":4},{"description":"Heat 1 tbsp oil in a large skillet over medium high heat. Add chicken and cook for 3 to 4 minutes until caramelised. Turn and cook the other side for 3 – 4 minutes.","duration":3.5,"images":[],"step":5},{"description":"Remove onto a plate, cover loosely with foil. Rest for 3 minutes then slice.","duration":3,"images":[],"step":6},{"description":"To Serve:","images":[],"step":7},{"description":"Warm tortillas using chosen method.","images":[],"step":8},{"description":"Pile peppers and onion onto tortilla. Top with chicken, drizzle with sour cream, squeeze over lime juice. Fold, devour and be happy.","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","fajitas","gluten-free-recipes","main-dishes","mains","mexican-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ec1393e00f2e', 'en', 'US', 'Lemon Chicken Salad', 'Recipe video above. A substantial salad with a lemon marinated chicken, dressed with a dill lemon dressing with a touch of honey. You''ll love how the dressing does double duty as the marinade! Bacon is optional - totally delicious without, but always fabulous with. Serves 2 as a meal, 4 as a side.', 'https://www.recipetineats.com/tachyon/2018/07/Lemon-Chicken-Salad-1a.jpg', 15, 8, 23, 2, '[{"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 8.0, "unit": "head"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.007, "unit": "can of 400g"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}]', '[{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice","1 tbsp honey","1 tsp Dijon mustard","3 tbsp extra virgin olive oil","1 large garlic clove (, minced)","1/2 tsp salt + 1/4 tsp black pepper"],"purpose":"Dressing/Marinade:"},{"ingredients":["1 large chicken breast (, halved horizontally* OR 2 boneless skinless chicken thighs)","1 tbsp lemon juice (, extra)","Salt and pepper","1/2 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["2 tbsp finely chopped dill","8 cups cos/romaine lettuce (, chopped (or other lettuce of choice, Note 2))","1 cup cherry tomatoes (, halved)","1 medium avocado (, quartered and sliced thickly)","1/2 red onion (, small, finely sliced)","3/4 cup corn kernels (, fresh or canned drained)","120g/ 4 oz bacon (, cooked then chopped (optional))"],"purpose":"Salad:"}]', '[{"description":"Place Dressing ingredients in a jar. Shake well.","images":[],"step":1},{"description":"Place chicken in a bowl. Add 2 tbsp Dressing, 1 tbsp extra lemon juice, plus a pinch of salt and pepper. Mix well. Marinate minimum 20 minutes up to 24 hours.","images":[],"step":2},{"description":"Heat oil in a non stick skillet over medium high heat (or use bacon fat if you use bacon in this!). Add chicken and cook. Halved breasts: 2 minutes each side. Thigh: 4 minutes each side.","images":[],"step":3},{"description":"Transfer to plate, cover loosely with foil for 3 minutes. Slice.","duration":3,"images":[],"step":4},{"description":"Add dill into remaining dressing. Shake.","images":[],"step":5},{"description":"Place remaining salad ingredients in a bowl. Top with chicken.","images":[],"step":6},{"description":"Drizzle dressing all over. Crumble over bacon if using. Serve immediately!","images":[],"step":7}]', '["mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_902ae41fc7cd', 'en', 'US', 'Mexican Avocado Chicken Salad', 'Recipe video above (see how I scoop out avocado!) A fully loaded salad, satisfying to have as a meal! Crunchy lettuce, creamy avocado corn and tomato salsa, marinated Mexican chicken drizzled with a lime dressing. Makes 2 meal size servings or 3 normal servings. Marinate 30 min.', 'https://www.recipetineats.com/tachyon/2017/05/Mexican-Chicken-Salad-4.jpg', 15, 8, 23, 3, '[{"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lettuce", "quantity": {"value": 5.0, "unit": "head"}}]', '[{"ingredients":["2 tbsp lime juice","1 tbsp honey","1/4 cup olive oil (65ml)","1 garlic clove, minced","½ tsp salt + black pepper"],"purpose":"Lime Dressing / Marinade:"},{"ingredients":["2 small chicken breasts, 400g/14oz (pound or split if thicker than 2cm / 4/5”)","1/2 tsp EACH chipotle powder (Note 1) and oregano","1/4 tsp cumin powder","Salt & pepper","1/2 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["1 avocado, chunky dice (watch video to see how I do this)","1 cup cherry tomatoes, halved","¾ cup corn kernels (canned, drained)","½ red onion, finely chopped"],"purpose":"Avocado Salsa:"},{"ingredients":["1/4 cup coriander / cilantro, finely chopped","5 heaped cups cos / romaine lettuce, cut into bite size pieces"],"purpose":"Salad:"}]', '[{"description":"Place Lime Dressing ingredients in a jar, shake well.","images":[],"step":1},{"description":"Put 2 tablespoons of Dressing in a ziplock bag. Add chipotle, oregano, cumin, salt and pepper, mix/squidge bag. Add chicken, seal and massage to coat. Marinate 30 min – overnight.","images":[],"step":2},{"description":"Heat 1 tbsp olive oil in skillet over medium low, cook chicken to taste (2cm / 4/5” takes around 8 minutes), getting a nice brown crust on it. Rest 5 min then slice.","images":[],"step":3},{"description":"Add 2 tablespoons of coriander into Dressing, shake.","images":[],"step":4},{"description":"Place avocado, corn, tomato and onion in a bowl. Add remaining coriander, drizzle with a bit of Dressing, toss gently.","images":[],"step":5},{"description":"Place lettuce in a bowl, drizzle with a bit of Dressing, toss.","images":[],"step":6},{"title":"Assemble Salad","description":"Place lettuce on a serving platter. Top with Salsa and sliced chicken. Drizzle with remaining Dressing. Serve.","images":[],"step":7}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","mexican-recipes","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa81cb546061', 'en', 'US', 'Chicken Tikka Masala', 'Recipe VIDEO above. Make this iconic curry at home!!! It''s a stunner - and although there''s an extensive looking list of ingredients, it''s astonishingly straight forward. Far better than paste in a jar, less oily than restaurants, and you can get everything you need from supermarkets!Spice level: Low. Marinating time: 3 - 24 hours', 'https://www.recipetineats.com/tachyon/2018/04/Chicken-Tikka-Masala_0.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 12.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garam_masala", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_oil", "quantity": {"value": 0.09, "unit": "bottle"}}, {"id": "ing_turmeric", "quantity": {"value": 0.025, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 80.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.4, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["600g/ 1.2lb chicken thigh (boneless, skinless), cut into 3cm / 2.2\" cubes (Note 1)","1/2 cup plain yoghurt, ( full fat best (Greek is fine))","6 cloves garlic (, minced (~1.5 tbsp))","1 tbsp fresh ginger (, grated)","1 tsp garam masala (Note 2)","1 tsp each salt, cumin, ground coriander, paprika (sweet, normal or smokey)","1 tbsp vegetable oil","1/8 tsp cayenne pepper (optional)","Pinch black pepper","2 tsp lemon juice"],"purpose":"Chicken Tikka Marinade:"},{"ingredients":["1 - 2 tbsp oil (Note 3)"],"purpose":"Cooking Chicken:"},{"ingredients":["2 tsp turmeric","1 tbsp garam masala (Note 2)","2 tsp coriander","1 tsp cumin","1/8 tsp cardamom powder","1/8 tsp cayenne pepper"],"purpose":"Curry Sauce Spices:"},{"ingredients":["3 tbsp (65ml) vegetable oil (Note 3)","30g / 2 tbsp unsalted butter OR ghee","1 onion, finely chopped (brown, white or yellow)","1 tsp salt","2 tbsp fresh ginger (, grated)","6 cloves garlic (, crushed or grated)","1 tbsp paprika (not smoked)","1 2/3 cups (400ml) tomato passata (tomato puree)","1 2/3 cups (400ml) water","100 ml (1/3 cup + 1 tbsp) cream (thickened or pure is fine)","1 tsp sugar","50g / 3 tbsp unsalted butter OR ghee"],"purpose":"Curry Sauce:"},{"ingredients":["Basmati rice"],"purpose":"Serving"}]', '[{"description":"Combine all ingredients except chicken in a bowl and mix. Add chicken and turn well to coat.","images":[],"step":1},{"description":"Cover with cling wrap and leave in fridge to marinate overnight (3 hours minimum).","images":[],"step":2},{"description":"Heat 1 tbsp oil in a non stick pan over high heat until smoking. Add half the chicken and spread out. Leave for 2 minutes or until charred. Turn each piece and cook the other side until charred - don''t worry if not cooked inside. (Note 4, also Video helpful here) Remove into bowl.","duration":2,"images":[],"step":3},{"description":"Scrape out charred bits left in pan and discard. Add more oil if required and cook remaining chicken.","images":[],"step":4},{"description":"Wipe skillet with paper towels (or do this part in a pot as you need a lid). Turn heat down to medium high.","images":[],"step":5},{"description":"Add oil and butter. When butter is melted, add onions, ginger and salt.","images":[],"step":6},{"description":"Cook, stirring constantly to ensure it doesn''t burn, until the ginger is starting to turn golden and the onions smell sweet, about 5 - 7 minutes.","images":[],"step":7},{"description":"Reduce the heat to medium. Add the garlic and paprika, and cook for 2 minutes.","duration":2,"images":[],"step":8},{"description":"Add the Curry Sauce Spices, and cook a further 2 minutes, stirring.","images":[],"step":9},{"description":"Add tomato passata and water, and mix. Bring to a simmer, then cover and reduce heat to low.","images":[],"step":10},{"description":"Simmer for 15 minutes, stirring occasionally.","duration":15,"images":[],"step":11},{"description":"Pour curry into a bowl, then use a stick blender to puree until smooth (Note 5).","images":[],"step":12},{"description":"Return sauce to skillet. Add cream, sugar and butter. Stir to melt the butter.","images":[],"step":13},{"description":"Add chicken, stir. Simmer for a few minutes until the chicken is cooked through.","images":[],"step":14},{"title":"Optional","description":"Sprinkle with a pinch of extra garam masala at the end.","images":[],"step":15},{"description":"Serve over basmati rice, sprinkled with coriander/cilantro if desired. Try this No Yeast Flatbread as a quick naan!","images":[],"step":16}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["chicken-breast-recipes","chicken-recipes","curry-recipes","dietary","gluten-free-recipes","iconic-dishes","indian-recipes","main-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94039338708c', 'en', 'US', 'Oven Baked Chicken with Rice Pilaf (Cranberry, Walnut and Apple)', 'The RICE PILAF in this recipe is sensational. Tastes savoury but with a touch of apple sweetness, herby fragrance, combined with plump cranberries, warm crunch of walnuts, and with fresh apple providing a fabulous finishing touch. The chicken is sticky from the jam (great shortcut trick) and savoury from the seasoning spices. The key step that makes a real difference is "oven sautéing" onion and garlic first. Festive inspired midweek meal to have all year round! Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/12/Baked-Chicken-with-Rice-Pilaf-2.jpg', 15, 65, 80, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cranberries", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 0.5, "unit": "jar"}}, {"id": "ing_apples", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_jam", "quantity": {"value": 0.003, "unit": "jar of 370g"}}, {"id": "ing_mustard", "quantity": {"value": 0.015, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["5 chicken thigh fillets (, bone in (about 220g / 7oz each) (Note 1))"]},{"ingredients":["1 small onion (, finely chopped)","1 garlic clove (, minced)","50g (3.5 tbsp) unsalted butter (or sub with oil of choice)","1 1/2 cups (270g) long grain white rice (, uncooked (Note 2))","1 1/4 cups (315 ml) apple juice","1 1/2 cups (375 ml) chicken broth","1 cup (120g) dried cranberries (or other dried fruit of choice)","1 cup (125g) walnuts , roughly chopped (or other nuts of choice)","1 red apple (, cut into small dice)"],"purpose":"Rice:"},{"ingredients":["3/4 tsp dried rosemary","1 tsp dried thyme","3/4 tsp salt","1/2 tsp pepper"],"purpose":"Rice Herbs:"},{"ingredients":["1/3 cup (100g) apricot jam (or other jam - Note 3)","2 1/2 tbsp Dijon mustard","1/2 tsp garlic powder","1/2 tsp All Spice","1/4 tsp paprika","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Sticky Chicken Glaze:"},{"ingredients":["Oil spray","Fresh parsley (, finely chopped)"],"purpose":"Garnish (optional):"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection).","images":[],"step":1},{"description":"Use a baking dish about 22 x 33cm / 9 x 13\".","images":[],"step":2},{"description":"Scatter onion and garlic in baking dish, dollop butter over. Bake for 15 minutes, then remove.","duration":15,"images":[],"step":3},{"description":"If your chicken has skin on it, remove it (just pull it off). Otherwise, the rice will be too greasy.","images":[],"step":4},{"description":"Whisk together Sticky Chicken Glaze. Add chicken, turn to coat.","images":[],"step":5},{"description":"Add rice, apple juice, chicken broth and Rice Herbs into the pan with the onion. Stir.","images":[],"step":6},{"description":"Add cranberries and walnuts. Stir.","images":[],"step":7},{"title":"Top with chicken","description":"it will be partly submerged. Save glaze in bowl.","images":[],"step":8},{"title":"Cover with foil. Bake 20 minutes. Remove foil","description":"don''t worry if there''s still liquid (Note 4).","images":[],"step":9},{"title":"Spoon all remaining Glaze onto chicken. Optional","description":"spray with oil (gives chicken a slightly nicer finish). Bake for another 30 - 35 minutes until chicken is browned.","images":[],"step":10},{"description":"Remove pan from oven. Rest 5 minutes. Remove chicken, add apple, then use fork to fluff rice.","images":[],"step":11},{"description":"Serve chicken with rice pilaf, garnished with fresh parsley if desired.","images":[],"step":12}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_968c3ab634e5', 'en', 'US', 'Garlic Herb Butter Roasted Turkey Breast', 'RECIPE VIDEO above. An incredible way to roast turkey breast! The garlic herb butter smeared under the skin bastes the breast while it roasts, and creates a butter pan sauce to serve on the side. A meat thermometer will ensure your turkey comes out beautifully juicy. Truly worth using fresh herbs for this recipe, but see notes for dried options.', 'https://www.recipetineats.com/tachyon/2017/11/Herb-Garlic-Butter-Roast-Turkey-Breast-4.jpg', 20, 90, 110, 6, '[{"id": "ing_5_6_lb_single_turkey_breast", "quantity": {"value": 2.75, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.024, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 4.0, "unit": "pack of 3 heads"}}, {"id": "ing_sage", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2.5 - 3 kg / 5-6 lb single turkey breast (, skin on, bone in (Note 1), NOT BRINED)","1/2 tsp salt","Black pepper","Small bunch of fresh herbs - 4 rosemary sprigs (, 8 sprigs sage, 10 thyme sprigs)","12 garlic cloves (, smashed with side of knife (see video))"]},{"ingredients":["150 g / 5 oz (10 tbsp) unsalted butter, softened","1 1/4 tsp table salt or 1 1/2 tsp kosher salt","1/2 tsp black pepper","4 large garlic cloves (, minced)","1 tbsp finely chopped sage (, fresh)","1 tbsp finely chopped rosemary (, fresh)","1 tbsp fresh thyme leaves (, fresh)","1 tbsp finely chopped parsley leaves (, fresh)"],"purpose":"Butter:"}]', '[{"title":"Remove fridge chill","description":"Take turkey out of the fridge 45 minutes before cooking (or 30 minutes if it''s super hot where you are).","images":[],"step":1},{"description":"Preheat oven to 200C / 390F (all oven types). Put rack in the lower middle position. (Note 3)","images":[],"step":2},{"description":"Place garlic and bunch of herbs in the middle of a baking dish. (Note 4)","images":[],"step":3},{"title":"Butter","description":"Mix Butter ingredients together.","images":[],"step":4},{"title":"Loosen skin","description":"Use an upside teaspoon to help loosen the skin from the turkey flesh (easiest to go under the paper thin layer under the surface skin). Video helpful here.","images":[],"step":5},{"title":"Smear butter under skin","description":"Use about 2/3 of the butter, and smear it under the skin on the top half of the breast. Best to smear using hands under the skin (not on surface), to ensure it spreads as evenly as possible.","images":[],"step":6},{"description":"Turn turkey upside down. Reserve about 2 tbsp butter for the surface, smear the rest on the underside.","images":[],"step":7},{"description":"Place turkey in pan on the herbs, skin side up. Now smear skin with remaining butter - you don''t want much on the skin because the herb bits burn.","images":[],"step":8},{"title":"STOP HERE for make ahead option","description":"the turkey can be left like this for up to 24 hours. Remove from fridge 45 minutes before serving then proceed.","images":[],"step":9},{"description":"Sprinkle top and sides of breast with salt and pepper all over. Place turkey in oven, turn DOWN to 180C/350F.","images":[],"step":10},{"description":"Roast for 1 hr 30 minutes, basting all over every 30 minutes. (Note 5)","duration":60,"images":[],"step":11},{"title":"COOK TIME / INTERNAL TEMPERATURE","description":"The turkey is cooked when the meat thermometer inserted at the thickest part is 74C/165F. I check in several places. Allow 15 minutes per 500g/1 lb of turkey. My 2.8 kg / 5.5lb bone in turkey took 1 hr 40 minutes.","images":[],"step":12},{"description":"COVER turkey with foil when it becomes golden to your taste, at any point during the cook time (1 hr 15 minutes for me).","images":[],"step":13},{"title":"Rest","description":"Remove turkey from pan and place on serving plate. Cover loosely with foil and rest for 15 to 20 minutes before carving.","duration":17.5,"images":[],"step":14},{"description":"Butter Sauce (Note 6):","images":[],"step":15},{"description":"The pan will have melted butter and roasting juices. Remove herbs and garlic, squeezing out juices. Pour sauce into jug, serve with turkey.","images":[],"step":16},{"title":"Gravy option","description":"see Note 11. I personally love using the butter, but I understand if you feel the need for gravy!","images":[],"step":17}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","gluten-free-recipes","main-dishes","roasts","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_303938c20540', 'en', 'US', 'BAKED Chicken Meatballs with Spaghetti', 'Recipe VIDEO above. Golden brown on the outside, soft and juicy on the inside, these Baked Chicken Meatballs are lip smackingly delicious! Pass them around with ketchup at a gathering or make Spaghetti and Meatballs!', 'https://www.recipetineats.com/tachyon/2017/09/Baked-Chicken-Meatballs-2.jpg', 20, 25, 45, 4, '[{"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.005, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.75, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["500 g/1lb chicken mince (ground chicken), or turkey or pork (Note 1)","1/4 small white onion (, grated into the bowl)","1/2 cup panko breadcrumbs","1/3 cup grated parmesan","1 large garlic clove (, minced)","1/4 cup finely chopped parsley (or 2 tsp dried parsley or basil)","1 egg","1/4 tsp salt","1/2 tsp pepper","Olive oil spray (or olive oil)"],"purpose":"Meatballs:"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, finely chopped)","3/4 small onion , finely chopped","800 g / 28 oz crushed tomato","1 cup / 250 ml water (swirl in tomato can to clean out)","Handful basil leaves (, torn, or 1 tsp dried herbs (e.g. Italian mix, oregano, thyme, basil))"],"purpose":"Pasta Sauce:"},{"ingredients":["250 g/ 1/2 lb spaghetti or other long strand pasta of choice (, cooked per packet)","Fresh basil (, optional)","Parmesan cheese"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection).","images":[],"step":1},{"description":"Place a rack on a tray, and spray the rack with oil.","images":[],"step":2},{"description":"Place Meatball ingredients in a bowl, mix well. Scoop up a heaped tablespoon, roll into a ball and place on the rack. Repeat with remaining mixture - should make 25 - 30. Tip: spray hands with oil or wet lightly with water.","images":[],"step":3},{"description":"Spray each ball well with oil, then bake for 25 minutes until golden brown. Give ''em a squeeze and you''ll see how soft they are!","duration":25,"images":[],"step":4},{"description":"Heat oil in a large skillet over medium high heat. Add garlic and onion, cook for 2 - 3 minutes until translucent. Add tomato and water, stir then turn heat down to medium. Simmer for 5 - 10 minutes, then season to taste with salt and pepper and stir through basil (or use dried herbs).","duration":2.5,"images":[],"step":5},{"description":"Cook pasta in a large pot of boiling water. Drain then return pasta to the same pot.","images":[],"step":6},{"description":"Add Sauce and meatballs, toss.","images":[],"step":7},{"description":"Serve, garnished with fresh basil and parmesan.","images":[],"step":8}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","italian-recipes","main-dishes","meatball-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0ce59a76942f', 'en', 'US', 'Baked Balsamic Chicken', 'Recipe video above! No marinating required, just mix together a simple sauce, pour it over the chicken and bake. You will be amazed how incredible it tastes - and how sticky they are! PS If using the recipe scaler (hover over Servings), please read notes.', 'https://www.recipetineats.com/tachyon/2017/04/Balsamic-Baked-Chicken-4.jpg', 5, 50, 55, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 3.0, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 kg / 2 lb chicken thighs (5 pieces, bone in, skin on), or drumsticks or wings (any combination) (Note 1)"]},{"ingredients":["1/4 cup (65 ml) balsamic vinegar","2 1/2 tbsp / 50 ml soy sauce (, all purpose or light (not dark soy sauce))","1/4 cup (85 g / 65 ml) honey","1/4 cup (45g) brown sugar (, loosely packed (Note 2))","2 garlic cloves, minced (or 1 1/2 tsp garlic paste from jar)"],"purpose":"Sauce:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Line a baking dish with foil and baking / parchment paper.","images":[],"step":2},{"description":"Mix together Sauce in a bowl.","images":[],"step":3},{"description":"Place chicken in baking dish, skin side down for thighs and wings. Make sure the pan is big enough so the chicken is squished up next to each other (sauce may not reduce enough), but not so large that there is more than 4\"/10 cm between every piece of chicken (sauce may reduce too much).","images":[],"step":4},{"description":"Pour over Sauce. Bake 30 minutes. Turn chicken over, spoon over sauce.","images":[],"step":5},{"description":"Bake 20 minutes or until chicken is cooked through. The Sauce should have thickened.","images":[],"step":6},{"description":"Stand for 5 minutes, then spoon Sauce over chicken and serve.","duration":5,"images":[],"step":7}]', '["gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_edc77abe1b6b', 'en', 'US', 'One Pot Italian Chicken & Orzo / Risoni Pasta', 'RECIPE VIDEO ABOVE. A super tasty and quick meal all made in one pot! Chicken infused with Italian flavours and a rich tomato basil orzo / risoni pasta. Refer to the notes for how to skip the marinating time and also how to cook the chicken WITH the risoni. Feel free to add or substitute the capsicum / bell peppers in this!', 'https://www.recipetineats.com/tachyon/2017/01/One-Pot-Italian-Chicken-and-Tomato-Basil-Risoni.jpg', 10, 25, 35, 4, '[{"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp white wine vinegar","1 tbsp olive oil","1 tsp Dijon mustard","1 tsp Italian herb mix (or make your own with basil, parsley, oregano)","1 garlic clove (, minced)","1/2 tsp salt + black pepper"],"purpose":"Marinade"},{"ingredients":["1 tbsp olive oil","4 x 110 - 120g/4oz chicken breasts (, skinless and boneless (Note 1))"],"purpose":"Chicken"},{"ingredients":["1/2 tbsp olive oil (if required)","1 small onion (, finely chopped (brown, white, yellow))","1 garlic clove (, minced)","1 red capsicum / bell pepper (, chopped)","1 1/2 cups risoni / orzo pasta (Note 2)","400 g / 14 oz can crushed tomato","3 cups chicken stock / broth","1 tsp Italian herb mix","Pinch of red pepper flakes (chilli flakes) (optional)","Salt and pepper","1/4 cup (3 tbsp) grated parmesan cheese (optional)","1 cup basil leaves"],"purpose":"Risoni"}]', '[{"description":"Mix Marinade ingredients together in a large bowl. Add chicken and mix to coat. Marinate for 1 hour - 24 hours (See Note 3 to skip marinating).","images":[],"step":1},{"description":"Heat oil in skillet over medium heat. Add chicken and cook for 4 minutes on each side, or until cooked. Transfer to a plate and cover with foil to keep warm while resting.","duration":4,"images":[],"step":2},{"description":"Turn heat up to medium high. Add oil if required.","images":[],"step":3},{"description":"Add onion and garlic, cook for 2 minutes. Add capsicum and cook for 1 minute or until onion is translucent.","duration":2,"images":[],"step":4},{"description":"Add risoni, tomato, chicken stock, Italian herbs, red pepper flakes, salt and pepper. Mix and bring to simmer, then lower heat to medium low or so it simmers gently.","images":[],"step":5},{"title":"Cook for 9","description":"10 minutes, stirring frequently (otherwise it will stick).","duration":9.5,"images":[],"step":6},{"description":"Take it off the stove when the risoni is just cooked (touch under is ok, finishes cooking in residual heat very quickly). It should still be saucy (see video).","images":[],"step":7},{"title":"Stir through parmesan and basil","description":"excess liquid will evaporate in this step.","images":[],"step":8},{"description":"Spoon risoni into serving bowls, top with chicken. Serve with extra parmesan and basil.","images":[],"step":9}]', '["gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["chicken-breast-recipes","chicken-recipes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31dcc08f179e', 'en', 'US', 'Oven Baked Chicken Quesadillas', 'This is how to make multiple Quesadillas in one batch, rather than making them one by one on the stove! They are crispy and stuffed with Fajita flavoured chicken, onion, capsicum/bell peppers and of course cheese. Use this technique to make quesadillas with anything you want - just ensure you cool the filling. See recipe VIDEO below the recipe to see how crispy these are!', 'https://www.recipetineats.com/tachyon/2016/12/Baked-Chicken-Quesadillas-7.jpg', 15, 16, 31, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 4.0, "unit": "pack of 8"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["400 g / 14 oz chicken (, cut into small bite size pieces (thigh, breast or tenderloin))","1 tsp cumin powder","1 tsp garlic powder (or sub with onion powder)","1/2 tsp cayenne pepper (or adjust to taste)","1 tsp paprika powder","1/2 tsp salt + black pepper","1 tbsp olive oil"],"purpose":"Chicken"},{"ingredients":["1 tbsp olive oil","1/2 small onion (, diced (brown, white, yellow))","1 garlic clove (, minced)","1 red capsicum / bell pepper (, diced)","1 green capsicum / bell pepper (, diced)"],"purpose":"Filling"},{"ingredients":["4 flour tortillas (20cm/8\")","Olive oil spray","1 cups grated cheese, or more to taste (tasty, cheddar, Monterey Jack, Pepper Jack or other melting cheese of choice) (Note 1)"],"purpose":"Quesadillas"}]', '[{"description":"Place Chicken ingredients in a bowl and mix to coat chicken.","images":[],"step":1},{"description":"Heat oil in skillet over high heat. Add onion and garlic, cook for 1 minute. Then add capsicum and cook for 2 minutes until starting to soften. Transfer into bowl.","duration":1,"images":[],"step":2},{"description":"Return skillet to the stove. Add chicken and cook until browned. Add to same bowl. Set aside until the filling cools (to speed it up, cover and refrigerate, and/or spread out on plate).","images":[],"step":3},{"description":"Preheat oven to 220C / 430F (standard) or 200C/390F (fan / convection).","images":[],"step":4},{"description":"Spray baking tray lightly with olive oil. Heat in the oven while you assemble the quesadillas.","images":[],"step":5},{"description":"Divide the filling between the tortillas, covering half the surface. Top with cheese. Fold in half and press down gently but firmly.","images":[],"step":6},{"description":"Remove baking tray from oven. Transfer quesadillas onto tray (you should hear a soft sizzle).","images":[],"step":7},{"description":"Bake for 8 minutes. Then turn the quesadillas (over the folded edge) then press down with the egg flip. Bake for a further 8 minutes or until the surface is crispy.","duration":8,"images":[],"step":8},{"description":"Remove from oven and serve immediately!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mexican-recipes","most-popular","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b53ba108fe9', 'en', 'US', 'Creamy Chicken and Bacon Pasta', 'Recipe video above. This is for those days when you just need a really, really great creamy pasta but you want to keep it simple. The pops of bacon in this is sooo good, and the sauce is utterly luxurious and unapologetically rich, saucier than a classic Alfredo.But, for those days when you want to go all out, make the Creamy Chicken Pasta of My Dreams (it''s more loaded, and name-worthy!).', 'https://www.recipetineats.com/tachyon/2016/12/Creamy-Chicken-Bacon-Pasta-4.jpg', 5, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 6.0, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 3.0, "unit": "pack of 500g"}}, {"id": "ing_bacon", "quantity": {"value": 6.0, "unit": "pack of 200g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cream", "quantity": {"value": 0.012, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["6 oz / 180 g fettuccine (or other long strand pasta)","3/4 cup pasta cooking water (, scoop out just before draining)","5 -7 oz / 150 - 200 g bacon (, chopped)","6 oz / 180g chicken breast (, cut in half horizontally (1 large))","1/4 tsp each salt and pepper (, for seasoning chicken)"]},{"ingredients":["1 tbsp (15 g) unsalted butter","2 garlic cloves (, finely minced)","1/2 small onion (, finely chopped (brown, white or yellow))","3/4 cup heavy cream / thickened cream (or any full fat cream)","1/4 tsp each salt and pepper (, for sauce)","1/2 cup finely shredded parmesan (or 1/4 cup store bought grated) (Note 2)"],"purpose":"Creamy pasta sauce"},{"ingredients":["Fresh parsley","Parmesan"],"purpose":"To Serve"}]', '[{"description":"Cook pasta per packet minus 2 minutes, reserve 1 cup pasta water before draining. Cook bacon, then chicken, sauté garlic and onion, simmer with cream, 3/4 cup pasta water, parmesan, salt and pepper. Toss with pasta 1 1/2 minutes, TASTE to check for salt. Serve with parmesan.","images":[],"step":1},{"title":"Cook pasta","description":"Bring a large pot of salted water to boil. Add pasta and cook for time per packet MINUS 2 minutes (finishes cooking in Sauce).","images":[],"step":2},{"title":"RESERVE water (important!)","description":"SCOOP OUT 1 cup (250ml) of pasta cooking water, then drain.","images":[],"step":3},{"title":"Cook bacon","description":"Meanwhile, heat the oil in a non-stick pan and cook bacon until golden. Remove and drain on paper towels, reserve bacon fat in pan.","images":[],"step":4},{"title":"Cook chicken","description":"Season chicken on both sides with the salt and pepper. Cook in the bacon fat for 2 minutes on each side. Remove, then cut into thick slices when cool enough to handle (do this while sauce is simmering).","duration":2,"images":[],"step":5},{"description":"Wipe pan (optional) using paper towels to keep sauce pretty and white, and for a buttery clean tasting sauce rather than very bacon-y (Note 3).","images":[],"step":6},{"title":"Sauté onion","description":"Over medium heat using the same pan, melt the butter. Add garlic and onion, cook for 3 - 4 minutes until onion is light golden and soft.","duration":3.5,"images":[],"step":7},{"title":"Make sauce","description":"Add cream, about 3/4 cup pasta water, parmesan, salt and pepper. Stir, then simmer for 2 minutes until it reduces slightly - the sauce will still be a too thin, don''t worry, it thickens in the next step.","duration":2,"images":[],"step":8},{"description":"Add pasta and toss gently in the sauce for about 1 1/2 minutes, still on the stove. The sauce will thicken and coat the pasta rather than pooling in the pan. Do this step until you get the sauce consistency you want. If your sauce gets too thick, add a splash of pasta water.","images":[],"step":9},{"title":"Toss and taste","description":"Toss through bacon and chicken. Taste and add more salt if needed (depends on bacon saltiness).","images":[],"step":10},{"title":"Serve","description":"Serve immediately, garnished with parmesan and parsley!","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d510a78a7505', 'en', 'US', 'Honey Mustard Chicken', 'This is a homemade version of the popular Honey Mustard simmer sauces sold at supermarkets. The Honey Mustard Sauce is slightly tangy, sweet and beautifully creamy. Great for chicken, pork, turkey and fish. **ADJUST SERVINGS by using the slider!**', 'https://www.recipetineats.com/tachyon/2016/08/Honey-Mustard-Chicken_2.jpg', 7, 10, 17, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.113, "unit": "jar of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700 g / 1.4 lb chicken tenderloin or chicken breast cut into thick strips (Note 1)","Salt and pepper"]},{"ingredients":["2 tbsp flour","1 tsp garlic powder"],"purpose":"Seasoning (optional – Note 2)"},{"ingredients":["1 tbsp mayonnaise (Note 3)","1 tsp cornstarch / cornflour or 2 tsp flour"],"purpose":"Thickener"},{"ingredients":["1 1/2 tbsp + 1/2 tbsp olive oil","2 cloves garlic (minced)","1 cup chicken broth / stock (250ml)","1/4 cup Dijon mustard (70g)","1/4 cup honey (85g)"],"purpose":"Sauce"},{"ingredients":["1 - 2 tbsp wholegrain mustard, adjust to taste","2 tsp sprigs thyme or 1/2 dried thyme (Note 4)","Fresh parsley, finely chopped"],"purpose":"Optional Extras (I used these)"}]', '[{"description":"Sprinkle chicken with salt and pepper, then toss with Seasoning if using.","images":[],"step":1},{"title":"Thickener","description":"In a small bowl, mix together the mayonnaise and flour.","images":[],"step":2},{"description":"Heat 1 1/2 tbsp oil in a skillet over medium high heat. Add chicken and cook for 2 minutes on each side or until golden. Remove onto a plate.","duration":2,"images":[],"step":3},{"description":"Reduce heat to medium. Add remaining oil in the middle of the skillet and put garlic straight onto the puddle of oil. Sauté for 20 seconds or until golden (don''t let it burn).","duration":0.3333333333333333,"images":[],"step":4},{"description":"Add chicken broth, bring to simmer, scraping the bottom of the fry pan.","images":[],"step":5},{"description":"Whisk in Dijon Mustard and honey, then whisk in Thickener (make sure you scrape it all in).","images":[],"step":6},{"description":"Add thyme and wholegrain mustard, if using.","images":[],"step":7},{"title":"Cook for 1","description":"2 minutes or until starting to thicken. Adjust salt and pepper to taste.","duration":1.5,"images":[],"step":8},{"description":"Return chicken and any juices pooled on the plate into the sauce. Turn to coat and reheat through - about 1 1/2 minutes - or until sauce is thickened to your taste.","images":[],"step":9},{"description":"Serve on mashed potato, garnished with parsley, with a simple side salad.","images":[],"step":10}]', '["gluten","mustard"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74fb2f46ddf5', 'en', 'US', 'Chicken & Mushroom Risotto', 'The new way to make risotto that comes out just as creamy as the traditional method: no heating up the broth, no need to add it gradually and no need to stir constantly! The bacon garnish is optional but honestly, it is so worth the effort. Also, I use the bacon fat in the pot to cook the chicken and mushrooms. Why waste the free flavour? :)', 'https://www.recipetineats.com/tachyon/2016/08/Chicken-Mushroom-Risotto_4.jpg', 10, 40, 50, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 2.5, "unit": "pack of 200g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 13.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tsp - 1 tbsp olive oil","2.5 oz / 75 g bacon (preferably streaky / fatty) (optional)","12 oz / 350 g chicken thigh fillets (, cut into bite size pieces)","13 oz / 400 g mushrooms (, sliced (I use Swiss brown))","2 tbsp / 30 g unsalted butter","2 garlic cloves (, minced)","1 onion (, finely diced (brown, white, yellow))","1/2 cup / 125 ml white wine (optional - sub with water or chicken broth)","1 1/4 cups / 250 g arborio risotto rice (, uncooked (Note 1))","4 cups / 1 litre chicken broth/stock"]},{"ingredients":["1/2 cup / 35 g freshly grated parmesan cheese","1 - 3 tbsp / 15 - 50 g unsalted butter","Freshly chopped parsley"],"purpose":"Finishing"}]', '[{"description":"Heat 1 tsp oil in a pot or skillet (Note 2) over high heat. Add bacon and cook until golden. Transfer to small microwave-proof bowl.","images":[],"step":1},{"title":"Leave about 1 tbsp bacon fat in pot","description":"discard excess. Add chicken* and cook until browned and cooked through. Transfer to separate bowl.","images":[],"step":2},{"description":"Add mushrooms* and cook until light golden. Add to bowl with chicken.","images":[],"step":3},{"description":"Turn heat down to medium and return pot to the stove. Add butter, and melt. Add garlic and onion. Sauté for 3 minutes or until softened.","duration":3,"images":[],"step":4},{"description":"Turn heat up to high, add rice and stir until the grains become partially translucent - no longer than 1 minute. (Note 3)","images":[],"step":5},{"description":"Add wine and cook, scraping the bottom of the pot (to get any brown bits), until the alcohol smell evaporates ~ 2 minutes.","images":[],"step":6},{"description":"Turn heat down to medium low. Add about 3 cups of stock. Then leave it, uncovered, stirring just once or twice, until most of the liquid has been absorbed.","images":[],"step":7},{"description":"Check firmness of rice and add 1/2 cup of stock at a time, stirring in between until absorbed, until the rice is cooked to your taste. (Note 4)","images":[],"step":8},{"description":"Add chicken and mushrooms back into the risotto towards the end, just to heat through.","images":[],"step":9},{"description":"Right at the end when the risotto is ready, add a splash of chicken broth to make the risotto to make it slightly soupy, then take it off the stove.","images":[],"step":10},{"title":"KEY STEP","description":"Add butter (the more the better!) and parmesan, then stir vigorously (activates the starch and makes it super creamy). The excess liquid will evaporate quickly, so add more if you want a soupier risotto, like what you get at posh restaurants.","images":[],"step":11},{"description":"Serve IMMEDIATELY!! (Note5) Garnish with reheated bacon, and extra parmesan and parsley if desired.","images":[],"step":12}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","mushroom-recipes","quick-and-easy","risotto-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d4d8f52d5211', 'en', 'US', 'Bacon Wrapped Chicken', 'Juicy chicken wrapped in bacon, baked to golden perfection and slathered in gorgeous bacon juices! The brown sugar makes the bacon extra tasty and the Seasoning gives the chicken even more flavour. Simple and ridiculously delicious!', 'https://www.recipetineats.com/tachyon/2016/08/Bacon-Wrapped-Chicken_2.jpg', 15, 25, 40, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 8.0, "unit": "pack of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}]', '[{"ingredients":["1 tsp garlic powder","1 tsp paprika","1/2 tsp cayenne pepper (or sub with more paprika)","1 tbsp flour","1/2 tsp salt","Black pepper"],"purpose":"Seasoning"},{"ingredients":["4 large chicken thigh fillets (about 5oz / 150g each), cut in half (Note 1)","8 pieces bacon (, streaky (Note 2))","2 tbsp brown sugar","1 tsp olive oil (optional)"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200C/390F (fan forced / convection) (Note 3)","images":[],"step":1},{"description":"Line tray with baking paper.","images":[],"step":2},{"description":"Combine Seasoning in a small bowl. Place brown sugar in a separate bowl.","images":[],"step":3},{"description":"Coat chicken in Seasoning, shaking off excess. Place on one end of bacon and roll up, finishing with the seam side down. Repeat with remaining chicken.","images":[],"step":4},{"title":"Coat chicken in sugar","description":"use your fingers to rub it on if required. Place on baking tray.","images":[],"step":5},{"description":"Drizzle with olive oil (helps make it brown faster, optional)","images":[],"step":6},{"description":"Bake for 25 minutes. If the bacon is not golden enough for your taste, switch on the broiler for a few minutes.","duration":25,"images":[],"step":7},{"description":"Brush the juices on the tray onto the bacon to make it glossy and juicy. Serve on mashed potatoes, drizzled with extra pan juices if desired!","images":[],"step":8}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c02f2a8030e5', 'en', 'US', 'Chicken in White Wine Cream Sauce', 'Chicken in a creamy white wine sauce - comfort food and it''s finest! So simple to make, the key to this recipe is the white wine which transforms into an incredible broth by braising the chicken slowly in it so the chicken is incredibly tender. This is very French-country-chic! :)', 'https://www.recipetineats.com/tachyon/2016/07/Chicken-with-Bacon-White-Wine-Cream-Sauce_6.jpg', 10, 75, 85, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 5.0, "unit": "pack of 200g"}}, {"id": "ing_wine", "quantity": {"value": 2.0, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.012, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2.5 lb / 1.2 kg chicken pieces (, bone in thigh & drumsticks are ideal (Note 1))","1 tbsp / 15g / 0.5 oz butter","3 garlic cloves (, crushed)","1 onion (brown, white, yellow), finely chopped (~1 cup)","5 oz / 150 g bacon (, diced)","2 cups / 500 ml dry white wine (Note 2)","1 cup / 250 ml chicken broth / stock or water","2 tsp fresh thyme leaves (or 1 tsp dried)","3/4 cup / 185 ml cream (pouring or heavy cream, but not low fat cream)"]},{"ingredients":["Finely chopped parsley"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Season chicken with salt and pepper. Heat oil in an ovenproof skillet (with lid) over high heat. Add chicken skin side down and cook until golden brown, then turn and cook the other side for 1 minute. Remove chicken from skillet. Drain excess fat from skillet (do not wipe).","duration":1,"images":[],"step":2},{"description":"Reduce heat to medium high. Melt butter then add garlic and onion. Cook for 3 minutes until softened, then add bacon. Cook until golden.","duration":3,"images":[],"step":3},{"description":"Add wine. Bring to simmer, scraping the bottom of the skillet to mix the brown bits into the liquid. Simmer for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add chicken broth, thyme and return chicken to the skillet, skin side up. Cover with lid or foil, then transfer to the oven. Bake for 60 minutes, covered, then remove the lid and bake for a further 15 minutes to recrisp the skin. The chicken should be very tender.","duration":60,"images":[],"step":5},{"description":"Remove chicken or move to side. Stir cream into sauce and season with salt and pepper to taste.","images":[],"step":6},{"description":"Garnish with plenty of parsley. Serve with creamy mashed potatoes. Mine are pictured with Glazed Carrots.","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["French-style"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","one-pot-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fcc52bc66bbc', 'en', 'US', 'Sun Dried Tomato, Spinach & Cheese Stuffed Chicken Breast', 'Chicken breast slathered with an Italian dressing then stuffed with sun dried tomato, spinach and cheese. The chicken breast stays beautifully juicy because it cooks faster than whole chicken breast, even though this is stuffed. Also the juices from the sun dried tomato, cheese and Italian dressing baste the chicken as it roasts!', 'https://www.recipetineats.com/tachyon/2016/06/Sun-Dried-Tomato-Stuffed-Chicken-Breast_5.jpg', 5, 20, 25, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 4.0, "unit": "pack of 125g"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.02, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["6oz/180g small chicken breasts (2 pieces), boneless and skinless","1/2 cup sun dried tomato (oil packed. Use enough to cover the chicken, cut into strips)","4 slices mozzarella cheese (or other melting cheese of choice)","leaves Handful of spinach","2 tsp olive oil"]},{"ingredients":["1 tbsp Dijon Mustard","1 tbsp white wine vinegar or lemon juice","1/2 tsp sugar, any","2 tsp olive oil","1/2 tsp EACH Italian mixed herbs and red pepper flakes (Note 1)","Salt & pepper"],"purpose":"Italian Dressing"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Whisk together the Italian Dressing ingredients in a bowl. It will be thicker than salad dressing.","images":[],"step":2},{"description":"Cut a pocket into each chicken breast, taking care not to cut all the way though.","images":[],"step":3},{"description":"Coat the chicken (inside and out) with the Italian Dressing.","images":[],"step":4},{"description":"Place chicken on work surface. Stuff with sun dried tomato, top with cheese then finish with spinach leaves. Just stuff in as much as you can.","images":[],"step":5},{"description":"Seal with toothpicks (just stick them in on the diagonal - see photo in post).","images":[],"step":6},{"description":"Heat oil in an ovenproof skillet over high heat. Add chicken and cook for 1 1/2 minutes on each side, or until golden.","images":[],"step":7},{"description":"Transfer to oven and cook for 15 minutes, or until cheese is melted and bubbly and chicken is cooked through. Rest for 3 minutes before serving, drizzled with the juices in the skillet.","duration":15,"images":[],"step":8}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ace302a5f57e', 'en', 'US', 'Hawaiian Chicken Salad', 'A giant salad loaded with the tropical flavours of Hawaii! This recipe is based on the marinade for these Hawaiian Chicken Skewers I shared a few weeks ago - see note 1 for how to REUSE the marinade for this recipe. This recipe also uses leftover Coconut Lime Cilantro/Coriander Rice that I shared as a side for the skewers.', 'https://www.recipetineats.com/tachyon/2016/06/Hawaiian-Chicken-Salad-Lime-Dressing_3.jpg', 15, 10, 25, 2, '[{"id": "ing_marinade", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.003, "unit": "can of 400ml"}}, {"id": "ing_pineapple", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_pineapple", "quantity": {"value": 1.75, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 5.0, "unit": "head"}}, {"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_dressing", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_ime_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.001, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["Marinade ((Note 1):)","1/3 cup coconut milk (from a can)","1/4 cup pineapple juice (from can, save pineapple pieces)","1 tbsp tomato sauce/ketchup","1 tbsp soy sauce","Zest of 1 lime","2 garlic cloves (, minced)","1/4 tsp EACH onion powder (, cumin, paprika, ginger powder, salt)","Chicken & Salad:","1/2 tbsp olive oil","1 large chicken breast (, halved horizontally)","1/2 cup corn","1/2 - 3/4 cup pineapple pieces (from can)","4 - 6 cups chopped lettuce","1/2 avocado (, cut into wedges)","1/2 red onion (, finely sliced)","1/2 cup cherry tomatoes (, halved)","1 small carrot, finely shredded","1 - 1 1/2 cups Coconut Lime Cilantro / Coriander Rice (Note 2)","Dressing:","1 1/2 tbsp lime juice","2 1/2 tbsp olive oil","2 tbsp finely chopped cilantro/coriander","1/2 garlic minced","1/2 tsp sugar or honey","1/4 tsp salt","Black pepper"]}]', '[{"description":"Mix together Marinade ingredients, marinate chicken for minimum 3 hours, preferably overnight.","images":[],"step":1},{"description":"Shake Dressing ingredients together in a jar, set aside for at least 15 minutes.","images":[],"step":2},{"description":"Heat oil in a non stick skillet over high heat (or BBQ). Add chicken and cook each side for 3 minutes or until golden. Remove and cover loosely with foil for 5 minutes, then slice thickly.","duration":3,"images":[],"step":3},{"description":"Sear 1/2 cup pineapple pieces and corn in the skillet until golden.","images":[],"step":4},{"description":"Pile salad ingredients on a platter and top with sliced chicken. Drizzle over Dressing. Serve and pretend you''re in Hawaii!","images":[],"step":5}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":["Hawaiian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","most-popular","salad-recipes-main-course","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1accca9710b5', 'en', 'US', 'Oven Fried Parmesan Baked Chicken Tenders', 'These oven fried chicken tenders TRULY come out just like they''ve been fried! They are a beautiful golden brown all over and super crunchy. Make these with chicken tenderloins or cut chicken breast into tenderloin length strips! This is the parmesan flavoured version of these Truly Golden Crunchy Baked Chicken Tenders I shared last year.', 'https://www.recipetineats.com/tachyon/2016/06/Parmesan-Baked-Chicken-Tenders_3.jpg', 15, 15, 30, 3, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.005, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1 cup panko breadcrumbs (Note 1)","Olive oil spray","1/2 cup grated parmesan cheese (, store bought (Note 2))"],"purpose":"Breadcrumb"},{"ingredients":["1 egg","1 tbsp mayonnaise* (I use whole egg mayonnaise)","1½ tbsp dijon mustard* (or any other mustard of choice)","1 garlic clove (, minced*)","2 tbsp plain flour","Salt & pepper"],"purpose":"Batter"},{"ingredients":["500 g /1 lb chicken tenderloins (or chicken breast cut into ⅔\" / 1.5cm thick slices, lengthwise)","Oil spray"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Spread panko breadcrumbs on a baking tray. Spray lightly with oil. Bake for 3 to 5 minutes or until LIGHT golden.","duration":4,"images":[],"step":2},{"description":"Scrape into a bowl. Add parmesan and mix.","images":[],"step":3},{"description":"In a separate bowl, whisk together Batter ingredients with a fork. Add chicken and mix to coat.","images":[],"step":4},{"title":"Optional","description":"Place a rack on the baking tray (Note 3)","images":[],"step":5},{"description":"Pick up chicken with left hand and place in breadcrumbs. Use right hand to sprinkle with breadcrumbs, press to adhere. Use right hand to transfer to baking tray. Repeat with remaining chicken. Spray lightly with oil.","images":[],"step":6},{"description":"Bake for 15 minutes for small tenders, 18 minutes for large ones. No longer than 20 minutes, otherwise they will begin to lose juiciness.","duration":15,"images":[],"step":7},{"description":"Serve immediately with Ranch or Honey Mustard Dip if desired (Note 4).","images":[],"step":8}]', '["egg","gluten","milk","mustard"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1066f3c9c080', 'en', 'US', '5 Ingredient Sticky Stove Top Balsamic Drumsticks', 'Sticky chicken drumsticks that are cooked on the stove in half the time it takes to bake! Don''t let the short list of ingredients fool you - the glaze tastes like it has a lot more in it. Adapted from this Sticky Stove Top Chicken recipe from Sparks People. This recipe is NOT suited for scaling up because the glaze will not thicken. Watch the cooking video (in post) to see exactly how this is made - in particular, watch the braising liquid transform into the sticky glaze!', 'https://www.recipetineats.com/tachyon/2015/04/Sticky-Balsamic-Drumsticks_4.jpg', 5, 25, 30, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.04, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 chicken drumsticks (2 lb / 1 kg) (Note 1)","1 cup water","1/2 cup balsamic vinegar","1/3 cup soy sauce (all purpose or light, not dark)","3 tbsp sugar (brown)","3 garlic cloves (, minced)"]},{"ingredients":["2 tsp fresh grated ginger","2 tbsp Sriracha or 1 tsp red pepper flakes (Note 2)"],"purpose":"Extra Flavourings (Optional)"},{"ingredients":["Parsley or shallots/scallions (, finely sliced)"],"purpose":"Garnishes (optional)"}]', '[{"description":"Combine all ingredients (including Extra Flavourings, if using) in a large skillet/fry pan or pot (Note 3) over medium high heat. The chicken should be in a single layer.","images":[],"step":1},{"description":"Bring to boil, turn chicken, then turn down to medium so it simmers energetically but not rapidly. DO NOT cover the pan with a lid.","images":[],"step":2},{"description":"Cook for 20 minutes, turning the chicken at 10 minutes.","duration":20,"images":[],"step":3},{"description":"At 20 minutes, the chicken should be cooked. Move the chicken to the side of the skillet, propping and stacking them up on the edges of the skillet to clear the surface of the liquid as much as possible so it can reduce.","images":[],"step":4},{"description":"Simmer for 5 minutes or until the liquid thickens (consistency of thick pouring cream) and coats the chicken. Keep an eye on the sauce, once it starts to thicken it will reduce quickly, don''t let it go too far. Roll the chicken in the glaze.","duration":5,"images":[],"step":5},{"description":"Remove the skillet from the stove and stand for 5 minutes - the sauce will thicken slightly more. Roll the chicken in the glaze again, then serve, garnished with parsley or scallions if desired.","duration":5,"images":[],"step":6},{"description":"Serve, garnished with scallions/shallots if using.","images":[],"step":7}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6addde9f9b4', 'en', 'US', 'Mexican Shredded Chicken', '5 minutes prep is all that''s required for this shredded chicken tossed in a smokey, mildly spicy red sauce that''s loaded with flavour. Make this in your slow cooker, pressure cooker or on the stove - directions provided for all!', 'https://www.recipetineats.com/tachyon/2016/03/Slow-Cooker-Mexican-Chicken_1.jpg', 10, 240, 250, 5, '[{"id": "ing_chicken_breast", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_chipotles_in_adobo_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 14.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}]', '[{"ingredients":["1.5 lb / 750g chicken breast (, skinless boneless (~3 halves))","1/2 cup Chipotles in Adobo Sauce (4 chillies + sauce) (Note 1)","14 oz / 400g can crushed tomatoes","2 garlic cloves (, crushed)","1 tsp EACH dried oregano, cumin powder and onion powder (or garlic powder)","2 tsp sugar (any)","3/4 tsp salt (Note 2)","Pepper"],"purpose":"Chicken & Sauce"},{"ingredients":["3 tbsp olive oil (Note 3)","2 tbsp lime juice"],"purpose":"To Finish"}]', '[{"description":"Cook Chicken","images":[],"step":1},{"title":"Slow Cooker","description":"Place Chicken & Sauce ingredients in the slow cooker and cook for 4 hours on low. The chicken is ready when it can be shredded easily with 2 forks but it should NOT be mushy (i.e. overcooked).","images":[],"step":2},{"title":"Pressure cooker","description":"35 minutes on high.","images":[],"step":3},{"title":"Stove","description":"Place Chicken & Sauce ingredients in a medium saucepan and add 1 cup water. Simmer covered on medium low for 40 - 50 minutes, turning chicken occasionally, until chicken can be shredded with 2 forks.","duration":45,"images":[],"step":4},{"description":"Remove chicken and shred. Set aside.","images":[],"step":5},{"description":"Add lime juice (to taste) and 1 tbsp olive oil to the sauce. Use a stick blender (or transfer to blender) to puree the sauce. Adjust salt and pepper to taste. You should have about 2 cups of sauce.","images":[],"step":6},{"description":"Brown Chicken","images":[],"step":7},{"description":"Heat 1 tbsp oil in a large skillet over high heat. Add 1/3 to 1/2 the chicken and fry until dark golden brown on one side, flip and cook the other side very briefly (don''t brown), then remove. Use 1 tbsp oil for each batch you fry.","images":[],"step":8},{"description":"To Serve","images":[],"step":9},{"description":"Toss chicken in the sauce OR serve it on the side.","images":[],"step":10},{"description":"Use for tacos (guacamole and Pico de Gallo, enchiladas, burritos, on green Mexican rice, quesadillas, sliders, on tostadas.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","main-dishes","mexican-recipes","most-popular","quick-and-easy","slow-cooker-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a1591af3a72', 'en', 'US', 'KFC Oven Baked "Fried" Chicken Tenders', 'Crunchy and perfectly seasoned, it really does taste like KFC! It is a mash up of my own recipe, the "11 Secret Herbs and Spices" from the Homemade KFC recipe by Every Nook & Cranny, and the coating recipe from this Best Baked "Fried" Chicken by Carlsbad Cravings.. Marinating makes the chicken extra juicy but if you don''t have time to marinate, this is still worth making! (See Note 3) PS I know it looks like a lot of salt but it''s not overly salty, it''s KFC level salty. Reduce salt and/or celery salt if desired.', 'https://www.recipetineats.com/tachyon/2015/09/KFC-Copycat-Oven-Baked-Fried-Chicken-Tenders_680px_2.jpg', 15, 25, 40, 4, '[{"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_paprika", "quantity": {"value": 0.075, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_chicken", "quantity": {"value": 1.3, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.4, "unit": "tub of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1/2 tsp salt","1 tbsp celery salt (Note 1)","2 tsp garlic powder","1/2 tsp dried thyme","1/2 tsp dried basil","1/2 tsp dried oregano","1/2 tbsp coarsely ground black pepper","1 tbsp mustard powder","2 tbsp paprika (not smoked, use sweet or plain)","1 tsp ground ginger","1 tsp cayenne pepper or ground pure chili (optional - for KFC \"Zinger\" flavour!)"],"purpose":"KFC Spice Mix"},{"ingredients":["1.2 - 1.4 lb / 600 - 700 g chicken tenderloin (10 - 12 pieces) (Note 2)","1 cup buttermilk OR 1/3 cup plain yoghurt + 2/3 cup milk (Note 3)","1 cup flour","1 cup panko breadcrumbs","1/4 cup cornmeal (Note 4)","2 tbsp butter (unsalted)","1 tbsp vegetable or canola oil","Oil spray"],"purpose":"Chicken"}]', '[{"description":"Combine the Spice Mix in a bowl.","images":[],"step":1},{"description":"Place 1 tbsp of Spice Mix in a ziplock bag with the chicken and buttermilk. Set aside to marinate for at least 2 hours, preferably 3 but ideally overnight.","images":[],"step":2},{"description":"To Cook","images":[],"step":3},{"description":"Preheat oven to 400F/200C.","images":[],"step":4},{"description":"Place the butter and oil on a large rimmed baking tray. Place in the oven for a few minutes until the butter is just melted. Remove and tip the tray to spread the oil and butter all over.","images":[],"step":5},{"description":"Combine the remaining Spice Mix, flour, panko and cornmeal in a bowl and mix. Place half in a large ziplock bag.","images":[],"step":6},{"description":"Drain the chicken of excess marinade using a colander.","images":[],"step":7},{"description":"Transfer half the chicken into the ziplock bag, seal in air so it is puffed like a balloon, then shake to coat the chicken in the seasoning. Press through the bag so the coating is firmly stuck onto the chicken. Place the chicken onto the baking tray.","images":[],"step":8},{"description":"Place the remaining coating into the ziplock bag and repeat with remaining chicken.","images":[],"step":9},{"description":"Spray the top with oil and place in the oven. Bake for 12 minutes, then turn, spray and bake for a further 8 to 10 minutes or until golden. Don''t bake more than 25 minutes, otherwise the chicken will dry out!","duration":12,"images":[],"step":10},{"description":"Serve with your favourite dipping sauce. I used Honey Mustard Sauce (Note 7).","images":[],"step":11}]', '["gluten","milk","mustard"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fd20cfe1d1d5', 'en', 'US', 'Chicken Meatloaf Wellington with Sun Dried Tomatoes', 'A fresh take on meatloaf! Made with chicken, scattered with sun dried tomatoes and the fresh burst of basil. Encase in puff pastry to create a cross between the British classic Beef Wellington and meatloaf (but made with chicken!).', 'https://www.recipetineats.com/tachyon/2015/09/Chicken-Meatloaf-Wellington_1-Featured.jpg', 15, 40, 55, 5, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 3.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1 small onion (, grated (about 1/2 cup))","1 lb / 500 g ground chicken (mince) (Note 1)","3/4 cup panko breadcrumbs","1/4 cup parmesan cheese (, finely grated)","1 egg","1/3 cup fresh basil (, roughly chopped (Note 2))","3/4 cup roughly chopped sun dried tomatoes","1 tsp salt","Black pepper"],"purpose":"Filling"},{"ingredients":["1 sheet puff pastry (, thawed)","1 egg (, lightly beaten (optional) (Note 3))"],"purpose":"Pastry"}]', '[{"description":"Preheat oven to 180C/350F. Line a baking tray with parchment paper.","images":[],"step":1},{"description":"Place the Filling ingredients in a bowl and use your hands to mix together. It should be quite soft and wet, not dry and crumbly.","images":[],"step":2},{"description":"Place the filling onto the puff pastry. Shape into a loaf and roll the puff pastry up, ending with the seam side down.","images":[],"step":3},{"description":"Transfer to baking tray. Cut a few diagonal slashes across the top.","images":[],"step":4},{"description":"Brush with egg wash and bake for 35 to 40 minutes, or until the pastry is deep golden brown. Turn the tray at around 25 minutes for even browning.","duration":37.5,"images":[],"step":5},{"description":"Remove from the oven. Rest for 5 minutes before serving.","duration":5,"images":[],"step":6}]', '["egg","milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-mince-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4473cf255160', 'en', 'US', 'White Chicken Enchiladas', 'This white sauce version of Enchiladas gives the classic a serious run for its money!', 'https://www.recipetineats.com/tachyon/2015/08/White-Enchiladas_Plated-Featured.jpg', 15, 25, 40, 4, '[{"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 1.0, "unit": "tub of 250g"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.5, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_rtillas", "quantity": {"value": 8.0, "unit": "unit"}}]', '[{"ingredients":["2 1/2 tbsp butter","3 tbsp flour","1 cup milk","1/2 cup light sour cream","1 cup chicken broth","1/2 tsp cumin powder","2 tbsp finely chopped jalapeños OR canned green chilies (Note 2)","1/2 tsp salt + pepper"],"purpose":"White Sauce"},{"ingredients":["2 1/2 cups shredded cooked chicken (I used poached chicken breast)","1 cup frozen corn","1/2 cup sliced scallions","Salt and pepper","2 cups grated cheese (Note 1)","8 to rtillas (flour or corn)"],"purpose":"Enchiladas"}]', '[{"description":"Melt butter over medium heat in a skillet. Add flour and cook for 1 minute.","duration":1,"images":[],"step":1},{"title":"Add milk, whisk until thickened","description":"about 30 seconds to 1 minute. Add sour cream and chicken broth. Whisk and cook for 2 minutes - it should thicken slightly. Stir through cumin, jalapeños, salt and pepper. Remove from heat and set aside.","duration":2,"images":[],"step":2},{"description":"Preheat oven to 180C/350F.","images":[],"step":3},{"description":"Mix together 1/4 cup White Sauce, chicken, corn, scallions, 1 cup of grated cheese, salt and pepper.","images":[],"step":4},{"description":"Pop the tortillas in the microwave for 15 seconds to warm through (so they don''t crack when rolled up).","duration":0.25,"images":[],"step":5},{"description":"Divide filling between tortillas, and roll them up like a cigar.","images":[],"step":6},{"description":"Smear 2 tbsp of White Sauce in baking dish. Place enchiladas in the dish, seam side down. Pour over remaining White Sauce, scatter with remaining cheese.","images":[],"step":7},{"description":"Bake for 25 minutes, until bubbly and golden. Serve hot!","duration":25,"images":[],"step":8},{"title":"Optional","description":"Serve Pico de Gallo to top it or serve it on the side. I added avocado to my base Pico de Gallo Recipe.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","enchiladas","main-dishes","mexican-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_52d01eac228e', 'en', 'US', 'Prosciutto Wrapped Chicken and Scalloped Potatoes (One Pan!)', 'This is one of those recipes that is easy enough for midweek but elegant enough for company - at least, in my opinion! By baking the chicken on top of the potato, the juices mingles with the salty prosciutto then drips down onto the potato, adding extra (serious) flavour oomph!', 'https://www.recipetineats.com/tachyon/2015/08/One-Pan-Prosciutto-Chicken-Potatoes_Featured.jpg', 15, 45, 60, 4, '[{"id": "ing_ricotta", "quantity": {"value": 0.008, "unit": "tub of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_sage", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_ong_or_8_small_thin_slices_of_prosciutto", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.5, "unit": "bag of 2kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2/3 cup ricotta","Zest of 1 small lemon (, or 1/2 large lemon)","1 1/2 tsp finely sliced fresh sage leaves (Note 1)","1/4 tsp salt","Pepper"],"purpose":"Ricotta Filling"},{"ingredients":["4 chicken thigh fillets (, skinless and boneless (about 5 - 7 oz / 150 - 200g each))","4 long or 8 small thin slices of prosciutto","1.5 lb / 750 g potatoes (, peeled and cut into thin slices)","1 garlic clove (, crushed (optional))","1 1/2 tbsp olive oil + 1/2 tbsp extra olive oil","1 tsp dried thyme leaves","1/4 cup freshly grated parmesan","Salt and pepper"],"purpose":"Prosciutto Chicken & Potatoes"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix together the Ricotta Filling ingredients in a small bowl.","images":[],"step":2},{"description":"Lay out the prosciutto on a work surface. Place chicken lengthwise at the bottom of each strip.","images":[],"step":3},{"description":"Divide Ricotta Filling between the chicken, placing it at the bottom (closest to you).","images":[],"step":4},{"description":"Roll up the chicken, wrapping it in the prosciutto, finishing with the seam side down. Not too tightly otherwise the ricotta will ooze out!","images":[],"step":5},{"description":"Use toothpicks to seal the ends. (Note 2)","images":[],"step":6},{"description":"Spread the potato slices on the base of a roasting dish or large ovenproof skillet. Fan them out so they are overlapping slightly.","images":[],"step":7},{"description":"Mix together 1 1/2 tbsp olive oil and garlic then pour over the potatoes, using a teaspoon or brush to spread it out. Sprinkle with salt and pepper and thyme leaves.","images":[],"step":8},{"description":"Place chicken on top of the potato, drizzle the chicken with 1/2 tbsp olive oil and bake for 40 minutes.","duration":40,"images":[],"step":9},{"description":"Remove chicken onto a plate to rest, covered loosely with foil.","images":[],"step":10},{"description":"Sprinkle the potatoes with parmesan cheese, then return just the potatoes back into the oven and turn up the oven to maximum. Bake for 5 minutes.","duration":5,"images":[],"step":11},{"description":"Remove potatoes from the oven. Place chicken back on top.","images":[],"step":12},{"description":"Serve asap!","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a474fbff15c1', 'en', 'US', 'Shredded Sweet Soy Chicken Breast', 'A simple, fast, very tasty way to prepare chicken. Chicken breast is perfect for shredding. Because it''s so lean, it is especially great combined with a jammy intense flavoured sauce that is sweet and sour. Add a kick of chili if you want! Great served on rice, or use the sauce as the flavouring for a fried rice!', 'https://www.recipetineats.com/tachyon/2015/07/Sweet-Soy-Shredded-Chicken_600px_1_Featured-Image.jpg', 10, 60, 70, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_jam", "quantity": {"value": 0.113, "unit": "jar of 370g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.037, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}]', '[{"ingredients":["1 lb / 500g chicken breast (skinless, boneless pieces)","2 cloves of garlic (, minced)","1/2 onion (, finely diced)","1 tbsp oil (vegetable, canola, olive oil or grapeseed oil)","1/3 cup soy sauce (ordinary soy sauce)","1/3 cup white vinegar (or substitute with other vinegar except balsamic)","3 tbsp jam (Note 1)","1 tbsp black peppercorns or 1/2 tbsp ground black pepper (Note 2)","3/4 cups water"],"purpose":"Shredded Chicken"},{"ingredients":["2 tsp cornstarch / cornflour","3 tsp water"],"purpose":"Sauce Thickening"}]', '[{"title":"Slow Cooker","description":"Place all the Shredded Chicken ingredients in the slow cooker and cook on low for 5 hours (or 2 1/2 hours on high).","images":[],"step":1},{"title":"Pressure Cooker","description":"Place all the Shredded Chicken ingredients in the pressure cooker. Cook for 35 minutes on high.","duration":35,"images":[],"step":2},{"title":"Stove","description":"Place all the Shredded Chicken ingredients in a saucepan large enough for the chicken to fit snugly in one layer. Add 1/2 cup extra water so the chicken is mostly, but not completely submerged. Cover and simmer for about 50 to 60 minutes, turning once or twice.","images":[],"step":3},{"description":"The chicken is ready when it can be easily shredded with two forks. Remove the chicken from the liquid and shred it while it is warm. Set aside and cover to keep warm.","images":[],"step":4},{"description":"Transfer the liquid from the slow cooker / pressure cooker to a saucepan and bring to simmer. (Note 3) Reduce to around1 1/4 cups - it should only take a few minutes.","images":[],"step":5},{"description":"Mix together the Sauce Thickening ingredients and add to the saucepan. Simmer until it it thickens to a syrup consistency.","images":[],"step":6},{"description":"Toss the chicken in the sauce and serve over rice. (Note 4)","images":[],"step":7}]', '["gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","most-popular","quick-and-easy","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1936d88c97f7', 'en', 'US', 'One Pot Creamy Parmesan Garlic Risotto with Lemon Pepper Chicken', 'Two dishes made in one pot! Creamy, dreamy risotto with yummy garlic parmesan flavours topped with crispy roast chicken. Cooking the chicken on top of the rice is like making rice with triple strength stock!', 'https://www.recipetineats.com/tachyon/2015/06/One-Pot-Creamy-Risotto-Lemon-Pepper-Chicken-4.jpg', 10, 50, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.094, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 tbsp olive oil","2 lb / 1 kg chicken thighs (, skin on and bone in (5 pieces) (Note 1))","2 - 3 tbsp Lemon Pepper Seasoning (Note 2)"],"purpose":"Chicken"},{"ingredients":["2 tbsp butter","4 garlic cloves (, minced)","1 onion (, finely diced)","1 1/2 cups risotto rice (arborio)","1/2 cup white wine (, any (or stock or water))","4 cups chicken broth (stock)","1 cup milk (I use low fat)","1/2 tsp salt","Black pepper"],"purpose":"Risotto"},{"ingredients":["1 cup freshly grated parmesan (lightly packed)","2 tbsp butter","1/2 to 1 cup milk (preferably warmed)","Fresh thyme leaves (, or finely chopped parsley, chives or oregano (optional))"],"purpose":"Risotto Finishes"}]', '[{"description":"Preheat oven to 180C/350F (fan forced) / 200C/390F (conventional).","images":[],"step":1},{"description":"Coat chicken with Lemon Pepper Seasoning, using most of it on the skin.","images":[],"step":2},{"description":"Heat olive oil over medium heat in a large oven proof fry pan (Note 3).","images":[],"step":3},{"description":"Place the chicken in the pan skin side down. Cook for 3 minutes then turn the heat up to medium high and cook for a further 2 minutes or until browned. Turn and cook for 3 minutes. (Note 4)","duration":3,"images":[],"step":4},{"description":"Remove chicken onto a plate. Discard excess oil in the pan and wipe the pan with a paper towel.","images":[],"step":5},{"description":"Return the pan to the stove, still on medium high.","images":[],"step":6},{"description":"Melt butter in the pan. Add garlic and onion and cook for 2 minutes or until onion is translucent.","duration":2,"images":[],"step":7},{"description":"Add rice and stir until the grains turn from white to translucent. Add wine and cook for 1 to 2 minutes, or until the wine is mostly evaporated.","duration":1.5,"images":[],"step":8},{"description":"Add chicken broth, milk, salt and pepper. Bring to a simmer on the stove. Give it a quick stir then place the chicken on top of the rice (pour juices on the plate in too). Then place a lid (or foil) on the pan and transfer to the oven.","images":[],"step":9},{"description":"Bake for 20 minutes with the lid on. Remove the lid and return to the oven for another 10 minutes, or until the rice is firm but just cooked (not mushy!) and the chicken is crispy.","duration":20,"images":[],"step":10},{"description":"Remove the chicken from the rice. Stir through Risotto Finishes, using the milk to get the risotto to a creamy consistency.","images":[],"step":11},{"description":"Return chicken on top. Serve immediately, with fresh thyme leaves and extra parmesan, if desired.","images":[],"step":12}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","risotto-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eb1ac84490df', 'en', 'US', 'Jamie Oliver''s Chicken in Milk {Seriously Delish}', 'Though the ingredients list might seem odd, this is actually one of the best chicken dishes I have ever had. Possibly the best roast chicken I''ve ever had. It''s incredibly easy to make and produces a very tender chicken with crispy skin on top. The braising liquid reduces to a fabulous sauce that has a hint of freshness from the lemon and muskiness from the sage and cinnamon. The whole cloves of garlic cook in the skin so they are soft and mushy (mild garlic flavour, much more sweet), perfect for popping out of the skin and eating with the chicken, or spread it on toast! The milk dissolves into bits of curd which remind me of bocconcini and taste like little bursts of creaminess.', 'https://www.recipetineats.com/tachyon/2014/12/Chicken-in-Milk-1445.jpg', 5, 100, 105, 4, '[{"id": "ing_chicken", "quantity": {"value": 3.25, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_stick_cinnamon", "quantity": {"value": 0.001, "unit": "jar"}}, {"id": "ing_oosely_packed_sage_leaves", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_emons", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_milk", "quantity": {"value": 3.0, "unit": "L"}}]', '[{"ingredients":["3 - 3.5 lb / 1.5 - 1.8 kg whole chicken","2 tsp salt (plus more to taste)","Black pepper","2 tbsp olive oil","1/2 stick cinnamon","1/4 cup loosely packed fresh sage leaves","2 lemons (, zest only (avoid grating the pith which is bitter))","10 cloves of garlic (, whole, skin on)","2 1/4 cups milk (I used low fat)"]}]', '[{"description":"Preheat oven to 190C/375F.","images":[],"step":1},{"description":"Wash the chicken under water and pat dry with paper towels.","images":[],"step":2},{"description":"Sprinkle over the salt and 5 grinds of black pepper and pat all over the chicken, concentrating on the top and sides.","images":[],"step":3},{"description":"Heat oil in a heavy based pot over high heat. (Note 1)","images":[],"step":4},{"description":"Brown the chicken all over as best you can. I find the easiest way to do this (and minimising skin tearing) is with tongs stuck in the rear of the chicken and a wooden spoon to lift and leverage the chicken. Tilt the chicken as required to brown as much of the skin as you can. (Note 2)","images":[],"step":5},{"description":"If you can manage it (or if you have a helper), pour the excess fat out of the pot with the chicken still in it. If you can''t, remove the chicken onto a plate, then drain the fat.","images":[],"step":6},{"description":"Add the remaining ingredients into the pot (return the chicken to the pot if you removed it).","images":[],"step":7},{"description":"Bake covered for 40 minutes, then bake uncovered for 50 minutes (1.5 hrs in total).","duration":40,"images":[],"step":8},{"description":"Let stand for 5 minutes or so before removing the chicken from the pot onto a serving plate. Serve the sauce on the side. I prefer not to strain it because I want the bits of curd and garlic on my chicken, as well as bits of sage.","duration":5,"images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","one-pot-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a818b0da846', 'en', 'US', 'Syrian Chicken', 'This is a simple but exotic dish of chicken with a spiced crispy skin baked with a rich tomato broth. It is served with Giant Couscous (also known as Moghrabieh, Israeli or Pearl Couscous) which can be substituted with ordinary couscous, pasta (risoni/orzo), rice, polenta or even mashed potato.', 'https://www.recipetineats.com/tachyon/2014/10/Syrian-Chicken-with-Giant-Couscous-12-Version-4.jpg', 15, 30, 45, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 14.0, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_saffron_powder", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_currants", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_giant_couscous", "quantity": {"value": 8.0, "unit": "pack"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["2 tbsp olive oil","2 lb / 1 kg chicken thigh fillets (, bone in and skin on (4 to 5 pieces) (see notes))"]},{"ingredients":["1 tsp cumin powder","1 tsp cinnamon powder","1 tsp salt","Black pepper"],"purpose":"Chicken Spices"},{"ingredients":["1 1/2 tbsp fresh ginger (, finely chopped)","3 garlic cloves (, minced)","1 onion (, halved and finely sliced)","2 birds eye chilis (, finely chopped (or to taste) (see notes))","1/4 cup (combined) mint and coriander leaves, roughly chopped","2 tbsp lemon juice","14 oz / 400 g canned crushed tomato","1 cup chicken stock / broth","1/8 tsp saffron powder (see notes)","1/2 tsp cumin powder","3 sprigs of thyme or 1 tsp dried thyme leaves","1/4 cup dried currants or sultanas (optional) (see notes)"],"purpose":"Sauce"},{"ingredients":["8 oz / 250 g giant couscous (Israeli or Pearl Couscous)","Yoghurt (optional)"],"purpose":"To Serve"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place chicken on a plate or in a large bowl. Sprinkle with Chicken Spices and use your hands to coat the chicken.","images":[],"step":2},{"description":"Heat olive oil in a large, oven proof fry pan over high heat.","images":[],"step":3},{"description":"Add chicken, skin side down, and sear until the skin is nicely browned. Turn chicken over and cook the other side until browned. Remove chicken from pan. Drain pan of excess oil.","images":[],"step":4},{"description":"Add onion, garlic, ginger and chili into the pan. Saute for 2 minutes until the onion is translucent and starting to brown.","duration":2,"images":[],"step":5},{"description":"Add canned tomato, chicken stock/broth, saffron powder, cumin powder and thyme. Bring to simmer, then turn the stove off. Nestle the chicken into the tomato broth, then cover with foil (or lid) and place into the oven. Bake for 25 to 35 minutes.","duration":30,"images":[],"step":6},{"description":"Meanwhile, cook the Giant Couscous according to packet instructions. Usually it just needs to be boiled in salted water for around 4 minutes, then drain it.","images":[],"step":7},{"description":"When the chicken is dark golden brown and cooked, remove from oven. Stir through dried currents (if using), lemon juice and half the mint and coriander. Then sprinkle over remaining mint and coriander.","images":[],"step":8},{"description":"Serve on Giant Couscous with a dollop of yoghurt, if using.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Middle Eastern","Syrian"],"categories":["chicken-recipes","dinner-tonight","main-dishes","mediterranean-recipes","most-popular","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c764a49c0479', 'en', 'US', 'Cobb Salad', 'Recipe video above. The mighty Cobb Salad! Don''t skip the blue cheese. It''s what makes this a Cobb Salad, and not just another chicken salad. :) Love the presentation on a big platter with the ingredients in neat rows. Serve Dressing on the side for everyone to help themselves (better than tossing each item individually).', 'https://www.recipetineats.com/tachyon/2023/08/Cobb-Salad_0.jpg', 15, 20, 35, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 0.333, "unit": "carton of 12"}}, {"id": "ing_lettuce", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gorgonzola_dolce_or_roquefort", "quantity": {"value": 200.0, "unit": "unit"}}, {"id": "ing_chives", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 500ml"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["400g/14 oz chicken breast (2 pieces)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Chicken:"},{"ingredients":["200g/7oz streaky bacon strips","4 x 9 minute boiled eggs (, quartered)","12 cups cos / romaine lettuce (1 large head, 2 small), chopped (or other crispy lettuce)","2 large tomatoes (, cut into 8 wedges then halved (or 250g/8oz cherry tomatoes halved))","2 avocados (, cut into large pieces)","200g/7oz gorgonzola dolce (my favourite) or roquefort (traditional), ( crumbled (or other blue cheese - Note 1))","2 tbsp chives (, finely chopped)"],"purpose":"Cobb Salad:"},{"ingredients":["1 tbsp dijon mustard","5 tbsp extra virgin olive oil","5 tbsp apple cider vinegar (sub white wine or red wine vinegar)","3/4 tsp cooking/kosher salt","1/4 tsp black pepper","2 tbsp eschallot ((US: shallot), very finely minced)","1/2 tsp white sugar"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Shake ingredients in a jar.","images":[],"step":1},{"title":"Flavour chicken","description":"Poach chicken using this method (20 minute foolproof-guaranteed-juicy). Cool to room temperature then cut into 2cm / 0.75” cubes. Toss with salt, pepper and 2 tablespoons of Dressing. Set aside.","images":[],"step":2},{"title":"Crisp bacon","description":"Place bacon strips in a non-stick pan (not heated, no oil). Turn heat onto medium high - as the pan heats up, the fat will begin to melt. Cook for 2 minutes until golden, turn and cook the other side for 1 1/2 minutes until golden. Drain on paper towels. Once cool and crisp, chop into 1.5cm / 0.6\" pieces.","duration":2,"images":[],"step":3},{"title":"Assemble","description":"Spread lettuce on a large platter. Arrange the ingredients on top in the Cobb Salad signature neat rows: egg, bacon, avocado, tomato and chicken. Crumble blue cheese across the top, sprinkle with chives. Pour dressing into a jug.","images":[],"step":4},{"title":"Serving","description":"Let everybody help themselves to the salad and Dressing!","images":[],"step":5}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["American","Western"],"categories":["chicken","chicken-breast-recipes","mains","no-cook-food","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_abcdc991d0d4', 'en', 'US', 'Duck Confit - French slow roasted duck legs', 'Recipe video above. A traditional recipe for Duck Confit from a French chef! Called Confit de Canard in French, duck legs are slow-cooked in duck fat until the meat is meltingly tender, then the skin crisped to golden perfection. This Duck Confit recipe is low-effort and DOESN''T require buckets of duck fat! Simple, yet a lusciously indulgent dish worthy of gracing restaurant tables. This might just be the ultimate dish for a low-stress dinner party or treating your loved ones!Recipe courtesy of our resident French Chef Jean-Baptiste Alexandre. Meet Chef "JB" here.', 'https://www.recipetineats.com/tachyon/2021/06/Duck-Confit-photo-_8.jpg', 15, 530, 545, 4, '[{"id": "ing_x_250g_duck_legs", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_duck_fat", "quantity": {"value": 750.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 6.0, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.037, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_star_anise", "quantity": {"value": 0.02, "unit": "jar"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_juniper_berries", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_s", "quantity": {"value": 8.0, "unit": "pack"}}]', '[{"ingredients":["4 x 250g / 8oz duck legs (, skin on, bone in (aka maryland); (Note 1))","750 ml / 25 oz duck fat (Note 2)"],"purpose":"Duck:"},{"ingredients":["4 tsp cooking/kosher salt (Note 4)","1/3 cup thyme sprigs (, lightly packed)","1/3 cup sage sprigs (, lightly packed)","1/3 cup rosemary sprigs (, lightly packed)","1/3 cup oregano sprigs (, lightly packed)","6 cloves garlic (, smashed with skin on)","1 eschalot ((US: shallot), peeled and sliced 0.7cm (1/3\") thick)","1 tbsp black peppercorns","1 tbsp coriander seeds","8 star anise","2 bay leaves","2 tbsp juniper berries","8 cloves"],"purpose":"Dry cure (Note 3):"}]', '[{"title":"Coat duck with dry cure","description":"Place duck legs and all the Dry Cure ingredients in a large bowl. Toss well with your hands.","images":[],"step":1},{"title":"Cure 12","description":"24 hrs: Transfer to a ceramic or glass dish large enough so the duck fits in a single layer but snugly. Cover and refrigerate for 12 - 24 hours (no longer is necessary).","images":[],"step":2},{"title":"Rinse","description":"Brush off cure and rinse duck under tap water to clean them (remove all salt and black bits). Pat dry with paper towels.","images":[],"step":3},{"description":"Slow cooking (confit):","images":[],"step":4},{"description":"Preheat oven to 100°C/210°F (80°C fan) with a shelf positioned in the middle of the oven.","images":[],"step":5},{"title":"Roasting pan","description":"Place duck in a small metal roasting pan with high sides. They should fit snugly, touching each other, but in a single layer. (Note 5)","images":[],"step":6},{"title":"Cover with duck fat","description":"Pour fat over duck. It should pretty much cover the legs. (Note 6)","images":[],"step":7},{"title":"Heat fat in pan","description":"Place pan on the stove over medium-high heat. Heat fat until bubbling energetically all across the surface (ie not just around the edges).","images":[],"step":8},{"title":"Cover with paper","description":"Turn off stove. Cover surface with baking / parchment paper, cut to size so it sits on the surface of the fat over the duck. Gently push down to remove air bubbles. Cover pan tightly with a double layer of foil.","images":[],"step":9},{"title":"Slow cook","description":"Carefully transfer to the oven. Cook for 8 hours.","images":[],"step":10},{"title":"Check flesh","description":"Remove one duck leg (gently). Turn over to check the flesh side – meat should be fall-apart tender. Leg should also give easily when pressure is applied to the joint (see video).","images":[],"step":11},{"description":"Storing cooked Duck Confit (optional):","images":[],"step":12},{"description":"Duck can be stored submerged in fat at this stage. The meat juice should be strained off first.","images":[],"step":13},{"description":"Remove duck to a non-reactive container in which they fit snugly. (Note 7) Pour over cooled duck fat, leaving juice sediment behind. Ensure it fully covers the duck (push duck under while warm and pliable as needed, using tongs).","images":[],"step":14},{"description":"Once fully cool, cover with lid and place in fridge (5 days) or freezer (3 months). Fat will solidify.","images":[],"step":15},{"description":"To cook, heat duck gently in a container in microwave to melt the fat. Proceed with recipe.","images":[],"step":16},{"description":"Crisping skin and finishing Duck:","images":[],"step":17},{"description":"Preheat oven to 240°C/465°F (220°C fan). Place a rack over a deep roasting pan.","images":[],"step":18},{"title":"Remove duck from fat","description":"Remove duck from fat, allowing excess oil to drip off. Pat excess oil off with paper towels.","images":[],"step":19},{"title":"Prepare for roasting","description":"Pour 2.5cm / 1\" of boiling water water into the roasting pan (steam keeps flesh moist). Place duck on rack, skin side up.","images":[],"step":20},{"title":"Crisp skin","description":"Roast duck for 40 minutes until the skin is a deep golden and crispy. Rotate pan as needed for even colour. (You won''t have problems with fat smoking as it drips into the water)","duration":40,"images":[],"step":21},{"title":"Serve","description":"Rest briefly to cool, and serve! A classic French side dish for Duck Confit is Lentil Ragout. (pictured in post)","images":[],"step":22}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","duck","iconic-dishes","mains","roasts","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3c19280c16c', 'en', 'US', 'Thai Glass Noodle Stir Fry (Pad Woon Sen)', 'Recipe video above. A big, family-size home-style Thai noodle stir fry using glass noodles, those thin clear noodles you probably bought by accident instead of rice vermicelli noodles and forgot about in the pantry - that''s me! Classic Thai flavours, savoury with a touch of sweet, with a nice hit of garlicky goodness. I chose vegetables that make this fast to make, but feel free to use what you want, just keep it to about 5 cups total. Soy sauce works fine if you don’t have MAGGI seasoning (every Thai household will have this though!). Adapted from this Pad Woon Sen on Hot Thai Kitchen. My recipe is scaled up, add-ins streamlined and sauce strength slightly tweaked to my palette.', 'https://www.recipetineats.com/tachyon/2026/03/Thai-Glass-Noodles-Pad-Woon-See_5.jpg', 15, 10, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.25, "unit": "carton of 12"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_maggi_seasoning", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["250g / 8 oz dried bean thread noodles (glass noodles), prepared per packet (Note 1)","2 tbsp canola oil (, or other neutral oil suitable for stir fries)","1/2 onion (, cut into thin wedges)","4 garlic cloves (, finely minced (knife or crusher is fine))","1 big bunch Chinese broccoli (gai lan), or choi sum","3 eggs (, whisked)"],"purpose":"Glass noodle stir fry:"},{"ingredients":["350g / 12 oz chicken thighs (, boneless and skinless, sliced into small 5mm / 0.2\" thin strips (Note 3))","2 tsp MAGGI seasoning (or light soy sauce (Note 4))","Pinch white pepper (substitute black pepper)"],"purpose":"Chicken:"},{"ingredients":["2 tbsp oyster sauce (or vegetarian oyster sauce)","1 tbsp fish sauce","1 tbsp MAGGI seasoning (, substitute light or all-purpose soy sauce (Note 4))","1 tbsp canola oil (, or other plain flavoured oil)","1 tsp white sugar","1/8 tsp white pepper (substitute black pepper)"],"purpose":"Sauce:"}]', '[{"description":"Mix sauce, toss chicken in Maggi. In 30cm/12\" pan, cook onion 15 sec, cook chicken ~ 2 min, adding Chinese broccoli stems and garlic towards end. Push everything to side, drizzle oil, scramble eggs, mix everything together. Add Chinese broccoli leaves, noodles, sauce, toss well. Serve!","images":[],"step":1},{"description":"Toss chicken with MAGGI and pepper. Set aside while you finish preparing everything else.","images":[],"step":2},{"description":"Mix the sauce ingredients in a small bowl. (It won''t seem enough for the volume of noodles but trust the process! It packs a ton of flavour.)","images":[],"step":3},{"title":"Cook chicken and onion","description":"Heat 2 tablespoons of the oil in a large 30cm/12\" non-stick pan over high heat until very hot (see Note 5 if your pan is smaller). Add onion and stir for 15 seconds. Add chicken and stir for 2 minutes until almost cooked through.","duration":0.25,"images":[],"step":4},{"description":"Add garlic and Chinese broccoli stems. Stir for 1 minute or until chicken is cooked.","duration":1,"images":[],"step":5},{"title":"Scramble eggs","description":"Push everything to one side of the pan, drizzle 1/2 tablespoon oil in the cleared space. Pour the eggs in and gently stir to scramble. When it''s almost cooked, toss through the chicken.","images":[],"step":6},{"title":"Leaves, noodles and sauce","description":"Add the Chinese broccoli leaves, noodles (on top, to weigh down) then pour the sauce all over the noodles. Use two spatulas to toss until the noodles are all stained with sauce and there''s no water in the pan.","images":[],"step":7},{"description":"Serve immediately!","images":[],"step":8}]', '["egg","fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","noodles","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_631884abba0c', 'en', 'US', 'Layered Golden Rice Bake with Spiced Meat', 'Recipe video above. This is essentially a streamlined version of Tachin, the iconic Middle Eastern saffron rice cake with its signature crispy crust, baked, then inverted like a pie. Here, I skip the flipping, use ingredients you can find at regular stores, and it''s a large format that serves 10 yet takes little more effort than Bolognese.The top gets crispy, the meat layered inside is fragrant with Middle Eastern spices, and the rice is vibrant yellow with the distinct perfume of saffron. If saffron threads are out of reach, use imitation powder instead. Though it won''t smell the same, you’ll still get vibrant yellow colour!PS. DO NOT SKIP THE LEMON YOGURT SAUCE! (Please, please🥰) See Note 5.', 'https://www.recipetineats.com/tachyon/2026/03/Golden-Saffron-Rice-Bake-with-Baharat-Spiced-Lamb_2.jpg', 30, 70, 100, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_baharat_spice_mix", "quantity": {"value": 0.007, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_cayenne", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_saffron_threads", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.004, "unit": "tub of 500g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_pine_nuts", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.012, "unit": "tub of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.03, "unit": "pack of 100g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","4 garlic cloves (, finely minced)","1 onion (, finely diced)","750g / 1 1/2 lb lamb mince (first choice), or beef (Note 1)","2 1/2 tbsp baharat spice mix (- store bought or make your own (Note 3))","2 tsp cumin powder","2 tsp cooking salt / kosher salt","1/2 tsp cayenne powder (, optional, for very subtle warmth)","3 tbsp tomato paste","1 small eggplant (, skin on, cut into 1cm / 0.4\" cubes, ~2 heaped cups (Note 2))","1 1/2 cups water"],"purpose":"Persian spiced meat filling:"},{"ingredients":["3 cups basmati rice (, uncooked)","1 tbsp cooking salt / kosher salt (, for rice cooking water)","1/2 tsp saffron threads (Note 4 for imitation powder, more cost effective)","2 tbsp boiling water","1 1/2 cups plain unsweetened yogurt (, full fat (regular, Greek or Greek-style))","2 large eggs (~55g/2oz each in-shell)","1/4 cup extra virgin olive oil","1 tsp cooking salt / kosher salt"],"purpose":"Golden rice:"},{"ingredients":["1/4 cup pine nuts (slivered or flaked almonds also great)","2 - 3 tbsp extra virgin olive oil (, for drizzling)"],"purpose":"Layering:"},{"ingredients":["3 batches Lemon Yogurt Sauce (YES 3 BATCHES!), or even plain yogurt or sour cream (Note 5)","2 tbsp coriander / cilantro roughly chopped (, optional garnish)","1 tbsp roughly chopped toasted pine nuts (, optional garnish)"],"purpose":"Serving:"}]', '[{"title":"Filling","description":"sauté onion and garlic, then cook lamb. Add spices, tomato paste then eggplant and water. Simmer 8 min until filling thickens. Saffron rice: grind saffron, soak in hot water. Mix with yogurt, oil, eggs and salt, mix in par boiled rice. Layer in pan with lamb, drizzle, bake 50 min until top is crispy. Slice and serve!","images":[],"step":1},{"description":"Preheat oven to 200°C/400°F (180°C fan-forced).","images":[],"step":2},{"title":"Toast pine nuts","description":"Heat a large non-stick pan (30cm/12\") over medium heat. Add pine nuts and toast for 1 minute, stirring constantly, until they have golden brown spots. Remove into a bowl and set aside.","duration":1,"images":[],"step":3},{"description":"Spiced lamb filling:","images":[],"step":4},{"title":"Cook meat","description":"In the same pan, heat the oil over high heat. Cook the onion and garlic for 1 1/2 minutes. Add lamb and cook, breaking it up as you go, for 5 minutes until you no longer see red.","duration":5,"images":[],"step":5},{"title":"Spices","description":"Add the baharat, cumin and salt. Cook for 1 minute, then stir in tomato paste. Add the eggplant and stir to coat in the flavours until you no longer see any white eggplant flesh.","duration":1,"images":[],"step":6},{"title":"Simmer","description":"Add the water and bring it to a rapid simmer. Lower heat to medium high, then simmer for 8 minutes, stirring regularly, until the filling is thick enough that you can draw a path across the pan and it holds in place. The eggplant should be mostly cooked through (cooks more in oven). It''s now ready for use (can use hot or or cool).","duration":8,"images":[],"step":7},{"title":"Soak saffron","description":"Grind the saffron mostly into a powder in a mortar and pestle (Note 4). Add hot water and leave for 5 minutes+ to soak.","duration":5,"images":[],"step":8},{"title":"Parboil rice","description":"Bring a large pot of water to the boil with the 1 tablespoon of salt. Add rice and boil for 5 minutes, stirring every now and then. Drain well in a colander. (The rice is only partially cooked, it finishes cooking in the oven).","duration":5,"images":[],"step":9},{"title":"Yogurt mixture","description":"Whisk together the yogurt, saffron water, oil, eggs and salt in a large bowl (or used rice boiling pot). Add rice and mix to combine - it will be pale yellow (becomes brighter once baked).","images":[],"step":10},{"description":"Assemble and bake:","images":[],"step":11},{"title":"Assemble","description":"Spread half the rice in a 23 x 33cm / 9 x 13\" dish. Spread over all the lamb mixture then sprinkle with pine nuts. Dollop remaining rice across the surface then spread.","images":[],"step":12},{"title":"Bake","description":"Drizzle over the extra virgin olive oil. Bake 50 minutes until the top is golden around the edges.","images":[],"step":13},{"description":"Rest 10 minutes in the pan then cut. Serve with Lemon Yogurt Sauce.","images":[],"step":14}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Persian"],"categories":["cuisines","dietary","gluten-free-recipes","middle-eastern-recipes","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2cbcdaa90dec', 'en', 'US', 'Thai red duck curry', 'Recipe video above. There''s something magical about the combination of rich duck meat and Thai red curry! This duck curry recipe features duck breast with golden skin that''s thickly sliced and served in a coconut red curry sauce. Add lychees or pineapples for a very special dish that''s to die for!Note: the duck skin doesn''t stay super crispy given the saucy environment it ends up in. I like to serve the duck with most of the skin above the sauce line so it doesn''t go completely soggy, though if that doesn''t bother you it''s also nice to stir the duck slices throughout the sauce. Your choice!', 'https://www.recipetineats.com/tachyon/2025/01/Thai-red-duck-curry_8.jpg', 15, 30, 45, 4, '[{"id": "ing_duck_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 115.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 7.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 0.24, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_ychees", "quantity": {"value": 10.0, "unit": "unit"}}, {"id": "ing_pineapple", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["500g/ 1 lb duck breasts (, boneless, skin on (3 pieces) (Note 1))","1/4 tsp cooking salt / kosher salt","1/4 tsp white pepper (sub finely ground black pepper)"],"purpose":"Crispy skin duck:"},{"ingredients":["115g/ 4 oz (1/2 cup) Thai red curry paste","2 large garlic cloves (, finely grated (Note 3))","2 tsp fresh ginger (, finely grated (Note 3))","1 cup chicken stock/broth (, low sodium)","400ml/ 14 oz coconut milk (, full fat (Note 4))","6 - 8 makrut lime leaves (, crushed in hand (Note 5))","2 tsp white sugar","2 tsp fish sauce","120g/ 4oz green beans (, trimmed and cut in half)","1 lightly packed cup Thai basil leaves (sub regular basil, Note 6)"],"purpose":"Thai red curry:"},{"ingredients":["8 - 12 lychees (, whole, peeled, seed removed. Fresh best, canned ok too! (Note 7))","1 1/4 cups pineapple pieces (, preferably fresh, canned ok (Note 7))"],"purpose":"Lychees or pineapple – CHOOSE ONE:"},{"ingredients":["Jasmine rice (cook 2 cups of raw rice)","Thai basil leaves (, extra)","Coriander/cilantro leaves/small sprigs (, optional)","Large red chilli (, finely sliced (optional))","Lime wedges (, recommended)"],"purpose":"For serving / garnish:"}]', '[{"description":"Slash duck skin, season. Cold pan, no oil, 10 min medium low (weigh down duck) until golden. Reserve 3 tbsp fat. Finish in oven 8 min (target 60°C/140°F, medium), rest. Sauté curry paste in duck fat with garlic and ginger, add stock, reduce by half, add coconut, fish sauce, sugar, lime leaves, simmer 2 min. Add beans, simmer 3 min, add lychees or pineapple, simmer 2 min. Slice duck, serve!","images":[],"step":1},{"description":"Crispy golden duck breast:","images":[],"step":2},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":3},{"title":"Score","description":"Sprinkle half the salt and pepper on the flesh of the duck. Turn. Use a sharp knife to make 5 or 6 diagonal scores on the skin of the breast. Don''t pierce the flesh and don''t cut all the way to the edge of the skin (Note 8). Pat the skin dry with paper towels, sprinkle with remaining salt and pepper.","images":[],"step":4},{"title":"Cold pan, no oil","description":"Don''t turn the stove on yet. Use an oven-proof pan (any type). Place the duck skin side down in the cold pan, no oil required. Place another pan on top to lightly weigh the duck down (keeps skin flat).","images":[],"step":5},{"title":"Cook 10 minutes","description":"Turn the stove onto medium low. Cook for 10 minutes or until the skin is golden and crispy. Fat will melt out of the duck skin and it will cook in its own fat. (Note 8)","duration":10,"images":[],"step":6},{"title":"Reserve duck fat","description":"Pour off 2 to 3 tablespoons of the duck fat into the pan you will use to make the curry sauce.","images":[],"step":7},{"title":"Oven 8 minutes","description":"Once the skin is crispy, turn and cook the flesh side for 1 minute. Then transfer the pan to the oven for 8 minutes or until the internal temperature is 60°C/140°F (medium, Note 9)","duration":1,"images":[],"step":8},{"title":"Rest","description":"Transfer to a rack or plate and rest for 5 minutes until ready to assemble the curry.","duration":5,"images":[],"step":9},{"description":"Thai red curry sauce:","images":[],"step":10},{"title":"Sauté curry paste","description":"Heat the duck fat (from step 6 above) on medium heat in a deep skillet. Cook the curry paste, garlic and ginger for 4 to 5 minutes. It will dry out and darken in colour, and substantially improves the flavour (especially store bought, but even homemade).","duration":4.5,"images":[],"step":11},{"title":"Sauce","description":"Add chicken stock, stir, then simmer rapidly to reduce by half (2 -3 minutes). Stir in coconut milk, hand-crushed kaffir lime leaves, sugar and fish sauce. Simmer gently on medium for 2 minutes.","duration":2,"images":[],"step":12},{"title":"Add ins","description":"Add the beans, simmer for 3 minutes until just cooked. Add the lychees or pineapple, simmer 1 minute. Taste and add a tad extra fish sauce if it needs salt.","duration":3,"images":[],"step":13},{"description":"Spoon some sauce in to cover the base of a large deep platter or wide bowl.","images":[],"step":14},{"description":"Slice duck breast, just shy of 5mm / 0.2\" thick. Place on the sauce, fanning it out slightly to expose the pink flesh.","images":[],"step":15},{"title":"Remaining sauce","description":"Spoon the remaining sauce, lychees etc around the duck, avoiding the duck skin.","images":[],"step":16},{"description":"Garnish with Thai basil leaves, coriander, chilli and lime wedges.","images":[],"step":17},{"title":"Serve","description":"Take to the table with flourish and serve with jasmine rice!","images":[],"step":18}]', '["fish"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","duck","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e9697f3f5416', 'en', 'US', 'Fall-apart massaman lamb shoulder', 'Recipe video above. Fall-apart succulent lamb smothered in a rich massaman curry sauce with melt-in-your-mouth potatoes that will take you 5 minutes to prepare. This larger-format version of Lamb Shanks Massaman Curry is made for groups: make up to 4 shoulders at once (serves 25 - 30!), reheats 110% perfectly (unlike lamb leg!), it looks impressive and a crowd pleaser. Plus it''s kid friendly because Massaman Curry isn''t spicy!', 'https://www.recipetineats.com/tachyon/2024/10/Massaman-lamb-shoulder_9a.jpg', 5, 270, 275, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.125, "unit": "kg"}}, {"id": "ing_maesri_massaman_curry_paste", "quantity": {"value": 114.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_star_anise", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2-2.25kg/ 4 - 4.5 lb lamb shoulder (, bone in, excess fat trimmed (but leave thin fat layer on (Note 1))","114g/ 4oz (1/2 cup) Maesri Massaman curry paste (1 can) (, or other brand (Note 2))","400g/ 14 oz can coconut milk (, full fat (Note 3))","3 cups chicken stock/broth (, low sodium)","1 onion (, halved then cut into 1 cm / 1/2\" thick wedges)","2 cinnamon sticks (or 1/2 tsp powder)","2 star anise (won''t ruin if you don''t have this)","600g/ 1.2 lb small baby potatoes (, whole (don''t cut cubes, Note 4))"]},{"ingredients":["2 large red chillis (, finely sliced diagonally (optional))","1 cup (lightly packed) coriander leaves & sprigs (cilantro) (, highly recommended)","Jasmine rice (basmati also excellent)"],"purpose":"Garnishes / serving:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Whisk curry, coconut and stock, put lamb in upside down. Add spices and potatoes, foil cover, roast 1 hour at 220°C/425°F (200°C fan), 3 hours 180°C/350°F (160°C fan) or until fall-apart. Uncover, turn lamb, 30 minutes. Garnish, serve!","images":[],"step":2},{"description":"Full recipe steps:","images":[],"step":3},{"description":"Preheat the oven to 220°C/425°F (200°C fan-forced).","images":[],"step":4},{"description":"Whisk the curry paste, coconut milk and chicken stock in a pan until lump free. Put lamb shoulder in, turn to coat in the sauce then place it so it''s upside down (ie meaty / fat side down).","images":[],"step":5},{"description":"Place the onion, cinnamon sticks, star anise and potatoes around the lamb. Cover with foil.","images":[],"step":6},{"title":"Slow-cook","description":"Roast for 1 hour. LOWER the oven to 180°C/350°F (160°C fan) then roast for a further 3 hours. (Note 5)","images":[],"step":7},{"title":"Check","description":"Remove foil and use forks to check the meat is virtually “fall-apart-tender”, it should be by this time. If not, cover and keep cooking.","images":[],"step":8},{"title":"Brown","description":"Turn the lamb over, spoon over sauce. Bake uncovered 30 minutes or until deep golden. (Note 6 for sauce adjustments)","images":[],"step":9},{"title":"Serve","description":"Rest for 10 - 15 minutes. Spoon off as much or as little excess fat off surface, discard. Mix sauce well (it''s quite runny, if it was thicker it''d be too rich). Transfer to a serving dish, if you like, sprinkle with chilli and coriander. Serve! (Note 7 for serving styles)","duration":12.5,"images":[],"step":10}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai-ish"],"categories":["cuisines","curry-recipes","iconic-dishes","lamb-recipes","main-dishes","mains","roast-lamb","roasts","stews","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_713940c7c1c2', 'en', 'US', 'Tray bake dinner: lamb kofta meatballs', 'Recipe video above. This easy sheet pan dinner combines beautifully spiced lamb kofta meatballs with colourful roast vegetables for a Middle Eastern dinner that''s as versatile as it is delicious. Stuff into warm flatbreads, serve with couscous or rice bowls, or add a side of roasted cauliflower for a substantial low-carb dinner.Less messy and healthier than pan frying - less oil! Tip: make meatballs on the large side so they don''t dry out in the oven.', 'https://www.recipetineats.com/tachyon/2024/03/Baked-lamb-kofta-meatballs_2.jpg', 20, 20, 40, 4, '[{"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_round_cinnamon", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.007, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.001, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_quantity_tahini_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 onion (, grated using a box grater)","500 g / 1 lb lamb mince ((ground lamb), or beef)","1/4 cup panko breadcrumbs (sub regular breadcrumbs)","2 cloves garlic (, finely minced)","2 tbsp coriander/cilantro (, finely chopped)"],"purpose":"KOFTAS"},{"ingredients":["2 tsp cumin","2 tsp coriander","2 tsp paprika (plain, sub smoked)","1 1/2 tsp ground cinnamon","3/4 tsp cayenne pepper (a bit spicy, reduce to taste or leave out)","3/4 tsp cooking salt / kosher salt","1/2 black pepper"],"purpose":"KOFTA SPICES"},{"ingredients":["1 large red capsicum (, deseeded, sliced into 1 cm thick slices)","1 large yellow capsicum (, deseeded, sliced into 1 cm thick slices)","1 red onion (, cut into thin wedges)","1 tbsp extra virgin olive oil","1/4 tsp each cooking/kosher salt and pepper"],"purpose":"VEGETABLES"},{"ingredients":["1 quantity Tahini sauce","1 quantity Lemon Yogurt Sauce (or even just plain yogurt)"],"purpose":"SAUCE OPTIONS (Choose one):"},{"ingredients":["Olive oil spray (for the meatballs)","4 flatbreads (or rice, couscous or cauliflower rice)","3 cups shredded iceberg lettuce (or other leafy greens)","2 tomatoes (, halved, cut into thin slices)","1 tbsp coriander/cilantro leaves (, finely chopped, optional (for sprinkling))"],"purpose":"SERVING (wraps option)"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan-forced).","images":[],"step":1},{"title":"Kofta meatballs","description":"Place the Kofta ingredients and spices in a bowl. Use your hands to combine thoroughly then roll 16 large-ish meatballs (I scoop all mixture onto a tray, then roll into balls). Spread them out on a large tray.","images":[],"step":2},{"title":"Vegetables","description":"Toss the vegetables with the oil, salt and pepper. Scatter around the meatballs.","images":[],"step":3},{"title":"Bake","description":"Spray the meatballs with oil. Bake for 15 minutes then switch the oven to the grill/broiler on high. Cook for a further 5 minutes to get some colour on the surface.","duration":15,"images":[],"step":4},{"title":"Serve","description":"Sprinkle with the chopped coriander then serve! To make wraps, stuff with lettuce, tomato, meatballs, and the cook capsicum and onion. Drizzle with lots of tahini sauce or Lemon Yogurt Sauce then tuck in! Other ideas: rice or couscous bowls or big salads - see below.","images":[],"step":5}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["cuisines","lamb-recipes","meatball-recipes","middle-eastern-recipes","one-pot-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1431fc0ca79d', 'en', 'US', 'Panang Curry - real, from scratch', 'Recipe video above. This is a stunning Panang Curry made entirely from scratch. It''s for people who adore real Thai food, can handle the heat and understand that you just can''t replicate the fresh flavour of a real Penang Curry using paste from a jar! Not even using my favourite Maesri curry paste that I''ll happily use for Thai Red and Green Curry.It calls for a trip to the Asian store but once you have the ingredients, it''s straightforward to make. See SPICINESS note in notes section below - yep, it''s spicy, and it can''t be avoided!', 'https://www.recipetineats.com/tachyon/2023/08/Panang-curry-prawn_8-close-up.jpg', 30, 30, 60, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_roasted_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_lemongrass", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_eschalots", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_galangal_note_5", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.01, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_oil", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_cream", "quantity": {"value": 0.008, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 0.4, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 13.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["700g/ 1.4 lb whole raw prawns/shrimp ((ie shell on), medium ~8cm / 3\"long - Note 1)","350g / 12 oz boneless, skinless chicken thighs (, cut into 7mm/ 1/3\" slices)"],"purpose":"Protein – choose ONE:"},{"ingredients":["1 1/2 cups chicken stock/broth (, low-sodium (not fish/seafood - Note 2))"],"purpose":"For prawn stock (shrimp):"},{"ingredients":["2/3 cup dried Chinese chillies (not Thai!) ((24 x 6cm/2.5\" long, 1/2 cup (15g) once deseeded chopped) - Note 3)","3 tbsp roasted peanuts unsalted","2 lemongrass stems (, finely grated (2 x 20cm/8\" lengths) - Note 4)","2 eschalots (, roughly chopped (1/2 cup))","1 tbsp galangal, finely grated ((~1.5cm / 0.6\" piece) - Note 5)","5 garlic cloves (, finely minced)","1 1/2 tbsp shrimp paste in bean oil ( - Note 6)","1/2 tsp each ground coriander, cumin, nutmeg","1 tbsp (packed) finely sliced kaffir lime leaves ( (~ 6 leaves) - Note 7)"],"purpose":"Curry paste:"},{"ingredients":["3 tbsp canola oil","1 1/4 cups coconut cream (, full-fat (standard Aus 270ml small can ok))","3 1/2 tsp white sugar","4 1/2 tsp fish sauce","1/4 tsp cooking/kosher salt","200g/7oz green beans (, trimmed, cut in half (~1 1/2 cups))","12 Thai basil leaves ( - Note 8)"],"purpose":"Curry:"},{"ingredients":["Jasmin rice","2 tbsp unsalted peanuts (, finely chopped)","Red cayenne peppers (, finely sliced (optional))","Thai basil leaves (, 3 leaves per serving - Note 8)"],"purpose":"SERVING and GARNISHES"}]', '[{"title":"Simmer","description":"Peel and devein prawns, reserving heads and shells. Bring chicken stock to a simmer in a small pot on high heat. Add prawn heads & shells, bring back to a simmer, then reduce to low heat. Simmer uncovered for 15 minutes, periodically crushing the heads lightly with a potato masher and skimming off any orange scum.","duration":15,"images":[],"step":1},{"description":"Strain into a jug, discarding heads. You should have just over 300 ml (1 1/4 cups) of stock. Leave undisturbed to let the sediment settle (~ 5min+).","images":[],"step":2},{"description":"Cut chillies in half then tap / squeeze out seeds (use a chopstick if needed for stubborn seeds). Discard seeds (spicy!). Chop chilli.","images":[],"step":3},{"description":"Soak dried chillis in 2 cups of boiling water for 30 minutes. Drain in a colander, reserve soaking liquid.","duration":30,"images":[],"step":4},{"title":"Peanuts","description":"Put peanuts in a tall jar that comfortably fits the head of a stick blender (or use a small blender). Cover the jar opening with your hand and pulse until finely ground.","images":[],"step":5},{"title":"Blitz paste","description":"Add drained chillis and remaining Curry Paste ingredients, along with 1/4 cup of the reserved chilli soaking liquid. Blend, scraping down the sides as you go, for about 30 seconds until smooth, using extra chilli water only if needed to help blend.","images":[],"step":6},{"description":"Cooking:","images":[],"step":7},{"title":"Cook curry paste","description":"Heat oil in a large deep frying pan over medium-low heat. Cook curry paste for 5 minutes, stirring constantly. The paste should be drier, darker, smelling aromatic and no longer raw.","duration":5,"images":[],"step":8},{"title":"Sauce","description":"Add 1 cup (250 ml) prawn stock, being careful to pour off just the clearer liquid and leaving the sediment behind. Stir in the coconut cream, sugar, fish sauce and salt. Mix in the green beans.","images":[],"step":9},{"description":"Simmer for 2 minutes until the sauce thickens and the beans are half cooked.","duration":2,"images":[],"step":10},{"description":"Add prawns, stir, then simmer for another 2 minutes until the prawns are cooked. Stir in the Thai basil leaves. The final taste should lean mostly savoury and sweet, and medium spiciness.","images":[],"step":11},{"description":"Serve over jasmine rice garnished with chopped peanuts, chilli and more Thai basil leaves!","images":[],"step":12}]', '["fish","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","prawns-shrimp","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_640c9bf238ad', 'en', 'US', 'Moroccan Lamb Meatballs', 'Recipe video above. The fragrance when these meatballs are cooking is outrageous! These meatballs are based on my fan-favourite Lamb Koftas, flavoured with a special blend of spices that smells so exotic but are everyday pantry staples!The Minted Yoghurt is fabulous - pairs so well with the flavour of these meatballs. See notes for suggestions for more sides - pictured in post stuffed in pita pockets.', 'https://www.recipetineats.com/tachyon/2017/07/Moroccan-lamb-meatballs_2.jpg', 25, 10, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.006, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 5.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_red_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil (for cooking)"]},{"ingredients":["500 g / 1 lb lamb mince (ground lamb) (Note 1)","1 small onion (, grated using box grater (~1/2 cup, including juices, Note 2))","1/2 cup panko breadcrumbs (sub ordinary)","1 egg","2 cloves garlic, crushed","1/4 cup coriander/cilantro leaves (, finely chopped)","1 1/2 tsp EACH cumin, coriander, paprika (any, but I like smoked paprika)","1/2 tsp EACH cinnamon, cayenne pepper (add more for spicy)","1 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Meatballs:"},{"ingredients":["3/4 cup plain yoghurt (I use Greek)","1/2 cup (tightly packed) mint leaves","2 tsp lemon juice","1/4 tsp cooking/kosher salt"],"purpose":"Minted Yoghurt Sauce (Note 3):"},{"ingredients":["4 pita pockets (, Lebanese or pita bread)","5 cups shredded lettuce (iceberg, cost/romaine)","2 tomatoes (, halved, thinly sliced)","1 red onion (, halved, finely sliced)","OR Shredded Red Cabbage, Carrot and Mint Salad (instead of lettuce, tomato and onion)","Extra coriander/cilantro leaves, (finely chopped (optional))"],"purpose":"To Serve as pockets:"}]', '[{"title":"Mint yogurt sauce","description":"Set aside 1/2 cup yogurt. Place all other ingredients in a jug that fits the head of a stick blender. Blitz until it turns green - it will be runny. Stir in reserved yogurt (this thickens it again). Refrigerate until required.","images":[],"step":1},{"title":"Meatballs","description":"Place all Meatball ingredients in a bowl. Mix well with your hands. Measure out 1 heaped tablespoon, then roll into balls. Repeat with remaining mixture - should have 20 - 24 meatballs.","images":[],"step":2},{"title":"Cook","description":"Heat oil in a large non stick pan over medium heat. Add half the meatballs and cook, turning to brown all over, for 8 minutes, or until cooked through. Transfer to plate. (Oven option - Note 4)","duration":8,"images":[],"step":3},{"title":"Serving","description":"Cut pita pockets in half, warm for 10 seconds in the microwave, then pry it open. Stuff with lettuce, tomato, onion, then meatballs (I do 2 per half pocket). Drizzle with Mint Yogurt Sauce and fresh coriander.","duration":0.16666666666666666,"images":[],"step":4}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Moroccan"],"categories":["cuisines","dinner-tonight","lamb-recipes","main-dishes","meatball-recipes","middle-eastern-recipes","moroccan","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7b181e442b60', 'en', 'US', 'Thai Yellow Curry (from scratch!)', 'Recipe video above. Thai curries are famous for the sublime aromatic flavours balancing sweet, tart, savoury and spiciness. Thai Yellow Curry is one such magnificent example, with its rich yellow colour, incredible depth of flavour and a heady combination of both fresh and ground herbs and spices.This is made from scratch with a homemade Yellow Curry Paste. There are quite a few ingredients involved but if you truly want the best, it''s worth it!This is a creation the RecipeTin Team is proud to call our own - we worked damn hard on it! (Then we celebrated by making another 100 as the first meals we donated through RecipeTin Meals ❤️)SPICINESS: Adjust by varying fresh chilli. Use 1 for extremely mild, 2 for quite mild, 4 for spicy (but not blow-your-head off).', 'https://www.recipetineats.com/tachyon/2021/08/Thai-Yellow-Curry_26a.jpg', 30, 30, 60, 4, '[{"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 2.5, "unit": "pack of 100g"}}, {"id": "ing_lemongrass", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_eschalots", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_galangal", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 8.0, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_fenugreek_powder", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.2, "unit": "carton of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 0.04, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_bamboo_shoots", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 16.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["10 dried red chillis (~6cm/2.5\" long), chopped into 1cm / 0.5\" pieces (Note 1)","1 - 4 fresh birds eye chillis (, deseeded, roughly (1 for extremely mild, 4 for fairly spicy, Note 2))","2 lemongrass stems (Note 3)","1 large or 2 small eschalots (, roughly chopped (~ 1/2 cup) (Note 4))","2 tbsp fresh turmeric (, finely grated (about 2cm / 0.8\" piece) (Note 5))","2 tbsp galangal (, finely grated (about 2cm / 0.8\" piece) (Note 6))","8 cloves garlic (, roughly chopped)","1 1/2 tbsp Thai shrimp paste in bean oil (Note 7)","1 tsp ground coriander","1 tsp ground cumin","1/4 tsp ground cardamom","1/2 tsp fenugreek powder (Note 8)","1/8 tsp white pepper (sub black)"],"purpose":"Thai Yellow Curry Paste:"},{"ingredients":["3 tbsp vegetable oil (or canola or peanut oil)","1 medium potato (, peeled, cut into 2.5cm / 1\" pieces x 1cm/ 0.4\" thick (Note 9))","1 small carrot (, peeled, sliced into 5mm / 0.2\" slices on the diagonal)","1 cup chicken stock (, low sodium)","300 ml / 10oz coconut cream (Note 10)","4 tsp fish sauce (, plus more to taste (Note 11))","5 tsp white sugar","2 tsp tamarind puree (Note 12)","350g / 12oz prawns/shrimp (, medium, peeled, tail on optional (700g/1.4lb unpeeled) (Note 13))","1/2 cup bamboo shoots (, canned, drained, loosely packed (Note 14))"],"purpose":"Curry:"},{"ingredients":["16 Thai basil leaves (highly recommended, Note 15)","1 Red chilli (, finely sliced (optional, use large for not spicy))","2 tbsp Crispy fried shallots (optional, store bought, Note 16)","Jasmine rice"],"purpose":"Garnishes & serving:"}]', '[{"title":"Soak dried chillis","description":"Roughly chop chillies and transfer to bowl, leaving behind seeds. Cover with boiling water and soak for 30 minutes then drain (reserve soaking water).","duration":30,"images":[],"step":1},{"title":"Check spiciness","description":"Have a nibble of soaked chilli, should not be that spicy. If it is spicy, only use 1/3 to 1/2 of the amount (Note 1).","images":[],"step":2},{"title":"Prepare lemongrass","description":"Remove woody top half and outer layers of lemongrass. Grate with microplane. (See in post or video for preparation demo)","images":[],"step":3},{"title":"Make curry paste","description":"Place chillis, lemongrass and all remaining curry paste ingredients in a jar just wide enough to fit a stick blender. Add 3 tablespoons chilli soaking water. Blitz with stick blender until smooth so there''s no hard grit - rub between your fingers to check - about 15 seconds on high. (Or use small food processor or Nutribullet, scraping down sides well).","images":[],"step":4},{"title":"Cook off curry paste","description":"Heat oil in a medium heavy based skillet over medium heat. (Mine is a 26cm / 10.5\" Lodget cast iron) Add curry paste and cook for 3 to 4 minutes until it dries out a bit a smells fragrant.","duration":3.5,"images":[],"step":5},{"title":"Reduce stock","description":"Add chicken stock, stir to dissolve paste, then simmer for 1 minute.","duration":1,"images":[],"step":6},{"description":"Cook curry:","images":[],"step":7},{"title":"Add remaining curry sauce ingredients","description":"Reduce heat to medium low. Add tamarind, fish sauce and sugar. Stir until tamarind is dissolved. Then stir in coconut, carrot and potato.","images":[],"step":8},{"title":"Simmer","description":"Bring to simmer, then simmer gently for 15 minutes or until potato is almost fully soft. Pierce with knife to check, it might take 20 minutes.","duration":15,"images":[],"step":9},{"title":"Prawns and bamboo shoots","description":"Add prawns and bamboo shoots. Stir, then cook for 3 minutes until prawns are just cooked.","duration":3,"images":[],"step":10},{"title":"ADJUST sauce","description":"Taste and adjust the curry sauce at this point. Thin sauce with stock or water, add salt, fish sauce or sugar if needed. See Note 17.","images":[],"step":11},{"description":"Serve! Transfer curry to serving bowl. Garnish with Thai Basil, fresh chilli and crispy shallots. Serve with jasmine rice.","images":[],"step":12}]', '["fish","peanuts","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f949117e775', 'en', 'US', 'Vegetable Tagine', 'Recipe video above. A vegetarian Moroccan stew loaded with heady and warm spices, filled with tender vegetables. Make this with any veg you have - just don''t skimp on the spices!!Pan-roasting each vegetable to get a bit of colour on them before simmering is worth the effort to get the most flavour out of the vegetables. Because colour = flavour! Serve with couscous.', 'https://www.recipetineats.com/tachyon/2021/01/Vegetable-Tagine_3.jpg', 30, 60, 90, 8, '[{"id": "ing_cardamom_powder", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_round_fennel_seeds_fennel_powder", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_cayenne", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 0.025, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_60z_green_beans", "quantity": {"value": 0.4, "unit": "pack"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_almonds", "quantity": {"value": 1.0, "unit": "pack of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1 tbsp cardamom powder","1 tbsp coriander powder","1 tbsp cumin powder","1 1/2 tsp ground fennel seeds / fennel powder","1 tsp cayenne (omit for non-spicy)","2 tsp turmeric","1/4 tsp ground cloves","1/4 tsp ground ginger"],"purpose":"Tagine spice mix:"},{"ingredients":["5 tbsp olive oil","1/2 red onion (sliced; (sub any type of onion))","1 garlic clove (, finely minced)","800g/1.6lb butternut pumpkin / squash ((1/2 a small), peeled, cut into 2.5cm / 1\" cubes)","1 small eggplant (, cut into 2.5cm / 1/2\" cubes)","1/2 cauliflower head (, small, cut into bite size florets)","1 capsicum / bell pepper (, cut into 2.5cm / 1\" pieces (red or yellow))","2 tomatoes (, seeds removed, cut into 1cm / 1/3\" dice)","3 1/2 cups water","2 tsp salt","1/2 tsp black pepper","400g/ 14oz canned chickpeas (, drained)","200g / 60z green beans (, cut into 3.5cm / 1.5\" pieces (~2 cups cut))","Zest of 1 lemon","2 tbsp lemon juice"],"purpose":"Tagine (Note 1):"},{"ingredients":["1/2 cup slivered almonds (, toasted)","1/4 cup coriander / cilantro (, roughly chopped)","Plain yogurt","Pinch of paprika or cayenne pepper"],"purpose":"Garnishes / for serving:"}]', '[{"description":"Combine Tagine Spice Mix ingredients.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large, heavy-based pot over medium high heat. Add garlic and onion, cook until onion is wilted (~ 1 1/2 minutes), then remove to a large bowl. Scrape out any remaining garlic bits from pan (so they don''t burn).","images":[],"step":3},{"description":"Add pumpkin / squash and cook, stirring, for 3 minutes or until lightly golden on most sides. Remove to same bowl.","duration":3,"images":[],"step":4},{"description":"Add 2 tbsp olive oil. Cook eggplant for 3 minutes until tinged with gold on most sides, remove to same bowl.","duration":3,"images":[],"step":5},{"description":"Add 1 tbsp oil if pot is looking dry. Add capsicum and cauliflower, cook for 2 minutes until the cauliflower is a bit golden on the edges. Remove into bowl.","duration":2,"images":[],"step":6},{"description":"Add tomato and cook for 1 minute. Add Spice Mix, stir for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add all vegetables back to pot. Add water (it should just about cover the vegetables, they will sink), salt and pepper. Stir, bring to simmer on stove, then transfer to oven for 30 minutes. (Alternatively simmer on low stove, but stir gently otherwise veg may breakdown too much.)","duration":30,"images":[],"step":8},{"description":"Remove from oven, add beans and chickpeas. Simmer for 15 minutes uncovered on stove on medium-low to cook the beans and reduce the sauce.","duration":15,"images":[],"step":9},{"description":"Stir through lemon juice and zest. The idea here is that some of the veg (butternut, cauliflower) breaks down a bit to slightly thicken the sauce. It also gets thicker left overnight.","images":[],"step":10},{"description":"For a traditional experience, serve over couscous. Otherwise, try white, brown, or basmati rice, or quinoa. Or, serve just as is like a chunky stew. For a low-carb option try cauliflower rice! I like to top mine with a dollop of yogurt, a sprinkle of almonds, coriander/cilantro and a pinch of paprika or cayenne.","images":[],"step":11}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Moroccan"],"categories":["cuisines","dietary","gluten-free-recipes","low-calorie-recipes","middle-eastern-recipes","moroccan","stews","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a8ea660f762', 'en', 'US', 'Lamb Shanks Massaman Curry', 'Recipe video above. Epic combination - fall apart lamb shanks in a rich massaman curry sauce, a wildy popular dish at upscale Thai restaurants! The coconut and spice infused flavour of the curry sauce is a dead set perfect match with the flavour of lamb meat. Don''t be fooled by the simplicty of this recipe - hours in the oven works magic. (Read in post if you are dubious!)SPICINESS - mild! Massaman curry is one of the mildest curries in Thai cuisine.', 'https://www.recipetineats.com/tachyon/2020/06/Lamb-Shanks-Massaman-Curry_0.jpg', 5, 180, 185, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_maesri_massaman_curry_paste", "quantity": {"value": 114.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 400.0, "unit": "bag of 2kg"}}, {"id": "ing_star_anise", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1.5kg/ 3 lb lamb shanks (5 small, 4 medium, 2 - 3 large) (Note 1)","114g/ 4oz Maesri Massaman curry paste (1 can) (, or other brand (Note 2))","400ml/ 14oz coconut milk (, full fat (Ayam brand is best, Note 3))","2 cups chicken stock/broth (, low sodium (Note 4))","1 onion (, halved then sliced 1cm / 1/3\" thick (brown, white, yellow))","400g/ 14oz small potatoes (2.5cm/1\" wide, halve if bigger)","1 star anise","1 cinnamon stick"]},{"ingredients":["Red chilli (, finely sliced (small = spicy, large = less spicy))","Coriander/cilantro","Steamed jasmine rice"],"purpose":"Garnishes:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Mix curry paste, coconut milk and stock in a 22 x 33cm / 9 x 13\" baking dish, preferably glass or ceramic (Note 5). Add onion, potato, star anise, cinnamon and lamb.","images":[],"step":2},{"description":"Turn shanks to coat in sauce, then cover with foil.","images":[],"step":3},{"description":"Bake in oven for 2 hours. Remove foil, bake for a further 1 hour (small shanks) or 1.5 hrs (medium to large shanks), turning lamb twice to brown evenly, until meat is so tender it can easily be teased apart with 2 forks.","images":[],"step":4},{"description":"Remove lamb onto plate. Carefully skim off excess fat off the surface (tilt dish, it''s easier) - I get about 1/3 cup. Mix sauce in baking dish - it should be reduced down to a syrupy thickness (Note 6).","images":[],"step":5},{"description":"Serve lamb with sauce over jasmine rice, garnished with chilli and coriander. For a larger banquet, put the curry out on a platter to share!","images":[],"step":6}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Modern Asian","Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","lamb-recipes","lamb-shanks","slow-cooked-fall-apart","stews","sunday-supper","thai-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b357ff850d2b', 'en', 'US', 'Thai Green Curry', 'Recipe video above. This is how to make a really great QUICK green curry by pimping up curry in a jar, OR using a homemade green curry paste! Don''t skip frying off the curry paste, this makes all the difference. See Spiciness info in Note 1 (remember, Green Curry is supposed to be spicy!)', 'https://www.recipetineats.com/tachyon/2019/02/Thai-Green-Curry_5.jpg', 15, 20, 35, 4, '[{"id": "ing_thai_red_curry_paste", "quantity": {"value": 0.3, "unit": "bottle"}}, {"id": "ing_quantity_homemade_green_curry_paste", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_snow_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_basil", "quantity": {"value": 16.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 - 6 tbsp Thai Green Curry Paste (Maesri best) OR (Note 1)","1 quantity homemade green curry paste (Note 1)"],"purpose":"Curry – use ONE:"},{"ingredients":["2 large garlic cloves (, minced)","2 tsp fresh ginger (, finely grated)","1 tbsp lemongrass paste (Note 2)"],"purpose":"Extras – for jar curry paste (Note 2):"},{"ingredients":["2 tbsp vegetable oil","1 cup (250ml) chicken or vegetable broth, low sodium","400 g/14oz coconut milk (, full fat (Note 4))","1 - 3 tsp fish sauce *","1 - 3 tsp white sugar *","1/8 tsp salt *","6 kaffir lime leaves (, torn in half (Note 5))","350 g/12 oz chicken thigh (, skinless boneless, sliced (Note 6))","2 Japanese eggplants, (, small, 1cm / 2/5\" slices (Note 7))","1 1/2 cups snow peas (, small, trimmed)","16 Thai basil leaves (Note 8)","Juice of 1/2 lime (, to taste)"],"purpose":"Green Curry:"},{"ingredients":["Crispy fried Asian shallots (, high recommended (Note 9))","Thai basil or cilantro/coriander (, recommended)","Green or red chillies slices (, optional)","Steamed jasmine rice"],"purpose":"Garnishes:"}]', '[{"description":"Heat oil in a heavy based skillet or pot over medium high heat.","images":[],"step":1},{"description":"Add curry paste (and garlic, ginger and lemongrass Extras, if using) and cook for 2 to 3 minutes until it mostly \"dries out\" - see video. Don''t breath in the fumes!!","duration":2.5,"images":[],"step":2},{"description":"Add chicken broth and coconut milk, mix to dissolve paste.","images":[],"step":3},{"title":"Curry in a jar seasonings","description":"Add 1 tsp fish sauce, 1 tsp sugar, no salt.","images":[],"step":4},{"title":"Homemade curry paste seasonings","description":"Add 3 tsp fish sauce, 3 tsp sugar, 1/8 tsp salt.","images":[],"step":5},{"description":"Add kaffir lime leaves. Mix then bring to simmer.","images":[],"step":6},{"description":"Add chicken, stir then lower heat to medium so it''s bubbling gently. Cook 7 minutes.","images":[],"step":7},{"description":"Add eggplants, cook 5 minutes until soft.","images":[],"step":8},{"description":"Taste sauce. Add fish sauce or salt for more saltiness, sugar for sweetness.","images":[],"step":9},{"description":"Add snow peas, cook 2 minutes until a bit softened, then stir through basil and lime juice. Sauce should have reduced but will still be a be on the thin side, not thick - that''s how it''s should be. DO NOT keep simmering - sauce will darken.","images":[],"step":10},{"description":"Serve curry over jasmine rice with garnishes of choice.","images":[],"step":11}]', '["fish"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_911abc5e0cf9', 'en', 'US', 'Middle Eastern Shredded Lamb', 'I can''t say with certainty that this is authentic because it''s a recipe I created. But it uses classic Middle Eastern ingredients, so possibly it is! The lamb is really juicy because it''s made with lamb shoulder, a cut that is made for slow cooking. The pan frying step to get the crunchy brown bits is not optional - it''s key! ! ! As with any shredded meat recipe, a little goes a long way. This makes around 8 cups of shredded lamb which I think is enough to serve 8 people as a main (with rice). See separate recipe below for Chickpea Pilaf (Rice).', 'https://www.recipetineats.com/tachyon/2015/05/Middle-Eastern-Shredded-Lamb-Chickpea-Pilaf-Rice-1.jpg', 10, 210, 220, 8, '[{"id": "ing_cumin", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_cardamon", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.068, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_lamb", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[]', '[{"description":"Preheat oven to 150C/300F.","images":[],"step":1},{"description":"Combine the Spice Mix ingredients in a small bowl. Set aside 1 1/2 tbsp of the Spice Mix for later (to pan fry the lamb).","images":[],"step":2},{"description":"Add the olive oil and garlic into the Spice Mix, then rub all over the lamb.","images":[],"step":3},{"description":"Place the lamb on a roasting rack set in a roasting dish (Note 1). Pour the water in the base of the dish. Cover with a lid or double layer of foil.","images":[],"step":4},{"description":"Roast for 3 1/2 hours or until the meat is tender enough to pull off with a fork.","images":[],"step":5},{"description":"Remove the lid. Turn the oven up as high as it will go and roast for 15 - 20 minutes until the lamb is browned.","duration":17.5,"images":[],"step":6},{"description":"Remove the lamb from the oven. Allow to rest for 20 minutes, then shred coarsely with two forks.","duration":20,"images":[],"step":7},{"description":"Skim excess fat off the juices in the roasting dish then set aside. (Note 2)","images":[],"step":8},{"description":"Browning the Shredded Lamb","images":[],"step":9},{"description":"Toss the shredded lamb with the reserved Spice Mix (from Step 2 above).","images":[],"step":10},{"description":"Heat 1 tbsp of oil in a heavy based pan over high heat. Add some lamb (don''t crowd the pan) and drizzle over about 3 tbsp of the pan juices. Cook until the underside is dark golden brown and crispy - about 1 to 1 1/2 minutes (the juices you poured over will evaporate).","images":[],"step":11},{"description":"If the lamb is cold, flip to warm the other side but do not brown too much (retains juiciness).","images":[],"step":12},{"description":"Remove lamb from the fry pan, and repeat with remaining lamb, adding extra oil if required.","images":[],"step":13},{"description":"To serve, drizzle with a squeeze of lemon juice (this makes a big difference) and top with fresh coriander, plus yoghurt (if using). Serve on Chickpea Pilaf (Rice).","images":[],"step":14}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Easter / Moroccan"],"categories":["cuisines","dietary","gluten-free-recipes","lamb-recipes","main-dishes","middle-eastern-recipes","rice-recipes","side-dishes","slow-cooker-recipes","sunday-supper","uncategorized","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_76db1d8792e7', 'en', 'US', 'Melting Afghan chickpea curry', 'Recipe video above. I never knew chickpeas could be so meltingly creamy by adding a smidge of baking soda! I also love how the sauce is thickened by cooking lentils until they breakdown, two neat tricks picked up from this Pakistani Lahori Chanay by Sugar Spice & More. Combined with an Afghan spice mix from the chickpea curry in Parwana, a wonderful Afghan cookbook by Durkhanai Ayubi, adapted in pursuit of recreating the chickpea curry I had from Afghan Sufra in Lakemba, an area of Sydney known for its wonderful Middle Eastern and sub-continental food scene. I’m obsessed!', 'https://www.recipetineats.com/tachyon/2025/05/Afghani-Chickpea-Curry_0.jpg', 15, 45, 60, 5, '[{"id": "ing_ghee", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lentils", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 0.007, "unit": "can of 400g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.005, "unit": "tub of 200g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.007, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp ghee (, substitute unsalted butter or coconut oil (for vegan))","2 cinnamon sticks (sub 1/2 tsp powder, add with other spices)","1 onion (, finely chopped)","1 1/2 tbsp grated ginger","1 1/2 tbsp grated garlic","2 bay leaves (, preferably fresh else dried)","1/2 cup dried red split lentils (Note 1)","1 cup water","1 litre vegetable stock (, low sodium)","1/2 tsp cooking / kosher salt","3 x 400g/14oz cans chickpeas (, drained (Note 2))","1/4 tsp baking soda / bi-carbonate soda (makes chickpeas creamy, optional)"]},{"ingredients":["1 tbsp coriander powder","1 tbsp cumin powder","1 1/2 tsp turmeric powder","3/4 tsp cardamom powder","1/4 tsp ground cloves"],"purpose":"Spices (Note 3):"},{"ingredients":["Basmati rice (and/or Afghan bread (Note 4), or other flatbread)","Yogurt (I like to slightly thin with water so it can be drizzled)","Fresh coriander / cilantro leaves (, roughly chopped)"],"purpose":"Serving:"}]', '[{"title":"Sauté","description":"Melt the ghee in a large pot over medium high heat. Add the cinnamon and toast for 30 seconds. Add the onion, ginger, garlic and bay leaves. Cook for 3 minutes until the onion is translucent (stir regularly so the garlic & ginger don''t catch).","duration":0.5,"images":[],"step":1},{"title":"Spices and lentils","description":"Add the Spices and stir for 30 seconds. Add the lentils and stir to coat in the spices.","duration":0.5,"images":[],"step":2},{"title":"Simmer lentils","description":"Add the stock and salt. Stir, bring to a simmer. Lower the head to medium, put the lid on and simmer for 15 minutes.","duration":15,"images":[],"step":3},{"title":"Simmer chickpeas","description":"Add the chickpeas, water and baking soda. Increase the heat to make it simmer again. Then lower the stove slightly and leave to simmer gently for 30 minutes without a lid or until the lentils mostly broken down to make a thin gravy (you can cook an extra 10 minutes to thicken more if you want).","duration":30,"images":[],"step":4},{"description":"Serve with rice on the side and Afghan or other flatbreads for dunking, drizzled with yogurt and sprinkled with fresh coriander if you want (I do).","images":[],"step":5}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Afghan","Middle Eastern"],"categories":["curry-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e669ddde7782', 'en', 'US', 'Lamb korma curry', 'Recipe video above. In stark contrast to bold spicy curries like Vindaloo, Lamb Korma is creamy, nutty and gently spiced. It''s easy to love and so family-friendly, I call it the "other butter chicken"! Slow cooked until the meat is fall-apart tender, I particularly love the subtle cashew flavour in the sauce from the pureed cashews, and the distinct flavour that lamb adds to sauce.* Oven method yields the best flavour but see note 8 for slow cooker, instant pot and pressure cooker methods. Super handy, and I was very happy with it!', 'https://www.recipetineats.com/tachyon/2024/05/Lamb-korma_main.jpg', 20, 150, 170, 4, '[{"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 8.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_cashews", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_ghee", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_lamb", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_round_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_aram_marsala", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_naan", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 large onions (, cut into 1cm/1/2\" squares (brown or yellow))","8 large garlic cloves (, peeled, halved)","4cm/ 1.5\" piece ginger (, peeled, sliced 3mm/0.2\" thick)"],"purpose":"Onion paste:"},{"ingredients":["1/4 cup cashews (, roasted, unsalted (~20 cashews))","1/3 cup water"],"purpose":"Cashew puree:"},{"ingredients":["3 tbsp ghee ((Note 1), or unsalted butter)","800g / 1.6 lb lamb shoulder ((Note 2), trimmed off excess fat, cut into 4-5 cm / 2\" cubes)","1/2 tsp ground turmeric","2 1/2 tsp ground ginger","5 1/2 tsp garam marsala (Note 3)","1 tsp kashmiri chilli powder (or smoked paprika + cayenne - Note 4)","2 cups chicken stock/broth (, low-sodium)","10 cardamom pods (green), lightly crushed, wrapped and tied in muslin or cheesecloth (Note 5)","2 cinnamon sticks","4 tsp white sugar","1 1/2 tsp cooking salt / kosher salt","1/2 cup coconut cream (, full-fat (Note 6))","1/2 cup cream (, full-fat (any type - thickened/heavy, pure etc)(Note 6))"],"purpose":"Lamb korma"},{"ingredients":["Basmati rice (or other plain white rice of choice)","Naan (, for dunking! (optional))","Cashews finely chopped (optional sprinkle)","Coriander/cilantro leaves (, roughly chopped (optional garnish))"],"purpose":"SERVING"}]', '[{"title":"Onion puree","description":"Place the onion, garlic and ginger into a tall container that fits the head of a stick blender. Blitz until smooth – about 5 to 10 seconds. Scrape into a bowl, set aside.","images":[],"step":1},{"title":"Cashew puree","description":"In the same jar, while covering the mouth of the jar with your hand (to prevent flying cashew comets), blitz the cashews and water with the stick blender until smooth, about 10 seconds. , Set aside.","images":[],"step":2},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":3},{"title":"Reduce onion puree","description":"Melt and heat ghee in a ~24 cm/ 10\" oven-proof pot over high-heat. Cook the onion puree, stirring regularly, for 8 minutes until it has reduced by half. Don’t let it caramelise.","duration":8,"images":[],"step":4},{"description":"Add lamb, reduce to medium-high heat then stir until the meat changes from red to light brown. Don’t try to brown the meat (it won''t happen).","images":[],"step":5},{"title":"Sauce","description":"Add turmeric, ground ginger, garam marsala and kashmiri chilli, then stir through. Pour in the stock (the liquid should just barely cover the meat). Add cardamom pod sachet and cinnamon sticks, then stir. Bring to a simmer, cover with a lid then transfer to the oven.","images":[],"step":6},{"title":"Slow cook","description":"Cook for 1 1/2 hours. Stir in Cashew Puree, put the lid back on then return to the oven for another 30 minutes. The sauce should have thickened to a creamy consistency and lamb should be tender end to pull apart with forks with no effort. (Note 6)","images":[],"step":7},{"title":"Creamy sauce","description":"Place the pot on a low heat. Add the sugar, salt, coconut cream and cream, then stir. Simmer for 2 minutes, then you’re done!","duration":2,"images":[],"step":8},{"description":"Serve over basmati rice with a sprinkle of cashew nuts and coriander, if desired. Naan for dunking highly recommended!","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","indian-recipes","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48fe9b3f9de7', 'en', 'US', 'Vindaloo', 'Recipe video above. Vindaloo is a traditional Indian curry that''s not for the faint hearted! Big, bold curry flavours. Deep, vibrant red colour. Chunks of beef slow cooked to fall apart perfection. And yep, it''s spicy! For serious curry lovers, it''s hard to top this. As with all curries, use fresh spices for the best results (yes, spices fade in flavour over time). And no, unfortunately this won''t work in a slow cooker, pressure cooker or instant pot (Note 7).Serve with naan for mopping and yogurt for cooling. ** SPICE WARNING!!! Read Spiciness note below. **', 'https://www.recipetineats.com/tachyon/2021/07/Beef-Vindaloo_1.jpg', 20, 150, 170, 4, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.18, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_s", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.01, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.028, "unit": "pack of 3 heads"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fenugreek_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.105, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_ghee", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.01, "unit": "jar of 200g"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_curry_leaves", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["800g / 1.6 lb beef chuck (, cut into 3cm / 1.2\" cubes (Note 1))","1 1/2 tsp salt"]},{"ingredients":["6 tbsp Kashmiri chilli powder - TEST spiciness before using! (Note 2)","2 tsp coriander seeds","3 tsp cumin seeds","4 cloves","4 cardamom pods (green)","2 tsp cinnamon powder","1/2 tsp black peppercorns","2 tbsp fresh ginger (, roughly chopped)","10 garlic cloves (yes, 10!)","1 tsp brown sugar","1 tsp fenugreek seeds (Note 3)","1/4 tsp turmeric powder","7 tbsp white vinegar","2 cups water"],"purpose":"Curry paste:"},{"ingredients":["50g / 3 tbsp ghee or unsalted butter (Note 4)","1 onion (, finely chopped (brown, yellow, white))","2 tsp ginger (, finely grated)","4 garlic cloves (, finely minced)","1 1/2 tsp black mustard seeds (Note 5)","2 tbsp tomato paste","10 curry leaves (, fresh (Note 6))","2 cups beef stock (, low sodium (if using homemade, add 1/2 tsp salt))"],"purpose":"Curry sauce:"},{"ingredients":["2 tbsp coriander/cilantro leaves (, roughly chopped)"],"purpose":"Garnish:"}]', '[{"title":"Salt beef","description":"Toss beef in salt.","images":[],"step":1},{"description":"Check spiciness of kashmiri chilli powder and adjust if desired. See Spiciness Note below.","images":[],"step":2},{"title":"Curry Paste","description":"Place Curry Paste ingredients in a Nutribullet or small food processor with 1 cup of the water. Blitz until smooth. Pour over beef. Pour remaining 1 cup water into Nutribullet, shake (to clean out remaining curry paste), then pour/scrape over beef.","images":[],"step":3},{"title":"Marinate beef","description":"Mix beef in curry paste, cover, then marinate 2 hours. (Note: marinade is fairly thin - the water cooks down during slow cooking.)","images":[],"step":4},{"description":"Preheat oven to 190°C/375°F (170°C fan).","images":[],"step":5},{"title":"Curry sauce","description":"Melt ghee over medium high. Cook onion, ginger and garlic until they become translucent - about 3 minutes.","images":[],"step":6},{"title":"Mustard seeds","description":"Add black mustard seeds then cook until onion is tinged with gold. Stir in tomato paste, cook 1 minute.","images":[],"step":7},{"title":"Puree sauce","description":"Add beef stock, stir. Transfer into a jug then use a stick blender to puree until smooth. Pour back into the pot.","images":[],"step":8},{"title":"Add beef","description":"Add beef and curry leaves, stir then bring to boil.","images":[],"step":9},{"title":"Slow cook","description":"Cover with a lid, then place in the oven for 2 hours or until beef is fall apart tender and the sauce has darkened in colour and thickened. (See Note 7 if sauce hasn''t reduced enough).","images":[],"step":10},{"title":"Serve","description":"Garnish with coriander, then serve over basmati rice with a side of naan!","images":[],"step":11}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","indian-recipes","slow-cooked-fall-apart","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92e4271893a8', 'en', 'US', 'Palak Paneer – Indian Spinach Curry with Homemade Fresh Cheese', 'Recipe video above. A dish this iconic demands to be made properly – from scratch, with lots of fresh spinach and homemade paneer (Indian fresh cheese!) This is a magnificent vegetarian curry, packed with an extraordinary amount of nutrition and goodness!', 'https://www.recipetineats.com/tachyon/2021/02/Indian-Palak-Paneer_4.jpg', 45, 25, 70, 6, '[{"id": "ing_batch_homemade_paneer", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_ghee", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.5, "unit": "pack of 1kg"}}, {"id": "ing_fenugreek_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.002, "unit": "pack of 100g"}}, {"id": "ing_spinach", "quantity": {"value": 700.0, "unit": "bag of 250g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 batch homemade Paneer (Indian fresh cheese; recipe linked below)","30g / 2 tbsp ghee or unsalted butter (for pan frying, Note 2)"],"purpose":"Homemade Paneer (Note 1):"},{"ingredients":["30g/2 tbsp ghee or unsalted butter (Note 2)","1 1/2 onions (, finely chopped (brown or yellow))","1 tsp fenugreek seeds (whole) (Note 3)","1 tsp ground cumin","1 tsp ground coriander","3/4 tsp salt (, kosher/cooking salt (if using table salt, reduce by 1/4 tsp))","1/4 tsp black pepper","2 garlic cloves (, finely chopped)","2 tsp ginger (, finely grated (20g))","2 tomatoes (, peeled, seeded and diced (Note 4))","1 green chilli (, finely sliced (cayenne, Note 5))","700g/ 1.4lb fresh spinach leaves (English spinach) (, thoroughly washed and roughly chopped (~9 cups very tightly packed) (Note 6))","1/4 cup water","1/3 cup + 1 tbsp cream (pure, heavy or thickened)","1 tbsp lemon juice"],"purpose":"Palak Paneer:"}]', '[{"title":"Saute onion & spices","description":"Melt butter in a large pot over medium heat. Add onion, fenugreek, cumin, coriander, salt and pepper. Cook for 3 minutes until onion is softened but not golden.","duration":3,"images":[],"step":1},{"description":"Add garlic and ginger, cook for 2 minutes.","duration":2,"images":[],"step":2},{"description":"Add the tomato and chilli, cook for 3 minutes on a medium heat.","duration":3,"images":[],"step":3},{"title":"Add spinach: Add about 1/3 of the spinach","description":"or as much as you can handle in the pot (!) – and stir until wilted. Then add more spinach along with the water, cook again until wilted. Repeat until all the spinach is wilted.","images":[],"step":4},{"title":"Cook 10 minutes","description":"Cook, stirring every now and then, for 10 minutes still on a medium heat.","duration":10,"images":[],"step":5},{"title":"Cream & lemon","description":"Add the cream and lemon juice. Cook, stirring gently, for 3 minutes.","duration":3,"images":[],"step":6},{"title":"Puree half spinach","description":"Remove half the spinach into a tall container and blend it to a puree using a stick blender. Pour pureed spinach back into the pot, and stir to combine.","images":[],"step":7},{"title":"Add Pan Fried Paneer","description":"Gently stir in golden pan-fried paneer (see below). Stir gently to mix through.","images":[],"step":8},{"description":"Serve over basmati rice with fluffy, chewy homemade naan on the side!","images":[],"step":9},{"description":"Golden Pan-Fried Paneer (Note 8):","images":[],"step":10},{"description":"Cut paneer into 1.25cm / ½\" thick slices. Then cut each slice into 2.5cm x 2 x 1.25cm thick pieces / 1 x ⅘\" x ½\" pieces – approximately!","images":[],"step":11},{"description":"Melt half the ghee or butter in a non-stick pan over medium-high heat.","images":[],"step":12},{"title":"Place half the paneer in the pan and cook for 1","description":"1 1/2 minutes until light golden - I tend to make it deep golden because colour = more flavour, but traditional is just a hint of gold Turn, then cook the other side until light golden.","images":[],"step":13},{"description":"Remove onto paper towel-lined plate. Repeat with remaining butter and paneer. Use per recipe.","images":[],"step":14}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","iconic-dishes","indian-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0c5641317a17', 'en', 'US', 'Goan Fish Curry', 'Recipe video above. This famous Goan fish curry comes to you from Goa, a little pocket of Indian paradise that''s all about the sun, surf, sand and excellent seafood! Deeply aromatic with a tomato and coconut based sauce, this recipe has a few more spices and steps than the more home-style recipes you''ll find online because this aims to replicate the richer sauce and layers of flavour you get at (good) Indian restaurants.Once you''ve made this with fish, try it with prawns/shrimp - it''s also excellent!SPICINESS: Quite spicy as written, but not blow-your-head-off! I thoroughly enjoy it as written, not suffering. See Spice Note below for adjustment to reduce / eliminate spiciness.', 'https://www.recipetineats.com/tachyon/2020/10/Goan-Fish-Curry_6.jpg', 15, 20, 35, 4, '[{"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_fenugreek_powder", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 0.007, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 6.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 1/2 tbsp Kashmiri chilli powder (Note 1)","1 tbsp coriander","2 tsp cumin","1 tsp turmeric","1/2 tsp fenugreek powder (Note 2)","3/8 tsp ground cloves","6 cloves garlic (, minced)","1 tbsp fresh ginger (, finely grated)","2 tbsp tamarind puree (Note 3)","1/2 red onion (, chopped)","6 tbsp water (plus more, as needed)"],"purpose":"Curry paste:"},{"ingredients":["3 tbsp vegetable oil","1/2 tsp black mustard seeds (Note 4)","1/2 red onion (, cut in half again (like a quartered orange) and thinly sliced)","1 tbsp tomato paste","2/3 cup canned tomato pulp/polp (Mutti), OR tomato passata or crushed tomato, Note 5)","2/3 cup water","400ml/ 14oz coconut milk (, full fat (Note 6))","1 1/4 tsp salt (, cooking/kosher (or 3/4 tsp fine table salt))","1 1/2 tsp sugar","1/4 tsp chilli powder (pure chilli, not US Chili Powder which is a mix, Note 7)","2 long green chillies (, cut into half lengthwise and deseeded, optional (Note 8))","1 tomato (, cut into 8 wedges then into 2.5cm / 1\" chunks)","600g / 1.2 lb firm-fleshed white fish (, cut into 3cm / 1.25\" cubes (Note 9))"],"purpose":"Curry:"},{"ingredients":["1/4 cup fresh coriander/cilantro leaves","Finely sliced green chillies (, optional)","Basmati rice"],"purpose":"Garnishes / serving:"}]', '[{"description":"Place Curry Paste ingredients in a tall jug or milkshake container (something that fits the head of a blender stick) then blitz on high for 5 to 10 seconds until the onion is pureed. Add more water if needed to make it puree.","duration":0.125,"images":[],"step":1},{"title":"Sizzle black mustard seeds","description":"Heat oil over medium heat in a large pot. Add black mustard seeds and let them sizzle for 30 seconds - careful, they might pop!","duration":0.5,"images":[],"step":2},{"title":"Saute onion","description":"Add red onion and cook for 3 minutes until edges start to tinge with gold.","duration":3,"images":[],"step":3},{"title":"Cook off curry paste","description":"Add curry paste and cook for 3 minutes - to evaporate water, make spices bloom and cook garlic & ginger.","duration":3,"images":[],"step":4},{"title":"Cook off tomato","description":"Turn heat up to medium high. Add tomato paste and tomato pulp, cook for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Coconut milk","description":"Add water, coconut milk, sugar, salt and chilli powder if using. Stir, then bring to simmer, low heat so it''s bubbling gently.","images":[],"step":6},{"title":"Simmer 2 minutes, add tomato & green chilli","description":"Simmer for 2 minutes, add tomato and green chilli.","duration":2,"images":[],"step":7},{"title":"Simmer 3 minutes","description":"Simmer for another 3 minutes, stirring every now and then - sauce should be thickened (not watery), it gets looser again when fish is added (because fish will drop some juices = even more flavour!).","images":[],"step":8},{"title":"Add fish","description":"Add fish, stir, cook for 3 to 4 minutes until fish easily flakes.","duration":3.5,"images":[],"step":9},{"title":"Garnish & serve","description":"Remove from stove and transfer to serving bowl. Garnish with coriander/cilantro and fresh green chillies if desired. Serve with basmati rice!","images":[],"step":10}]', '["fish","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","fish-recipes","indian-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92c0519c1b52', 'en', 'US', 'Rogan Josh (Indian Lamb Curry)', 'Recipe video above. An Indian lamb curry to die for! A heady combination of intense spices in a creamy tomato curry sauce, the lamb is fall apart tender and packs a serious flavour punch. While this recipe calls for a lengthy list of spices, you won''t need to take a trip to an Indian store to get them - they''re even sold at my local grocery store!', 'https://www.recipetineats.com/tachyon/2020/02/Rogan-Josh_4.jpg', 20, 150, 170, 4, '[{"id": "ing_hee", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.015, "unit": "jar of 40g"}}, {"id": "ing_s", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lamb", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.075, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.05, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.025, "unit": "jar"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garam_marsala", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_fennel", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_garam_masala", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_fennel", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["3 1/2 tbsp ghee (, substitute butter (Note 1))","1 cinnamon stick","6 green cardamom pods (, lightly bruised)","4 cloves","1 large onion (, finely chopped)","3 cloves garlic (, finely minced)","1 tbsp ginger (, finely grated)","5 tbsp tomato passata (US: tomato puree/sauce, Note 5)","1 tsp cooking salt / kosher salt (halve for table salt, double for flakes)","750g/1.5lb boneless lamb shoulder (, cut into 3cm/1.2\" cubes (Note 6))","1 1/2 cups chicken stock (, salt reduced (broth))"]},{"ingredients":["2 tbsp paprika (, normal or sweet)","3/4 tsp chilli powder (or to taste, Note 2)","4 tsp ground coriander","4 tsp ground cumin","2 tsp turmeric powder","1/4 tsp nutmeg powder","1 tsp garam marsala (Note 3)","1/2 tsp fennel powder (Note 4)"],"purpose":"SPICES:"},{"ingredients":["1/2 cup plain yoghurt (Greek yogurt fine)","1/2 tsp extra garam masala (Note 3)","1/2 tsp extra fennel powder"],"purpose":"FINISHES"},{"ingredients":["Chopped coriander leaves, finely shredded ginger, yogurt","Basmati rice"],"purpose":"SERVING/GARNISH"}]', '[{"description":"Toast whole spices in ghee, then sauté onion, garlic and ginger. Toast ground spices 30 seconds, add tomato, salt, stock and lamb. Simmer gently covered 1 hr 45 min until lamb fork-tender, simmer with lid off 15 min to reduce. Stir in Finishes, serve!","images":[],"step":1},{"title":"Toast whole spices","description":"Melt ghee over medium heat in large heavy based pot. Add cinnamon, cardamom and cloves and cook for one minute.","images":[],"step":2},{"title":"Sauté","description":"Add onion and cook for 7 minutes, stirring frequently, until pieces are golden and starting the brown on the edges. Add the garlic and ginger, cook for another minute.","duration":7,"images":[],"step":3},{"title":"Toast spices","description":"Stir in the Spices, cook for 30 seconds.","duration":0.5,"images":[],"step":4},{"title":"Sauce and lamb","description":"Mix in the tomato puree and salt, then add stock and mix. Add lamb, stir, bring to simmer.","images":[],"step":5},{"title":"Simmer 1 h 45 min","description":"Place lid on and adjust heat to low or medium low so it''s simmering gently. Cook 1 hour 45 minutes, giving it an occasional stir, until lamb is quite tender - use 2 forks to check, it should pry apart pretty easily.","images":[],"step":6},{"title":"Reduce","description":"Remove lid, and continue cooking for another 15 minutes (to reduce sauce slightly) - lamb should be very tender by this stage.","images":[],"step":7},{"title":"Finish","description":"Stir in the Yogurt, the Extra garam marsala and fennel. Cook for another few minutes.","images":[],"step":8},{"description":"Serve with basmati rice, sprinkled with fresh coriander leaves and other garnishes if desired. More sides (pictured): Cucumber salad (Note 7) and Easy naan - No Yeast Flatbread","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","indian-recipes","lamb-recipes","main-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e4a089c7c802', 'en', 'US', 'Curried Sausages', 'Recipe video above. A retro classic! Browned sausages smothered in a curry flavoured gravy with onions, carrots and peas. Skip the old school method of boiling sauces - that''s throwing away free flavour! Browning sausages in the same skillet used to make the curried gravy makes a MUCH tastier sauce. I promise!', 'https://www.recipetineats.com/tachyon/2019/04/Curried-Sausages_2.jpg', 5, 15, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 0.03, "unit": "bottle"}}, {"id": "ing_sausages", "quantity": {"value": 1.2, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.037, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_peas", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["0.5 tbsp oil","600g / 1.2lb sausages (, of choice (Note 1))","2 garlic cloves (, minced)","1 onion (, halved and sliced)","1 carrot (, peeled, sliced on the diagonal)","1 tbsp curry powder (, or more (Note 2))","3 tbsp flour (, any type (Note 3 for GF))","2 cups (500ml) chicken stock/broth (, low sodium)","1 tsp sugar","1/2 tsp salt (, plus more to taste)","1/2 tsp black pepper","1 cup peas (, frozen)"]}]', '[{"description":"Heat oil in a large skillet over medium high heat.","images":[],"step":1},{"description":"Cook sausages, turning to brown all over then remove. Optional: slice sausages into pieces on the diagonal.","images":[],"step":2},{"description":"In the same skillet, add garlic and onion. Cook for 2 minutes until translucent.","duration":2,"images":[],"step":3},{"description":"Add curry powder and stir for 30 seconds.","duration":0.5,"images":[],"step":4},{"description":"Add flour and mix for 30 seconds.","duration":0.5,"images":[],"step":5},{"description":"Gradually pour in chicken stock, mixing constantly.","images":[],"step":6},{"description":"Add carrots, sugar, salt and pepper, stir well.","images":[],"step":7},{"description":"Add sausages and peas, bring to simmer and cook for 3 minutes or until sauce thickens.","duration":3,"images":[],"step":8},{"description":"Serve over mashed potato, rice, pasta or noodles. For low carb, try mashed cauliflower!","images":[],"step":9}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["curry-recipes","dinner-tonight","quick-and-easy","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_81a2e1367367', 'en', 'US', 'Chicken Biryani', 'Recipe video above. Curried chicken cooked in a pot buried under a mount of fragrant, fluffy rice. Biryani is a celebration of all that we love about Indian food! Make this with other proteins or vegetables - see notes. There''s a load of spices in this - and it''s worth it! (Plus you''ll find everything at every day supermarkets). Spiciness: moderate low.', 'https://www.recipetineats.com/tachyon/2018/08/Chicken-Biryani_1-1.jpg', 20, 60, 80, 8, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.006, "unit": "tub of 500g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.012, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_round_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cinnamon", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cayenne", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garam_marsala", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.075, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_s", "quantity": {"value": 10.0, "unit": "pack"}}, {"id": "ing_bay_leaf", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_star_anise", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cardamon_pods", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_saffron_threads", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["750g (1.5 lb) chicken thighs (, skin on, bone in, halved along bone (Note 1))"]},{"ingredients":["2/3 cup (150 ml) yoghurt (, plain)","1/2 cup (125 ml) water","2 tbsp vegetable oil (or other plain oil)","6 garlic cloves (, minced)","2 tsp finely grated fresh ginger","1/8 tsp ground turmeric","1/4 tsp cinnamon","1/2 tsp cayenne (adjust spiciness to taste)","1/2 tsp ground cardamom","2 tsp garam marsala (Note 2)","2 tsp coriander","1 tbsp cumin","2 tbsp paprika (, sweet / ordinary (not smoked))","1 3/4 tsp salt"],"purpose":"Marinade:"},{"ingredients":["2 tbsp salt","10 cloves","5 dried bay leaves","1 star anise","6 green cardamon pods","2 1/4 cups (450g) uncooked basmati rice (Note 3)"],"purpose":"Par Boiled Rice:"},{"ingredients":["2 medium onions (yellow, brown) (, halved and finely sliced)","1 cup (250 ml) oil (, for frying)"],"purpose":"Crispy Onions (Note 4):"},{"ingredients":["1 tsp saffron threads (loosely packed) (Note 5)","2 tbsp warm water"],"purpose":"Saffron:"},{"ingredients":["1 cup coriander / cilantro (, chopped)","1/4 cup (60g) ghee or unsalted butter (, melted (Note 6))"],"purpose":"Biryani:"},{"ingredients":["Crispy onions (above)","Chopped coriander / cilantro","Yoghurt (Note 7)"],"purpose":"Garnish:"}]', '[{"description":"Mix Marinade in a large pot (about 26cm / 11\" diameter). Add chicken and coat well. Marinade 20 minutes to overnight.","images":[],"step":1},{"description":"Par Boiled Rice:","images":[],"step":2},{"description":"Bring 3 litres / 3 quarts water to the boil, add salt and spices.","images":[],"step":3},{"description":"Add rice, bring back up to the boil then cook for 4 minutes, or until rice is just cooked still a bit firm in the middle. Rice will taste salty at this stage, disappears in next stage of cooking.","duration":4,"images":[],"step":4},{"title":"Drain immediately. Set aside. (Note 10 re","description":"leaving whole spices in)","images":[],"step":5},{"description":"Heat oil in a large saucepan over medium high heat. Cook onion, in batches, for 3 to 4 minutes, until golden brown. Don''t burn - they become bitter.","duration":3.5,"images":[],"step":6},{"description":"Remove onto paper towel lined plate. Repeat with remaining onion.","images":[],"step":7},{"description":"Place in a bowl, leave for 10 minutes+.","duration":10,"images":[],"step":8},{"description":"Place pot with chicken in it onto a stove over medium heat. Cover and cook for 5 minutes.","duration":5,"images":[],"step":9},{"description":"Remove lid. Cook for 5 minutes, turning chicken twice.","duration":5,"images":[],"step":10},{"description":"Remove from heat.","images":[],"step":11},{"title":"Turn chicken so skin side is down","description":"it should cover most of the base of the pot.","images":[],"step":12},{"description":"Scatter over half the onion then half the coriander.","images":[],"step":13},{"description":"Top with all the rice. Gently pat down and flatten surface.","images":[],"step":14},{"description":"Drizzle saffron across rice surface in random pattern, then drizzle over ghee.","images":[],"step":15},{"description":"Place lid on. Return to stove over medium heat.","images":[],"step":16},{"description":"As soon as you see steam, turn down to low then cook for 25 minutes.","duration":25,"images":[],"step":17},{"description":"Remove from stove, rest with lid on for 10 minutes.","duration":10,"images":[],"step":18},{"description":"To Serve:","images":[],"step":19},{"description":"Aim to serve it so you get nice patches of yellow rice, white rice, the curry stained rice + chicken (rather than all mixed up). To do this, use a large spoon and dig deep into the pot, and try to scoop up as much as you can in one scoop.","images":[],"step":20},{"title":"Turn out into bowl","description":"or onto platter. Garnish with remaining onion and coriander with yoghurt on the side (see Note 7 for Minted Yoghurt)","images":[],"step":21}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","dietary","gluten-free-recipes","iconic-dishes","indian-recipes","main-dishes","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c07e19c1c759', 'en', 'US', 'Vegetable Curry', 'This packs a serious flavour punch and is loaded with vegetables! I used plenty of variety, but feel free to use less. Just substitute based on volume rather than weight (because vegetable weight/density differs), and adjust the chilli and cayenne pepper to control spiciness, as well as using either mild or hot curry powder.', 'https://www.recipetineats.com/tachyon/2017/07/Vegetable-Curry.jpg', 15, 25, 40, 5, '[{"id": "ing_curry_powder", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.007, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 1.0, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sweet_potato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_frozen_peas", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp curry powder (, mild or hot (Note 1))","1 tsp All Spice powder","1 tsp nutmeg powder (or 1/2 tsp freshly grated nutmeg)","1 1/2 tsp smoked paprika (sub with sweet or ordinary paprika)","2 tsp dried thyme leaves (or 3 tsp fresh thyme leaves)","1 tsp cumin powder","3/4 tsp cayenne pepper (adjust to taste)","1 tsp pepper (white or black)"],"purpose":"Spice Mix:"},{"ingredients":["3 tbsp cooking oil","1 large onion (, diced (brown, white, yellow))","1 large red chilli / cayenne pepper (, deseeded and finely sliced)","2 large garlic cloves (, minced)","1 large red capsicum / bell pepper * (, chopped into 1.7cm / 2/3\" pieces (~1.5 cups))","800g/ 28 oz canned crushed tomato","2 cups (500 ml) vegetable or chicken broth","1 zucchini (, diced (~1 cup) *)","2 cups sweet potato * (, 1.5cm / 3/5\" cubes (~225g/7.5oz))","2 cups cauliflower florets * (, small / medium (~180g/6oz))","3/4 cup frozen peas *","2 handfuls baby spinach (, optional (Note 2))","1/2 cup finely chopped coriander/cilantro ((leaves and stems), plus more for garnish)","Salt and pepper","Yoghurt (plain or Greek)"],"purpose":"Curry:"},{"ingredients":["Basmati rice","White rice"],"purpose":"Serving – choose:"}]', '[{"description":"Heat oil in a large pot over medium high heat. Add garlic and onion, cook for 2 minutes. Add cayenne and cook until onion is translucent.","duration":2,"images":[],"step":1},{"description":"Add Spice Mix and cook, stirring constantly, for 1 - 2 minutes until the spice is fragrant and wet. If too dry, add a tiny touch of water or oil.","duration":1.5,"images":[],"step":2},{"description":"Add capsicum and zucchini, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add tomato, broth, potato and cauliflower. Mix well, bring to simmer, cover, lower heat to medium.","images":[],"step":4},{"description":"Simmer for 15 minutes or until potato is pretty soft, then remove lid and simmer for another 10 minutes+ until sauce is slightly thickened and potato is soft.","duration":15,"images":[],"step":5},{"description":"Add peas, stir, cook for 2 minutes. Add coriander and spinach, stir until wilted.","duration":2,"images":[],"step":6},{"description":"Season to taste until salt and pepper. Serve over basmati rice or plain white rice. Garnish with yoghurt and more coriander.","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Caribbean"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","main-dishes","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f629f547dae', 'en', 'US', 'Country harvest root vegetable soup', 'Recipe video above. I don''t harvest and I don''t live in the country. I just didn''t think "Root Vegetable Soup" did this recipe justice - so I got creative to get your attention!😅 Root veg are great for naturally creamy soups thanks to the higher starch content, though we give this a luxe boost with a scant 1/2 cup of cream. Nourishing, never boring, and flexible too - in case your harvest basket is missing items! Love that it''s made with water not stock - curry powder adds a flavour boost so it doesn''t taste flat. Bonus - LOW CAL!', 'https://www.recipetineats.com/tachyon/2025/05/Creamy-root-vegetable-soup_1.jpg', 20, 30, 50, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.037, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 1.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_sweet_potato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_medium_parsnip_cut_into_1_5cm_0_5_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_celeriac_cut_into_1_5cm_0_5_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp extra virgin olive oil","1 tbsp (15g) unsalted butter","1 onion (, chopped into large dice)","3 garlic cloves (, chopped)","1 tbsp curry powder (I like Clive, but any will do, Note 1)","1 tsp dried thyme leaves (Note 2)","1 1/2 litre (6 cups) water","2 tsp cooking salt/kosher salt (halve for table salt)","1/2 tsp black pepper","1/2 cup thickened cream (heavy cream, or regular), plus extra for garnish (Note 3)"]},{"ingredients":["1 large potato ((~300g/10oz), peeled, cut into 2.5cm/1\" cubes)","1 medium sweet potato ((350g/12oz), peeled, cut into 2.5cm/1\" cubes)","2 medium carrots (, peeled, cut into 1.5cm/0.5\" pieces)","1 small/medium parsnip ((150g/5oz), peeled, cut into 1.5cm/0.5\" pieces)","1 small celeriac (600g/1.2 lb), peeled, cut into 1.5cm/0.5\" pieces (~2 heaped cups)"],"purpose":"Root vegetables (Note 4):"},{"ingredients":["Warm crusty bread","Parsley (, finely chopped)","Pinch extra curry powder","Pinch black pepper"],"purpose":"Serving/garnish (optional):"}]', '[{"title":"Sauté","description":"Put the olive oil and butter in a large heavy-based pot over medium-high heat. Once the butter is melted, cook the onion and garlic for 2 minutes until the onion is softened.","duration":2,"images":[],"step":1},{"description":"Add root vegetables, thyme and curry powder. Cook for three minutes stirring regularly, until the outside of the vegetables starts to soften.","images":[],"step":2},{"title":"Simmer 15 minutes","description":"Turn stove up to high. Add water, salt and pepper. Stir, then once it comes to a simmer, lower heat to medium high and simmer rapidly for 15 minutes (no lid) until all the vegetables are soft (check with knife).","duration":15,"images":[],"step":3},{"description":"Stir in cream, simmer for 1 minute.","duration":1,"images":[],"step":4},{"title":"Blitz","description":"Remove from heat and use a stick blender to blitz until smooth. (Note 5 for blender) Adjust to taste - water to thin, salt and pepper if needed, extra cream for more indulgent.","images":[],"step":5},{"description":"Serve in bowls. Drizzle with cream, pinch of curry powder, parsley and pepper. Serve with warm crusty bread!","images":[],"step":6}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c559c7f6dc4', 'en', 'US', 'Puttanesca Fish Tray Bake', 'Recipe video above. Baked fish dinners can be so dull. Not this one! Think - spaghetti puttanesca flavours in the form of a one pan fish dinner. It''s a Puttanesca fish tray bake! Good for you, easy to make, fabulously delicious.Note: If you only have fine table salt, halve the salt quantities else it will be too salty.', 'https://www.recipetineats.com/tachyon/2025/05/Puttanesca-fish-tray-bake-shoot-1_3.jpg', 15, 45, 60, 4, '[{"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_fennel", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_pitted_kalamata_olives", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_baby_capers", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_organo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["600g/1.2 lb baby potatoes (, smaller ones up to 3.5cm/1.5\" halved, larger ones quartered (Note 1))","1 1/2 tbsp extra virgin olive oil","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Roasted potatoes:"},{"ingredients":["1 medium fennel (, fronds reserved for garnish, halved, cut into 0.5cm / 0.2\" half moon shapes (Note 2))","1 1/2 cups (200g) cherry or grape tomatoes (1 punnet)","1/2 cup pitted kalamata olives","3 garlic cloves (, finely minced (can use garlic crusher))","3 tbsp baby capers (or regular, roughly chopped)","3 anchovy fillets (, finely minced - can reduce to 1 (Note 3))","400g/ 14oz canned tomato (, crushed or diced)","1/2 tsp chilli flakes ((red pepper flakes), mild spiciness, can reduce or omit)","1 tsp dried organo","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Puttanesca sauce:"},{"ingredients":["4 x 160 - 180g / 6oz barramundi fillets (, skinless, or other firm fish fillets about 2.5/3cm/1\" thick (Note 4))","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 1/2 tbsp extra virgin olive oil"],"purpose":"Fish:"},{"ingredients":["1 loosely packed cup basil leaves (, roughly chopped (recommended but can live without or sub with 2 tbsp roughly chopped parsley))","Warm crusty bread (, for mopping)"],"purpose":"Finishing / serving:"}]', '[{"description":"Preheat oven to 220°C/390°F (200°C fan-forced).","images":[],"step":1},{"title":"Roast potatoes","description":"In a large mixing bowl, toss the potatoes with the oil, salt and pepper. Spread on a baking tray with a rim at least 2cm/0.8\" high (or 23x33cm / 9x13\" pan). Roast for 20 minutes.","duration":20,"images":[],"step":2},{"title":"Puttanesca sauce","description":"Meanwhile, mix all the sauce ingredients together (use the potato bowl, no need to clean). Add to the tray, toss with the potatoes, return to the oven for 10 minutes.","duration":10,"images":[],"step":3},{"title":"Season fish","description":"Pat the fish dry with paper towels. Sprinkle each side with the salt and pepper.","images":[],"step":4},{"title":"Bake fish","description":"Place fish on top of puttanesca sauce. Drizzle all over with the 1 1/2 tablespoons of oil. Bake 15 minutes or until fish is just cooked through (it should flake easily).","images":[],"step":5},{"title":"Serve","description":"Remove from the oven. Drizzle with a bit more olive oil, scatter with basil and reserved fennel fronds. Serve with warm, crusty bread!","images":[],"step":6}]', '["fish","gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","fish-recipes","gluten-free-recipes","mains","one-pot-recipes","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d1115e64f3d8', 'en', 'US', 'Vietnamese Peanut Sauce Lettuce Wraps', 'Recipe video above. Such a great DIY summer spread, a regular all through summer in my circles! It''s essentially a lower-cal version of Vietnamese rice paper rolls. The fresh herbs and the peanut sauce are key here! Everything else you can switch: prawns for shredded chicken, pan fried salmon or other fish (flake into big chunks) or even tofu (I pan fry batons). Use whatever shreddable veg you want. Emergency version: store bought roast chicken (shredded) + packet shredded coleslaw veg + peanut sauce + noodles. SO GOOD.', 'https://www.recipetineats.com/tachyon/2024/01/Vietnamese-lettuce-wraps-with-peanut-sauce_8.jpg', 20, 0, 20, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.15, "unit": "pack of 500g"}}, {"id": "ing_lettuce", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_mint", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_roasted_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.08, "unit": "jar of 375g"}}, {"id": "ing_hoisin", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_lime", "quantity": {"value": 1.5, "unit": "net of 500g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_sambal_oelak_can_omit", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_dark_soy", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_radishes", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 3.0, "unit": "L"}}]', '[{"ingredients":["300g / 10 oz peeled whole cooked prawns/shrimp (, medium (600g/1.2lb unpeeled whole prawns - this is what I use) - Note 1)","75g / 2.5 oz dried vermicelli noodles (or glass noodles or rice)","12 large or 16 -20 small lettuce leaves ((I used baby cos/romaine), eg iceberg, butter lettuce)"],"purpose":"The lettuce cups:"},{"ingredients":["1 batch quick pickled carrots and daikon (, below *recommended* OR 2 carrots finely julienned (use plain))","2 cups beansprouts","2 cucumbers (, julienned)","2 cups mint leaves","2 cups coriander/cilantro sprigs (sub with chives + extra mint)","3 birds eye red chilli (, finely sliced (optional))","1/4 cup roasted peanuts (, finely chopped (recommended))"],"purpose":"Veg and herbs:"},{"ingredients":["2 tbsp natural peanut butter (, smooth (ie not sweetened) - Note 2)","2 tbsp hoisin","1 - 2 tbsp lime juice (, sub rice vinegar)","1/3 cup LOW FAT coconut milk (Note 3)","1 large garlic clove (, finely grated)","1 tsp+ sambal oelak (or other chilli sauce/paste of choice), can omit (adj to taste)","1 tsp dark soy (Note 4)","1 tsp white sugar","1/2 tsp cooking salt / kosher salt"],"purpose":"Vietnamese Peanut Sauce:"},{"ingredients":["2 medium carrots (, peeled cut into 2 mm / 1/10″ batons)","1/2 large white radish (daikon) (, peeled, cut the same as carrots)","1 1/2 cups boiling water","1/2 cup white sugar","4 tsp cooking salt / kosher salt","3/4 cup rice wine vinegar (sub apple cider vinegar)"],"purpose":"Quick pickled vegetables"}]', '[{"title":"Pickle first","description":"Put the boiling water, salt and sugar in a bowl. Mix to to dissolve, then add vinegar. Submerge vegetables and leave for 2 hours. Drain then use per recipe (or store in fridge submerged in liquid).","images":[],"step":1},{"title":"Peanut sauce","description":"Mix the peanut sauce ingredients and set aside for the flavours to meld while you prepare the platter. Start with 1 tbsp lime juice and add more if you want tarter.","images":[],"step":2},{"title":"Prawns (shrimp)","description":"Cut the prawns in half horizontally and remove the vein.","images":[],"step":3},{"title":"Noodles","description":"Soak the noodles in boiling water per packet directions. Rinse under cold water (to prevent stickiness) then drain very well.","images":[],"step":4},{"title":"Lay it all out","description":"Pile everything onto a giant platter or put things in little bowls, then let everybody help themselves!","images":[],"step":5},{"title":"Assemble","description":"Here''s my order: lettuce leaf, noodles first, then veg* (carrots, bean sprouts etc), prawns, stuff herbs down the side, drizzle with sauce, sprinkle with peanuts and chilli. Bundle and bite!","images":[],"step":6}]', '["milk","peanuts","shellfish","soy"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","no-cook-food","prawns-shrimp","summer","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_880b53615e1c', 'en', 'US', 'Almost no-oil Pan Fried Eggplant', 'Recipe video above. This is a recipe for how to cook eggplant on the stove with virtually no oil - less than 1/2 teaspoon for a whole eggplant! I use a highly effective, simple pan-steaming method used for Asian dumplings like gyoza! Eat it as is, or see in post for a list of toppings and sauces to serve with this pan fried eggplant. Which one is your favourite??', 'https://www.recipetineats.com/tachyon/2023/10/Pan-fried-eggplant-with-little-oil_3.jpg', 3, 10, 13, 2, '[{"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_see_in_post_for_ideas_and_links_to_recipes_for_sauces_etc", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1 large eggplant (aubergine), around 20cm/8” (~400g/14 oz) (Note 1)","Olive oil spray (or other oil spray) (Note 2)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/4 cup water"]},{"ingredients":["See in post for ideas and links to recipes for sauces etc!"],"purpose":"Sauces and toppings for serving:"}]', '[{"description":"Cut the eggplant into 2cm / 0.8” rounds.","images":[],"step":1},{"description":"Spray each side generously with oil and sprinkle with salt and pepper.","images":[],"step":2},{"title":"Brown","description":"Heat a large non-stick pan with a lid over medium high heat, no oil. (Note 3) Add the eggplant slices and pan fry for 1 1/2 to 2 minutes on each side or until you get some nice browning on it. As much or as little as you want!","images":[],"step":3},{"title":"Pan steam","description":"Carefully add water around the eggplant (it will bubble and steam, so do this carefully). Then immediately cover with a lid to trap the steam in. Steam for 2 minutes or until the water has evaporated.","duration":2,"images":[],"step":4},{"title":"Check","description":"Use a butter knife to check to ensure the eggplant is cooked through. If not, add a bit more water and steam again!","images":[],"step":5},{"title":"Serve","description":"Transfer to a serving plate and serve! Great as is, or to dress it up a tiny bit, add a swish of olive oil, squeeze of lemon juice and parsley leaves, or a smear of chilli crisp! See in post for more ways to serve.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","eggplant","how-to","low-calorie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d103e1d2cd8e', 'en', 'US', 'Roast Lamb Leg with Gravy', 'Recipe video above. I love a roast lamb leg! My top tip is to use a meat thermometer. There''s no way to guarantee perfect blushing pink roast lamb without one, even if it''s a cheap one!Rubbed with rosemary garlic and accompanied with a killer gravy for lamb. Serve with peas, buttered steamed carrots and crunchy roast potatoes (either classic or ultra crunchy duck fat potatoes).', 'https://www.recipetineats.com/tachyon/2016/10/Roast-lamb-leg_2.jpg', 5, 100, 15, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.875, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["2.75 - 3 kg / 5.5 - 6 lb lamb leg (, bone-in (Note 1))","1 1/2 tsp cooking salt","1/2 tsp black pepper"]},{"ingredients":["1 1/2 tbsp fresh rosemary leaves (, finely chopped)","3 garlic cloves (, finely minced)","2 tbsp olive oil"],"purpose":"Rub"},{"ingredients":["2 whole heads of garlic (, halved horizontally (Note 2))","Few sprigs rosemary (optional)"],"purpose":"Base"},{"ingredients":["4 tbsp flour (, plain/all purpose)","2 1/2 cups beef broth / stock (, low sodium (Note 3))"],"purpose":"Gravy"}]', '[{"description":"Take lamb out of fridge at least 1 hour before roasting. (Note 4)","images":[],"step":1},{"description":"Preheat oven to 240°C/475°F (220°C fan) with oven shelf in the middle.","images":[],"step":2},{"title":"Rub","description":"Mix rosemary, garlic and olive oil.","images":[],"step":3},{"title":"Prepare lamb","description":"Place lamb leg in a roasting pan. Coat with the rub using your hands, the sprinkle with the salt and pepper. Place garlic and rosemary sprigs underneath the lamb, garlic cut face up.","images":[],"step":4},{"description":"Roast lamb leg for 20 minutes. Turn the oven down to 200°C/400°F (180°C fan) and roast for a further 1 hour or until the internal temperature reaches 53°C/127°F for medium rare (Note 5 other doneness). Check first at 45 minutes - everyone''s oven is different!","duration":20,"images":[],"step":5},{"title":"Rest","description":"Remove lamb from oven. Transfer lamb to plate, loosely cover with foil and rest for 20 minutes to 1 hour (it will still be warm enough for serving!). The internal temperature will rise to 62°C/144°F (medium rare). Make gravy while lamb is resting - below.","duration":20,"images":[],"step":6},{"description":"Serve lamb with gravy, duck fat or classic crunchy roast potatoes, peas and steamed carrots tossed with butter and parsley.","images":[],"step":7},{"description":"Gravy for roast lamb leg","images":[],"step":8},{"title":"Drippings in pan","description":"Discard rosemary sprigs. You should have around 4 - 5 tbsp of fat (drippings). If less, add butter. If much more, discard a bit.","images":[],"step":9},{"title":"Add flour","description":"Place roasting pan on stove over medium heat. When the fat starts to bubble, then add flour. Mix flour in and cook for 1 minute.","duration":1,"images":[],"step":10},{"title":"Stock","description":"Pour in half the beef stock and mix to dissolve sludge in, then add remaining beef stock and mix.","images":[],"step":11},{"title":"Garlic squidging","description":"Use a potato masher (if you''re really keen like me) to mush the garlic to squeeze out the flavour (also helps flour caught in garlic to dissolve).","images":[],"step":12},{"title":"Taste","description":"Check salt and pepper (I don''t add more).","images":[],"step":13},{"title":"Thicken","description":"Simmer for a couple of minutes, stirring, until it starts to thicken. Take it off the stove BEFORE the gravy is the thickness you want because it will keep thickening.","images":[],"step":14},{"description":"Strain into a bowl, mushing garlic to squeeze all the liquid out. Then pour into gravy jug and serve with lamb!","images":[],"step":15}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Aussie","British","New Zealand"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","lamb-recipes","main-dishes","most-popular","roast-lamb","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_681954c5523d', 'en', 'US', 'Gazpacho', 'Recipe video above. If the thought of this chilled Spanish soup conjures up visions of watery, bland, pureed vegetables, think again! Fabulous refreshing and full of flavour. Marinating isn''t traditional but does improve flavour. So it''s recommended, especially if you use economical vinegar or if your tomatoes aren''t farm-fresh-ripe-and-sweet (ie typical tomatoes from everyday grocery stores....)This version has no bread in it - it''s thick enough as is, I find. Serve with crusty bread on the side, for dunking. Fabulous meal for a hot summer day!Serves 3 hearty appetites, 4 normal appetites (with bread for dunking).', 'https://www.recipetineats.com/tachyon/2023/01/Gazpacho_2.jpg', 15, 0, 15, 3, '[{"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 kg / 2 lb ripe tomatoes ((~7), cut into 8 wedges, core removed)","1 cucumber (20cm/8\" long) (, peeled and diced into 1cm / 1/2\" cubes)","1 red capsicum/bell pepper (, cut into 1.5 cm / 1/2\" cubes)","2 garlic cloves (, chopped)","1/4 cup red onion (, finely diced (Note 1))","1/4 cup extra virgin olive oil (, + extra for serving)","1 1/2 tbsp sherry vinegar (sub white wine or champagne vinegar)","3/4 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Gazpacho:"},{"ingredients":["Crusty bread","Cucumber (, cut into small cubes (optional))"],"purpose":"Serving:"}]', '[{"title":"Marinate","description":"Toss all the gazpacho ingredients together in a large bowl. Cover then set aside to marinate, preferably 12 to 24 hours, or at least 3 hours. (Note 3)","images":[],"step":1},{"title":"Blitz","description":"Transfer everything into a blender and blitz on high until smooth. (Or use a tall jug with a hand blender). For 100% perfectly smooth, pass through a fine mesh strainer or food mill and discard solids (Note 2)","images":[],"step":2},{"title":"Serve","description":"Pour into a bowl. Rest for 15 minutes to let the bubbles subside. Stir, then ladle into bowls.","duration":15,"images":[],"step":3},{"title":"Garnish","description":"Top with diced cucumber, if using, and a swish of olive oil. Serve with crusty bread!","images":[],"step":4}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Spanish"],"categories":["dietary","low-calorie-recipes","no-cook-food","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c93e7300e836', 'en', 'US', 'Immunity Boosting Green Goddess Soup', 'Recipe video above. A feel-good soup packed full of nutrition created to cure winter colds! While you could switch out the veg with whatever you’ve got, I’ve tried various combinations and this is my favourite for best flavour so it doesn’t taste like you’re eating a bowl of hot grass.Don’t skip the spices. Doesn’t look like much but it really makes a difference!', 'https://www.recipetineats.com/tachyon/2022/07/Immunity-Boosting-Green-Goddess-Soup-1.jpg', 15, 0, 15, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_fennel", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 0.01, "unit": "pack of 3 heads"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.007, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.007, "unit": "jar of 40g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 1.75, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_baby_spinach", "quantity": {"value": 5.0, "unit": "bag of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.012, "unit": "carton of 250ml"}}, {"id": "ing_cup_sunflower_seeds", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, diced (Note 1))","1 leek (white part only) or another onion (, diced (Note 1))","1 medium fennel (, chopped (Note 2))","2 celery stems (, roughly chopped)","5 garlic cloves (, roughly minced)","3/4 tsp all spice powder (sub mixed spice)","3/4 tsp cumin powder (sub coriander)","1 medium potato ((any type), peeled, 1.5 cm cubes )","1 head broccoli (, florets (peel and chop stalk too))","2 1/2 tsp cooking / kosher salt","3/4 tsp black pepper","1.75 litres / quarts water (Note 3)","1 cup frozen peas (Note 4)","5 cups (tightly packed) kale leaves (, roughly chopped (1 small bunch, Note 5))","5 cups (tightly packed) baby spinach (Note 6)","3/4 cup thickened cream (Note 7)"]},{"ingredients":["2 tbsp sunflower seeds, toasted (or croutons or other toasted nuts, Note 8)","Cream and/or olive oil for drizzling"],"purpose":"Garnishes"}]', '[{"title":"Sauté aromatics","description":"Heat oil in a very large pot (6L/qt) over medium high heat. Cook onion, leek, celery, garlic and fennel for 5 minutes until softened.","duration":5,"images":[],"step":1},{"title":"Cook spices","description":"Add all spice and cumin, and cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add water, potatoes, broccoli, salt and pepper. Stir, bring to simmer, and simmer for 7 minutes (no lid) until the broccoli is tender.","duration":7,"images":[],"step":3},{"title":"Add peas","description":"Add peas, simmer for 1 minute.","duration":1,"images":[],"step":4},{"title":"Blitz in kale","description":"Remove pot off the stove. Add kale, push it under the liquid, then blitz with a stick blender until mostly smooth. Add spinach, push under the liquid then blitz again until smooth as possible (approx 3 to 5 mins). This will result in a smooth soup but with little green bits in it - I like this for a little texture.","images":[],"step":5},{"title":"Serve","description":"Stir in cream. Ladle into bowls, drizzle with extra cream and/or olive oil and finish with a sprinkle of sunflower seeds. Eat and feel great!","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","low-calorie-recipes","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b5556e564bb', 'en', 'US', 'Fish Seasoning - for any fish', 'Recipe video above. This is a great spice seasoning for fish that makes for a quick and easy way to add flavour to fish. Based on Old Bay Seasoning, it''s a combination of spices that works really well together. I''ve used flathead fillets today, but it can be used for any fish suitable for pan-frying. Don''t worry if you don''t have all the spices, there''s plenty of subs. Allow ~180g/6oz fish per person.', 'https://www.recipetineats.com/tachyon/2021/06/Fish-Seasoning-Flathead-_6.jpg', 5, 10, 15, 4, '[{"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_mace", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 tsp celery salt ((or 3/4 tsp salt])","1/4 tsp black pepper","1 tsp smoked paprika","1/2 tsp mustard powder","1/4 tsp mace","1/4 tsp allspice","1/8 tsp ground clove","1/8 tsp ginger powder","1/8 tsp cayenne pepper (or pure chilli powder)","1/8 tsp ground cardamom"],"purpose":"Fish Seasoning (Note 1 for subs):"},{"ingredients":["750g / 1.5lb fish fillets (, skinless, boneless (I used flathead, Note 2))","45g / 3 tbsp unsalted butter","30g / 2 tbsp Extra unsalted butter – for drizzling (optional)"],"purpose":"Fish:"}]', '[{"title":"Fish Seasoning","description":"Place ingredients in a bowl and mix to combine. It will keep for months in an airtight container. This quantity is enough for 750g / 1.5lb fish (serves 4 people)","images":[],"step":1},{"description":"Seasoning and cooking fish:","images":[],"step":2},{"title":"Season fish","description":"Sprinkle Seasoning on both sides of fish. Lightly rub to spread Seasoning.","images":[],"step":3},{"title":"Cook fish in two batches","description":"Melt 30g / 2tbsp butter in large non-stick skillet over medium high heat. Cook fish until golden on each side (see Cook times below). Remove to a plate.","images":[],"step":4},{"title":"Cook remaining fish","description":"Melt remaining butter in skillet and cook remaining fish.","images":[],"step":5},{"title":"Rest","description":"Rest fish for 3 minutes before serving with extra butter sauce (see next step).","duration":3,"images":[],"step":6},{"title":"Extra butter sauce (optional)","description":"Add extra butter into pan over medium heat and melt until foaming. Drizzle over fish when serving.","images":[],"step":7}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","fish-recipes","low-calorie-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e573b3148f8', 'en', 'US', 'Tuna Steak', 'Recipe video above. The perfect tuna steak is seared on the outside and deliciously rare on the inside. It takes 2 1/2 minutes flat - fastest fish recipe ever! Tuna loin is lean so best served raw or rare if cooked, to enjoy the tender, almost creamy flesh. There''s a reason why tuna is a darling of the fine dining scene! Best served just slightly warm or at room temperature. Pictured with Sauce Vierge, a summery, simple French salsa / vinaigerette sauce that pairs perfectly with fish!', 'https://www.recipetineats.com/tachyon/2021/05/Tuna-Steak-Main_2.jpg', 5, 3, 8, 2, '[{"id": "ing_x_180_200g_tuna_2_5_3cm_1_1_2_thick", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sauce_vierge", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chervil", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 x 180 - 200g (6.5 - 7oz) tuna (skinless, boneless). 2.5-3cm / 1-1.2\" thick (Note 1)","1 tsp olive oil","1/4 tsp sea salt","1/8 tsp black pepper"]},{"ingredients":["2 tsp olive oil (, or oil spray)"],"purpose":"Cooking:"},{"ingredients":["Sauce Vierge (French salsa / vinaigrette for fish)","Chervil sprigs (substitute small flat leaf or curly parsley leaves) or small edible flowers (optional)"],"purpose":"Serving suggestion (Note 2):"}]', '[{"title":"Prepare resting tray","description":"Place a rack on a tray. (Note 3)","images":[],"step":1},{"title":"Oil and season tuna","description":"Drizzle half the oil over the tuna. Smear over one side, then sprinkle with half the salt and pepper. Flip and repeat.","images":[],"step":2},{"title":"Heat skillet","description":"Heat skillet (preferably a skillet with grille lines) over high heat until smoking hot. The hotter, the better!","images":[],"step":3},{"title":"Oil skillet (if required)","description":"If your skillet is not well-seasoned, brush skillet with olive oil or take pan off stove and spray with any oil (SAFETY WARNING! Note 4)","images":[],"step":4},{"title":"Cook first side","description":"Place tuna steak in the skillet (I do one at a time for best results, Note 5) and cook for 45 seconds.","duration":0.75,"images":[],"step":5},{"title":"Rotate for grill lines","description":"Turn steak 45 degree. Continue cooking another 45 seconds.","images":[],"step":6},{"title":"Cook other side","description":"Flip tuna carefully, then leave for 1 minute or until the internal temperature in the middle reads 48°C / 118°F (Note 6).","duration":1,"images":[],"step":7},{"title":"Rest","description":"Remove tuna from skillet and place on rack. Rest for 5 minutes – it will cool down almost to room temperature. This is desirable for easier slicing and better eating (Note 7) Serve! See Note 2 for sauce options.","duration":5,"images":[],"step":8},{"title":"Plating up","description":"with Sauce Vierge option (pictured):","images":[],"step":9},{"title":"Slice, if desired (Note 7)","description":"Place tuna on a board with criss-crossing grill lines facing up. Slice the tuna into 4 or 5 thick slices, holding the edges with your fingers as needed to ensure the seared surface doesn''t crumble. Transfer to serving plate and separate the slices slightly so they insides are just visible, or on an a slightly angle, overlapping each other.","images":[],"step":10},{"title":"Sauce Vierge","description":"Spoon the Sauce Vierge over steaks, leaving small piles of tomato here and there on the tuna slices, and a few on the plate. Other sauce options: See Note 2.","images":[],"step":11},{"title":"Finishing","description":"Drizzle with a bit of olive oil. It looks beautiful as it is, but if you want to raise the bar even higher, add a few small sprigs of chervil and some edible flowers!","images":[],"step":12}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Universal","Western"],"categories":["dietary","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","low-calorie-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d684710170c', 'en', 'US', 'Whole Baked Fish – Herb-stuffed with Garlic & Dill Butter Sauce', 'Recipe video above. For anyone who''s wondered how to cook a whole fish, the best and easiest way is to bake it whole. The flesh is at its juiciest and most tender, and it''s completely effortless! Roasting fish this way is easy enough for midweek meals, but still makes an impressive centrepiece for occasions! I''m using a whole snapper today, but this recipe will work for virtually any fish. See Note 1 for other fish ideal to cook whole.', 'https://www.recipetineats.com/tachyon/2021/04/Whole-Baked-Fish_7.jpg', 10, 20, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_dill_sprigs_packed", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_dill", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["2 x 800g / 1.6 lb whole snapper or other whole fish (, scaled, gutted and cleaned (Note 1))","1 1/2 tsp salt (, kosher/cooking (not table salt))","1/2 tsp black pepper","2 tbsp extra virgin olive oil"]},{"ingredients":["1/2 cup fresh dill sprigs, packed","1/2 cup parsley leaves, packed","4 garlic cloves (, finely sliced)","1 lemon (, sliced (8 slices each lemon))"],"purpose":"Stuffing:"},{"ingredients":["150g / 10 tbsp unsalted butter (, cut into cubes)","2 tsp garlic (, finely minced)","1 tbsp fresh dill (, finely chopped)"],"purpose":"Dill Garlic Butter:"}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan). Line a tray with parchment/baking paper.","images":[],"step":1},{"title":"Trim fins","description":"Cut all fins off the fish using scissors – both fins on the side, and the fins on the back and underside of the fish (but not the tail).","images":[],"step":2},{"title":"Slash flesh","description":"Cut 3 slashes on each side of the fish, cutting through flesh down to the bone (see photos in post and/or video, helpful!).","images":[],"step":3},{"title":"Stuff fish (Note 2)","description":"Sprinkle a bit of salt and pepper inside the cavity of the fish. Scatter the cavity with garlic slices, then stuff with parsley and dill. Layer lemons on top of herbs.","images":[],"step":4},{"title":"Tie fish (Note 3)","description":"Using kitchen string make 3 ties to hold fish together.","images":[],"step":5},{"title":"Season skin","description":"Sprinkle remaining salt and pepper on the skin (both sides), including a bit on the head of the fish. Then drizzle with olive oil. Rub all over the fish, including in the slashes.","images":[],"step":6},{"title":"Bake 20 minutes (Note 4)","description":"Place fish on prepared tray. Bake for 20 minutes or until the internal temperature is 55°C/131°F (insert thermometer in the thickest part of the fish, not against the bone). Alternatively, use a small knife at one of the cut slits in the fish to prise a bit of meat gently away from the spine. If it flakes away from the bone without resistance, it''s done.","duration":20,"images":[],"step":7},{"title":"Rest","description":"Remove from oven, transfer to serving platter and leave it to rest for 5 minutes. The internal temperature will rise to 58°C / 136.5F (\"medium\", ie. just-cooked and not raw at all, very juicy and moist).","duration":5,"images":[],"step":8},{"description":"Serve with Garlic & Dill Butter Sauce on the side. Either pour over the butter just prior to serving the fish, or let everyone help themselves. See this video by Serious Eats for a concise tutorial for how to carve and serve a whole roasted fish.","images":[],"step":9},{"description":"Garlic & Dill Butter Sauce:","images":[],"step":10},{"title":"Melted butter","description":"Place butter in a saucepan over medium-high heat. Once melted, add garlic and cook, stirring, for 45 seconds to 1 minute until it smells ridiculously good and you''re salivating!","duration":0.75,"images":[],"step":11},{"title":"Add dill","description":"Remove from heat. Stir in dill. Use per recipe.","images":[],"step":12}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","mains","other","seafood-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_82881b115ad1', 'en', 'US', 'Slow-Roasted Crispy Pork Belly', 'Recipe video above. This is a pork belly that''s slow-roasted so the fat renders and cooks the belly confit-style in its own fat. The result? Ridiculously juicy, impossibly tender yet still-sliceable meat, crowned with the most amazing crispy crackling of your life. It comes down to three simple, game-changing techniques: 1. Do NOT score the skin; 2. Low heat followed by high heat; 3. Keep the pork level using balls of foil.Perfect meat, perfect crackling ... Every. Single. Time! (Read the post for all the details on how to do it right!)Bonus: Excellent for make ahead, reheats 99% perfectly the next day. See notes.', 'https://www.recipetineats.com/tachyon/2021/04/Overhead-slow-roasted-pork-belly.jpg', 5, 180, 185, 4, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_fennel_powder_fennel_seeds", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_apples", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_vermouth_jus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_see_in_post_for_more_sauce_options", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1kg / 2 lb pork belly with skin on","1 1/2 tsp olive oil (, divided)","1/2 tsp fennel powder / ground fennel seeds (, optional, Note 3)","1 tsp salt (, cooking/kosher salt (or 7/8 tsp table salt), divided)","1/4 tsp black pepper"]},{"ingredients":["Apple Sauce ()","Vermouth Jus ()","Cauliflower Puree (, (Note 2))","See in post for more Sauce options"],"purpose":"For serving (as pictured in post):"}]', '[{"title":"Dry skin overnight","description":"Place pork belly on a plate. Pat skin dry with paper towels. Leave uncovered in fridge overnight to dry out the skin. (If you don''t have time, pat the skin dry as best you can).","images":[],"step":1},{"description":"Preheat oven to 140°C/285°F (120°C fan).","images":[],"step":2},{"title":"Season flesh","description":"Drizzle flesh (only) with 1 tsp oil. Sprinkle over 1/2 tsp salt, the pepper and fennel powder. Rub all over the flesh, including on the sides, being sure you get right into all the cracks and crevices.","images":[],"step":3},{"title":"Wrap in foil","description":"Place 2 pieces of foil on a work surface. Put the belly in middle of foil, skin side up. Fold the sides in to enclose the belly, forming an open box, pinching corners to seal tightly and make it as snug as possible. Place meat on a tray.","images":[],"step":4},{"title":"Season skin","description":"Pat skin dry with paper towels. Rub with 1/2 tsp oil then sprinkle remaining 1/2 tsp salt evenly all over the skin surface, from edge to edge.","images":[],"step":5},{"title":"Slow roast 2 1/2 hours","description":"Place in the oven and roast for 2 1/2 hours. After 1 1/2 hours, remove and tighten the foil (pork will have shrunk), and continue cooking. This keeps the pork fat level up as high as possible, and the flesh protected so it stays moist.","images":[],"step":6},{"title":"Increase heat","description":"Remove pork from oven, then increase heat to 240°C/465°F (all oven types).","images":[],"step":7},{"title":"Level pork","description":"Remove pork from foil and place on a rack set over a tray (using rack is best, but optional). Use scrunched up balls of foil stuffed under pork to prop up so the skin surface is as level and horizontal as possible (see photos in post).","images":[],"step":8},{"description":"30 minutes on high heat! Place the pork back in the oven for 30 minutes, rotating after 15 minutes as needed, until the crackling is deep golden, puffy and crispy all over. If some patches are browning faster, protect with foil patches. ⚠️ Open oven with care as it will be smokey - open your windows!","duration":30,"images":[],"step":9},{"title":"Rest 10 minutes","description":"Remove pork from oven. Rest for 10 minutes before slicing.","duration":10,"images":[],"step":10},{"title":"Serving","description":"Slice into 2cm / ⅘\"-thick slices using a serrated knife. Pictured in post with Apple Sauce and Vermouth Jus, with a side of Cauliflower Puree (Note 2)! See directions in post for how to plate it up as pictured (fine dining style!), as well as a list of more sauce options.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","iconic-dishes","mains","pork","pork-recipes","roasts","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c6510f43ab62', 'en', 'US', 'Garlic Butter Salmon recipe', 'Recipe video above. This is a simple-yet-luxurious, cheffy way to cook salmon. By basting continuously with foaming garlic butter, it seeps into every crack and crevice of the salmon and gives it the ultimate buttery crust.It may seem like a lot of butter for one recipe, but you need it to ensure good basting coverage. You do not have to use all of it for serving. Save leftover butter (even if just a smear!) and pan fry bread with it tomorrow, see post for photos. It''s Amazing – with a capital A!', 'https://www.recipetineats.com/tachyon/2021/03/Garlic-Butter-Salmon_9.jpg', 5, 8, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.03, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["4 salmon fillets ((180g/6oz each), skinless and boneless)","1/2 tsp salt (, cooking / kosher)","1/4 tsp black pepper","1 1/2 tbsp olive oil","1 tbsp garlic (~2 cloves) (, finely minced by hand (don''t use a garlic press))","90g / 6 tbsp salted butter (, cut into cubes (or unsalted + 1/4 tsp salt))","1 tsp lemon juice (, plus more to taste)","2 tsp parsley (, finely chopped)"]}]', '[{"title":"Season salmon","description":"Take salmon out of fridge 30 minutes prior to cooking. Sprinkle both sides with salt and pepper.","images":[],"step":1},{"title":"Sear salmon 3 mins","description":"Heat oil in large non stick skillet over medium-high heat. Add salmon, presentation side (ie. curved side) down, and cook for 3 minutes until golden.","duration":3,"images":[],"step":2},{"title":"Turn, cook 1 min, then add butter","description":"Turn salmon and cook the other side for 1 minute. THEN put the butter in.","duration":1,"images":[],"step":3},{"title":"Baste 1 1/2 minutes","description":"Once butter is melted and foaming, add garlic and immediately start spooning the bubbling butter continuously over the salmon for 1 1/2 minutes. To do this, tilt the pan slightly so the butter pools on one side. Use a large spoon to scoop the butter up and spoon it over the salmon.","images":[],"step":4},{"title":"Remove salmon from stove","description":"Check Internal temperature of salmon. It should be 50°C/122°F for medium-rare (optimum juiciness pull temp). Remove salmon to a plate. Rest for 3 minutes – it will rise to 53°C/127°F. (See Note 2 for internal temperatures)","duration":3,"images":[],"step":5},{"title":"Add lemon juice to butter","description":"Put pan back on unlit stove to keep butter hot. Add lemon juice.","images":[],"step":6},{"title":"Serve","description":"Place salmon on serving plates. Spoon over butter (be judicious, it''s rich!), garnish with a sprinkle of parsley. Pictured in the post with Cauliflower Mash and leafy greens with French Vinaigrette.","images":[],"step":7}]', '["fish","milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","mains","other","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3a94444db743', 'en', 'US', 'Slow Roast Leg of Lamb', 'Recipe video above. A very forgiving, very easy way to roast a leg of lamb, where the meat is slow-cooked until it''s tender enough to pull it off the bone with tongs. It is not the blushing pink flesh carving sort (use this traditional Roast Lamb recipe if that''s what you''re after). Lamb leg is lean, so to slow cook it''s best to partially submerge in a flavoured liquid which keeps the flesh moist plus infuses with flavour. I''m using garlic and rosemary in this recipe - classic lamb flavours!**IMPORTANT** Lamb leg is lean so it should only be cooked for 1.5 hours until blushing pink & juicy (per this traditional Roast Lamb recipe) or slow cooked for 4.5 hrs until fall apart (this recipe). Anything in between is tough and not nice! For more roast lamb recipes, browse the recipe collection or take my Roast Lamb Matchmaker to find your perfect recipe!', 'https://www.recipetineats.com/tachyon/2020/04/Slow-Roasted-Lamb-Leg-featured-image.jpg', 15, 315, 330, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.25, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2.25 kg / 4.5 lb leg of lamb (, bone in (or shoulder) (Note 1))","1 1/2 tsp cooking salt / kosher salt (double for flakes)","1/2 tsp black pepper","1 1/2 tbsp olive oil","1 whole garlic head (, unpeeled, cut in half horizontally)","1 onion (, quartered (unpeeled is fine))","2 rosemary sprigs (2 = whisper of rosemary flavour, 4 sprigs = stronger flavour)","3 cups beef stock/broth (, low sodium (or homemade))","2 cups water"]},{"ingredients":["4 tbsp plain flour (all-purpose flour)","1 cup water","Salt and pepper (, to taste)"],"purpose":"Gravy:"}]', '[{"description":"Season leg with salt and pepper, place upside down on garlic, onion and rosemary. Pour liquids in, drizzle with oil, cover with foil. Roast 4 1/2 hours at 170°C/335°F (150°C fan) until meat is pull-apart tender. Flip, return to oven 20 - 30 minutes at 200°C/390°F (180° fan) until well browned. Make gravy while resting.","images":[],"step":1},{"description":"Preheat oven to 170°C/335°F (150°C fan-forced).","images":[],"step":2},{"description":"Place garlic, onion and rosemary in a metal roasting pan.","images":[],"step":3},{"title":"Season lamb","description":"Place lamb leg right side up in the pan. (Note 2) Sprinkle the surface with half the salt and pepper and rub it in.","images":[],"step":4},{"description":"Turn lamb over and place it so it mostly sits on the garlic and onion. Sprinkle with remaining salt and pepper, rub it in. (Video helpful here)","images":[],"step":5},{"title":"Add liquids and cover","description":"Drizzle lamb with olive oil. Pour broth and water around the lamb - it won''t cover it, that''s ok, the lamb sinks into it. Cover with foil (don''t use a lid, you want a bit of liquid to steam out).","images":[],"step":6},{"title":"Slow roast","description":"Place in the oven and roast for 4 1/2 hours. (See Notes for roasting time table)","images":[],"step":7},{"title":"Check meat","description":"Remove from the oven, remove foil. Turn lamb over. Check it to ensure the meat is tender enough to pry a bit off easily with a fork. If not, return, covered, to oven.","images":[],"step":8},{"title":"Brown lamb","description":"Return uncovered lamb to the oven and roast for a further 40 minutes or until well browned all over. (Don''t increase the temperature as then it doesn''t brown as evenly)","images":[],"step":9},{"title":"Rest","description":"Remove lamb, spoon over pan juices generously. Transfer to serving platter, cover loosely with foil while you make the gravy (stays warm for 1 - 1 1/2 hours).","images":[],"step":10},{"title":"Skim fat","description":"Use a large spoon to skim off and discard some of the fat from the surface of the liquid.","images":[],"step":11},{"title":"Add flour","description":"Place pan on the stove on medium high. When the liquid bubbles, add flour. Use a whisk to mix it in - this may take a few minutes as the liquid reduces.","images":[],"step":12},{"title":"Add water","description":"Once it looks like sludge (see video), whisk in 1/2 - 1 cup of water until it becomes a gravy consistency to your taste. Adjust salt and pepper to taste - I rarely add extra salt.","images":[],"step":13},{"description":"Strain gravy into a bowl, pressing juices out of the onion etc. Pour gravy into jug.","images":[],"step":14},{"description":"The meat is tender so you will only need tongs to tear the meat off. Serve with gravy!","images":[],"step":15}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","iconic-dishes","lamb-recipes","main-dishes","roast-lamb","roasts","slow-cooked-fall-apart","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e90cafbc9909', 'en', 'US', 'Garlic Prawns (Shrimp!)', 'Recipe video above. Hands down, my favourite way to cook fresh prawns! Simple and fabulous, the 3 tips for top notch garlic prawns is to chop rather than use a mincer for the garlic (it splatters and burns on high heat), add the garlic partway through cooking (else it burns), and a splash of wine gives this a flavour edge as well as stopping the garlic from burning. Serves 2 - 3 as a main, 4 - 5 as a starter.', 'https://www.recipetineats.com/tachyon/2017/05/Garlic-Prawns_6.jpg', 10, 6, 16, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.03, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["500g / 1lb prawns (shrimp) (, peeled and deveined, tail on (unpeeled weight 1kg/2lb, Note 1))","1/2 tsp cooking/koshfer salt","1/2 tsp black pepper","3 tbsp extra virgin olive oil (separated)","3 tsp finely minced garlic cloves (~ 4 cloves) (use knife, not crusher/mincer)"]},{"ingredients":["40g / 3 tbsp unsalted butter (, cut into 1.5cm / 1/2\" cubes (Note 2))","1/4 cup chardonnay or other dry white wine (Note 3)","1 tbsp lemon juice","1 tbsp parsley, finely chopped (garnish)"],"purpose":"Garlic butter sauce"},{"ingredients":["Lemon wedges","Bread for mopping!"],"purpose":"Serving"}]', '[{"title":"Marinade","description":"Place the prawns, 1 tablespoon olive oil and pepper in bowl. Gently toss then set aside for 20 minutes (no longer else the prawns will sweat from the salt),.","duration":20,"images":[],"step":1},{"description":"Cooking","images":[],"step":2},{"title":"Sear in batches","description":"Heat 1 tablespoon olive oil in a large non-stick frying pan over high heat. Place half the prawns in the pan then sear each side for just 45 seconds, using tongs to turn.","images":[],"step":3},{"title":"Remove & repeat","description":"Remove prawns onto a plate, heat the last 1 tablespoon of oil and cook each side for 45 seconds.","duration":0.75,"images":[],"step":4},{"description":"Return first batch of prawns back into pan.","images":[],"step":5},{"title":"Garlic","description":"Add garlic then stir for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Add wine","description":"it will sizzle and be steamy! Stir, scraping the bottom of the pan, until wine mostly evaporates - around 30 seconds.","images":[],"step":7},{"title":"Butter & lemon","description":"Scatter butter across pan, add lemon juice. Swirl butter around the pan until it melts, then toss through the parsley.","images":[],"step":8},{"title":"Serve","description":"Transfer the prawns and all the butter sauce onto a serving plate. Serve with extra lemon wedges. Bread for mopping is essential - try this simple Crusty Artisan Bread!","images":[],"step":9}]', '["gluten","milk","shellfish"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","gluten-free-recipes","main-dishes","prawns-shrimp","quick-and-easy","seafood-recipes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_83ce9102cb6e', 'en', 'US', '45 Cal Creamy HEALTHY Soup!', 'Recipe video above. {Low Cal, GF, low carb} My secret method to make a really low calorie creamy soup that is seriously delicious! Using boiled PEELED zucchini, simmer until soft then blitz into what looks like everybody''s favourite calorie-laden creamy broths.....but it''s guilt free. Zucchini is ideal - purees smooth, neutral flavour that''s easily disguisable. It doesn''t taste like zucchini - just a savoury creamy soup. I''ve used it to make a healthy version of homemade Cream of Chicken Soup. But imagine the possibilies - use it in place of any soup that has a creamy white broth!', 'https://www.recipetineats.com/tachyon/2020/01/Super-Skinny-Cream-of-Chicken-Soup_6.jpg', 10, 20, 30, 5, '[{"id": "ing_zucchini", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 0.6, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.5, "unit": "head"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700g/ 1.2 lb zucchinis ((4 largish), peeled and cut into 1.5cm / 3/5\" slices)","1/2 large onion (, roughly chopped (brown, white, yellow))","2 garlic cloves (, whole)","2 cups (500 ml) chicken broth (or veg broth)","2 cups (500 ml) water","1/2 tsp each garlic and onion powder (or 1 tsp of one of them)","1/4 tsp black pepper","1 cup (250 ml) 0% fat milk (or other milk of choice)"],"purpose":"Healthy Creamy Soup Broth:"},{"ingredients":["1 tbsp (15g) butter or olive oil","2 garlic cloves (, minced)","1/2 large onion (, finely chopped)","1.5 cups carrot (, peeled and finely diced)","1.5 cups celery (, finely chopped)","1 small red capsicum/bell pepper (, finely chopped)","1.5 cups cooked chicken breast (, diced)","3/4 cup frozen peas"],"purpose":"Soup Add Ins:"},{"ingredients":["Fresh thyme (high recommended, or sub chives)"],"purpose":"Garnish:"}]', '[{"description":"Healthy Creamy Broth:","images":[],"step":1},{"description":"Place all Broth ingredients EXCEPT milk into a pot, cover with lid and bring to energetic simmer over medium high heat.","images":[],"step":2},{"description":"Lower to medium and simmer for 15 minutes until zucchinis is very soft.","duration":15,"images":[],"step":3},{"description":"Remove from heat, add milk. Use a handheld blender to blitz until smooth. Add salt to taste. Marvel at creamy broth with so few calories!","images":[],"step":4},{"description":"Healthy Cream of Chicken Soup:","images":[],"step":5},{"description":"Melt butter in a pot or large saucepan over medium heat.","images":[],"step":6},{"description":"Add garlic, onion, carrot and celery. Cook for 3 minutes, then add capsicum. Cook for another 2 minutes until onion is translucent and sweet.","duration":3,"images":[],"step":7},{"description":"Add Broth, chicken and peas. Bring to gentle simmer for just 2 to 3 minutes or until peas are cooked.","images":[],"step":8},{"description":"Taste and adjust salt and pepper.","images":[],"step":9},{"description":"Ladle into bowls, sprinkle with a pinch of fresh thyme leaves. Devour, and marvel at how such a creamy, totally delicious bowl of soup has so few calories!!","images":[],"step":10}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31e4a72ef630', 'en', 'US', 'Fish Fingers', 'Recipe video above. Fish Fingers so perfectly golden and crunchy it''s hard to believe they''re BAKED rather than fried! Toasting the breadcrumbs makes all the difference because fish cooks in the oven so much faster than it takes to brown the breadcrumbs. BONUS: This is a mess free breading technique!', 'https://www.recipetineats.com/tachyon/2020/01/Fish-Fingers_5.jpg', 15, 15, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_paprika", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_tartare_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600g / 1.2lb white fish fillets (, patted dry (Note 1))","Oil spray (olive oil or any plain)"]},{"ingredients":["1 1/2 cups (75g) panko breadcrumbs (Note 2)","1/4 cup (25g) parmesan","2 tsp paprika (, optional)","1/2 tsp salt and pepper (, each)"],"purpose":"Crumb"},{"ingredients":["1 egg","1 tbsp mayonnaise","2 tbsp flour","1/4 tsp salt and pepper (, each)"],"purpose":"Batter"},{"ingredients":["Tartare sauce or other seafood dipping sauce","Lemon wedges","Finely chopped chives or parsley (, garnish (optional))"],"purpose":"Serving"}]', '[{"description":"Preheat oven to 180°C / 350°F.","images":[],"step":1},{"title":"Toast breadcrumbs","description":"Spread breadcrumbs on tray. Spray with oil, bake 4 minutes until golden. Transfer toasted breadcrumbs into bowl, add remaining Crumb ingredients and mix.","images":[],"step":2},{"description":"Increase oven to 220°C / 425°F (fan 200°C). Spray used tray with oil.","images":[],"step":3},{"title":"Batter","description":"Mix Batter ingredients in a separate bowl.","images":[],"step":4},{"description":"Cut the fish into strips 1.5 x 11 cm / 3/5 x 4.5\" (they shink 30% in length).","images":[],"step":5},{"description":"Place fish in Batter, gently mix with rubber spatula to coat. Do not leave sitting around (will become watery), coat immediately.","images":[],"step":6},{"title":"Breading","description":"Pick up fish with tongs, place in breadcrumbs. Spoon over crumb, use fingers to press to adhere.","images":[],"step":7},{"title":"Baking","description":"Transfer to baking tray. Spray with oil, bake 13 minutes or until crispy on the outside.","images":[],"step":8},{"description":"Serve immediately with lemon wedges, Tartare Sauce or other Sauce of choice - see here for recipes, any of these great for fish fingers! Also Note 3 for few quick sauce options.","images":[],"step":9}]', '["egg","fish","gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","fish-recipes","low-calorie-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2112cd9cfad7', 'en', 'US', 'Pizza Stuffed Mushrooms', 'Recipe video above. This is the sort of recipe that you can absolutely make your own with your favourite pizza toppings! TIP: avoid watery filling by cutting a small cross in the cap of the mushroom to let excess water drain out as it bakes. Serve as a light meal, or serve 2 as a main meal.', 'https://www.recipetineats.com/tachyon/2019/07/Pizza-Stuffed-Mushrooms_0.jpg', 10, 20, 30, 5, '[{"id": "ing_mushroom", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_salami", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_black_olive_slices", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}]', '[{"ingredients":["5 large mushrooms (, 10cm/4\" wide (portobello, flat mushrooms etc, Note 1))","2 tbsp olive oil","Salt and pepper","2/3 cup pizza sauce (I use store bought)","100g/ 3.5 oz salami slices (, chopped)","1/4 red onion (, finely chopped)","1/3 cup black olive slices","1 cup (100g) mozzarella cheese (, shredded )"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Carefully break or cut the stems off the mushrooms.","images":[],"step":2},{"description":"Chop stems (will use as filling).","images":[],"step":3},{"description":"Place mushrooms cap side up. Using a small, sharp, THIN knife, cut a small cross in the mushroom, taking great care not to split the mushroom (to drain excess water, Note 2)","images":[],"step":4},{"description":"Brush the tops with oil, then quickly sprinkle on salt and pepper (be fast so it sticks!)","images":[],"step":5},{"description":"Flip then lightly dab the inside with remaining oil, sprinkle with salt and pepper.","images":[],"step":6},{"description":"Fill mushrooms with pizza sauce, sprinkle with chopped mushroom, onion, half salami and half olives.","images":[],"step":7},{"title":"Bake 1","description":"Bake 10 minutes, remove from oven.","images":[],"step":8},{"description":"Top with cheese, remaining salami and olives.","images":[],"step":9},{"title":"Bake 2","description":"Bake further 10 minutes until cheese is melted. Serve immediately!","images":[],"step":10},{"description":"Preheat BBQ to medium high.","images":[],"step":11},{"title":"Follow above steps in closed BBQ","description":"10 minutes for Bake 1, then 5 - 8 minutes for Bake 2.","images":[],"step":12}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","low-calorie-recipes","mushroom-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5413fbde8c0', 'en', 'US', 'Oven Baked Sausages with Potatoes, Vegetable AND Gravy!', 'Recipe VIDEO above. Cooking sausages in the oven with vegetables and gravy is a terrific quick dinner idea that takes mere minutes to assemble! The sausages get nicely browned, the vegetables tender, and a flavour packed gravy. Kind of like making a stew!', 'https://www.recipetineats.com/tachyon/2018/03/Sausage-Bake_4-1.jpg', 15, 45, 60, 4, '[{"id": "ing_potato", "quantity": {"value": 700.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sausages", "quantity": {"value": 9.0, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.4, "unit": "kg"}}]', '[{"ingredients":["700g / 1.4 lb baby potatoes (, halved)","3 carrots (, peeled and cut into 2\"/5cm pieces)","2 red onions (, each cut into 8 wedges)","2 garlic cloves, minced","2 tbsp olive oil","2 tsp dried thyme","1 tsp dried oregano","Salt and pepper"],"purpose":"Vegetables"},{"ingredients":["8 - 10 sausages (500-700g / 1-1.4lb) (Note 2)","Oil spray (optional)"],"purpose":"Sausages"},{"ingredients":["2 tbsp / 30g melted butter, unsalted","2 1/2 tbsp flour (plain / all purpose)","2 cups / 500 ml beef broth (or chicken) ( (Note 3))","Fresh thyme (, for garnish (optional))"],"purpose":"Gravy"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan / convection).","images":[],"step":1},{"description":"Place Vegetable ingredients in a large bowl. Toss well to coat.","images":[],"step":2},{"description":"Add sausages and toss briefly.","images":[],"step":3},{"description":"Transfer into roasting pan. Pan should be of a size so the vegetables are stacked about 2 deep - see photos and video. Rearrange sausages so they are on top.","images":[],"step":4},{"description":"In the same bowl used for the vegetables, add butter and flour. Whisk.","images":[],"step":5},{"description":"Add a bit of beef broth and whisk, then whisk in remaining broth. (Don''t worry if you end up with some floating butter bits)","images":[],"step":6},{"description":"Pour down the side of the pan (don''t pour over the sausages or veggies).","images":[],"step":7},{"title":"Optional: Spray sausages with oil","description":"browns slightly better (especially lean sausages).","images":[],"step":8},{"description":"Bake 25 minutes. Turn sausages. Spray again with oil (optional) then bake for a further 25 minutes or until sausages are browned and potatoes are soft.","images":[],"step":9},{"description":"Serve Sausages and Vegetables with Gravy on top, garnished with fresh thyme leaves if desired. (See notes for Gravy thickness adjustment)","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b76c889202ce', 'en', 'US', 'Creamy Vegetable Soup with Noodles (No cream!)', 'Recipe video above. A cream cream-less soup with lots and lots of fresh veggies, plus noodles! Use 7 - 8 cups of diced vegetables of choice, including onion. If making ahead or you know you''ll have leftovers, cook the pasta separately and place in the bowl, then ladle over soup (because noodles left in soup becomes bloated and overly soft). Make it Gluten Free by using GF pasta and cornflour sub to thicken soup (Note 2).', 'https://www.recipetineats.com/tachyon/2018/09/Cream-of-Vegetable-Soup-with-Noodles_1a.jpg', 10, 20, 30, 4, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegeta", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.5, "unit": "can of 400g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["50g (3 tbsp) butter (, unsalted)","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","1 tsp dried thyme","1/3 cup (70g) flour (Note 2 cornflour/cornstarch GF)","3 cups (750 ml) milk (, any (I use low fat))","2 cups (500 ml) vegetable or chicken broth (, low sodium)","1 cup (250 ml) water","3 tsp Vegeta or other stock powder (Note 1)","200g / 7oz linguine or other pasta (, broken into 4 pieces)","Salt and pepper to taste"]},{"ingredients":["2 carrots (, diced)","2 celery ribs (, diced)","1 red capsicum/bell pepper (, diced)","1 cup corn kernels (, frozen or canned drained)","1 cup frozen peas"],"purpose":"Vegetables (sub 8 cups any diced veg):"},{"ingredients":["Fresh thyme leaves"],"purpose":"Optional garnish:"}]', '[{"description":"Melt butter in a large pot over medium high heat. Add garlic and onion, cook for 2 minutes. Then add carrot and celery. Cook for a further 2 minutes, then add capsicum and cook for another 1 minute.","duration":2,"images":[],"step":1},{"description":"Add flour and mix, cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add about half the broth and mix. Once flour is incorporated into the broth, add remaining broth, milk, water, dried thyme, Vegeta and pepper. Mix, then add corn and peas.","images":[],"step":3},{"description":"Bring to simmer then lower heat slightly.","images":[],"step":4},{"description":"Break pasta into 4 pieces and add into pot. Cook for 10 minutes or until pasta is just cooked. Adjust salt and pepper to taste.","duration":10,"images":[],"step":5},{"description":"Ladle into bowls and serve, garnished with a tiny sprinkle of fresh thyme leaves if desired.","images":[],"step":6}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9a05a24052e5', 'en', 'US', 'Vegetable Pasta - One Pot!', 'Recipe video above. A quick healthy dinner with more veg and less pasta, all made in one pot! For a lower cal option, skip the cheese and serve with parmesan sprinkled on top. Workflow: Get the onion cooking while you prep the other ingredients.', 'https://www.recipetineats.com/tachyon/2018/09/One-Pot-Vegetable-Pasta_3.jpg', 5, 15, 20, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.5, "unit": "can of 400g"}}, {"id": "ing_broccoli", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.006, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","2 zucchinis* (, halved lengthwise and cut into sliced 0.8cm / 1/3\" slices)","1 red capsicum/bell pepper* (, halved and sliced)","1 cup corn* (frozen or canned)","1 broccoli* (, broken into bite size florets)","250g/ 0.5lb ziti/penne (, or other short pasta (Note 1))","800 g / 28 oz crushed tomato","1.5 cups / 375 ml vegetable or chicken broth","2 tbsp tomato paste","1 tbsp Italian herb mix (or other dried herbs)","1 tsp garlic powder","1/2 tsp red pepper flakes (chilli flakes, adjust spiciness to taste)","1.5 tsp salt","0.5 tsp black pepper"]},{"ingredients":["1.5 cups shredded cheese of choice (Cheddar, tasty, Monterey Jack etc)"],"purpose":"Optional:"},{"ingredients":["Finely chopped parsley (optional)","Parmesan (if not using cheese)"],"purpose":"To serve:"}]', '[{"description":"Heat oil in a large pot over medium. Add garlic and onion - cook slowly for 3 to 4 minutes until onion is translucent and sweet.","duration":3.5,"images":[],"step":1},{"description":"Turn heat up to medium high, add zucchini and capsicum. Cook 1 1/2 minutes.","images":[],"step":2},{"description":"Add remaining ingredients EXCEPT pasta and broccoli. Stir until tomato paste dissolves.","images":[],"step":3},{"description":"When liquid starts bubbling, lower heat to medium, add pasta and stir. Top with broccoli, push in.","images":[],"step":4},{"description":"Place lid on and cook for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Remove lid. Cook for another 3 to 4 minutes, stirring frequently, until pasta is almost cooked through and most of the liquid has been absorbed by the pasta.","images":[],"step":6},{"description":"Stir through half the cheese (if using). Adjust salt and pepper to taste.","images":[],"step":7},{"description":"Top with remaining cheese, put lid on. Leave for 1 minute until cheese is melted and pasta is perfectly cooked.","duration":1,"images":[],"step":8},{"description":"Garnish with parsley and serve immediately. Don''t leave leftovers in the pot, residual heat will overcook the pasta so transfer into a serving dish.","images":[],"step":9}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","low-calorie-recipes","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6a84414fab73', 'en', 'US', 'Prawn Risotto (Shrimp)', 'This is a great everyday prawn risotto that’s a cut above basic risottos. Searing the prawn (shrimp) makes a terrific flavour base that compensates for not using a homemade seafood stock. And as long as you use a large pot, you don’t need to stand at the stove for 20 minutes to stir constantly and add hot broth a ladle at a time for ultra creamy risotto – read more in post. Recipe video below.', 'https://www.recipetineats.com/tachyon/2018/05/Prawn-Risotto_0.jpg', 10, 25, 35, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 – 2 tbsp olive oil","400 – 500g (14oz – 1 lb) prawns/shrimp, raw, peeled (Note 1)","Salt and pepper","1 1/2 tbsp (20g) butter","1/2 onion (, finely chopped)","2 garlic cloves (, minced)","1/3 cup (85 ml) dry white wine (or water)","1 1/2 cups (270g) Arborio rice (, uncooked (Note 2))","3 cups (750ml) chicken broth (, low sodium, at room temp)","1 cup (250 ml) milk (, room temp (full or low fat))","1 cup (150g) frozen peas (, thawed)","1/3 cup (40g) grated parmesan"]},{"ingredients":["1 – 2 tbsp (15 – 30g) Extra Butter","Grated parmesan","Finely chopped parsley (optional)"],"purpose":"Finishing / serving:"}]', '[{"description":"Heat 1 tbsp oil in a large heavy based pot over medium high heat. Spread half the prawns in a single layer, sprinkle with salt and pepper. Cook for 1 ½ minutes, then turn and cook the other side for 1 minute. Remove into bowl.","duration":1,"images":[],"step":1},{"description":"Add a touch more oil and repeat with remaining prawns. Set aside and keep warm.","images":[],"step":2},{"description":"Turn heat down to medium. Melt butter in pot then add onion and garlic. Cook for 2 minutes until translucent.","duration":2,"images":[],"step":3},{"description":"Add wine, and stir, scraping the bottom of the pot to mix the brown bits from the prawn into the liquid. Bring to simmer and cook for 2 minutes until harsh alcohol smell is gone.","duration":2,"images":[],"step":4},{"description":"Add rice and stir for 30 seconds until rice is translucent on edges.","duration":0.5,"images":[],"step":5},{"description":"Add about 2/3 of the chicken broth. Stir, bring to simmer. Adjust heat so it’s simmering gently.","images":[],"step":6},{"description":"Simmer for 5 minutes. Stir, then simmer for a further 2 minutes until broth is mostly absorbed and rice is visible on the surface (see video and photos).","duration":5,"images":[],"step":7},{"description":"Add remaining broth and milk. Stir, simmer for 3 minutes. Stir, simmer for 2 minutes.","duration":3,"images":[],"step":8},{"description":"Risotto should be soupy and rice still a tiny bit undercooked.","images":[],"step":9},{"description":"Add peas and parmesan, quickly stir.","images":[],"step":10},{"description":"Taste, then add salt and pepper, then quickly stir.","images":[],"step":11},{"description":"Add Extra Butter, then stir vigorously for 10 seconds (this is the step that makes it very creamy).","duration":0.16666666666666666,"images":[],"step":12},{"description":"Lastly, gently stir through prawns (tip in any juices too).","images":[],"step":13},{"description":"Remove risotto from heat, it should be porridge-like. (Note 3, see video) To loosen, add hot tap water 2 tbsp at time and stir through.","images":[],"step":14},{"description":"Give it a good final stir just before serving. Then ladle into bowls (it should ooze a bit, not be sticky lump). Garnish with parmesan and parsley if desired.","images":[],"step":15}]', '["milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","prawns-shrimp","quick-and-easy","rice-recipes","risotto-recipes","seafood-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cd31ed7ba9a4', 'en', 'US', 'Oven Baked Rice and Vegetables', 'Recipe video above. Fluffy seasoned rice AND oven roasted veggies, all baked in ONE PAN! Imagine the possibilities!', 'https://www.recipetineats.com/tachyon/2017/09/Oven-Baked-Vegetables-and-Rice.jpg', 10, 50, 60, 5, '[{"id": "ing_jasmine_rice", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_zucchini", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.005, "unit": "can of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 cups basmati or jasmine rice (, uncooked (Note 1 for other rice types))","1 1/2 cups (375ml) chicken or vegetable broth (I use chicken)","1 1/4 cups (315ml) water","2 garlic cloves (, minced)","2 medium carrots (, cut into 1 cm thick slices, larger pieces halved)","30g (2 tbsp) unsalted butter (optional)"],"purpose":"Rice:"},{"ingredients":["1 red onion (, halved and cut into wedges)","1 capsicum / bell pepper (, cut into 2.5cm / 1\" pieces)","1/2 small cauliflower (, broken into florets)","2 zucchini (, cut into 2cm / 4/5\" chunks)","2 corn cobs (, each cut into 3 (6 small cobs))","1/4 cup olive oil (, plus more for drizzling)"],"purpose":"Roasting Vegetables (Note 2):"},{"ingredients":["1 1/2 tsp paprika","1 1/2 tsp thyme or other dried herb of choice","1 tsp garlic powder (or onion powder)","1 tsp salt (Note 3 for low sodium)","1 tsp pepper (, plus extra)"],"purpose":"Spice Mix:"},{"ingredients":["Finely chopped parsley"],"purpose":"Garnish (optional):"}]', '[{"description":"Preheat oven to 200C/390F (standard) / 180C/350F (fan / convection).","images":[],"step":1},{"description":"Mix Spice Mix in a small bowl.","images":[],"step":2},{"description":"Place Rice ingredients in a baking dish (including the carrots), about 23 x 30 cm / 9 x 13\". Add 1 1/2 tsp Spice Mix. Stir, cover with foil, bake for 20 minutes.","duration":20,"images":[],"step":3},{"description":"Meanwhile, place Roasting Vegetable ingredients in a large bowl, drizzle with 1/4 cup olive oil. Sprinkle over remaining Spice Mix. Mix well - hands are best for this.","images":[],"step":4},{"description":"Remove rice from oven.","images":[],"step":5},{"description":"Turn oven UP to 220C/430F (standard) / 200C/390F (fan / convection).","images":[],"step":6},{"description":"Take off foil. Spread the Roasting Vegetables on top of the rice. Make sure there''s a bit of each type of vegetable on the surface. Push corn mostly under.","images":[],"step":7},{"description":"Drizzle with more oil (optional), sprinkle with more pepper.","images":[],"step":8},{"title":"Bake for 30 minutes. Remove from oven, rest for 5","description":"10 minutes.","duration":30,"images":[],"step":9},{"description":"Sprinkle with parsley if desired. Push vegetables aside, fluff rice and toss it through the vegetables a bit (rice gets more flavour). Serve!","images":[],"step":10}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","easter-sides-warm-hearty","gluten-free-recipes","one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c29732007fd', 'en', 'US', 'Spanish Healthy Vegetable Soup', 'Recipe video above. This is my version of the famous Zero Weight Watchers Points vegetable soup. Mine has 0.4 WW points but is much MUCH tastier! Spanish flavours inspired by the seasoning for homemade Chorizo (yes, really!), the broth of this soup is MUCh tastier than the Zero WW soup!!!', 'https://www.recipetineats.com/tachyon/2017/07/Healthy-Vegetable-Soup.jpg', 15, 30, 45, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 0.025, "unit": "jar"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_capsicum", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 5.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tsp olive oil","1 onion (, finely chopped)","2 garlic cloves (, minced)","1 tbsp dried oregano","2 tsp fennel seeds (optional)","2 medium carrots (, finely chopped)","1 large celery stalk/rib (, finely chopped)","2 red capsicums / bell peppers (, cut into 2 cm / 4/5” pieces)","5 cups cabbage (, cut into 3 cm / 1.2” pieces (about 400g/14oz))","800g / 28 oz crushed tomato","3 cups (750 ml) vegetable or chicken broth (low fat!)","1 tbsp smoked paprika (or any paprika)","1 tsp cayenne pepper (adjust spiciness to taste)"],"purpose":"Soup:"},{"ingredients":["Salt and pepper to taste","1 lemon – zest + juice to taste","Finely chopped parsley"],"purpose":"Finishes (not optional!):"}]', '[{"description":"Heat oil in a large pot over medium heat. Add garlic and onion, cook for 30 seconds or so.","duration":0.5,"images":[],"step":1},{"description":"Add oregano and fennel seeds, cook for 2 minutes (lets flavour “bloom”).","duration":2,"images":[],"step":2},{"description":"Turn heat down to medium low. Add carrots and celery, cook, stirring regularly, for 8 minutes until onion is sweet (not browned). This step is key to the flavour base of this soup.","duration":8,"images":[],"step":3},{"description":"Add capsicum, turn heat up to high and cook for 2 minutes, stirring constantly.","duration":2,"images":[],"step":4},{"description":"Add remaining Soup ingredients, bring to simmer then place lid on. Turn heat down to medium low, simmer for 25 minutes.","duration":25,"images":[],"step":5},{"description":"Remove lid, adjust salt and pepper to taste.","images":[],"step":6},{"description":"Ladle soup into bowls. Grate over lemon zest, squeeze of lemon juice and sprinkle with parsley. Serve!","images":[],"step":7}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Spanish Style","Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","mediterranean-recipes","quick-and-easy","soup-recipes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92db19b9d29d', 'en', 'US', 'Port Braised Lamb Shanks', 'These lamb shanks are just like what you get at high end restaurants! Port and red wine is the key to the incredible sauce that these lamb shanks are braised in. Get discount bottles - no need to splurge on expense wine for this!', 'https://www.recipetineats.com/tachyon/2016/09/Lamb-Shanks-Port-Braised_4.jpg', 15, 180, 195, 4, '[{"id": "ing_amb_shanks", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_port", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_wine", "quantity": {"value": 2.0, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 5.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 lamb shanks (, approx 400g/13oz each (Note 1))","Salt and pepper","2 tbsp olive oil (, separated)","2 garlic cloves (, minced)","1 onion (, finely chopped (white, brown, yellow))","1 celery stalk (, finely chopped (optional, but recommended))","1 carrot (, finely chopped (optional, but recommended))","3 tbsp / 1/4 cup flour (35g)","2 cups / 500 ml beef broth (liquid beef stock) (or sub with chicken broth)","3 cups / 750 ml port (Note 2)","1 1/2 cups / 375ml red wine (, or more beef broth (Note 3))","3 tbsp / 1/4 cup tomato paste","5 sprigs thyme or 2 tsp dried thyme","3 dried bay leaves (or 5 fresh)","4 stalks fresh parsley (optional)"]},{"ingredients":["Fresh parsley (, finely chopped)"],"purpose":"To Serve"}]', '[{"description":"Season lamb with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a dutch oven or large heavy based pot over high heat. Add 2 lamb shanks and cook, turning, until browned (see photo). Remove then repeat with remaining lamb.","images":[],"step":2},{"description":"Turn heat down to medium. Add remaining 1 tbsp oil, garlic, onion, carrot and celery. Sauté for 5 minutes until onion is softened.","duration":5,"images":[],"step":3},{"description":"Add flour. Mix into onion mixture.","images":[],"step":4},{"title":"Add remaining ingredients. Mix","description":"lumps are ok, they will dissolve while cooking.","images":[],"step":5},{"title":"Add lamb back in","description":"the meat should be mostly submerged. Bring to simmer, then turn heat down to medium low and cover with lid.","images":[],"step":6},{"description":"Simmer for 2 hours (Note 4) then remove lid and simmer for 30 minutes.","images":[],"step":7},{"description":"Remove lamb into a bowl.","images":[],"step":8},{"title":"Optional","description":"Strain sauce in dutch oven into a bowl. Use spoon to press into onion etc to squeeze out all the flavourful liquid. Pour sauce into dutch oven. (Note 5)","images":[],"step":9},{"description":"Skim excess fat off sauce.","images":[],"step":10},{"description":"Increase heat to medium high and reduce liquid by half or until it thickens to a syrup consistency.","images":[],"step":11},{"description":"Return lamb shanks and juices pooled in the bowl into sauce to reheat, then serve with creamy mashed potato, garnished with parsley.","images":[],"step":12}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","gluten-free-recipes","lamb-shanks","main-dishes","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3afa1e590bac', 'en', 'US', 'Balsamic Pork Chops', 'Super simple, yet serious flavour!! The Balsamic sauce is tangy and sweet, and this will go fantastically with any protein - chicken, beef, pork and even lamb! The flavour of this syrup is quite intense so you do not need much for each serving - just spoon a couple of tablespoons over each pork. While the total cook time may seem long, it is mostly hands off time because the balsamic syrup doesn''t need to be watched over as it reduces.', 'https://www.recipetineats.com/tachyon/2016/07/Balsamic-Pork-Chops_5.jpg', 5, 25, 30, 4, '[{"id": "ing_pork", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 pork chops (, 2.5cm / 1\" thick, about 200-250g/7-8oz each (excluding any bone) (Note 1))","1 - 2 tbsp olive oil","1 garlic clove (, minced)","1 onion (, finely sliced (~1 cup of onion, brown, yellow or white))","1 cup balsamic vinegar","1/3 cup / 60g brown sugar (Note 2)","Salt and pepper"]},{"ingredients":["Crumbled goats cheese or feta","Fresh parsley or thyme"],"purpose":"Garnish (optional)"}]', '[{"description":"Sprinkle both sides of pork with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large skillet over medium high heat. Cook the first side for 4 minutes until it has a lovely dark gold crust, then turn and cook the other side for 3 minutes. (Note 3)","duration":4,"images":[],"step":2},{"description":"Transfer to a plate, cover loosely with foil.","images":[],"step":3},{"description":"Add 1 tbsp oil to the skillet, still on medium high. Add garlic and onion, cook until translucent - around 3 minutes.","images":[],"step":4},{"description":"Add balsamic vinegar and brown sugar. Stir until the sugar is melted. When it comes to a simmer, adjust the heat so it is bubbling gently, not rapidly.","images":[],"step":5},{"description":"Simmer for ~5 to 8 minutes or until it reduces by almost half and is a THIN syrup. Then add the pork back into the skillet, including all the juices on the plate. Simmer, turning pork to reheat, for 2 minutes or until the the sauce becomes syrupy (to your taste) and pork is reheated. (Note 4)","duration":2,"images":[],"step":6},{"description":"Serve, garnished with crumbled goats cheese if desired.","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa2bb99d5e87', 'en', 'US', 'Chorizo & Kale Risotto', 'Risotto in a rich Chorizo flavoured tomato broth! I used kale to add greens and a pop of colour, but you can substitute with spinach, or even leave it out!', 'https://www.recipetineats.com/tachyon/2016/04/Chorizo-Risotto_1.jpg', 10, 25, 35, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chorizo", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["3 cups chicken broth/stock (, salt reduced)","2 tbsp tomato paste","2 cups tomato passata (Note 1)"],"purpose":"Stock"},{"ingredients":["1/2 tbsp olive oil","350g (12oz) chorizo (, some sliced and the remainder finely chopped (Note 7))","1 onion (, finely chopped (brown, white or yellow))","2 garlic cloves (, minced)","1 1/2 cups arborio rice (risotto rice), uncooked (Note 2)","1/2 cup white wine (sub with chicken broth or water)"],"purpose":"Risotto"},{"ingredients":["5 cups kale leaves (, removed from stalk, torn into bite size pieces (packed) (Note 3))","2 - 4 + tbsp butter","Freshly grated parmesan cheese (optional)"],"purpose":"To Finish"}]', '[{"description":"Whisk together Stock ingredients in a small saucepan over medium low heat. Once heated, turn down to low and keep warm. (Note 4)","images":[],"step":1},{"description":"Heat oil in a pot or large skillet over high heat. Add chorizo and cook until golden brown. Remove into a bowl and set aside.","images":[],"step":2},{"description":"There should be some red oil in the skillet from the chorizo. If not, add a bit of oil.","images":[],"step":3},{"description":"Turn heat down to medium. Cook onion and garlic for 5 minutes until translucent.","duration":5,"images":[],"step":4},{"description":"Add rice and stir to coat grains in oil until translucent.","images":[],"step":5},{"description":"Add wine, turn up the heat to medium high and simmer, stirring, until most of the wine has evaporated.","images":[],"step":6},{"description":"Turn heat down to medium low and add 1 cup of stock. Stir leisurely until mostly absorbed into the rice, then add another cup of stock. Continue 1 cup at a time until the risotto is just cooked - squeeze a grain, it should still be firm but cooked through - about 15 minutes. Make the risotto as saucy (or not) as you want - liquid will absorb in the next step so lean towards saucier than what you want.","images":[],"step":7},{"description":"When the risotto is done (Note 5), remove it from the stove.","images":[],"step":8},{"description":"Add butter (the more the better!) and stir energetically - this will activate the starch and make it creamy. Stir chorizo in then partially stir kale through the risotto. Plonk the lid on and let it rest for 3 minutes (kale will wilt in this step).","duration":3,"images":[],"step":9},{"description":"Adjust salt and pepper to taste. Serve immediately! (Note 6)","images":[],"step":10}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","quick-and-easy","risotto-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_87663ec90e4a', 'en', 'US', 'Brown Sugar Broiled Salmon', 'Really great quick way to cook salmon - a brown sugar glaze smeared on salmon fillets, optional addition of veggies, then broil it. Terrific caramelisation, really quick delicious dinner.', 'https://www.recipetineats.com/tachyon/2016/04/One-Tray-Brown-Sugar-Salmon_5.jpg', 4, 8, 12, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["4 x 5-8 oz/ 150-180g salmon fillets (, skin on or off (I use on))","2 bunches asparagus (Note 1)","1 bunch broccolini (Note 1)","1 cup cherry tomatoes","1 tbsp olive oil","Salt and pepper"]},{"ingredients":["1 tbsp Dijon mustard","1 tbsp mayonnaise (I use whole egg mayonnaise)","2 tbsp brown sugar","1/4 tsp cayenne pepper"],"purpose":"Glaze (Note 2)"}]', '[{"description":"Preheat broiler/griller on high. Place the oven shelf 6\"/15cm from the heat source.","images":[],"step":1},{"description":"Spray a baking tray with oil (I use olive oil, any is fine).","images":[],"step":2},{"description":"Pile asparagus, broccolini and cherry tomatoes on the baking tray. Drizzle with olive oil and sprinkle with salt and pepper. Toss with hands then spread out on the tray, mostly on one layer.","images":[],"step":3},{"description":"Wedge salmon pieces on the tray between the vegetables. Sprinkle with salt and pepper.","images":[],"step":4},{"description":"Mix Glaze ingredients together. Slather on the salmon - tops and sides.","images":[],"step":5},{"title":"Grill/broil for 8 minutes","description":"don''t flip. The salmon should be caramelised and the inside should be blushing pink.","duration":8,"images":[],"step":6},{"description":"Rest for 2 minutes then serve with crusty bread rolls.","duration":2,"images":[],"step":7}]', '["egg","fish","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","low-calorie-recipes","main-dishes","one-pot-recipes","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_56520156fdc2', 'en', 'US', 'Greek Slow Roasted Leg of Lamb', 'This is the Greek way of roasting lamb - slow roasted until tender enough to pull apart, braised in a lemon garlic thyme broth that infuses the flesh with flavour and reduces into a lemony, herby jus rather than having to fuss with making a gravy. Easier and more foolproof than traditional roast lamb leg (the carving sort with pink meat) because there’s no worry about overcooking. There’s also a rosemary garlic version of this slow cooked leg (with gravy!) and plenty of other roast lamb recipes - take the Roast Lamb Matchmaker to find your perfect one!This recipe takes 7 1/2 hours to cook (7 hours in oven plus 30 minutes resting time) and is best served freshly made, so start late morning to serve for dinner, or get up VERY early to serve for lunch!Source: adapted from this Slow Roasted Leg of Lamb by Kalofagas', 'https://www.recipetineats.com/tachyon/2016/03/Greek-Slow-Roast-Lamb_7.jpg', 15, 420, 465, 8, '[{"id": "ing_garlic", "quantity": {"value": 12.0, "unit": "pack of 3 heads"}}, {"id": "ing_lamb", "quantity": {"value": 7.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 10.0, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bayleaves", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_wine", "quantity": {"value": 2.0, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}]', '[{"ingredients":["12 cloves of garlic, peeled","7 lb / 3.5 kg leg of lamb (, bone-in (Note 1 & Note 3 for roasting times for larger/smaller))","1 1/2 tsp cooking salt / kosher salt (double for flakes or flaky salt)","1/2 tsp black pepper","3 tsp paprika powder (regular / sweet, not spicy or smoked)","3 tsp garlic powder (or sub with onion powder)","2 tbsp olive oil","2 large onions (, quartered (white, brown, yellow, red))","10 sprigs of thyme","3 sprigs rosemary","3 tsp dried oregano","3 dried bayleaves (or 5 fresh)","1/2 cup lemon juice ((2 - 3 lemons), plus more to taste)","1 1/2 cups white wine (or sub with chicken broth/stock, low salt)","2 cups chicken broth/stock (, low sodium)"]}]', '[{"description":"Stuff incisions with garlic, season, roast leg uncovered 30 min at 240°C/465°F (220°C fan). Lower to 180°C/350°F (160°C fan). Put everything else in pan, flip leg upside down, fill with hot water 1/4 way up, roast covered 3 1/2 hours. Flip lamb, roast covered another 2 1/2 hours, then brown uncovered 30 minutes. Strain pan juices, serve!","images":[],"step":1},{"description":"Preheat oven to 240°C/465°F (220°C fan-forced). (Note 2)","images":[],"step":2},{"title":"Garlic incisions","description":"Use a small knife to make around 25 incisions all over the lamb, with most on the top. Cut around 6 cloves into slivers and stuff them into the incisions.","images":[],"step":3},{"title":"Season","description":"Sprinkle the lamb generously all over with salt, pepper, paprika and garlic powder. Drizzle with olive oil and rub all over the lamb.","images":[],"step":4},{"title":"30 minute browning","description":"Place the lamb in a roasting pan and roast for 30 minutes or until it has a nice brown crust.","duration":30,"images":[],"step":5},{"title":"Prepare for slow-roasting","description":"Remove from the oven. Turn the oven down to 180°C/350°F (160°C fan-forced). Turn the lamb upside down. Pour / place all the remaining ingredients in the pan around the lamb (including remaining garlic cloves). Fill the roasting pan with hot water so it comes up about 1/4 - 1/3 of the way up the height of the lamb.","images":[],"step":6},{"title":"Slow roast part 1 (3 1/2 hours)","description":"Cover with lid or with baking/parchment paper then 2 layers of foil. Roast for 3 1/2 hours. Top up water if it dries out (e.g. Might happen if your foil is loose) ** See Note 3 for larger/smaller leg roasting times **","images":[],"step":7},{"title":"Slow roast part 2 (2 1/2 hours)","description":"Remove the roast from the oven and remove the lid/foil. Turn the lamb over so it is the right side up. Cover again and roast for a further 2 1/2 hours, or until you can pull meat apart easily with forks.","images":[],"step":8},{"title":"Finish browning","description":"Remove cover and roast for a further 20 - 30 minutes (to brown).","images":[],"step":9},{"title":"Rest","description":"Remove from the oven and transfer lamb to serving platter. Cover loosely with foil and rest for 30 - 40 minutes.","duration":35,"images":[],"step":10},{"title":"Sauce","description":"Strain liquid into a clear jug. The fat will rise to the top. Scoop/pour most of it off and discard (I get 3/4 - 1 cup). There should be 2 - 3 cups of Sauce left. Adjust salt, pepper and lemon to taste.","images":[],"step":11},{"description":"Serve lamb with the Sauce on the side and Truly Crunchy Roast Potatoes* or Greek Lemon Potatoes. The lamb will stay warm enough for 1 hour so you can roast / prep other sides during this time.","images":[],"step":12}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","greek-recipes","lamb-recipes","main-dishes","mediterranean-recipes","roast-lamb","roasts","slow-cooked-fall-apart","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6aab0fa959bd', 'en', 'US', 'Apple Cider Glazed Pork Tenderloin', 'Apple cider is the secret to a marinade that makes pork tenderloin incredibly moist with a gorgeous glaze! The marinade also does double duty as the sauce. You will be amazed at the incredible flavour in this with so few ingredients! I used Rochdale Apple Cider for this recipe - a New Zealand cider that is available at all major liquor outlets in Australia including Dan Murphy''s and Liquorland.', 'https://www.recipetineats.com/tachyon/2016/01/Apple-Cider-Glazed-Pork-Tenderloin_6.jpg', 5, 30, 35, 4, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 11.0, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_honey", "quantity": {"value": 0.06, "unit": "jar of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 lb/500g pork tenderloin"]},{"ingredients":["11 oz/330ml sweet apple cider (alcoholic aka \"hard cider\") - I used Rochdale Apple Cider (Note 1)","1 bay leaf (, dried (or 2 fresh))","2 tbsp honey","2 tbsp brown sugar","2 garlic cloves (, minced)","1/2 tsp salt","Black Pepper"],"purpose":"Marinade"},{"ingredients":["1 tbsp olive oil"],"purpose":"To Cook"},{"ingredients":["1 1/2 tbsp butter","1 tbsp dijon mustard","Salt and pepper"],"purpose":"Sauce"}]', '[{"description":"Mix the Marinade ingredients in a bowl.","images":[],"step":1},{"description":"Place Marinade and pork in a large ziplock bag and marinate in the refrigerator overnight, up to 24 hours.","images":[],"step":2},{"description":"To Cook","images":[],"step":3},{"description":"Remove pork in the marinade from the refrigerator 30 minutes prior to cooking (to bring to room temperature).","images":[],"step":4},{"description":"Preheat oven to 180C/350F.","images":[],"step":5},{"description":"Heat olive oil in a skillet over medium high heat. Remove pork from marinade (reserve marinade) and place in pan. Sear until golden brown all over - don''t let it burn (Note 2).","images":[],"step":6},{"description":"Transfer skillet to the oven and roast for 15 to 20 minutes, or until the internal temperature using a meat thermometer reads 145F/62C. (Note 3)","duration":17.5,"images":[],"step":7},{"description":"Remove pork from skillet onto a plate and cover loosely with foil to rest while you make the sauce.","images":[],"step":8},{"description":"Place skillet on the stove over high heat with butter. When the butter is melted, add reserved Marinade and mustard. Whisk until smooth.","images":[],"step":9},{"description":"Bring to boil, then turn heat down so it is simmering VERY rapidly, and cook until the liquid becomes syrupy - about 4 to 5 minutes. Adjust salt to taste.","images":[],"step":10},{"description":"Remove skillet from the stove, roll pork in the sauce, then remove and slice. Pour remaining sauce in the skillet into a jug and serve on the side.","images":[],"step":11},{"description":"I served this with a fennel apple salad on the side. (Note 4)","images":[],"step":12}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8eb5ae9eb3cd', 'en', 'US', 'One Tray Oven Baked Honey Chili Lime Salmon with Potatoes and Beans', 'Easy midweek cooking without compromising on flavour! Golden crunchy roasted potatoes with salmon glazed with chili, lime and honey and a side of greens to make it a complete meal. If you use smaller salmon, you can most certainly make this for 4.', 'https://www.recipetineats.com/tachyon/2015/06/Chili-Lime-Salmon-Overhead.jpg', 15, 35, 50, 3, '[{"id": "ing_salmon_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.004, "unit": "jar of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 14.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 8.0, "unit": "pack"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["3 pieces of salmon (5 - 7 oz / 150 - 200g each, skin on or off)"]},{"ingredients":["1 large lime ((or 2 small ones) - 1 1/2 tsp zest + 3 tbsp lime juice)","1 1/2 tbsp honey","1 tbsp soy sauce (or fish sauce)","2 garlic cloves (, minced)"],"purpose":"Marinade"},{"ingredients":["14 oz / 450 g baby potatoes (, halved (Note 1))","1 1/2 tbsp melted butter (or olive oil)","1/8 tsp salt","1 garlic clove (, minced (optional))"],"purpose":"Roast Potatoes"},{"ingredients":["8 oz / 250 g green beans (, trimmed)","1 tsp olive oil"],"purpose":"Beans"},{"ingredients":["1/2 tsp salt","Black pepper","1 birds eye chili (, frozen whole (or finely chopped unfrozen chili))","1 lime"],"purpose":"Garnish and seasoning"}]', '[{"description":"Preheat oven to 180C/350F and place a large rimmed baking tray in the oven.","images":[],"step":1},{"description":"Combine the Marinade ingredients in a bowl or ziplock bag. Add the salmon and set aside to marinate for 20 minutes (while the potatoes are roasting). (Note 2)","duration":20,"images":[],"step":2},{"description":"Toss the Roast Potato ingredients in a bowl. Remove the tray from the oven and pour the potatoes onto the tray. Place in the oven and roast for 20 minutes. (Note 3)","duration":20,"images":[],"step":3},{"description":"Combine the Beans ingredients into bowl you used for the potatoes (so residual butter sticks to beans) and toss.","images":[],"step":4},{"description":"Remove salmon from the Marinade, reserving the Marinade.","images":[],"step":5},{"description":"Remove tray from the oven. Move the potatoes to one side and place the salmon in the middle, skin side down. Pile the beans into one corn of the tray (don''t spread them out, they will overcook).","images":[],"step":6},{"description":"Sprinkle over the salt and pepper all over everything on the tray.","images":[],"step":7},{"description":"Drizzle some Marinade on each salmon, then place the tray into the oven and bake for 4 minutes per 1/2 inch / 5 minutes per 1.5 cm of thickness (thickest part of the salmon). My salmon was 1.25 inches / 3 cm thick so I baked it for 10 minutes. (Note 4)","duration":4,"images":[],"step":8},{"description":"Turn the grill/broiler onto maximum. (Note 5) Drizzle the remaining Marinade onto the salmon and grill for 2 minutes or until light golden on top.","duration":2,"images":[],"step":9},{"description":"Rest for 3 minutes. Use a grater to grate frozen chili and lime zest over the salmon. Serve with lime wedges on the side.","duration":3,"images":[],"step":10}]', '["fish","gluten","milk","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","low-calorie-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ea484fd10fc8', 'en', 'US', 'Tzatziki', 'Recipe video above. Nobody makes Tzatziki as good as your yiayia, but just in case you want to make one using actual measurements (rather than a little bit of this and a slosh of that!), here is my recipe. Use as a dip for vegetable sticks and warm pita bread, as a sauce for Gyros, Doner kebabs and chicken skewers, and dolloping on Greek baked chicken pieces.', 'https://www.recipetineats.com/tachyon/2026/03/Tzatziki_7.jpg', 20, 6, 26, 1, '[{"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.004, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_dill_optional_see_note", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["2 Lebanese cucumbers (Persian cucumbers)","1 1/4 cups Greek yoghurt (or Greek-style yogurt, preferably full fat)","1 tbsp lemon juice","1 tbsp extra virgin olive oil (or more if you want richer)","1 garlic clove (, minced)","1/4 heaped teaspoon cooking salt / kosher salt (halve for table salt, +50% for flakes)","Pinch of black pepper","2 tbsp finely chopped dill ((or mint), OPTIONAL - see note)"]}]', '[{"title":"Deseed, shred and squeeze","description":"Cut the cucumber in half lengthwise. Use a teaspoon to scrape the watery seeds out. Coarsely grate the cucumber using a box grater. Then wrap in a tea towel and squeeze to remove excess liquid.","images":[],"step":1},{"title":"Mix","description":"Place cucumber in a bowl. Add remaining ingredients then mix to combine.","images":[],"step":2},{"description":"Set aside for at least 20 minutes for the flavours to meld.","images":[],"step":3},{"description":"Use immediately or keep in an airtight container in the fridge for 3 days.","images":[],"step":4}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Greek"],"categories":["dip-recipes","greek-recipes","quick-and-easy","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b570a1d6bb5c', 'en', 'US', 'How to cook crispy skin duck breast', 'Recipe video above. The trick to cooking duck breast is to start the skin in a cold pan with no oil, then cook it on low heat to let the fat render (melt) which allows the skin to go crispy. Then finish it off in the oven - best way to ensure the flesh is perfectly cooked from edge to edge, for tender, rich, perfect duck slices!As for doneness inside - treat duck like steak rather than chicken breast: it is more tender and juicy if it is medium rare rather than well done (whereas chicken is chewy if still pink!). Though I personally think duck is still enjoyable if well done (eg Chinese BBQ duck is well done and it''s not dry!).You can use this recipe for as many duck breasts as can fit in a pan without crowding it.', 'https://www.recipetineats.com/tachyon/2025/01/Crispy-skin-duck-breast_4.jpg', 2, 20, 22, 1, '[{"id": "ing_duck_breast", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 duck breast (, boneless, skin on (Note 1))","1/8 tsp cooking salt / kosher salt","Pinch white pepper (sub finely ground black pepper)"],"purpose":"Crispy skin duck:"}]', '[{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":1},{"title":"Score","description":"Sprinkle half the salt and pepper on the flesh of the duck. Turn. Use a sharp knife to make 5 or 6 diagonal scores on the skin of the breast. Don''t pierce the flesh and don''t cut all the way to the edge of the skin (Note 2). Pat the skin dry with paper towels, sprinkle with remaining salt and pepper.","images":[],"step":2},{"title":"Cold pan, no oil","description":"Don''t turn the stove on yet. Use an oven-proof pan (any type). Place the duck skin side down in the cold pan, no oil required. Place another pan on top to lightly weigh the duck down (keeps skin flat). (Note 3)","images":[],"step":3},{"title":"Cook 10 minutes","description":"Turn the stove onto medium low. Cook for 10 minutes or until the skin is golden and crispy. Fat will melt out of the duck skin and it will cook in its own fat. (Note 4)","duration":10,"images":[],"step":4},{"title":"Oven 8 minutes","description":"Once the skin is crispy, turn and cook the flesh side for 1 minute. Then transfer the pan to the oven for 6 minutes for medium rare (internal temperature 54°C/130°F, restaurant default) or 8 minutes for medium (60°C/140°F, my preferred).","duration":1,"images":[],"step":5},{"title":"Rest","description":"Transfer to a rack or plate and rest for 5 minutes before serving. Serve whole or slice!","duration":5,"images":[],"step":6}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["duck"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_68312a6b532d', 'en', 'US', 'Pierogi Ruskies - Polish Dumplings', 'Recipe video above. Pierogi Ruskie''s are Polish dumplings filled with cheesy, creamy mashed potatoes served with an onion butter sauce. They are even more delicious than they sound! Traditionally made with quark which is an European fresh cheese which isn''t easily found in Australia, so I''ve used cheddar because I want this recipe to be as accessible as possible to many people to experience the greatness that is Pieorgis!!! More in Note 2.Excellent weekend project – eat some today and freeze some for later (they cook from frozen). Makes a nice big batch of 30 pierogis. For more dumplings of the world - head here!', 'https://www.recipetineats.com/tachyon/2023/10/Pierogi-ruskies_5.jpg', 45, 40, 115, 30, '[{"id": "ing_flour", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 110.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_potato", "quantity": {"value": 500.0, "unit": "bag of 2kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_butter", "quantity": {"value": 25.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 cups flour (, plain/all-purpose)","1 tsp cooking/kosher salt","50g / 3 tbsp unsalted butter","1/2 cup water","1 large egg (, whisked (55-60g/2oz))"],"purpose":"Pierogi dough:"},{"ingredients":["500g / 1 lb potatoes (, peeled and sliced 1cm / 1/2\" thick (2 medium, Note 1))","1 tbsp cooking/kosher salt ( - for cooking potatoes)","30g / 2 tbsp unsalted butter","1 cup shredded cheddar cheese (, tightly packed cup (Note 2))","1/4 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Pierogi filling:"},{"ingredients":["30g/ 2 tbsp unsalted butter","1 onion (, finely diced)","1/2 tsp cooking/kosher salt"],"purpose":"Onion Butter:"},{"ingredients":["1 tbsp cooking/kosher salt (- for boiling water)","25g/ 1 1/2 tbsp unsalted butter (, per 8 - 10 pierogis (Note 3))","Sour cream (, for serving)","Parsley or chives (, finely chopped - just a pinch)"],"purpose":"Cooking and serving:"}]', '[{"title":"Boil potatoes","description":"Put potato and 1 tbsp salt in a large saucepan. Add cold tap water so it''s 3cm/1 inch above potatoes. Bring to a boil on high heat then reduce heat to medium high and simmer for 15 minutes or until potatoes are soft.","duration":15,"images":[],"step":1},{"title":"Mash","description":"Drain, then pass the potatoes through a potato ricer into a bowl (or use potato masher)","images":[],"step":2},{"title":"Cheese it","description":"Immediately add butter, cheese, salt and pepper. Mix with a wooden spoon until fully combined.","images":[],"step":3},{"title":"Cool","description":"Spread out ~1cm / 1/2\" thick on a tray. Cover with cling wrap, pressing so it is fully in contact. Cool on the counter (~30 min) then refrigerate until cold (1 hour+).","images":[],"step":4},{"title":"Melt butter","description":"Heat up the water and butter in a small saucepan over medium heat just until butter is melted, do not boil water. (Or do this in the microwave). Turn off heat.","images":[],"step":5},{"title":"Mix dough","description":"Whisk the flour and salt in a mixing bowl. Make a well in the centre and then add the butter water plus egg. Mix to combine into a shaggy dough.","images":[],"step":6},{"title":"Knead","description":"Scrape out onto a lightly floured work surface. Knead for 5 minutes until the dough becomes smooth (Note 3). You could also use your stand mixer.","duration":5,"images":[],"step":7},{"title":"Rest","description":"Wrap with cling wrap and leave on the counter for 30 minutes.","duration":30,"images":[],"step":8},{"description":"Wrapping pierogis:","images":[],"step":9},{"title":"Roll & cut","description":"On a lightly floured surface, roll out the dough to 3mm / 1/8\" thickness. Cut out rounds using a 7.5 cm / 3\" cutter. Do as many as you can, then gather surplus dough into a ball, wrap with cling wrap and set aside for later.","images":[],"step":10},{"title":"Fill & wrap","description":"Place 1 tablespoon of cheesy potato filling in the middle of a round. Dip finger with water and run along edge of half the circle. Fold dough over to enclose the filling and press to seal, making slight indents (no pleats).","images":[],"step":11},{"title":"Wrap remaining","description":"Place them on a lightly floured tray and continue to wrap remaining Pierogi (including rolling out the remaining dough). You should get ~30 pierogis.","images":[],"step":12},{"description":"Onion butter sauce:","images":[],"step":13},{"description":"In a non stick skillet, melt the butter until foamy over medium heat. Add onion and salt, then cook, stirring regularly, for 10 to 15 minutes until golden on the edges. Scrape out into a bowl, then set aside (OK to cool).","duration":12.5,"images":[],"step":14},{"description":"Cooking & serving pierogis:","images":[],"step":15},{"title":"Batch cooking","description":"Directions below are for cooking and serving 10. Boil pierogis in batches of 10 to 12 max, they need space to bounce around in the water, and you need space to toss them in the butter. (Note 4 for big batch cooking)","images":[],"step":16},{"title":"Boil 5 minutes","description":"Bring ~3 litres/quarts of water to the boil with 1 tbsp salt. Lower 10 piergosi into the water. Cook for 5 minutes - they should be floating on the surface.","duration":5,"images":[],"step":17},{"title":"Reserve water & drain","description":"Dip a jug into the water and scoop out ~1 cup water. Then use a slotted spoon to transfer pierogi into a bowl (or drain, if not cooking more).","images":[],"step":18},{"title":"Butter sauce","description":"Melt butter in a large skillet over medium heat. Add 1/3 of the onion butter plus the cooked pierogis with 2 tablespoons of the reserved cooking water. Toss for 1 minute, still on the stove, until the pierogis are coated in the butter. (Note 4 on scaling up)","duration":1,"images":[],"step":19},{"title":"Serve","description":"Slide onto a serving plate, scraping out every drop of butter. Sprinkle with parsley, add a dollop of sour cream. Eat and be happy!","images":[],"step":20}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["European","polish"],"categories":["dumplings","iconic-dishes","potato-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_878bc7d71be6', 'en', 'US', 'Malfatti (Italian Spinach Ricotta Dumplings in Napoli Sauce)', 'Recipe video above. Malfatti means “badly formed” in Italian. These irregular spinach ricotta gnocchi-like dumplings may look a bit wonky, but they taste incredible!Like gnudi except with the addition of spinach, this traditional Italian dish can be served straight after boiling them. But it''s really worth a quick 15 minute bake to get a light golden crust on the Malfatti as well as caramelisation on the edges of the Napoli sauce. It really takes it in a deliciously different direction!Servings: This will serve 4 very hungry people, or 5 standard servings.', 'https://www.recipetineats.com/tachyon/2021/06/Malfatti-Spinach-Ricotta-Dumplings_8.jpg', 25, 45, 70, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 300.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_basil", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 onion (, very finely diced)","800g / 24 oz crushed tomato (or diced)","1 tbsp tomato paste","1/2 cup water","1 basil stem (leaves kept for the Malfatti)","1/2 tsp white sugar","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Napoli Sauce:"},{"ingredients":["300g / 10oz baby spinach (~6 tightly packed cups, Note 4)","1/2 tsp salt"],"purpose":"Spinach for Malfatti:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1 eschallot (large), finely chopped (or 1/2 red onion)","500g / 1 lb ricotta (must be dry type, not wet and spreadable, Note 1)","1/4 cup (lightly packed) basil leaves, finely sliced (use stem for sauce)","1 egg (Note 2)","1 egg yolk (Note 2)","1 cup parmesan (, finely grated)","1/2 cup flour (, plain / all-purpose)","1/2 tsp salt","1/2 tsp black pepper"],"purpose":"Malfatti:"},{"ingredients":["1/4 cup parmesan (, finely grated)","Basil leaves (, small (optional))"],"purpose":"Serving:"}]', '[{"title":"Saute garlic and onion","description":"Heat oil in a small pot or large skillet over medium heat. Add garlic and onion and cook for 3 minutes until onion is softened.","duration":3,"images":[],"step":1},{"title":"Simmer sauce","description":"Add remaining ingredients plus the stem of basil. Bring to a simmer, then reduce stove to low and cook, stirring every now and then, for 20 minutes. It should be fairly thick rather than a loose runny sauce.","duration":20,"images":[],"step":2},{"title":"Drain ricotta, if needed","description":"The ricotta should be the dry and fairly crumbly type rather than wet, soft and almost spreadable. If it''s wet, see Note 1 for removing excess water (wet ricotta makes Malfatti hard to shape and cook!)","images":[],"step":3},{"title":"Sweat spinach","description":"Toss spinach with 1/2 tsp salt in large colander. Leave for 20 minutes. Roll up in tea towel and squeeze tightly to remove excess liquid. Roughly chop.","duration":20,"images":[],"step":4},{"title":"Sauté garlic, eschalot and spinach","description":"Heat oil in a skillet over medium high heat. Add garlic and eschalot, cook for 1 minute until translucent. Add spinach and cook until just wilted. Transfer to large bowl, allow to cool.","duration":1,"images":[],"step":5},{"title":"Malfatti mixture","description":"Add ricotta and all remaining Malfatti ingredients into the bowl. Mix well to combine. It should be too wet to roll with hands without sticking, but still firm enough to shape into dumplings.","images":[],"step":6},{"title":"Form dumplings","description":"Using 2 dessert spoons, scoop up about 1 1/2 tablespoons of mixture then shape into a football (quenelle) using the two spoons. Place on a paper-lined tray. You should get about 24-30.","images":[],"step":7},{"title":"Boil dumplings","description":"Bring a large pot of water to the boil, then carefully put 6 dumplings in. Cook for 2 minutes, they should float to the surface. Remove with slotted spoon on to paper towel lined tray. Repeat for remaining Malfatti.","duration":2,"images":[],"step":8},{"description":"Preheat oven to 180°C / 350°F.","images":[],"step":9},{"title":"Assemble","description":"Pour Napoli Sauce into a baking dish, then top with Malfatti. Drizzle with extra virgin olive oil.","images":[],"step":10},{"description":"Bake 15 minutes or until the Malfatti has a faint blush of gold on the surface (Note 3).","images":[],"step":11},{"description":"Serve! Sprinkle baked Malfatti with parmesan and basil leaves (tear large leaves). Spoon into bowls and served as-is. No starchy side is required, think of these as like gnocchi. Just add a leafy green salad with Italian Dressing or Balsamic Dressing!","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dumplings","italian-recipes","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5b79b5f1ce7c', 'en', 'US', 'French Fish Pie', 'Recipe video above. This is a homestyle fish pie I like to make for Easter, one of my mother used to make for us. Chunks of white fish fillets slowly poached in creamy béchamel with fennel, leek and fresh dill then topped with mashed potato and baked until golden. Don''t be surprised that it doesn’t call for a homemade fish stock, you’ll still get plenty of flavour from the fish itself and the fresh herbs.', 'https://www.recipetineats.com/tachyon/2026/03/French-Fish-Pie_3.jpg', 30, 60, 100, 6, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.035, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_fennel", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_eek_halved_lengthwise_then_cut_into_2cm_0_8_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_milk", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_dill", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["1 leek (, (white and pale green parts only), halved lengthwise, then cut into 2cm / 0.8\" pieces)","1/2 tsp cooking salt / kosher salt (half for table salt, +50% for flakes)"]},{"ingredients":["1 tbsp extra virgin olive oil","2 tbsp (30g) unsalted butter","1 brown / yellow onion (, diced 0.6cm / 0.2\")","1/2 fennel (stalks cut off) (, diced 0.6cm / 0.2\" (Note 2))","1 leek (, (white and pale green parts only), halved lengthwise, then cut into 2cm / 0.8\" pieces)","3 garlic cloves (, finely minced)","1/2 cup plain flour / all-purpose flour (, (Note 3))","1/2 cup dry white wine (, any type (Note 4))","1 1/2 cups HOT milk, full fat preferred (, but works with lite milk too)","1 cup HOT thickened cream / heavy cream","1 tbsp fresh dill (, finely chopped (substitute with parsley or 1/2 tbsp tarragon))","3/4 tsp cooking salt / kosher salt (, half for table salt)","1/4 tsp black pepper"],"purpose":"Fish pie sauce"},{"ingredients":["1kg / 2lbs starchy potatoes","2 tbsp (30g) unsalted butter (, cold, cut in small cubes)","1/3 cup hot milk, full fat preferred (, but works with lite milk too)","3/4 tsp cooking salt / kosher salt (, half for table salt)","1/8 tsp ground white pepper (, or black pepper)","olive oil spray (optional)"],"purpose":"Mash potato topping"}]', '[{"description":"Sauté onion, fennel, leek and garlic, add flour, wine, milk, cream, salt and pepper to make the sauce, stir in dill and add fish. Pipe on mashed potato. Spray olive oil. Bake for 35 minutes until golden. Rest 5 minutes, then serve.","duration":35,"images":[],"step":1},{"description":"First place potatoes in a large saucepan, cover with cold water. Bring to a boil, then simmer 25 minutes until very soft. You can start making the sauce while the potatoes are cooking.","images":[],"step":2},{"description":"Preheat oven to 200°C / 390°F (180°C fan). I highly recommend placing a baking tray lined with foil at the bottom of your oven to catch any bubbling filling that may leak during baking. Easier to clean!","images":[],"step":3},{"title":"Season fish","description":"Pat fish pieces dry with paper towels and sprinkle all sides with salt. Set aside.","images":[],"step":4},{"title":"Sauté vegetables","description":"Heat oil and butter in a 26cm / 10\" cast-iron skillet over medium-high heat. Add onion, fennel, leek and garlic. Cook 5 minutes until softened and light golden. Stirring regularly. (Note 5)","images":[],"step":5},{"title":"Make sauce","description":"Add flour, stir for 30 seconds. Pour in white wine. It will simmer rapidly at first, then mix it in, it will look pasty. Slowly pour in the HOT milk and cream while stirring. Add salt and pepper. Bring to a simmer, cook 1 minute until thickened. The sauce should be quite thick, fully coating the back of the spoon then gently run down it. Set aside.","duration":0.5,"images":[],"step":6},{"title":"Finish mashed potato","description":"(see instructions below).","images":[],"step":7},{"title":"Finish filling","description":"Stir in dill. Add the fish pieces to the sauce, gently nestling them in so they’re mostly submerged. Then, using a spatula, carefully stir and move them around just enough to coat them in the sauce. Smooth the surface.","images":[],"step":8},{"title":"Potato topping","description":"Pipe mounds of mashed potato swirls on the surface. My swirls have a 4.5cm base (1.6\"), about 4cm tall (1.4\"), then I fill gaps with small swirls/blobs. Make sure to use all the mash! Spray lightly with olive oil. (Note 6)","images":[],"step":9},{"title":"Bake","description":"Bake 35 minutes, rotating halfway, until golden on top. If it''s not golden enough, place it under the grill for a few minutes.","images":[],"step":10},{"title":"Serve","description":"Rest for 10 minutes before serving to cool slightly and let the sauce thicken a bit more.","duration":10,"images":[],"step":11},{"title":"Finish mash","description":"Drain well. Pass through a potato ricer or return to the pot and mash well with a potato masher. Do not use a stick blender, it will overwork the starch, turning the mash gluey instead of fluffy. Add butter, salt and white pepper, stir until combined then add hot milk. Stir until smooth. It should be creamy but not loose (so it holds its shape when piped).","images":[],"step":12},{"title":"Piping bag","description":"Transfer into a piping bag fitted with a star tip. (Note 7)","images":[],"step":13}]', '["fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["French","Western"],"categories":["easter-mains-fish-seafood","easter-recipes","fish-recipes","jbs-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c20b75a13838', 'en', 'US', 'Slow-roast Easter stuffed lamb', 'Recipe video above. Make this to impress! Lamb shoulder slow-cooked until fork-tender but still slices like a dream to show off that herby, nutty stuffing, a stunner with the rich lamb meat. You''ll love the impressive stuffing-to-meat ratio, confit-style melting potatoes, and lush gravy. PS. Yes the rolling/tying part can be fiddly if you''re new to it. But don''t be intimidated, watch the video and look at the step photos, it''s infinitely doable even for first timers. And don’t worry if your lamb comes out a little rustic - eg wonky, or filling burstage. Once it’s on the platter, no one will notice, but the flavour will be all there!Recipe credit: Our very own Chef JB!', 'https://www.recipetineats.com/tachyon/2025/04/Easter-stuffed-lamb-shoot-2_2.jpg', 40, 180, 400, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.425, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_eschalots", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_skinless_hazelnuts", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_pistachios", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_saut_ed_green_beans", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1.35 - 1.5 kg/ 2.7 - 3 lb deboned lamb shoulder (Note 1)","1 1/2 tsp cooking salt / kosher salt (, divided)","1 tsp black pepper (, divided)","2 tsp extra virgin olive oil"]},{"ingredients":["1 tbsp / 20g unsalted butter","2 eschalots (, finely diced (US: shallots, sub 1 small onion) (Note 2))","3 garlic cloves (, finely minced)","300g/ 10 oz mushrooms (, button/white (Note 3))","2 tightly packed cups baby spinach (, roughly chopped 100g)","3 tbsp skinless hazelnuts (Note 4)","3 tbsp pistachios (, roughly chopped (Note 4))","1 1/2 tbsp parsley (, finely chopped (ok to omit))","1 1/2 tsp rosemary (, fresh, finely chopped (sub fresh thyme, or 1 tsp dried))","1 tbsp lemon zest (divine touch, don''t skip this!)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"The fabulous herb & nut stuffing:"},{"ingredients":["1 kg/ 2 lb baby potatoes (, cut in half (4 if large) (Note 5))","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 tbsp extra virgin olive oil"],"purpose":"Melting potatoes:"},{"ingredients":["2 tbsp flour (plain / all-purpose)","1 1/4 cups beef stock/broth (, low sodium)","1/4 tsp dark soy sauce (optional, for deeper colour) (Note 6)","Salt and pepper (, if needed (I don''t add any more))"],"purpose":"Gravy:"},{"ingredients":["1 tbsp pistachios (, roughly chopped (optional garnish))","Rosemary sprigs (, optional garnish)","Sautéed green beans (pictured - vegetable side, splash of colour)"],"purpose":"Serving:"}]', '[{"title":"Roast hazelnuts","description":"Preheat oven to 180°C/350°F (160°C fan-forced). Roast the hazelnuts for 8 minutes. Cool, then roughly chop.","duration":8,"images":[],"step":1},{"description":"Blitz the mushrooms in a food processor, scraping down the sides as needed, until the mushrooms are chopped into little 3mm/0.1\" pieces.","images":[],"step":2},{"title":"Duxelle","description":"Melt the butter in a non-stick pan over high heat. Add eschalots, garlic and mushrooms. Cook, stirring regularly, for 5 minutes or until the liquid that comes out of the mushrooms mostly evaporates. Add spinach and cook until wilted.","duration":5,"images":[],"step":3},{"title":"Cool","description":"Transfer the filling into a bowl. Cool for 20 minutes then stir in remaining ingredients.","duration":20,"images":[],"step":4},{"title":"Stuffing log","description":"Pile the stuffing on a piece of cling wrap. Use your hands to roughly shape it into a 35cm / 13.5\" long log. Tightly roll up with cling wrap. Place in the freezer for 3 hours (up to 3 days) until it is firm. (Note 7)","images":[],"step":5},{"description":"Pound and roll lamb:","images":[],"step":6},{"title":"Pound","description":"Place the lamb shoulder fat-side down. Cover with plastic wrap (I use go between) or baking paper. Then use a rolling pin or meat mallet to pound the meat (hard!) into a 40 x 22cm rectangle (15.5 x 8.5\"). Aim for even thickness ~1.75cm (2/3\"). Trim and patch as needed to make your rectangle - see video, I cut & rearrange 2 large flappy bits that stick out.","images":[],"step":7},{"title":"Roll","description":"Sprinkle the surface of the lamb with half the salt and pepper. Unwrap the frozen stuffing log then roll it up tightly, finishing with the seam side down.","images":[],"step":8},{"title":"Tie","description":"Secure with kitchen twine tied every 2cm / 0.8\". (See video for tips)","images":[],"step":9},{"description":"Preheat oven to 220°C/425°F (200°C fan-forced).","images":[],"step":10},{"title":"Season","description":"Rub the lamb roll all over with the olive oil, then sprinkle with the remaining salt and pepper.","images":[],"step":11},{"title":"Potatoes","description":"Toss the potatoes with the salt, pepper and olive oil in a large roasting pan (not a baking tray). Put the lamb on top of the potato, on the diagonal if needed to fit.","images":[],"step":12},{"title":"Short high temp roast","description":"Roast for 30 minutes (renders some fat and gives the colour a head start).","duration":30,"images":[],"step":13},{"title":"Slow roast","description":"Turn the oven down to 160°C/320°F (140°C fan). Cook for 2 1/2 hours, or until the internal temperature is 98°C/208°F or the meat can be fairly easily teased apart using two fork (check in a discreet spot).","images":[],"step":14},{"title":"Rest","description":"Remove lamb and potato to a tray and loosely cover with foil while you make the gravy.","images":[],"step":15},{"title":"Drippings","description":"The roasting pan will have meat juices and fat. Tilt the pan so you can scoop off and discard all but 3 tablespoons of fat (the clear liquid that rises to the surface). Make sure you keep the dark brown juices in the pan. If you''re short of fat, add butter.","images":[],"step":16},{"title":"Heat fat","description":"Put the pan directly on the stove over medium heat. Once the fat is hot, sprinkle the flour over and stir for 1 minute.","duration":1,"images":[],"step":17},{"title":"Thicken","description":"While stirring, slowly pour in the stock. Add soy sauce, then keep stirring as it bubbles gently until it thickens into a maple syrup consistency.","images":[],"step":18},{"description":"Taste and add more salt and pepper if desired (I don''t need more). Pour into a jug (strain, if needed).","images":[],"step":19},{"description":"Cut the string off the lamb then slice into 2cm / 0.8\" thick slices.","images":[],"step":20},{"description":"Plate on a platter, surround with the potatoes. Serve with gravy, sprinkled with extra chopped pistachios if desired! (Shown in the video with sautéed green beans).","images":[],"step":21}]', '["gluten","milk","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","easter-sides-warm-hearty","lamb","lamb-recipes","mains","roast-lamb"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74a959c34823', 'en', 'US', 'Ultimate slow-roasted lamb: 12-hour Lamb Shoulder', 'Recipe video above. A 3-hour lamb shoulder is great. A 12-hour lamb shoulder is better! The meat is even more succulent because a lower cooking temperature means less moisture loss, and better flavour infusion from the rub. The sauce is a Lamb Jus made using the braising juices so it has phenomenal flavour. Don''t be intimidated, it''s simple and no more difficult to make than gravy!This is an excellent make-ahead recipe for gatherings. Why? Because you can make up to 4 shoulders in one standard oven. And the room for error is also almost nil; it''s almost entirely hands-off cooking that magically takes care of itself overnight. Most importantly, the meat is so juicy it reheats 100% perfectly. I cook it overnight and reheat to serve that evening.About scaling up: 2 shoulders can be cooked in one large pan with no change to cook time. 4 shoulders (2 lambs in 2 pans, on 2 shelves) takes about 14 to 15 hours.', 'https://www.recipetineats.com/tachyon/2021/10/12-Hour-Greek-Slow-Roasted-Lamb-Shoulder_4.jpg', 10, 780, 790, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.9, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["1.6 - 2.2kg / 3.2 - 4.4lb lamb shoulder (, bone-in (Note 1))","2 cups water (Note 2)","1 brown onion (unpeeled), cut into 6 wedges (Note 3)"]},{"ingredients":["2 1/2 tsp fresh rosemary (, chopped (finely))","1 tbsp dried oregano","2 garlic cloves (big!) (, finely chopped)","1 tsp salt (, kosher or cooking salt (or 3/4 tsp table salt))","1/2 tsp black pepper","1/4 cup extra virgin olive oil"],"purpose":"Marinade"},{"ingredients":["1 tsp cornflour / cornstarch","1/4 cup water","1/4 tsp salt"],"purpose":"Jus, for serving"}]', '[{"description":"Preheat oven to 230°C / 450°F (210°C fan).","images":[],"step":1},{"title":"Marinade/rub","description":"Mix the Marinade ingredients in a small bowl. Rub all over the lamb surface, getting it right into all the cracks and crevices!","images":[],"step":2},{"title":"Marinate 2","description":"24 hrs: If time permits, marinate for 2 hours on the counter in a roasting pan, or up to 24 hours in the fridge. I skip this step more often than not, however. (Note 4)","images":[],"step":3},{"title":"Prepare roasting pan","description":"Scatter onion in the base of the roasting pan. Place lamb shoulder on top . Pour water into pan.","images":[],"step":4},{"description":"Roast uncovered for 45 minutes.","duration":45,"images":[],"step":5},{"title":"Slow-roast 12 hours","description":"Turn oven down to 100°C/210°F (both fan and standard, Note 5). Cover lamb with baking paper, then a double layer of foil and seal very tightly to avoid water evaporation. Roast for 12 hours (I always do overnight!).","images":[],"step":6},{"title":"Check meat","description":"Test side of lamb with two forks. The meat should be fall-apart tender. If not, cover and return to oven.","images":[],"step":7},{"title":"Remove lamb","description":"There will (should!) be a lot of liquid pooled under the lamb in the roasting pan. Remove lamb to a large dish. Cover loosely with foil to keep warm. It will stay warm for 2 to 3 hours. See Note for reheating / making ahead.","images":[],"step":8},{"title":"Reduce liquid","description":"Strain all the liquid in the roasting pan into a saucepan (Note 2). Bring to a boil then simmer rapidly on medium-high until it reduces down to 1 cup (250ml).","images":[],"step":9},{"title":"Thicken","description":"Mix cornflour with water. Pour into jus in a thin stream while stirring continuously. Continue to cook for a minute or two over medium heat, stirring every now and then, until it thickens to a syrup consistency. Add salt and pepper to taste.","images":[],"step":10},{"description":"Serve:","images":[],"step":11},{"description":"Serve Slow Roasted Lamb with Jus. Use tongs for tearing meat off - no knife for carving needed! Pictured in post with Greek Lemon Roasted Potatoes, a perfect match for this Greek-ish flavoured lamb. Roasted Vegetables would also be ideal.","images":[],"step":12}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["easter-mains","easter-recipes","iconic-dishes","lamb","lamb-recipes","mains","roast-lamb","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74648aa2183d', 'en', 'US', 'Rack of Lamb with Rosemary Garlic Marinade (Oven Roasted)', 'Recipe video above. Here is a wonderful, classic way to cook a rack of lamb that makes the most of this premium cut of meat! Infused with the flavours of rosemary and garlic from a marinade, then roasted to perfection, it''s served with Salsa Verde for a deliciously fresh accompaniment that plays beautifully against the rich lamb.Allow 3 to 4 cutlets per person.', 'https://www.recipetineats.com/tachyon/2021/03/Lamb-Rack-Main.jpg', 10, 25, 35, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_quantity_salsa_verde", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["2 x 800g / 1.3lb racks of lamb (, frenched (Note 1))"]},{"ingredients":["4 garlic cloves (, minced)","1 tbsp fresh rosemary (, finely chopped)","4 tbsp extra virgin olive oil","1/2 tsp salt (, cooking/kosher salt)","1/4 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["2 tbsp olive oil - for searing (1 tbsp each rack)"],"purpose":"Cooking:"},{"ingredients":["30g / 2 tbsp butter (, cut into 1cm / ½\" cubes)","2 garlic cloves (, smashed (use side of knife))","1 sprig rosemary"],"purpose":"Basting finish:"},{"ingredients":["1 quantity Salsa Verde (see separate recipe)"],"purpose":"Serving:"}]', '[{"title":"Marinate lamb","description":"Mix marinade ingredients in a ziplock bag (Note 2). Place lamb in bag, massage to coat, then seal and marinate for at least 24 hours and up to 48 hours.","images":[],"step":1},{"description":"Remove lamb from fridge 1 hour prior to cooking, to ensure even cooking.","images":[],"step":2},{"title":"Wrap bones in foil (optional)","description":"Wrap each bone with a small piece of foil. This keeps the bones white and looks prettier.","images":[],"step":3},{"title":"Preheat oven","description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":4},{"title":"Sear","description":"Heat 1 tbsp oil in a cast iron skillet (or other oven-proof, heavy-based skillet) over high heat. Sear one lamb rack on all sides until golden brown, including the ends. Remove and repeat with other lamb rack.","images":[],"step":5},{"title":"Roast","description":"Place both racks in the skillet and roast for 15 minutes, or until the internal temperature is 57°C/135°F (for medium-rare). Remove pan from oven.","duration":15,"images":[],"step":6},{"title":"Baste","description":"Add butter, smashed garlic and rosemary to pan. The residual heat of the pan will melt the butter. Spoon the butter over the lamb continuously for 30 seconds.","duration":0.5,"images":[],"step":7},{"title":"Rest","description":"Remove lamb from skillet and place on a rack set over a tray. Pour butter remaining in the skillet over lamb. Cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":8},{"description":"Carve and serve! Cut lamb into individual cutlets or several cutlets per slice. Serve with Salsa Verde!","images":[],"step":9},{"title":"Sides","description":"Pictured in post with a Spring Salad and individual Mini Potato Gratin Stacks.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","easter-sides-warm-hearty","lamb-recipes","roast-lamb","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_498329e6e8d1', 'en', 'US', 'Pork Roast with Crispy Pork Crackling', 'Recipe video above. This is how to make a pork roast with tender juicy flesh, with a crazy-crispy crackling! The crackle is bubbly and puffy from edge to edge as it should be, rather than an impenetratable rock hard flat sheet of skin or worse still, littered with rubbery patches.And the gravy is to die for, thanks to the flavour loaded roasting pan juices!KEY STEPS: Use pork shoulder, dry skin, no need to score (but if it''s already scored, that''s ok), salt the skin evenly, slow roast low uncovered, keep the skin surface level using foil balls, and blast it for crispy skin! Read the post for extra tips, step photos, and why this recipe works!', 'https://www.recipetineats.com/tachyon/2018/04/Pork-Roast-Crispy-Crackling_0.jpg', 15, 200, 215, 10, '[{"id": "ing_pork_shoulder", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 0.025, "unit": "jar"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_cider", "quantity": {"value": 2.0, "unit": "bottle of 330ml"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["3 kg/ 6 lb boneless skin on pork shoulder, NOT scored (, unrolled / netting removed (Note 1 & 6))","3 tsp cooking / kosher salt (NOT salt flakes or table salt, Note 7)","1 1/4 tsp black pepper","2 tsp fennel seeds (or other herb/spice of choice)","1 tbsp+ 1 tsp olive oil","1 garlic bulb (, halved horizontally)","2 onions (, halved (brown, white, red))","2 cups dry white wine, or alcoholic or non-alcoholic cider (Note 2)"]},{"ingredients":["1/4 cup flour (Note 5)","2 cups chicken broth/stock (, low sodium)","Salt and pepper"],"purpose":"Gravy:"}]', '[{"title":"Dry skin","description":"Pat the skin dry with paper towels. If time permits, leave in the fridge uncovered overnight (even 1 hr helps). If not, pat extra well.","images":[],"step":1},{"description":"Preheat oven to 220°C/430°F (200°C fan).","images":[],"step":2},{"title":"Season flesh","description":"Sprinkle pork flesh with 1 1/2 tsp salt, all the pepper and all fennel seeds and 1 tbsp olive oil. Rub into flesh, right into all the crevices and cracks.","images":[],"step":3},{"title":"Salt skin","description":"Flip pork, drizzle skin with 1 tsp oil, then rub all over with fingers. Sprinkle all over with remaining 1 1/2 tsp salt, taking care to get even coverage. Un-salted patches will not become bubbly crackling, it will be a hard flat sheet.","images":[],"step":4},{"title":"Garlic & onion bed","description":"Place halved garlic bulbs and onion in roasting pan. Place pork skin side up on top of them.","images":[],"step":5},{"title":"Wine","description":"Carefully pour wine into the pan, being sure not to wet the skin. Transfer to oven.","images":[],"step":6},{"title":"Lower oven","description":"Immediately turn oven down to 160°C/320°F (140°C fan).","images":[],"step":7},{"title":"Slow roast","description":"Roast for 2 1/2 hours.","images":[],"step":8},{"title":"Level at 1 1/2 hours","description":"Check pork after 1 1/2 hours to see if the pork is warped and the skin''s overall surface is significantly unlevelled. If so, adjust to make the skin surface as level as possible using balls of foil and moving large dislodged pork pieces to the side (key tip for crispy crackling, Note 3). Then return to oven for the remaining 1 hour.","images":[],"step":9},{"title":"Check pan & salt on skin","description":"If pan is drying out, add some water. If there are bald patches on the skin without salt (eg it fell off), spray lightly with oil spray (or brush lightly with oil) then sprinkle with salt. (Remember, salt = bubbly skin!)","images":[],"step":10},{"title":"Increase heat","description":"Turn oven up to 250°C/485°F (all oven types), or as high as it will go if your oven won''t go this high.","images":[],"step":11},{"title":"Make skin crisp","description":"Return pork to oven for 30 minutes, rotating pan as needed, until skin is crisp and bubbly all over. If needed, use foil patches, secured with water soaked toothpicks, to cover parts that are done and keep crisping up remaining patches.","duration":30,"images":[],"step":12},{"title":"Rest","description":"Transfer pork to serving platter, tent loosely with foil (don''t worry, crackling stays super-crisp) and rest for 20 minutes (stays warm up to 1 hour). Then slice using a serrated knife.","duration":20,"images":[],"step":13},{"title":"Serve with gravy. Don''t pour gravy over crackling","description":"pour it off to the side! See note for reheating.","images":[],"step":14},{"title":"Transfer fat to saucepan","description":"Skim off 3 tablespoons of fat from the roasting pan and put in a saucepan.","images":[],"step":15},{"title":"Strain pan juices","description":"Place strainer over bowl and scrape in all the remaining pan juices (including onion and garlic). Press out juices, then discard onion & garlic. Skim off excess fat from surface and discard - no need to be exact here!","images":[],"step":16},{"title":"Gravy roux","description":"Heat the saucepan with the fat over medium heat. Add flour and cook for 1 minute.","duration":1,"images":[],"step":17},{"title":"Add liquids","description":"Pour stock in while whisking so it''s lump free. Then pour in strained pan juies.","images":[],"step":18},{"title":"Thicken","description":"Simmer until thickened to syrup consistency - about 3 minutes - it will thicken more as it cools a little while serving. (Note 4 for colour tip)","images":[],"step":19},{"title":"Season","description":"Adjust salt and pepper to taste. Pour into serving jug. Serve with pork.","images":[],"step":20}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","iconic-dishes","main-dishes","pork-recipes","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49924032080d', 'en', 'US', 'Rosemary Crumbed Rack of Lamb', 'Recipe video above. This is a recipe that really makes the most lamb racks which are a pricey cut of meat! Adding a crunchy rosemary-garlic crumb not only adds extra flavour but is also a great textural contrast to the soft and tender lamb meat. To stop the crumb falling off lamb racks, just add a touch of egg into the mustard spread. Egg is after all the ultimate natural food glue!Serve straight up (lamb cutlets are sooo juicy and tender, most people think no sauce is necessary!), with a Creamy White Wine & Mustard Sauce or else a Pea Puree (great colour and is as good as a sauce).', 'https://www.recipetineats.com/tachyon/2020/12/Crumbed-rack-of-lamb_5.jpg', 20, 45, 65, 3, '[{"id": "ing_lamb", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.25, "unit": "carton of 12"}}, {"id": "ing_mustard", "quantity": {"value": 0.3, "unit": "jar of 200g"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 rack of lamb (6 to 9 bones) (, your choice Frenched or not (Note 1))","1 1/4 tsp salt","3/4 tsp black pepper","2 tbsp olive oil"]},{"ingredients":["3 tsp egg (, lightly whisked (Note 2))","3 tbsp Dijon mustard","1 tbsp fresh rosemary leaves (, finely chopped)","1 small garlic clove (, minced)"],"purpose":"Dijon Mustard “Glue”:"},{"ingredients":["1 cup Panko breadcrumbs (Note 3)","2 tbsp parmesan (, finely grated)","1 garlic clove (, finely minced (knife, not garlic press))","1/4 tsp each salt and pepper","2 tbsp fresh rosemary leaves (, finely chopped)","30g / 2 tbsp butter (, melted)"],"purpose":"Garlic Parmesan Crumb:"},{"ingredients":["1 cup dry white wine (sauvignon blanc, pinto gris, semillon, or any blend)","1 cup chicken stock (, low sodium)","1 cup heavy/thickened cream","1 tbsp dijon mustard","1/8 tsp each salt and pepper"],"purpose":"Creamy White Wine & Mustard Sauce (Optional, Note 5):"}]', '[{"description":"Preheat oven to 200°C/390°F (all oven types). Place shelf in the middle of the oven.","images":[],"step":1},{"title":"Season","description":"Sprinkle lamb rack with salt and pepper.","images":[],"step":2},{"title":"Sear","description":"Heat 1 tbsp oil in a heavy based skillet over high heat. Sear lamb rack all over until nicely browned - including each short end - about 1 1/2 minutes on each side. It will be fully raw inside, but that''s OK. Transfer to plate and let cool for 5 minutes, uncovered.","duration":5,"images":[],"step":3},{"title":"Mustard Spread","description":"Mix dijon, rosemary and garlic in a small bowl. Then add 3 teaspoons of egg, and mix again.","images":[],"step":4},{"title":"Making the crumb","description":"Mix Crumb ingredients EXCEPT butter in a bowl. Then use a fork to stir through butter. Spread on a dinner plate (large enough that fits lamb).","images":[],"step":5},{"title":"Crumbing the lamb","description":"Spread the underside of the rack with mustard mix. Press into breadcrumb mixture, then spread mustard mix over the other side as well as each end. Then press those sides into the breadcrumb mixture.","images":[],"step":6},{"description":"Transfer lamb to rack set on a tray. Surround with parboiled vegetables if using - but don''t crowd the lamb.","images":[],"step":7},{"title":"Roast","description":"Frenched racks for 20 minutes, or untrimmed racks for 30 - 35 minutes, or until internal temperature registers 60°C/140°F (for medium rare).","duration":20,"images":[],"step":8},{"title":"Rest meat","description":"Transfer lamb to a cutting board, loosely cover with foil. (If you roasted veg, leave in tray or pan and keep warm in turned off oven).","images":[],"step":9},{"title":"Carve","description":"Rest 5 minutes then slice carefully using your hands to hold the crumb gently in place where you are cutting using a very sharp knife. If your service allows it, it''s best to cut 2 or 3 bones together (ie. a double/triple cutlet portion), because the crumb stays on better. Slicing single cutlets is super hard (sadly)!","images":[],"step":10},{"description":"Serve as-is (no sauce), with Creamy White Wine & Mustard Sauce, or Pea Puree.","images":[],"step":11},{"description":"Creamy White Wine & Mustard Sauce","images":[],"step":12},{"description":"Boil wine and chicken stock together until reduced by 3/4, then whisk in cream and mustard and simmer for 3 - 5 minutes until thickened. The consistency should be a thin pouring sauce. We don''t want to coat the lamb too thickly as the sauce flavour will be overpowering.","duration":4,"images":[],"step":13}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","lamb-recipes","main-dishes","mains","roast-lamb"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_72ecde8a7363', 'en', 'US', 'Lamb Chops with Rosemary Gravy (Loin chops, forequarter, cutlets)', 'Recipe video above. Rosemary and lamb is a classic combination. So we''re doubling up on rosemary here - marinading with garlic and rosemary first, then smothering in rosemary gravy!', 'https://www.recipetineats.com/tachyon/2020/06/Lamb-Chops-with-Rosemary-Gravy_6-copy.jpg', 10, 15, 25, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["750g/ 1.5lb lamb chops (loin chops, forequarter, cutlets) (Note 1)"]},{"ingredients":["1/4 cup extra virgin olive oil","3 garlic cloves (, finely minced)","1 tbsp rosemary leaves (, finely chopped (Note 2))","1 tsp each salt and pepper"],"purpose":"Lamb Chop Marinade:"},{"ingredients":["2 cups beef stock (, low sodium)","3 tbsp flour (, plain/all purpose (Note 3 for GF))","1 tbsp rosemary leaves (, finely chopped (Note 2))","2 rosemary sprigs (, optional)"],"purpose":"Gravy:"}]', '[{"title":"Marinade","description":"Mix Marinade ingredients together, then pour over chops. Turn to coat and leave to marinade for at least 1 hour, preferably 3 hours or overnight.","images":[],"step":1},{"description":"Cooking:","images":[],"step":2},{"description":"Take lamb out of fridge 30 minutes prior to cooking (to bring to room temp).","images":[],"step":3},{"description":"Heat a large skillet over high heat (no oil needed).","images":[],"step":4},{"description":"Pick up a chop, scrape off excess bits of garlic (it burns) and let excess oil drip off. Place in skillet. Once all chops are in, turn heat down to medium high.","images":[],"step":5},{"description":"Cook times for medium rare (internal temp 62°C/145°F):","images":[],"step":6},{"title":"Loin chops & forequarter chops","description":"4 minutes each side, or until internal temp is 62°C/145°F for medium rare (Note 4 other doneness)","images":[],"step":7},{"title":"Cutlets & thin leg steaks","description":"3 minutes on the first side then 2 minutes on the second side.","images":[],"step":8},{"title":"Rest","description":"Remove lamb from skillet and place on a plater. Loosely cover with foil and rest for 3 minutes while you make the gravy.","duration":3,"images":[],"step":9},{"description":"Pour off all but about 3 tbsp oil (if you''re short, add butter), return skillet to medium heat.","images":[],"step":10},{"description":"Add flour and stir for 30 seconds.","duration":0.5,"images":[],"step":11},{"description":"Pour in beef stock while stirring constantly to dissolve flour mixture in. If you have lumps, use a whisk.","images":[],"step":12},{"description":"Add chopped rosemary and sprig.","images":[],"step":13},{"title":"Simmer, stirring regularly, for 2","description":"3 minutes until it thickens in a gravy consistency.","duration":2.5,"images":[],"step":14},{"description":"Serve lamb chops with gravy over creamy mashed potato and a side of peas!","images":[],"step":15}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["easter-mains","easter-recipes","lamb","lamb-recipes","main-dishes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0aa249fafde6', 'en', 'US', 'Brown Sugar Glazed Ham', 'Recipe video above. It''s truly incredible how such a simple Brown Sugar Ham Glaze can transform into the most incredibly sticky, caramelised ham! See Notes for handy make ahead tips.New to glazed ham? Start here -> How to Make Glazed Ham. Want to try my signature clove studded Maple Glazed Ham? Here it is!', 'https://www.recipetineats.com/tachyon/2018/12/Brown-Sugar-Glazed-Ham_0-SQ.jpg', 15, 90, 105, 20, '[{"id": "ing_ham", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 500ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cinnamon", "quantity": {"value": 0.007, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.015, "unit": "jar of 200g"}}, {"id": "ing_ribbon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4-6 kg / 8-12 lb bone in ham, rind and fat on (Note 1)","2 cups water (Note 2)"]},{"ingredients":["3/4 cup brown sugar","1/4 cup honey (or maple)","1/4 cup Dijon mustard","1/4 cup apple cider vinegar (Note 3)","1/2 tsp black pepper"],"purpose":"Brown Sugar Ham Glaze:"},{"ingredients":["3/4 tsp cinnamon*","1/2 tsp All Spice*","3/4 tsp mustard powder * (ordinary, not hot)"],"purpose":"Spices (Note 4):"},{"ingredients":["Ribbon","Few sprigs of rosemary (or other herb / leaves)"],"purpose":"Presentation (optional):"}]', '[{"description":"Take ham out of the fridge 1 hour prior.","images":[],"step":1},{"description":"Preheat oven to 160C / 320F (standard) or 140C / 285F (fan). Arrange shelf in lower third so the ham will be sitting in the centre of the oven (not right at the top of the oven, this causes more uneven cooking on surface).","images":[],"step":2},{"description":"Remove rind & scoring:","images":[],"step":3},{"description":"Remove the rind (skin) of the ham, ensuring you leave the fat on (Note 5 for steps, photos in post and video above)","images":[],"step":4},{"title":"Scoring","description":"Cut 2.5cm / 1\" diamonds into the fat (don''t cut into flesh).","images":[],"step":5},{"description":"Brown Sugar Ham Glaze:","images":[],"step":6},{"description":"Place brown sugar, honey, mustard, cider vinegar, pepper and Spices into saucepan over medium high heat. Simmer and stir until sugar is dissolved.","images":[],"step":7},{"description":"Baste & Cook:","images":[],"step":8},{"description":"Place rack in a baking pan and place ham on rack.","images":[],"step":9},{"description":"Baste all over with the glaze (except the handle), including underside and the cut face. Reserve remaining glaze for basting.","images":[],"step":10},{"description":"Bake for 1.5 hours, basting every 20 minutes with reserved glaze (Note 6) and pan juices, until caramelised and the internal temperature is 60C/140F. (Note 7)","images":[],"step":11},{"description":"Stick bits of foil on parts that are browning too quickly, and you can even lower the oven temp. (Note 8)","images":[],"step":12},{"description":"Rest ham for 15 to 30 minutes+, basting generously with the pan drippings - use it like paint to make your ham beautifully bronzed all over with a thick glaze. (Note 9)","duration":22.5,"images":[],"step":13},{"description":"Sauce (Note 10):","images":[],"step":14},{"description":"Whisk water into pan juices until it''s a thick honey-like pouring consistency.","images":[],"step":15},{"description":"Presentation & Serving:","images":[],"step":16},{"description":"Wrap handle with baking paper, secure in place with ribbon. Stick in rosemary sprigs.","images":[],"step":17},{"description":"Place ham on table as centrepiece with Sauce on the side. Lovely served warm or at room temp!","images":[],"step":18},{"description":"Once everyone has oohed and aahed over it, nominate someone to be the Ham Carver! Slice thinly and serve with sauce.","images":[],"step":19},{"title":"Leftovers","description":"See list in post for recipe using leftover ham and ham bone!","images":[],"step":20},{"title":"Storing","description":"Will keep for at least a week in the fridge if properly stored using a water-vinegar soaked ham bag or pillowcase. Otherwise freeze - don''t forget the bone! See How to Store Glazed Ham for directions.","images":[],"step":21}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["easter-mains","easter-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31ccacae3b5c', 'en', 'US', 'Slow Cooker Pork Loin Roast OR Pork Shoulder', 'Recipe video above. Pork loin OR shoulder slow cooked in an incredible Honey Butter sauce! I love the way the pork soaks up the flavour of the sauce - and how it only requires 5 ingredients!', 'https://www.recipetineats.com/tachyon/2018/09/Slow-Cooker-Honey-Garlic-Pork-Roast_9-2.jpg', 10, 600, 610, 8, '[{"id": "ing_pork", "quantity": {"value": 2.125, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.006, "unit": "jar of 500g"}}, {"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}]', '[{"ingredients":["1.75 - 2.5 kg / 3.5 - 5lb pork loin OR shoulder/boston butt ( ,or scotch fillet, skinless (Note 1))","1.5 tbsp olive oil (, separated)"]},{"ingredients":["2 tsp EACH paprika, thyme","1 tsp EACH garlic powder, onion powder","1/2 tsp cayenne pepper (, optional)","1/2 tsp pepper","2 tsp salt"],"purpose":"Spice Rub:"},{"ingredients":["3/4 cup honey","125g / 1/2 cup butter (, unsalted)","5 cloves garlic (, minced)","1/4 cup cider vinegar","1/2 tsp salt and pepper (, each)"],"purpose":"Honey Butter Sauce:"},{"ingredients":["3 tsp cornflour/cornstarch mixed with splash of water"],"purpose":"Thickener:"}]', '[{"title":"Spice Rub","description":"Rub pork with about 1 tsp oil. Mix Rub together then sprinkle over pork. Pat to adhere all over.","images":[],"step":1},{"title":"Brown","description":"Heat 1 tbsp oil in a large skillet over medium heat. Add pork and sear all around until deep golden brown (don''t let spices burn). Place pork in slow cooker.","images":[],"step":2},{"title":"Honey Butter Sauce","description":"Wipe pan. Add butter and melt. Add garlic and cook for 1 minute until golden. Add remaining Sauce ingredients, mix, simmer rapidly for 30 seconds.","duration":1,"images":[],"step":3},{"description":"Slow Cook:","images":[],"step":4},{"description":"Pour Sauce over pork. Cover slow cooker.","images":[],"step":5},{"title":"Pork loin","description":"Cook on LOW for 4 to 5 hours (see Note 2 for cook times for different sizes)","images":[],"step":6},{"title":"Pork Shoulder","description":"Cook on LOW for 10 hours (see Note 2 for cook times for different sizes, and Note 4 for oven, InstantPot and pressure cooker methods).","images":[],"step":7},{"description":"Remove pork onto serving platter, cover loosely with foil (10 - 20 minutes rest). (See Note 6 on Doneness)","images":[],"step":8},{"description":"Pour all juices in slow cooker into large saucepan. Add cornflour water mixture, mix.","images":[],"step":9},{"title":"Thicken Sauce","description":"Simmer on medium high for 5 minutes or until it reduces down to a syrupy consistency (Note 3).","duration":5,"images":[],"step":10},{"title":"Slice pork into thick slices (1.5","description":"2 cm / 3/5 - 4/5\" thick). Serve with PLENTY of Honey Butter Sauce!","images":[],"step":11}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","easter-mains","easter-recipes","main-dishes","mains","pork","pork-recipes","quick-and-easy","roasts","slow-cooker-recipes","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3e9f49e09873', 'en', 'US', 'Fish Pie', 'Recipe VIDEO above. A grand Fish Pie, fit for a king yet economical to make! Chunks of fish flakes smothered in a creamy white sauce, topped with mashed potato then baked until golden. Use a combination of both smoked and raw unsmoked fish for optimum flavour and texture. Fresh tarragon is also optional - it gives an extra edge to the flavour that people can''t quite put their finger on!', 'https://www.recipetineats.com/tachyon/2018/03/Fish-Pie_2.jpg', 15, 60, 75, 6, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 110.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 0.333, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.005, "unit": "pack of 200g"}}]', '[{"ingredients":["400 g / 14 oz smoked fish of choice (Note 1)","400 g / 14 oz raw unsmoked fish of choice (, I used Perch (Note 2))","3 cups / 750 ml milk (, low fat or full fat)","1 brown onion (, quartered (Note 3))","4 cloves (, optional (Note 4))"],"purpose":"Fish:"},{"ingredients":["50 g / 3 tbsp unsalted butter","2 garlic cloves (, minced)","1/2 small onion (, finely chopped)","1 small carrot (, finely chopped)","1 small celery stick (, finely chopped)","1/3 cup / 50g plain flour (all purpose flour, Note 11 for GF)","1 tbsp fresh tarragon (, finely chopped (optional))","2 tbsp parsley (, finely chopped)","Salt and pepper"],"purpose":"White Sauce:"},{"ingredients":["750 g / 1.5 lb floury potatoes (, peeled and cut into 2.5cm / 1\" pieces (Note 5))","30 g / 2 tbsp+ unsalted butter","1/2 cup / 125 ml milk, any fat %"],"purpose":"Potato Topping:"},{"ingredients":["1 cup frozen peas","4 hard boiled eggs (, quartered (optional) (Note 6))","30 g / 2 tbsp butter (, melted)","1/4 cup / 15g grated parmesan cheese (, optional)","Finely chopped parsley (, for garnish (optional))"],"purpose":"Pie:"}]', '[{"description":"Push a clove into the skin of each onion. Place in a pot or large skillet, add milk, turn stove onto medium high heat.","images":[],"step":1},{"title":"When milk is barely simmering, add fish","description":"don''t worry if it''s not entirely covered, it can be turned / moved around.","images":[],"step":2},{"description":"Poach fish for 7 minutes, then use a slotted spoon to transfer fish straight into a medium baking dish (Note 8).","duration":7,"images":[],"step":3},{"description":"Flake into chunks using forks. Remove bones if you see any.","images":[],"step":4},{"description":"Use slotted spoon to remove onion and cloves from milk, discard. RESERVE milk.","images":[],"step":5},{"description":"Preheat oven to 180C/350F. Boil water for potatoes.","images":[],"step":6},{"description":"Melt butter in a large, deep skillet or pot over medium high heat. Add onion and garlic, cook for 1 minute. Then add celery and carrot, cook for 5 minutes until carrot is soft.","duration":1,"images":[],"step":7},{"title":"Turn heat down to medium low. Add flour, mix in","description":"it will look gluey.","images":[],"step":8},{"description":"Add half the milk and quickly start mixing. Once incorporated, the mixture will thicken quickly. Add remaining milk and stir. (Video helpful here)","images":[],"step":9},{"description":"Turn heat up to medium and keep stirring until the mixture thickens to the consistency of honey - about 3 minutes. (Note 7)","images":[],"step":10},{"description":"Take it off the heat, stir through tarragon and parsley. Adjust salt and pepper to taste.","images":[],"step":11},{"description":"Scatter top of flaked fish with peas, then pour over the Sauce. GENTLY stir through (don''t want fish to turn into mush!).*","images":[],"step":12},{"description":"Smooth top, then nestle egg in all over the pie.","images":[],"step":13},{"description":"Bring a large pot of water to the boil. Add potatoes and cook for 15 minutes or until soft. (Do this while making the Sauce).","duration":15,"images":[],"step":14},{"description":"Drain potato, add butter, milk, salt and pepper. Mash until creamy - add more milk if required.","images":[],"step":15},{"description":"Immediately dollop then spread onto pie (cold mash = hard to spread).","images":[],"step":16},{"description":"Use fork to draw squiggles on surface (rough surface = better golden bits).","images":[],"step":17},{"description":"Drizzle surface with melted butter, sprinkle with parmesan.","images":[],"step":18},{"description":"Bake for 35 minutes or until top is deep golden.","duration":35,"images":[],"step":19},{"description":"Stand for 5 minutes before serving, garnished with parsley if desired. See notes for reheating and make ahead.","duration":5,"images":[],"step":20}]', '["egg","fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["British","Western"],"categories":["easter-mains","easter-mains-fish-seafood","easter-recipes","fish-recipes","seafood-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a078e9455b91', 'en', 'US', 'Slow Cooker Roast Lamb Leg with Gravy', 'Recipe video above. The easiest, most succulent roast lamb you''ll ever have! This is not the carving sort of lamb, you can just tear the meat off using tongs.', 'https://www.recipetineats.com/tachyon/2017/04/Slow-Cooker-Roast-Lamb-7.jpg', 5, 600, 605, 5, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_braising_liquid_from_slow_cooker", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2.0 kg / 4 lb lamb leg, bone in (Note 1)","1 tsp salt","black pepper","2 large garlic cloves (, minced)","1 1/2 tsp dried thyme OR rosemary (or 2.5 tsp finely chopped fresh)","1 tbsp olive oil","2 cups / 500ml beef stock (or chicken) (Note 2)","1 sprig rosemary (, optional)"]},{"ingredients":["50 g / 3 tbsp butter","3 tbsp / 40 g flour (any white)","2 cups / 500 ml braising liquid from slow cooker (, strained)","Salt and pepper"],"purpose":"Gravy:"}]', '[{"description":"Place lamb in slow cooker or on work surface. Sprinkle with salt, pepper, thyme or rosemary and garlic. Drizzle over oil, then rub on both sides.","images":[],"step":1},{"description":"Pour beef stock into slow cooker, add sprig of rosemary (if using).","images":[],"step":2},{"description":"SLOW COOK on low for 10 hours, or pressure cook on high for 1 hour 40 minutes. (See oven version here)","images":[],"step":3},{"description":"The lamb should be tender enough to pull off with tongs, but still holding together (just!). Carefully remove lamb from slow cooker and transfer to tray.","images":[],"step":4},{"description":"Drizzle lightly with oil (any). Bake at 200C/390F for 20 minutes or until browned. Remove and rest for 10 minutes before serving with gravy.","duration":20,"images":[],"step":5},{"title":"Strain liquid in slow cooker into a bowl","description":"you will have more than the 2 cups of broth you added, I usually have over 3 cups. Measure out 2 cups of liquid, reserve remaining liquid just in case.","images":[],"step":6},{"description":"Melt butter in a saucepan over medium heat. Add flour and cook for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add a bit of liquid, mixing as you go so it dissolves. Then add remaining liquid. Whisk if there are lumps.","images":[],"step":8},{"description":"Increase to medium high heat and cook, stirring regularly, until thickened to your taste. Use remaining liquid to thin if required.","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","lamb-recipes","main-dishes","quick-and-easy","roast-lamb","roasts","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e9f2798e0ade', 'en', 'US', 'Baked Parmesan Crusted Salmon with Lemon Cream Sauce', 'A simple showstopper salmon recipe! Fantastic centrepiece for a special occasion yet easy enough for midweek. Don''t skip the sauce! It makes all the difference to this dish because the salmon is not marinated. Though made with cream, it is not rich, it''s quite tangy - perfect pairing with rich salmon.', 'https://www.recipetineats.com/tachyon/2016/11/Parmesan-Crusted-Salmon-6.jpg', 10, 30, 40, 6, '[{"id": "ing_salmon_fillets", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.338, "unit": "jar of 200g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 80.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.005, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 2.0, "unit": "bottle of 750ml"}}, {"id": "ing_cream", "quantity": {"value": 0.008, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 (1 - 1.4 kg / 2 - 2.8 lb) side of salmon ( (Note 1))","3- 4 tbsp Dijon mustard"]},{"ingredients":["1 cup panko breadcrumbs (50g) (Note 2)","Oil spray","50g / 3 tbsp butter (, melted)","1/3 cup grated parmesan (, store bought (1/2 cup fresh grated) (Note 3))","2 tbsp finely chopped fresh parsley","2 tbsp finely chopped fresh dill","Zest of 1 lemon","1/2 tsp salt","Pepper"],"purpose":"Parmesan Crumb"},{"ingredients":["30g / 2tbsp butter","1 eschallot / finely chopped (Note 4)","1 1/4 cups dry white wine (Note 5)","1 1/2 cups heavy cream / thickened cream","1 tbsp Dijon mustard","2 1/2 tbsp lemon juice (plus more to taste)","1/2 tsp sugar","Salt and pepper"],"purpose":"Lemon Cream Sauce"},{"ingredients":["Watercress","Lemon wedges","Fresh dill"],"purpose":"Serving"}]', '[{"description":"Take salmon out of the fridge to bring to room temperature.","images":[],"step":1},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":2},{"description":"Spread panko on baking tray, spray generously with oil then bake for 3 to 5 minutes until light golden brown. (Note 6) Scrape into bowl immediately.","duration":4,"images":[],"step":3},{"description":"Add butter and stir, then add remaining Parmesan Crumb ingredients.","images":[],"step":4},{"description":"Line same tray with foil. Place salmon on foil.","images":[],"step":5},{"description":"Spread Dijon on salmon using a butter knife. Just a thin coating - like buttering toast.","images":[],"step":6},{"description":"Sprinkle Crumb all over.","images":[],"step":7},{"description":"Bake for 20 minutes for just cooked juicy perfection, or to taste. (Note 7)","duration":20,"images":[],"step":8},{"description":"Remove from oven. Loosen salmon from foil using egg flip or butter knife - skin will hopefully be stuck to foil.","images":[],"step":9},{"description":"Plate watercress on serving platter.","images":[],"step":10},{"description":"Use foil to lift salmon onto watercress on serving plate, then slide out the foil from under it (see video under recipe). Serve with Lemon Cream Sauce and lemon wedges on the side.","images":[],"step":11},{"description":"Lemon Cream Sauce","images":[],"step":12},{"description":"Melt butter in a saucepan over medium high heat. Add eschalots and cook for 2 minutes. Add wine and bring to boil. Leave to boil rapidly for 5 minutes or until reduced by 3/4 or so.","duration":2,"images":[],"step":13},{"description":"Turn heat down to medium. Add cream, sugar, salt and pepper. Stir, then add lemon juice and mustard. Stir again. Simmer for 2 to 3 minutes or until thickened (see video). Adjust salt, pepper and lemon to taste. Be generous with the salt - remember the salmon is not marinated, the only salt is in the topping.","duration":2.5,"images":[],"step":14},{"title":"Optional","description":"strain. I don''t bother.","images":[],"step":15},{"description":"Allow to cool for 10 minutes or so. It will thicken as it cools. It can be served warm or at room temperature.","duration":10,"images":[],"step":16}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","easter-mains","easter-mains-fish-seafood","easter-recipes","fish-recipes","iconic-dishes","main-dishes","most-popular","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a788c343ff02', 'en', 'US', 'Stovetop Macaroni and Cheese', 'Recipe video above. This classic Macaroni and Cheese just happens to be made in one pot! Though made with the usual ingredients, the sauce is extra silky and glossy, and it clings to the macaroni without having to make make the sauce super thick because the pasta is cooked in the sauce. So there''s no risk of gluggy Mac N Cheese or overcooked pasta.', 'https://www.recipetineats.com/tachyon/2016/11/Mac-and-Cheese-Stovetop_-1.jpg', 3, 15, 18, 5, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 3.0, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}]', '[{"ingredients":["50 g / 3 1/2 tbsp butter","3 tbsp flour","2 cups milk (full fat preferred but low fat is ok)","2 1/2 cups water","250 g / 2 1/2 cups elbow macaroni (, uncooked)","3/4 cup mozzarella cheese (, shredded)","1 1/2 cups cheese (Cheddar, Colby, Gruyere) (, shredded (Note 1))","Salt and pepper"]},{"ingredients":["1 tsp garlic powder","1/2 tsp onion powder","1/2 tsp mustard powder"],"purpose":"Seasonings (optional)"}]', '[{"description":"Melt butter in a medium pot or large saucepan over medium heat. Add flour and cook for 1 minute.","duration":1,"images":[],"step":1},{"description":"Add about 3/4 cup of milk and mix into butter mixture - it will become a slurry pretty quickly.","images":[],"step":2},{"description":"Add remaining milk and mix so the slurry mixes in. Then add water and Seasonings.","images":[],"step":3},{"description":"Add macaroni and mix. Stir occasionally as it comes to heat. When you see wisps of steam as you stir, lower the heat down to medium low.","images":[],"step":4},{"title":"Stir regularly as it cooks for 9","description":"10 minutes (it will bubble gently), or until the sauce thickens and the macaroni is just cooked - tender but still firm. It should still be saucey at this stage and thinner than you want.","duration":9.5,"images":[],"step":5},{"description":"Take it off the stove and stir the cheese in quickly. Adjust salt and pepper to taste. <- In this step, the sauce thickens and reduces considerably.","images":[],"step":6},{"description":"Serve immediately!!","images":[],"step":7}]', '["gluten","milk","mustard"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","easter-recipes","easter-sides-warm-hearty","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","side-dishes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_96589e38feda', 'en', 'US', 'JB''s Cheese Soufflé - Soufflé au Fromage', 'Recipe video above. Cheese Soufflé is a traditional French dish that combines simple pantry staples into something truly special. It rises beautifully in the oven, with a golden top and soft, airy centre. Don’t be intimidated by the name, it’s easier than you think to make it at home. I promise! I still remember my restaurant days, total chaos every time a soufflé came out of the oven. Someone would shout “Soufflé!!” and hope the wait staff appeared instantly, because one thing’s for sure: Soufflé doesn’t wait.', 'https://www.recipetineats.com/tachyon/2025/10/Cheese-souffle_6.jpg', 15, 30, 45, 4, '[{"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 0.25, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 0.333, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 cups full fat milk (, but works with lite milk too)","75 g (5 tbsp) unsalted butter","1/2 cup plain flour (all-purpose)","1/2 tsp cooking salt / kosher salt (halve for table salt, + 50% for flakes)","2 pinches ground white pepper (substitute black pepper)","150 g (1 1/2 cups) Gruyère cheese (, shredded using a standard box grater (tightly packed if using cups) (Note 2 for other cheeses))","3 egg yolks (from large eggs (55g/2oz each in shell), at room temperature (Note 1))","4 egg whites (from large eggs, at room temperature (total egg whites ~ 120g/4.2oz, Note1))","1/2 tsp cream of tartar (, sifted if lumpy (Note 3))","15 g (1 tbsp) unsalted butter (, melted (to grease the ramekins))"]}]', '[{"description":"Melt butter, cook flour 2 minutes, whisk in warm milk in 3 batches. Add salt and pepper, turn off heat, whisk in yolks one at a time, then melt through gruyere over low heat. Beat egg whites and cream of tartar to firm peaks, starting on medium for 2 minutes, then increasing to high. Whisk 1/4 of the whites into Mornay Sauce, then fold through remainder in 3 batches. Fill butter brushed ramekins to 1cm/0.4” from rim, clean inside of rim. Bake at 200°C/400°F (180°C fan) for 20 minutes. No peeking! Serve immediately.","duration":2,"images":[],"step":1},{"description":"Preheat oven to 200°C / 400°F (180°C fan-forced). A properly hot oven is crucial, it''s what gives the soufflé its famous lift. A cold oven = a sad soufflé.","images":[],"step":2},{"title":"Prepare the ramekins (Note 4)","description":"Brush the insides of 4 (325ml / 1 1/3 cups) ramekins generously with melted butter (use all the butter). No need to brush upwards (see post for why). Set on a baking tray.","images":[],"step":3},{"description":"Make Mornay sauce (cheese sauce)","images":[],"step":4},{"title":"Heat the milk","description":"Place the milk in a small saucepan over medium heat. Warm it until it’s steaming but not boiling. Set aside.","images":[],"step":5},{"title":"Make the roux","description":"While the milk is heating, let’s start our roux. In a large saucepan, melt the butter over medium heat. Once melted, add the flour. Whisk it gently, it will be thick and pasty at first like a wet sand. Cook, whisking constantly, for about 2 minutes. It will thin up and become smooth and glossy. Make sure to use the whisk to get into the corners of the pot and don’t let it brown. Reduce heat if you think it’s too high.","images":[],"step":6},{"title":"Make Béchamel","description":"Add a third of the hot milk to the roux while whisking vigorously, it will thicken very quickly. Add half of the leftover milk, whisk until smooth and then pour the rest of it along with the salt and pepper. Keep whisking for 30 seconds to a minute until thickened and smooth, lumps will go away. It will be thick enough so you can draw a path with a spatula in the middle, it should hold its shape for a moment before slowly sinking back.","duration":0.5,"images":[],"step":7},{"title":"Turn it into a Mornay sauce","description":"Turn off the heat and whisk in the egg yolks, one at a time, until fully combined (don''t worry the egg yolks won''t cook). Then, turn the heat back on to medium and whisk in the grated Gruyère until melted through. Scrape down the sides and cover with a lid. Set aside.","images":[],"step":8},{"description":"Folding in the Egg Whites and Baking","images":[],"step":9},{"title":"Beat the egg whites, gently at first","description":"Add egg whites and the cream of tartar in a large bowl. Using a hand mixer or a stand mixer fitted with a whisk attachment, beat the egg whites on medium speed for 2 minutes then high speed for 30 seconds until you get firm peaks. Starting slowly helps the protein structure to develop properly. Rush it and you risk unstable, foamy whites that collapse when folded in.","duration":2,"images":[],"step":10},{"title":"Fold gently","description":"Give the Mornay a quick whisk to make it smooth again then add in a quarter of the egg whites and whisk it in to loosen it. Then gently fold a third of the remaining egg whites in using a rubber spatula until mostly incorporated. Use slow, sweeping motions from the bottom of the pot, you want to keep as much air in as possible. (See video at 2.15 minutes) Rough folding = flat soufflé. Few lumps are ok. Repeat twice more with the rest of the egg whites.","images":[],"step":11},{"title":"Fill the ramekins","description":"Pour the mixture evenly into the ramekins using a ladle or a large serving spoon, filling to about 1cm / 0.4\" below the rim. Smooth the tops with the back of a teaspoon dipped in water, no need to be 100% meticulous here, just get rid of big bumps. Run your thumb around the inside rim of each ramekin to clean it, this gives the soufflé a clean edge to rise against.","images":[],"step":12},{"title":"Bake","description":"Place the ramekins on a baking tray and bake for 20 minutes until tall and golden. Do not open the oven door while it''s baking, the sudden drop in heat will make them sink. When it''s cooked, the soufflés should jiggle a bit when you shake the ramekin.","duration":20,"images":[],"step":13},{"title":"Serve immediately","description":"As soon as they’re out, serve straight away. Soufflés don''t wait. So make sure all your family/guest are seated so they can enjoy the show!","images":[],"step":14}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner","lunch","snack"],"cuisine":["French"],"categories":["easter-brunch-recipes","egg-recipes","iconic-dishes","jbs-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_882560a6a52e', 'en', 'US', 'Pearl Couscous Salad', 'Recipe video above. I adore the bright Mediterranean flavours in this salad! Great one to take to gatherings for something a little different that everyone always loves. Serve as a side (6 to 8) or a meal in itself (serves 4).Also known as Israeli and gourmet Couscous, pearl couscous is the big brother version of the more common small couscous. Texture and taste like pasta – soft but a bit chewy, but has a pearly, slippery surface (hence the name).', 'https://www.recipetineats.com/tachyon/2017/07/Israeli-Couscous-Salad-3.jpg', 15, 15, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_pears", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 250.0, "unit": "punnet of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tsp olive oil","1 garlic clove (, minced)","½ small onion (, finely chopped)","1 1/2 cups (250g/ 8oz) pearl couscous (aka gourmet or Israeli couscous, Note 1)","1 1/2 cups vegetable or chicken broth (, low sodium)","1 cup water"],"purpose":"Couscous:"},{"ingredients":["2 cucumbers (, diced (about 2 cups))","250g / 8 oz cherry tomatoes (, halved (about 2 cups))","3 cups baby spinach (, finely sliced (Note 2))","¼ cup coriander / cilantro (, finely chopped (or sub with parsley))","¼ cup dill (, finely chopped)"],"purpose":"Salad:"},{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice","1/4 cup extra virgin olive oil","1 tsp Dijon mustard","1 garlic clove (, minced)","1 tsp sugar (, optional)","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Lemon Dressing (Note 3):"}]', '[{"title":"Sauté onion & garlic","description":"Heat oil in a large saucepan or small pot over medium high heat. Add garlic and onion, saute until the onion is translucent and starting to brown.","images":[],"step":1},{"title":"Couscous & broth","description":"Add couscous and stir, cooking for 1 minute. Add broth and water, bring to a simmer. Then place the lid on and turn the heat down to medium low so it is simmering gently.","duration":1,"images":[],"step":2},{"description":"Cook for 10 minutes until the liquid is absorbed and the couscous is cooked through but still firm. Use a fork to separate the couscous, then transfer into a large bowl to cool. (It will form a sticky block but don''t worry, it will separate when tossed with Dressing).","duration":10,"images":[],"step":3},{"title":"Dressing","description":"Place Dressing ingredients in a jar and shake well.","images":[],"step":4},{"description":"Toss! Add Salad ingredients into the bowl, pour over Dressing and toss. Serve at room temperature.","images":[],"step":5}]', '["gluten","mustard"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-brunch-recipes","easter-sides-fresh-light","mediterranean-recipes","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","salad-recipes-main-course","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c6fa390416b4', 'en', 'US', 'Christmas Baked Salmon', 'Recipe video above. Have you ever seen a Baked Salmon that looks so festive? What''s more, it''s DEAD EASY! Featuring a honey butter-glazed side of salmon baked in foil, slathered with creamy dill sauce and finally topped with a glittering Holiday "Tapenade", this Salmon Tarator inspired dish pays extremely high dividends for very little work.See notes for alternatives for many of the ingredients - even the salmon!', 'https://www.recipetineats.com/tachyon/2020/12/Christmas-Baked-Salmon_5.jpg', 20, 30, 50, 12, '[{"id": "ing_salmon_fillets", "quantity": {"value": 1.35, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.008, "unit": "tub of 250g"}}, {"id": "ing_dill", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_cranberries", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.8, "unit": "pack of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pomegranate", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_emons", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["1.2 - 1.5 kg / 2.4 - 3lb salmon side (skin on, bones removed, Note 1)","2 1/4 tsp salt (, cooking/kosher (Note 2))","1 tsp black pepper"],"purpose":"Salmon:"},{"ingredients":["150g / 5oz butter (, unsalted)","1/2 cup honey","3 garlic cloves (, finely minced (garlic press or knife))"],"purpose":"Honey Butter Glaze:"},{"ingredients":["1 1/2 cups sour cream (, full fat (low fat is too watery))","1/2 cup fresh dill (, finely chopped (lightly packed cup))","1/2 eschallot (French onion) (, finely grated)","1 1/2 tbsp lemon zest","1/2 tsp salt (, cooking/kosher (Note 2))"],"purpose":"Creamy Dill Sauce:"},{"ingredients":["1 cup dried cranberries","1 cup orange juice","1 cup slivered almonds (, toasted (Note 3))","1/3 cup parsley (, roughly chopped)","1/4 tsp each salt and pepper","1 tbsp extra virgin olive oil"],"purpose":"Holiday \"Tapenade\":"},{"ingredients":["1 pomegranate (, only the seeds)","1/4 cup parsley (, roughly chopped)","3 tbsp lemon juice","2 lemons, extra (, cut in 6 pieces each (for serving, don''t skip this))"],"purpose":"Finishing:"}]', '[{"description":"Creamy Dill Sauce","images":[],"step":1},{"description":"Mix ingredients in a bowl until smooth. Keep refrigerated until required.","images":[],"step":2},{"description":"Holiday Tapenade","images":[],"step":3},{"title":"Plump cranberries","description":"Heat orange juice in a saucepan over high heat until hot. Turn stove off, add cranberries, cover. Stand 15 minutes, then drain in a colander (discard liquid). Cool.","images":[],"step":4},{"title":"Mix","description":"Mix cranberries, toasted almonds (see Note 3), parsley, salt and olive oil in bowl. Use at room temp.","images":[],"step":5},{"description":"Cooking salmon","images":[],"step":6},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":7},{"title":"Prepare salmon","description":"Place a large sheet of foil on a tray (double layer for safety is recommended), then top with baking/parchment paper. Place salmon on paper, then fold up the foil sides a bit to cup them so glaze won''t run onto tray.","images":[],"step":8},{"title":"Glaze","description":"Place ingredients in a saucepan over medium high heat. Once it started foaming, turn down to medium, let it foam for 2 minutes then remove and pour straight over the salmon.","duration":2,"images":[],"step":9},{"title":"Season","description":"Sprinkle salmon with salt and pepper, putting most of the salt on the thicker part of the salmon.","images":[],"step":10},{"title":"Wrap","description":"Cover salmon with a smaller piece of paper, then foil. Fold and seal up sides to enclose salmon in a parcel - it doesn''t need to be 100% tightly sealed.","images":[],"step":11},{"description":"Bake 15 minutes. Remove salmon from oven.","images":[],"step":12},{"title":"Uncover / fold excess paper","description":"Remove paper and foil and paper cover. Fold/scrunch paper and foil sides down to expose salmon surface. Tucking paper down also ensures it won''t catch fire when broiling.","images":[],"step":13},{"title":"Grill/broil to brown","description":"Switch oven to grill/broiler on high. Place salmon on middle shelf in the oven and broil 7 to 10 minutes until you get caramelisation mostly on the edges, a bit on top. Don''t put it too close to the heat element otherwise paper might catch on fire! Check to ensure salmon is cooked - either pry open in middle to check or use a probe to check internal temperatures (Note 4).","images":[],"step":14},{"title":"Transfer to plate","description":"Use foil overhang to transfer salmon onto serving platter straight away (otherwise it keeps cooking). Slide the foil then paper out from under the salmon (see video at 1 min 24s or step photos in post), allowing juices to pool on platter (it''s gold stuff!).","images":[],"step":15},{"title":"Cool","description":"Loosely cover with foil, then leave to cool for at least 15 minutes, up to 1 hour or longer (for room temp serving - Note 6 for serving notes).","images":[],"step":16},{"description":"Assembly and serving","images":[],"step":17},{"description":"Dollop then thickly spread with Creamy Dill Sauce (~0.8cm / 1/3\" thick layer).","images":[],"step":18},{"description":"Pile over Holiday Tapenade, scatter generously with pomegranate seeds, and then remaining parsley. Squeeze over lemon juice.","images":[],"step":19},{"title":"Serving","description":"Serve with extra lemon wedges so people can add more to taste. Cut into pieces - I use a cake cutter for serving. Encourage people to slop up some of the honey-butter sauce that will be mixed with semi melted Creamy Dill Sauce - it''s so good! This dish is best served slightly warm, not piping hot, also excellent at room temp.","images":[],"step":20}]', '["fish","milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-mains-fish-seafood","fish-recipes","mains","other","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2d8e8d49a951', 'en', 'US', 'Spanakopita', 'Recipe video above. Spanakopita - the iconic traditional Greek Spinach Pie with layers upon layers of golden buttery flaky filo pastry. For the best Spanakopita of your life, use raw rather than cooked spinach, and layer the phyllo pastry with finely shredded Greek cheese so it sticks together rather than flying everywhere when you cut it!This pie is a perfect thickness with a good ratio of Spinach Feta filling to pastry. It will serve 4 to 5 people as a main dish.', 'https://www.recipetineats.com/tachyon/2021/03/Spanakopita_0-1-1.jpg', 40, 25, 65, 4, '[{"id": "ing_spinach", "quantity": {"value": 300.0, "unit": "bag of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_feta_cheese", "quantity": {"value": 175.0, "unit": "block of 200g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_mint", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_sheets_filo_pastry", "quantity": {"value": 16.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["300g/10oz English spinach leaves","1/2 tsp salt"],"purpose":"Spinach:"},{"ingredients":["175g/6oz Greek feta (, crumbled)","1/2 cup Greek yoghurt","2 green onions / scallions (, finely sliced)","1 egg","2 tbsp mint (, finely chopped)","1 tbsp dill (, finely chopped)","1/2 tsp lemon zest","1/2 tbsp lemon juice","2 garlic cloves (, finely chopped)","1/2 tsp nutmeg (, freshly grated)","1/4 tsp black pepper","1/4 tsp salt","1/4 tsp cayenne pepper"],"purpose":"Filling:"},{"ingredients":["16 sheets filo pastry (Note 2)","120g/ 8 tbsp butter (, melted)","60g / 2/3 cup Greek Kefalotyri cheese (, finely grated (sub parmesan, Note 3))","1/2 tsp white sesame seeds (or more black)","1/2 tsp black sesame seeds (or more white)"],"purpose":"Filo pastry:"}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan). Line a tray with baking paper / parchment paper.","images":[],"step":1},{"title":"Sweat spinach","description":"Place spinach in a large colander or bowl. Sprinkle with salt, toss through. Leave for 10 minutes to sweat.","duration":10,"images":[],"step":2},{"title":"Wring out water","description":"Place a handful of spinach in a tea towel, then wring out tightly to remove excess water.","images":[],"step":3},{"title":"Filling","description":"Place spinach in a bowl with remaining Filling ingredients. Mix well to combine.","images":[],"step":4},{"title":"Trim filo","description":"Cut 16 sheets of filo pastry into 32 x 25cm / 13 x 10\" (pictured) or 26cm / 10.5\" square.","images":[],"step":5},{"title":"8 base layers","description":"Layer 8 sheets of filo pastry on the tray, brushing each layer with melted butter.","images":[],"step":6},{"title":"Filling","description":"Spread filling on filo pastry. Smooth surface and leave a 2.5cm / 1\" border.","images":[],"step":7},{"title":"8 Filo topping layers (Note 4)","description":"Cover spinach with a sheet of filo pastry. Brush with butter, sprinkle with Kefalotyri. Repeat for Sheets #2 to #5. Then cover with filo sheets #6 to #8, brushing with butter in between, but do NOT sprinkle with cheese (neater finish).","images":[],"step":8},{"title":"Seal","description":"Press edges down to seal. Crimp and trim if desired (see process steps in post or video) or just leave the edges flat on the tray.","images":[],"step":9},{"title":"Sesame seeds","description":"Brush the top with butter, sprinkle with sesame seeds.","images":[],"step":10},{"title":"Bake","description":"Bake 25 minutes, or until golden brown on the surface.","images":[],"step":11},{"description":"Serve! Serve immediately! It is at its absolute prime fresh out of the oven, though still good as long as its hot (~15 min or so). The base does lose crispiness as it cools.","images":[],"step":12}]', '["egg","milk","sesame"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["easter-mains","greek-recipes","iconic-dishes","mediterranean-recipes","quiches-tart-and-pie-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c0d8526319a5', 'en', 'US', 'Fish koftas', 'Recipe video above. These fish koftas are like your favourite Middle Eastern lamb koftas - except made with fish. Adore the spicing! Serve with Jewelled rice pilaf for a stunning platter of food.Makes 10 to 12 koftas, serves 4 to 5.', 'https://www.recipetineats.com/tachyon/2023/04/Fish-koftas_4.jpg', 20, 10, 35, 10, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_feta_cheese", "quantity": {"value": 70.0, "unit": "block of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.006, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["500g/1 lb white fish fillets (,skinless, cut in pieces (Note 1))","1 egg white (add leftover yolk to scrambled eggs!)","1/2 red onion (, grated using a box grater (keeps koftas soft!))","2 garlic (, finely minced)","1 tsp cumin powder","1 tsp coriander powder","1/4 tsp cinnamon powder","1/4 tsp cardamom powder","1 tsp cooking salt (kosher salt)","1/2 cup rice flour (sub cornflour/cornstarch)","2 tbsp chopped parsley","70g/ 2.5 oz danish feta (, plus extra for optional garnish (Note 2))","2 tbsp extra virgin olive oil"]},{"ingredients":["3/4 cup plain yogurt (, unsweetened)","1/2 cup (tightly packed) mint leaves","2 tsp lemon juice","1/4 tsp cooking / kosher salt"],"purpose":"Minted yogurt"},{"ingredients":["Parsley or coriander (, roughly chopped)","Persian Jewelled Rice (or plain basmati rice)"],"purpose":"Serving (optional, pictured)"}]', '[{"title":"Fish & egg blitz","description":"Place fish and egg white in a food processor. Blitz on high until smooth. (30 sec to 1 minute) A stick blender also works but it will take a bit longer.","images":[],"step":1},{"title":"Kofta mixture","description":"Add onion, garlic, all the spices, salt, rice flour and parsley. Blitz on high until smooth (1 minute). Consistency should be like a paste. (Note","images":[],"step":2},{"title":"Feta","description":"Remove the blade, then crumble the feta in. Aim for chunks. Mix delicately (so the feta doesn''t disintegrate).","images":[],"step":3},{"title":"Form koftas","description":"Use wet hands so the mixture doesn''t stick. Portion the mixture into 10 - 12 (70g / 1/3 cup each), and shape into a 10cm / 4\" cylinder. Thread onto skewers then slightly flatten to 1.75cm / 2/3\" thick. (Note 3)","images":[],"step":4},{"title":"Cook","description":"Heat olive oil over medium high heat in a large non-stick pan. Cook half the koftas for 2 minutes on each side until golden, or until the internal temperature reaches 50°C/122°F.","duration":2,"images":[],"step":5},{"title":"Rest","description":"Remove onto a plate and cook the remaining koftas. (Internal temperature of cooked koftas will rise to 55°C/131°F).","images":[],"step":6},{"description":"Serve with Minted Yogurt and Jewelled rice pilaf for a stunning platter of food!","images":[],"step":7},{"description":"Blitz all ingredients in a tall jug just large enough to fit a stick blender. Keep refrigerated until required.","images":[],"step":8}]', '["egg","fish","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Persian"],"categories":["easter-mains-fish-seafood","fish-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b43d6353d607', 'en', 'US', 'Singapore Chilli Crab', 'Recipe video above. Here''s arguably the most famous crab recipe in the world: Singapore Chilli Crab! For the pinnacle of the experience, make this using fresh, live mud crab that you clean and cut yourself, or ask the fish shop to cut the crab for you (make sure they save the tomalley "crab mustard", Note 8). Be prepared to get messy eating it (half the fun!) – and to be surprised at how quick it is to make! Flavour: The sauce is a bit spicy but not excessively (Note 2 for adjustment). It is supposed to be a bit sweet, vinegary and intensely savoury. It gets massive flavour from the combination of crab juices, tomalley ("crab mustard", Note 8), belachan shrimp paste, and the soy bean paste! The traditional sauce has bits of egg ribbson in it, and includes ketchup - yes, really!Serves 3 - 4 as a meal with rice and some vegetables.', 'https://www.recipetineats.com/tachyon/2021/07/Singapore-Chilli-Crab_4.jpg', 20, 20, 40, 3, '[{"id": "ing_live_mud_crab_or_other_large_crab", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_taucu_paste", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.012, "unit": "pack of 3 heads"}}, {"id": "ing_eschalots", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.12, "unit": "bottle of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1.5 kg / 3lb live mud crab or other large, fresh crab"]},{"ingredients":["5 red cayenne chilli (, seeds left in, roughly chopped (Note 2))","2 tbsp taucu paste (fermeted soy paste, sub miso Note 3)","6 garlic cloves ((small), roughly chopped)","2 eschalots (small), roughly chopped (Note 4)","3 tbsp ginger (, roughly chopped (~7.5cm / 3\" piece))"],"purpose":"Chilli paste:"},{"ingredients":["1/4 cup canola oil","1 tbsp belachan dried shrimp paste (, chopped (sub shrimp paste, Note 5))","1 cup tomato passata (Note 6)","1/2 cup sweet chilli sauce","2 tbsp ketchup","2 cups water","1 egg (, lightly whisked)","3 tbsp white vinegar"],"purpose":"Singapore Chilli Crab Sauce:"},{"ingredients":["Fresh coriander (, leaves whole or roughly chopped)","2 tbsp green onion (, finely sliced (or 1/4 cup finely sliced on angle, ice water 3 minutes for slight curl))","Golden mantou buns (Note 7)"],"purpose":"Garnishes/serving:"}]', '[{"title":"Prepare crab","description":"See separate tutorial for how to clean and cut a whole crab. You will end up with: 1) Crab pieces; and 2) Reserved tomalley (\"crab mustard\", Note 8) and crab juices in a separate bowl. This is a key \"secret ingredient\" used to flavour the sauce.","images":[],"step":1},{"title":"Chilli paste","description":"Place ingredients in a small food processor or Nutribullet. Blitz until it''s a fairly smooth paste.","images":[],"step":2},{"title":"Sauté belachan","description":"Heat oil in a large pot over medium-high heat. Add belachan and cook for 2 minutes, stirring constantly. It will smell pungent (to put it mildly), but have faith! It will mellow and transform!","duration":2,"images":[],"step":3},{"title":"Cook off chilli paste","description":"Add chilli paste and cook, stirring, for 3 minutes.","duration":3,"images":[],"step":4},{"title":"Add tomato passata","description":"Add tomato passata and cook, stirring regularly, for 4 minutes.","duration":4,"images":[],"step":5},{"title":"Add remaining sauce ingredients","description":"Add sweet chilli sauce, ketchup, water and stir to combine.","images":[],"step":6},{"title":"Add claws","description":"Add the crab claws first (they take longer to cook), stir to coat in sauce. Bring to a boil, then reduce heat to simmer. Cover with a lid and cook 3 minutes.","images":[],"step":7},{"title":"Add \"crab mustard\" and juices","description":"Add the reserved tomalley (\"crab mustard\") along with all the crab juices.","images":[],"step":8},{"title":"Add remaining crab pieces","description":"Remove lid, add remaining crab pieces and any juices that have collected in this bowl. Stir pieces to coat, put the lid back on and cook for 7 minutes.","duration":7,"images":[],"step":9},{"title":"Remove crab","description":"Use tongs to remove crab pieces into a bowl.","images":[],"step":10},{"title":"Egg ribbons","description":"With the sauce still on the stove, and while stirring in a circular motion, pour the egg in a thin stream into the middle of the pot. This will create little ribbons of egg in the sauce that is traditional and look lovely.","images":[],"step":11},{"title":"Vinegar","description":"Stir in vinegar.","images":[],"step":12},{"title":"Return crab","description":"Return the crab pieces into the pot, gently stir to coat in the sauce.","images":[],"step":13},{"description":"Plating up and serving:","images":[],"step":14},{"description":"Transfer crab pieces into a large serving plate or shallow dish. Pour over all the sauce from the pot. Garnish with coriander and green onion.","images":[],"step":15},{"description":"Serve with golden mantou buns (steamed and fried Chinese buns, traditional - Note 7), or homemade brioche (ultimate sub!), baguette, crusty bread or dinner rolls. Alternatively serve with rice on the side.","images":[],"step":16},{"title":"How to eat","description":"Be prepared to get messy! Dive in for the claw (the prime piece!). Use crab or nut crackers to break the shell (or a meat tenderiser or hammer - anything to get to that meat!!) and reveal hunks of sweet juicy crab meat. Dunk generously in sauce and devour.","images":[],"step":17},{"title":"Leftover Sauce","description":"You will have leftover sauce. It''s loaded with flavour so save it, it''s precious! See in post for ideas for how to use.","images":[],"step":18}]', '["egg","shellfish","soy"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Singapore"],"categories":["easter-mains-fish-seafood","iconic-dishes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a590753dfec0', 'en', 'US', '"Poor Man''s Lobster" – Monkfish with Herb Browned Butter', 'Recipe video above. With sweet, meaty shellfish-like flesh, monkfish is affectionately known as "poor man''s lobster". But there''s certainly nothing "poor" about this dish!If you''re new to cooking monkfish, this is a good recipe to try. It''s easy and showcases just how good monkfish is. There''s a reason it''s a firm favourite with upmarket restaurants!Other names: Stargazer is another name for monkfish in Australia.Allow around 150 - 180g / 5 - 6oz monkfish per serving.', 'https://www.recipetineats.com/tachyon/2021/06/Monkfish_1.jpg', 10, 8, 18, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chives", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chervil", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["300g / 10oz monkfish fillets (, skinless and boneless (Note 1))","1 1/2 tbsp extra virgin olive oil","1/4 tsp salt","1/8 tsp black pepper (, finely ground)","2 tbsp/ 30g unsalted butter (, cut into 1cm (1/2\") cubes)","2 garlic cloves (, smashed (Note 2))","2 sprigs thyme"]},{"ingredients":["1/2 tsp parsley (, finely chopped)","1/2 tsp chives (, finely chopped)","1/2 tsp chervil (, finely chopped)"],"purpose":"Fresh herbs (Note 3):"}]', '[{"title":"Cut fillets","description":"Cut each monkfish into 3 or 4 even size pieces. (Note 1)","images":[],"step":1},{"title":"Season","description":"Sprinkle both sides of fish with salt and pepper.","images":[],"step":2},{"title":"Rack for resting","description":"Place a rack over a tray (optional, for resting fish, Note 5)","images":[],"step":3},{"description":"Cooking monkfish (Note 2):","images":[],"step":4},{"title":"Heat oil","description":"Heat oil in non-stick pan over medium heat (medium-high for weak stoves).","images":[],"step":5},{"title":"Sear first side, then turn","description":"Place thickest pieces of fish in the pan first. Leave for 1 minute then add the thinner pieces. (Note 4). Cook for a further 2 minutes, then flip fish.","duration":1,"images":[],"step":6},{"title":"Add butter and baste","description":"Add butter to pan. After it starts melting, add garlic and thyme. When the butter starts foaming, tilt the pan and start spooning the butter over the fish. Do this for 2 minutes or until the internal temperature is 55°C/131°F (Note 6), or the flesh flakes easily. Butter will begin to smell nutty - it''s now brown butter!","duration":2,"images":[],"step":7},{"title":"Rest","description":"Transfer fish onto the rack and rest for 3 minutes.","duration":3,"images":[],"step":8},{"title":"Add herbs","description":"Add herbs to butter remaining in pan. Serve this Herb Brown Butter with monkfish.","images":[],"step":9},{"description":"Optional plating up, fine dining style!","images":[],"step":10},{"description":"Slice monkfish into 2.5cm / 1\" pieces. Place on pea puree, then drizzle with Herb Brown Butter. Optional garnish with any combination of dill, parsley, chervil.","images":[],"step":11}]', '["milk"]', '["gluten_free","high_protein","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","easter-mains-fish-seafood","fish-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8037edf11742', 'en', 'US', 'Acqua Pazza - Italian Poached Fish', 'Recipe video above. This is a recipe that showcases Italian cooking at its best: a handful of simple ingredients to create something magical! Fish is half poached, half steamed in a tomato-white wine based sauce, then served over crispy garlic crostini.The literal translation of this dish is "fish in crazy water". Maybe because who would think that fish poached in water could be so delicious? That''s crazy! :)', 'https://www.recipetineats.com/tachyon/2021/02/Acqua-Pazza_0.jpg', 10, 40, 50, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.052, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_fennel", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 15.0, "unit": "punnet of 250g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 10.0, "unit": "punnet of 250g"}}, {"id": "ing_chardonnay", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}]', '[{"ingredients":["2 x 180g/6oz snapper fillets, or other white fish, (, skin on, bones and scales removed (Note 1))","1/4 tsp salt"]},{"ingredients":["2 tbsp extra virgin olive oil","1/4 red onion (, sliced 1cm / 1/3\" thick)","1/2 fennel (medium) (, sliced sliced 1cm / 1/3\" thick)","1/2 large red chilli (cayenne pepper) (, seeds removed and finely chopped (Note 2))","2 garlic cloves (, finely minced)","15 red cherry tomatoes (, halved)","10 yellow cherry tomatoes (, halved (or more red))","3/4 cup chardonnay (not too woody) (, or other dry white wine (Note 3))","2 cups water","1/4 tsp salt","1 tbsp basil (, finely sliced (keep stems), plus more for garnish)","1 tbsp parsley (, finely chopped (keep stems))"],"purpose":"Sauce:"},{"ingredients":["1 crusty baguette (, cut 4 to 6 slices on a diagonal, 1cm / 1/3\" thick)","1/4 tsp salt","1 - 2 tbsp extra virgin olive oil","1 garlic clove (, halved (for rubbing))"],"purpose":"Garlic Crostini:"}]', '[{"title":"Sauté fennel and onion","description":"Heat oil in a non-stick skillet over medium heat. Add fennel and onion, cook 4 minutes until softened but not golden.","images":[],"step":1},{"title":"Garlic and chilli","description":"Add garlic and chilli, cook for 1 minute until garlic is softened.","duration":1,"images":[],"step":2},{"title":"Tomatoes","description":"Add cherry tomatoes, cook for 4 minutes.","duration":4,"images":[],"step":3},{"title":"Reduce wine","description":"Turn stove up to high, add wine and simmer rapidly for 2 - 3 minutes until reduced by half.","duration":2.5,"images":[],"step":4},{"title":"Simmer sauce","description":"Add water and salt, and the basil & parsley stems if you kept them. Bring to boil, then lower stove to medium and simmer for 20 - 25 minutes until sauce reduces by about 2/3 (it will thicken from tomatoes breaking down).","duration":22.5,"images":[],"step":5},{"title":"Cook fish","description":"Sprinkle flesh side of fish with salt, then place on sauce skin side down (it will mostly sit above sauce). Cover with lid (or foil or tray) and cook for 6 minutes or until internal temperature registers 55°C/131°F (for medium, no rare/raw left with optimum juiciness).","duration":6,"images":[],"step":6},{"title":"Remove fish","description":"Remove lid, transfer fish to plate.","images":[],"step":7},{"title":"Add herbs","description":"Remove basil and parsley stems. Stir basil and parsley into sauce. Taste sauce, add more salt if required.","images":[],"step":8},{"description":"To serve:","images":[],"step":9},{"description":"Place 2 crostini in a shallow bowl. Spoon over a bit of the chunky sauce, top with fish. Spoon remaining sauce around.","images":[],"step":10},{"description":"Garnish with extra basil and a drizzle of olive oil. Serve immediately.","images":[],"step":11},{"description":"Garlic crostini:","images":[],"step":12},{"description":"Preheat oven to 180°C/350°F (all types).","images":[],"step":13},{"description":"Brush olive oil on bread, sprinkle with a bit of salt. Flip and repeat. Bake 10 minutes, turning halfway, or until fully crispy.","images":[],"step":14},{"description":"Rub bread lightly on one side with cut face of garlic. Use warm or at room temperature.","images":[],"step":15}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["easter-mains-fish-seafood","fish-recipes","italian-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_040012ed299e', 'en', 'US', 'Seafood Spaghetti Marinara', 'A classic seafood pasta made with a pre-made seafood marinara mix. This is really simple to make, and the key to this recipe is the step where the pasta is finished cooking in the sauce. This is called "emulsifying", and it''s an essential Italian cooking technique where the starch in the pasta cooking water reacts with the oil in the sauce and makes the sauce thick and luscious so it coats every strand of pasta.', 'https://www.recipetineats.com/tachyon/2016/06/Seafood-Marinara-Spaghetti_2.jpg', 5, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 6.0, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_seafood_marinara_mix", "quantity": {"value": 10.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["6 oz / 180g dried spaghetti pasta (or other long pasta of choice)","2 1/2 tbsp olive oil (, separated)","10 oz / 300g seafood Marinara mix (, or make your own (Note 1))","2 garlic cloves (, minced)","1/2 onion (, finely chopped (~1/2 cup))","1/2 cup white wine (any) (Note 2)","2 cups tomato passata/tomato puree ((Note 3) OR 600g/20oz canned crushed tomato + 1/2 cup water)","1/2 tsp sugar","2 tbsp finely chopped fresh parsley"]}]', '[{"description":"Bring a large pot of salted water to boil. Cook pasta according to packet directions, but reduce the cooking time by 1 minute (because the pasta will finish cooking in the sauce). RESERVE 1 mug of pasta water, then drain the pasta.","images":[],"step":1},{"description":"Separate the seafood mix based on cook time. Longest cook time: fish and medium / large prawns, medium cook time: small prawns, shortest cook time: calamari.","images":[],"step":2},{"description":"Heat 1 1/2 tbsp oil in a large skillet over high heat. Add fish and large prawns first, cook for 30 seconds. Add small prawns, cook for 30 seconds. Add calamari, cook for 1 minute. Immediately transfer everything to a bowl.","duration":0.5,"images":[],"step":3},{"description":"Reduce heat to medium high. Heat remaining 1 tbsp oil, then add garlic and onion. Cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":4},{"description":"Add wine and bring to simmer, scraping the bottom of the skillet to mix the brown bits into the liquid. Simmer for 1 minute or until alcohol smell has evaporated.","duration":1,"images":[],"step":5},{"description":"Add tomato passata, sugar, salt & pepper. Low heat to medium high, bring to simmer and cook for 2 minutes. Adjust salt and pepper to taste.","duration":2,"images":[],"step":6},{"description":"Add pasta, seafood, around 1/2 cup of reserved pasta cooking water into the sauce. Toss gently and cook for 1 to 2 minutes or until the sauce has thickened and coats the pasta.","duration":1.5,"images":[],"step":7},{"description":"Serve, garnished with fresh parsley. (See Note 4 re: parmesan cheese)","images":[],"step":8}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","easter-mains-fish-seafood","italian-recipes","main-dishes","pasta-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_182ebe92bda0', 'en', 'US', 'Italian Pasta Salad with Homemade Italian Dressing', 'Recipe video above. If you''re going to make a giant pasta, make it RIGHT with a beautiful homemade Italian Dressing!', 'https://www.recipetineats.com/tachyon/2017/03/Italian-Pasta-Salad-2.jpg', 15, 10, 25, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_thick_salami_cut_into_2_5cm_1_batons", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_baby_bocconcini", "quantity": {"value": 200.0, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_whole_olives", "quantity": {"value": 250.0, "unit": "bottle"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 2.0, "unit": "punnet of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup extra virgin olive oil","1/4 cup red or white wine vinegar (I like using red)","1 1/2 tbsp freshly grated parmesan cheese (Note 1)","1 tbsp sugar (any)","1 large garlic clove, minced","1/2 tsp each dried basil and oregano","1/4 tsp dried parsley","1/2 tsp dried chilli flakes (red pepper flakes) (optional)","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Italian Dressing"},{"ingredients":["300g/10oz spiral pasta, or other pasta of choice","180g/6oz thick sliced salami, cut into 2.5cm/1\" batons (see photo in post or videos) (I use spicy salami)","200g/7oz baby bocconcini, halved (Note 2)","1 red capsicum/bell pepper, cut into 3cm/2.2cm strips","250g/8oz whole olives (I used Sicilian and pitted black) (Note 3)","2 cups cherry tomatoes, halved (~1.5 Australian punnets)","1 cup (tightly packed) fresh basil leaves"],"purpose":"Pasta Salad"}]', '[{"description":"Place Dressing ingredients in a jar and shake well.","images":[],"step":1},{"description":"Cook pasta according to packet directions minus 1 minute. Drain in a colander and rinse under cold water to stop it cooking further. Shake excess water off well then transfer into large bowl.","images":[],"step":2},{"description":"Place remaining Pasta Salad ingredients in the bowl. Drizzle over Dressing and toss. Serve at room temperature.","images":[],"step":3},{"description":"Make ahead PRO TIP (Note 4):","images":[],"step":4},{"description":"SCOOP OUT a mug of pasta cooking water just before draining. Add 3 tbsp water to Dressing, shake well. Use this Dressing per above, but reserve 3 tbsp to freshen up pasta salad on Day 2 onwards.","images":[],"step":5},{"title":"Freshen up pasta salad","description":"Bring to room temp or briefly microwave (cold pasta = dry) to warm gently. Toss with Reserved Dressing then serve.","images":[],"step":6}]', '["gluten","milk"]', '[]', '{"mealType":["dinner","lunch"],"cuisine":["Italian"],"categories":["dinner-tonight","easter-sides-fresh-light","italian-recipes","no-cook-food","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d0fe3651165a', 'en', 'US', 'JB''s Pommes Anna', 'Recipe video above. Introducing Pommes Anna - the ultimate French potato cake. Thinly sliced potato, lots of butter, crispy edges, soft centre, and a big “wow” moment when you flip it out. We’ve had quite a few of those in the process of developing it! When simple ingredients make beautiful result.', 'https://www.recipetineats.com/tachyon/2025/11/Pommes-Anna_9-1.jpg', 30, 100, 140, 8, '[{"id": "ing_potato", "quantity": {"value": 1.6, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 160.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1.6 kg / 3.5 lb medium starchy potato","160g / 5.6 oz unsalted butter (makes 1/2 cup clarified butter) (Note 2)","1 tsp cooking salt / kosher salt","1/4 tsp white pepper powder"]},{"ingredients":["1 sprinkle sea salt flakes (, if you want (I did!))"],"purpose":"Optional"}]', '[{"description":"Build 3 layers of thinly sliced potatoes (1.5mm / 0.06\") in a spiral pattern brushing with clarified butter and seasoning as you go. Bake 70 minutes at 200°C / 400°F (180°C fan) covered with cartouche then 30 minutes uncovered. Rest 10 minutes, flip, and enjoy!","images":[],"step":1},{"description":"How to make Clarified Butter:","images":[],"step":2},{"description":"Melt the butter in a saucepan or microwave. Set aside for 5 minutes until the milk solids settle on the bottom (white stuff). Scrape off the foam, then slowly pour the clear golden butter through a small sieve into a jug while leaving the milk solids behind (discard it). That clear golden butter is your clarified butter.","duration":5,"images":[],"step":3},{"description":"How to make Pommes Anna:","images":[],"step":4},{"title":"Prep pan","description":"Preheat oven to 200°C / 400°F (180°C fan-forced). Brush the base of a 26cm / 10\" cast-iron skillet with 2 tablespoons of clarified butter. (Note 3)","images":[],"step":5},{"title":"Slice potatoes","description":"Peel potatoes and using a mandolin, slice 2 or 3 potatoes 1.5mm / 0.6\" thick. Quickly sort the slices into small, medium and large sizes. Do not put them in water. (Note 4 + 5)","images":[],"step":6},{"title":"Build the first layer","description":"Using the medium size slices, put one slice in the middle, then build a spiral around it, overlapping each slice by about 3/4. Then, using the larger slices, make a second spiral around the first one until the whole base is fully and evenly covered. If you have medium slices left, you can use them here too. The second spiral should slightly overlap the first to keep the final shape tidy and firm. Tuck some small slices inside the tiny gap in the centre, do this for every layer to keep the middle neat.","images":[],"step":7},{"description":"Brush / dab generously with clarified butter, taking care not to disturb or lift the slices. Season with a third of the salt and white pepper.","images":[],"step":8},{"title":"Build two more layers","description":"Repeat the same spiral pattern for 2 more layers, brushing with clarified butter and seasoning each layer.","images":[],"step":9},{"title":"Cartouche","description":"Place a cartouche (circle of baking paper / parchment paper) on top. (Note 6)","images":[],"step":10},{"description":"Bake for 70 minutes. Remove the cartouche, then bake another 30 minutes until the top and edges are deep golden and crispy.","duration":70,"images":[],"step":11},{"title":"Rest + flip","description":"Rest for 10 minutes on the counter. Flip onto a plate and lift the pan to reveal your beautiful Pommes Anna. Serve immediately, happiness does not wait 😊","duration":10,"images":[],"step":12}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["easter-sides-warm-hearty","jbs-recipes","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44a8ab2a6886', 'en', 'US', 'Carbonara (real)', 'Recipe video above. These days, so many carbonara recipes cheat with cream which is a shame. The traditional method uses raw egg which is mixed vigorously with hot pasta and parmigiana reggiano cheese which transforms into a silky, creamy, luxurious sauce unlike anything you''ve ever had before. Arguably the best pasta dish in the whole world!This is a pasta that must be eaten straight away to truly experience its magnificence. Serve in warm bowls!', 'https://www.recipetineats.com/tachyon/2023/01/Carbonara_6a.jpg', 5, 15, 20, 4, '[{"id": "ing_guanciale", "quantity": {"value": 0.175, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 8.333, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["175g/6 oz guanciale (pancetta or block bacon), ( weight after skin removed (Note 1))","2 large eggs (Note 2)","2 egg yolks (Note 2)","100g/3.5 oz parmigiano reggiano (, finely shredded (or pecorino romano, sub parmesan, Note 3))","1/4 tsp black pepper","400g/14 oz spaghetti","1 tbsp cooking/kosher salt (for cooking pasta)","1/2 cup pasta cooking water","1 garlic clove (, finely minced (optional, Note 4))"]},{"ingredients":["Parsley (, finely chopped)","Parmigiano reggiano"],"purpose":"Garnish (optional):"}]', '[{"title":"Guanciale","description":"Cut into 0.5cm / 1/5\" thick slices then into batons.","images":[],"step":1},{"title":"Carbonara sauce","description":"Place eggs and yolks in a large bowl. Whisk to combine. Then stir in the parmesan and pepper.","images":[],"step":2},{"title":"Cook pasta","description":"Bring 4 litres (4 quarts) of water to the boil with the salt. Add pasta and cook per the packet directions.","images":[],"step":3},{"title":"Reserve pasta water","description":"Just before draining, scoop out 1 cup of pasta cooking water, then drain the pasta.","images":[],"step":4},{"title":"Cook guanciale","description":"While the pasta is cooking, place guanciale in a non stick pan over medium high heat. Cook for 4 to 5 minutes until golden. No oil needed - as the guanciale heats up, the fat will melt so it fries in its own fat. If using garlic, add it in the last minute.","duration":4.5,"images":[],"step":5},{"title":"Pasta in pan","description":"Tip the hot pasta into the pan and toss to coat in guanciale fat.","images":[],"step":6},{"title":"Mix pasta in sauce","description":"Transfer the pasta and any residual fat in the pan into the bowl with the egg. Add 1/2 cup (125 ml) pasta cooking water. Stir vigorously using the handle of a wooden spoon for 1 minute and watch as the sauce transforms from watery to creamy and clings to the pasta strands!","duration":1,"images":[],"step":7},{"title":"Serve","description":"Transfer into warm bowls. Serve immediately, garnished with a little extra parmigiana reggiano if desired, and a pinch of black pepper and finely chopped parsley.","images":[],"step":8}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["egg-recipes","egg-yolk-recipes","iconic-dishes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f9aa619a366e', 'en', 'US', 'Béarnaise Sauce - Fast, easy, foolproof method', 'Recipe video above. Béarnaise Sauce, considered by many to be one of the finest steak sauces in the world, and a classic spin on Hollandaise sauce, one of the 5 French “mother sauces.” It''s notoriously difficult to make by hand. This recipe uses a foolproof stick blender method that yields exactly the same results in 2 minutes flat - and has the tick of approval from our resident French Chef JB!Serve over steak or pan seared salmon for a fine dining restaurant experience at home.Makes enough to (very) generously sauce 3 large steaks, or 4 sensible portions.', 'https://www.recipetineats.com/tachyon/2021/02/Spooning-Bearnaise-Sauce-on-Steak_5.jpg', 10, 2, 12, 4, '[{"id": "ing_wine", "quantity": {"value": 2.0, "unit": "bottle of 750ml"}}, {"id": "ing_vinegar", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_tarragon", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.25, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_tarragon", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chervil", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 1/2 tbsp white wine (, dry, not too fruity, sweet or woody (Note 1))","1 1/2 tbsp white wine vinegar (Note 2)","1/4 tsp black pepper (, coarsely crushed)","1 eschallot (small), peeled and finely sliced (Note 3)","2 sprigs tarragon (Note 6)"],"purpose":"Infused Vinegar :"},{"ingredients":["3 egg yolks (, at room temperature (Note 4))","1/4 tsp salt (, kosher/cooking salt)","225g / 16 tbsp unsalted butter (, cut into 1cm / 1\" cubes - 2 US sticks (Note 5))","1/2 tbsp tarragon leaves (, finely chopped (Note 6))","1/2 tbsp chervil (, finely chopped (Note 6))"],"purpose":"Béarnaise Sauce:"}]', '[{"description":"Infused Vinegar:","images":[],"step":1},{"description":"Place Infused Vinegar ingredients in a small saucepan over medium low heat.","images":[],"step":2},{"description":"Simmer for 2 minutes, then remove from stove and let it stand for 5 minutes to infuse.","duration":2,"images":[],"step":3},{"description":"Strain, pressing to extract as much liquid as possible. You should have around 1 tbsp of liquid. Cool 5 minutes before use.","images":[],"step":4},{"description":"Quick Clarified Butter:","images":[],"step":5},{"description":"Place butter in a jug and microwave until melted (1 - 1½ minutes on high, but watch it carefully so it doesn''t explode!).","images":[],"step":6},{"description":"Stand for 30 seconds until the milky whites settle at the bottom (this is the milk solids) and clarified butter (golden part) sits above it.","duration":0.5,"images":[],"step":7},{"description":"Pour off 175g / 3/4 cup of the clarified butter, discard the milky whites remaining. Use in this recipe while hot.","images":[],"step":8},{"title":"Alternative","description":"Just melt 175g / 3/4 cup ghee, which is the same thing as clarified butter.","images":[],"step":9},{"description":"Béarnaise Sauce:","images":[],"step":10},{"description":"Place egg yolks, infused vinegar and salt in a tall, narrow container that the blender stick fits in all the way to the base. Blitz briefly to combine.","images":[],"step":11},{"description":"With the stick blender going on high, slowly drizzle the butter in over about a minute. Important: The butter must still be hot! If it has cooled, reheat until hot.","images":[],"step":12},{"description":"After all the butter is in, blitz for a further 10 seconds, moving the stick up and down.","images":[],"step":13},{"title":"Thickness","description":"Add 1 tablespoon water, then blitz to incorporate. Add more water as needed, 1 teaspoon at a time, until the Bearnaise Sauce is a thick sauce but loose enough to ooze across a steak, coating it thickly.","images":[],"step":14},{"title":"Fresh herbs","description":"Stir in tarragon and chervil.","images":[],"step":15},{"title":"Using","description":"Use immediately, or keep warm until required. I use a thermos – a good one will keep it warm for at least 1 hour. Use warm or at room temperature. See note for storing and reheating.","images":[],"step":16}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["egg-yolk-recipes","roast-beef"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7be39f3c2fa0', 'en', 'US', 'Crispy pea fritters - great emergency meal!', 'Recipe video above. This is a super handy recipe for when your fridge is looking a little bare, because who doesn’t have some frozen peas lurking in the back of your freezer? Grab them and a bag of pre-shredded cheese, and you’ll have a stack of these crispy golden fritters on the table in 20 minutes flat! PS The more rustic they are, the better. Because rustic = ragged edges = more crispy cheesy edges. OBSESSED.', 'https://www.recipetineats.com/tachyon/2024/07/Crispy-pea-fritters_4-3.jpg', 10, 10, 20, 9, '[{"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 1.0, "unit": "pack of 400g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.003, "unit": "tub of 150g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1/4 cup flour ((plain/all-purpose) - Note 4 gluten free)","1/4 cup cornflour / cornstarch (, or more flour (Note 1))","1/2 tsp baking powder","1/2 tsp garlic powder","1/2 tsp cooking salt ((kosher salt), or 1/4 tsp table salt)","1/4 tsp black pepper","1 large egg (~55g/2 oz)","2 tbsp milk ((any type, any fat %), or water)"],"purpose":"Batter:"},{"ingredients":["2 cups frozen peas (, still frozen (break up large clumps) (Note 2))","1 cup shredded cheese ((cheddar, tasty, colby - anything that melts, Note 3), packet shredded is fine)","3/4 cup finely sliced green onion (ok to omit)"],"purpose":"Add-ins:"},{"ingredients":["1/4 cup olive oil (, for cooking)"],"purpose":"For cooking:"},{"ingredients":["1/2 cup plain yogurt","2 tsp lemon juice","2 tsp extra virgin olive oil","1/8 tsp finely grated garlic (, optional)","Pinch each salt and pepper"],"purpose":"Lemon Yoghurt Dipping Sauce:"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Mix the Batter ingredients. Stir in the Add-ins. Scoop, flatten, cook 1 1/2 minutes each side. Eat!","images":[],"step":2},{"description":"Full instructions","images":[],"step":3},{"title":"Lemon Yogurt Dipping Sauce","description":"Mix the ingredients together in a bowl and set aside while you cook the fritters to let the flavours meld.","images":[],"step":4},{"title":"Fritter batter","description":"Mix the Batter ingredients until combined. Add the Add-ins, then mix until the batter coats all the peas. It will look like waaaay too much peas for batter, but have faith! The batter will set as it cooks.","images":[],"step":5},{"title":"Measure & flatten","description":"Heat enough oil to cover the base of a pan on medium high (~2 1/2 tbsp). Pack a 3 tbsp cookie scoop (#20) or 1/4 cup measure firmly with the mixture. Place mound in the pan, then flatten to 1.25 / 0.5\" thick. Repeat to to fill the pan (I do 4 - 5 at a time)","images":[],"step":6},{"title":"Cook","description":"Cook for 1 1/2 minutes until the underside is golden, then turn and cook the other side for 1 1/2 minutes until golden and crispy. Transfer onto a paper towel lined tray. Repeat with remaining batter to make 9 -10 in total.","images":[],"step":7},{"description":"Serve with Lemon Yogurt Dipping Sauce!","images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["emergency-recipes","fritters-tots-and-similar","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_29409440487b', 'en', 'US', 'Swiss Mushroom Burgers', 'Recipe video above. Big, juicy Swiss Mushrooms Burgers are a mighty vegetarian burger that at first glance, looks like a beef burger! Large mushrooms are roasted with garlic butter, topped with Swiss cheese then stuffed into fully loaded soft rolls.Only got small mushrooms? No worries, read the recipe notes!Desperate for meat? Add a meat burger pattie (beef, chicken mince/ground, or chicken breast/thigh), or even bacon and egg!Fully loaded veggie burger - add a vegetarian burger pattie (one of my signature recipes!).', 'https://www.recipetineats.com/tachyon/2020/08/Easy-Swiss-Mushroom-Burgers_7.jpg', 10, 40, 50, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.005, "unit": "jar of 400g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.12, "unit": "bottle of 500g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.025, "unit": "bottle of 400ml"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 10.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["4+ BIG mushrooms - like portobello, BBQ flat mushrooms (20% larger than buns, or buy multiple per burger) (Note 1)","30g / 2 tbsp unsalted butter","2 garlic cloves (, finely minced)","1/2 tsp each salt and pepper","1/2 tbsp olive oil","4 slices swiss cheese (or any other cheese slice of choice)"]},{"ingredients":["3 onions (, cut into 0.7cm / 1/3\" rings)","1 tbsp olive oil","1/4 tsp each salt and pepper"],"purpose":"Onions (or use raw red onions)"},{"ingredients":["2/3 cup mayonnaise (or sour cream + pinch of salt)","2 tbsp ketchup","1 - 3 tsp Sriracha (adjust spiciness to taste)"],"purpose":"Pink Burger Sauce"},{"ingredients":["4 buns or rolls (I like brioche)","8 - 12 lettuce leaves","2 tomatoes"],"purpose":"Burgers (Note 2 for more options)"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Preheat oven to 220°C/450°F (200°F fan).","images":[],"step":1},{"title":"Garlic butter","description":"Place butter, garlic, salt and pepper in a heatproof jug. Microwave to melt butter, then stir.","images":[],"step":2},{"title":"Brush with butter","description":"Brush the mushroom cap with butter (smooth side), then place on a tray gills side up (ie stalk facing up). Brush remaining butter onto the rims and gills, being sure to scrape up all the garlic in the jug.","images":[],"step":3},{"title":"Olive oil","description":"Drizzle with olive oil.","images":[],"step":4},{"description":"Roast 25 minutes, then flip mushrooms. Brush with tay juices, roast a further 10 minutes or until the centre of the mushrooms are tender. {Meanwhile, cook onion, mix Sauce)","images":[],"step":5},{"title":"Top with cheese","description":"Place a slice of cheese on each mushroom, return to oven for 3 minutes just to melt the cheese.","duration":3,"images":[],"step":6},{"title":"Toast buns","description":"Place split buns in the oven at the same time - to lightly toast.","images":[],"step":7},{"description":"Assemble burgers","images":[],"step":8},{"description":"Spread base of bun with a dollop of Pink Sauce. Top with lettuce, then tomato, then mushroom, then onion. Spread lid with a lesser smear of Pink Sauce, then place on burger. Devour!","images":[],"step":9},{"description":"Mix together, use per recipe.","images":[],"step":10},{"description":"Heat oil in a large skillet over high heat. Cook onion for 5 to 7 minutes until tinged with gold and floppy. Season with a pinch of salt and pepper.","duration":6,"images":[],"step":11}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","emergency-recipes","main-dishes","mushroom-recipes","quick-and-easy","sandwiches-and-sliders","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8f047e5cdfeb', 'en', 'US', 'An excellent No Yeast Pizza Dough - quick easy homemade pizza!', 'Recipe video above. Meet your new best friend - a no yeast pizza dough that makes a quick and easy homemade pizza, fresh out of the oven in 20 minutes flat! This pizza crust without yeast is not just a sad substitute for the real deal made with yeast. It''s truly great, yet takes a fraction of the time and effort.Spread with pizza sauce, choose your favourite toppings then bake for a pizza night in!', 'https://www.recipetineats.com/tachyon/2020/05/No-Yeast-Pizza_0-1-2.jpg', 7, 13, 20, 1, '[{"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.025, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.01, "unit": "L"}}]', '[{"ingredients":["1 1/3 cups bread flour (or plain / all purpose flour, Note 2)","2 tsp baking powder","3/4 tsp salt","3/4 tsp sugar"],"purpose":"Dry ingredients:"},{"ingredients":["2 tsp olive oil (or any other oil)","1/2 cup water (cold tap water)"],"purpose":"Wet ingredients:"},{"ingredients":["1 tbsp Extra Flour (, for dusting)","2 tsp vegetable oil (optional) (, for brushing crust (or canola or other neutral oil) (Note 3))"],"purpose":"Other"}]', '[{"description":"Preheat oven to 250°C / 480°F (230°C fan) (Note 4.) Place shelf in the top quarter of the oven.","images":[],"step":1},{"description":"Spray pizza pan or baking tray lightly with oil.","images":[],"step":2},{"description":"Prepare pizza sauce and toppings. Keep shredded mozzarella in the fridge (Note 5).","images":[],"step":3},{"description":"Food processor option (40 sec):","images":[],"step":4},{"title":"Blitz","description":"Using the standard S blade, add Dry Ingredients and pulse twice. Add water and olive oil. Blitz on low for 40 seconds - it will come together into a shaggy ball (video 33 sec).","duration":0.6666666666666666,"images":[],"step":5},{"title":"Shape","description":"Sprinkle work surface with half Extra Flour, scrape dough out. Sprinkle with remaining Extra Flour and firmly shape into a ball. Proceed with rolling out steps below.","images":[],"step":6},{"description":"Hand Kneading option (3 min):","images":[],"step":7},{"title":"Mix","description":"Place Dry ingredients in a bowl, mix to combine with a rubber spatula. Add water and olive oil, mix until flour is incorporated as best you can.","images":[],"step":8},{"title":"Knead","description":"Sprinkle work surface with half Extra Flour, dip dough out. Sprinkle with remaining Extra Flour then knead for 3 to 4 minutes until it''s pretty smooth (video 38 sec), using more flour only if needed. Shape into a ball. Proceed with rolling out steps below.","duration":3.5,"images":[],"step":9},{"description":"Rolling out dough:","images":[],"step":10},{"title":"Goal dough texture","description":"Your dough should be soft and elastic, and not stick to your hands. It will not be completely smooth like yeast dough (video 38 sec)(Note 6).","images":[],"step":11},{"description":"Roll out your dough ball into a 30cm/12\" round.","images":[],"step":12},{"title":"Stretch","description":"Transfer to pizza pan, preferably with holes (for crispier base), or a baking tray (Note 7 pizza stone). Use your fingers to pull from the centre to fill the pan to the edge - avoid pinching the edges (to ensure puffy crust!).","images":[],"step":13},{"description":"Top with 1/4 cup pizza sauce and toppings of choice.","images":[],"step":14},{"description":"Brush the crust edge (just exposed edge with no toppings on it) with oil.","images":[],"step":15},{"description":"Bake 12 minutes, until the edges are crispy and golden. Cut and serve immediately!","images":[],"step":16}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["emergency-recipes","good-to-know","pizza-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_06b5e3fcec32', 'en', 'US', 'Emergency Corn Chowder Soup', 'Recipe video above. Emergency corn chowder is a soup recipe that involves little more than popping open cans of corn and USING THE EMPTIED CANS to measure the liquids to add into the soup! Tastes just like your favourite creamy corn chowder - but faster to make!', 'https://www.recipetineats.com/tachyon/2019/09/Emergency-Corn-Chowder__1.jpg', 3, 12, 15, 3, '[{"id": "ing_oil", "quantity": {"value": 0.02, "unit": "bottle"}}, {"id": "ing_bacon", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_milk", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}]', '[{"ingredients":["1 tsp oil ( or butter)","2 slices bacon (, streaky!)","2 garlic cloves (, minced)","400g/14oz can creamed corn (1 can)","400g/14oz can corn kernels (, drained (1 can))","1 2/3 cups (400ml) chicken stock ( / broth (1 empty can*))","3/4 cup (200ml) milk (, any fat % (1/2 empty can*))","1 potato (, diced into 1.5 cm/ 1/2\" small cubes)","1/2 tsp each salt and pepper","1 green onion (, finely sliced)"]},{"ingredients":["1/2 cup (125 ml) milk (, any fat % (1/4 empty can*))","1 1/2 tbsp cornflour / corn starch"],"purpose":"Soup thickener:"}]', '[{"description":"Place oil then bacon in pot. Turn stove onto medium high heat then cook until bacon is golden on both sides.","images":[],"step":1},{"description":"Remove bacon and chop once cooled.","images":[],"step":2},{"description":"If there''s loads of excess fat in the pot, drain some.","images":[],"step":3},{"description":"Add garlic and stir for 20 seconds. Add creamed corn, kernels, chicken stock, milk, potato, salt and pepper.","duration":0.3333333333333333,"images":[],"step":4},{"description":"Stir, bring to simmer then adjust to medium. Simmer 5 minutes until potato is just tender.","images":[],"step":5},{"title":"Soup Thickener","description":"Mix together milk and cornflour, then pour into soup.","images":[],"step":6},{"description":"Stir and simmer for 1 minute until it thickens into a creamy soup (see video for thickness).","duration":1,"images":[],"step":7},{"description":"Add more salt if needed.","images":[],"step":8},{"description":"Ladle into bowls, top with green onion and bacon. Devour!","images":[],"step":9}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","emergency-recipes","quick-and-easy","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7282f7fd574c', 'en', 'US', '12 Minute Baked Salmon Fajitas', 'Recipe video above. Here is a big Fajita dinner spread that''s all cooked in the oven at the same time! Caramelised cubes of salmon heavily seasoned with a Fajita spice blend, colourful fajita vegetables and a pile of steamy warm tortillas, just add sliced avocado and make a simple taco sauce while they''re in the oven. I used my new Creamy Jalapeño Sauce but if that''s out of reach or you''re worried about spiciness (it''s got a little zing), either use my Instant Pink Taco Sauce or just plain sour cream.', 'https://www.recipetineats.com/tachyon/2026/05/Tray-bake-salmon-fajitas-7.jpg', 18, 12, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_onion", "quantity": {"value": 0.01, "unit": "pack of 1kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_pink_taco_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_tortillas", "quantity": {"value": 14.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["600g / 1.2lb skinless salmon fillets (, cut into 2.5cm/1\" cubes (Note 1))"]},{"ingredients":["1 1/2 tbsp extra virgin olive oil","2 tsp smoked paprika (or regular paprika)","1 tsp EACH garlic, onion, cumin powder","1/2 tsp dried oregano","3/4 tsp cooking salt / kosher salt (halve for cooking salt, double for flakes)","1 tsp (tightly packed) brown sugar (helps the salmon brown!)","1/4 tsp cayenne pepper ((optional), for small spiciness)"],"purpose":"Fajita seasoning:"},{"ingredients":["3 capsicums (1 each red, yellow, green) (, deseeded, cut into 0.75cm / 1/3\" strips)","1 red onion (, cut into 0.75cm / 1/3\"wedges)","1 1/2 tbsp extra virgin olive oil","1 garlic clove (, minced using garlic press or knife)","1/2 tsp cooking salt / kosher salt"],"purpose":"Fajita Vegetables:"},{"ingredients":["Creamy Jalapeno Sauce","Pink Taco Sauce (2 ingredients!)","Sour cream"],"purpose":"CHOOSE a fajita sauce:"},{"ingredients":["12 - 16 taco-size tortillas (, corn or flour (3 to 4 per person, depending on size), wrapped in foil (make 2 parcels))","1 avocado (, sliced)","2 tbsp roughly chopped coriander ((cilantro), optional but recommended)","Lime wedges (, optional)"],"purpose":"Serving:"}]', '[{"description":"Toss Vegetable ingredients on a tray. Toss salmon with Fajita Seasoning, spread on separate tray lined with wrinkled foil. Bake 12 minutes at 240°C/465°F (220°C fan) along with foil wrapped tortillas. Make sauce. Serve!","images":[],"step":1},{"description":"Preheat oven to 240°C/465°F (220°C fan-forced).","images":[],"step":2},{"title":"Crinkled foil trick for baking fish","description":"Lightly scrunch up foil, then gently unfold it so it stays wrinkled. Lots of little pointing bits = good! The wrinkles lift the fish slightly, preventing sticking and soggy undersides – clever Japanese fish-cooking trick (thanks mum!). Place on one side of the tray and fold the edges over the rim to secure. Repeat with another sheet to cover the whole tray.","images":[],"step":3},{"title":"Fajita flavour fish","description":"Mix the Fajita seasoning ingredients in a bowl, it should be like a thin paste. Add fish and toss to coat. Spread out on the foil so the salmon is not touching each other.","images":[],"step":4},{"title":"Toss veg","description":"On a separate large tray, toss capsicum and onion with the oil, garlic and salt. Spread it out in a single layer.","images":[],"step":5},{"description":"Wrap stack of tortillas in foil (make 2 parcels).","images":[],"step":6},{"title":"Bake everything","description":"Put the salmon on the top shelf, vegetables on the middle shelf and tortillas into the oven (I put them on the floor of the oven but don’t do this if your heat element is there, mine comes from the back). Bake 12 minutes, or until the salmon flakes (don''t turn or toss).","images":[],"step":7},{"title":"Sauce","description":"Meanwhile, put the sauce ingredients in a small jug and blitz with stick blender until smooth.","images":[],"step":8},{"title":"Lay everything out","description":"Transfer the salmon and vegetable onto a serving platter, pour all tray juices over. Place warmed tortillas, sauce, avocado, lime wedges and coriander on the side.","images":[],"step":9},{"title":"Making a fajita","description":"Take a warm tortilla. Stuff with a little vegetables, place 2 pieces of salmon on then flake into large chucks. Tuck in avocado, drizzle with sauce, lime juice, sprinkle with coriander, devour!","images":[],"step":10}]', '["fish","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["fajitas","mains","mexican-recipes","one-pot-recipes","other","salmon-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b17e816fe02', 'en', 'US', 'Crispy Salt & Pepper Squid', 'Recipe video above. It only took us 3 years to crack the ultimate, truly crispy Salt and Pepper Squid! Hand on heart, this is crispier than any squid I''ve had in a restaurant, ever. The fry batter is light, super crunchy and not greasy at all. In fact, it''s so crispy it stays crispy even when it''s stone cold!After eliminating rice flour, potato flour and tapioca, we found the perfect ratio of flour to cornflour (cornstarch) that fries up crunchy in mere minutes, before the squid can overcook. But the final key was refrigerating the batter for 30 minutes. This allowed the gluten to develop so the batter clings to the slippery squid better and doesn''t fry up chewy or greasy.', 'https://www.recipetineats.com/tachyon/2024/02/Salt-and-pepper-squid-in-a-bowl.jpg', 15, 0, 15, 3, '[{"id": "ing_whole_baby_squid", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_squid_tubes", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 2.0, "unit": "pack of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.003, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.003, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}]', '[{"ingredients":["700 g / 1.4 lb medium whole baby squid","500 g / 1 lb squid tubes (, already cleaned)"],"purpose":"Squid – choose (Note 1):"},{"ingredients":["2/3 cup cornflour / cornstarch","1/3 cup plain / all-purpose flour","1/2 tsp baking powder","1/2 tsp cooking / kosher salt","1/4 tsp white pepper powder","2/3 cup cold tap water"],"purpose":"Batter (Note 2):"},{"ingredients":["3 – 4 cups vegetable or canola oil (~4cm / 1.5\" depth in a pot)","Cooking / kosher salt ( - just a pinch!)","White pepper powder"],"purpose":"Cooking / seasoning:"},{"ingredients":["1/2 cup whole egg mayonnaise ( or kewpie)","1/2 tsp finely grated garlic"],"purpose":"Easy aioli (garlic mayonnaise):"}]', '[{"description":"Preparing squid:","images":[],"step":1},{"description":"Cut one side of the squid tube to lay it out in one flat piece. Pat both sides dry with a paper towel.","images":[],"step":2},{"description":"Lightly score the inside with a small sharp knife in 1.5 cm / 0.6\" diamonds (don''t cut all the way through). (Note 3)","images":[],"step":3},{"description":"Cut the squid into pieces 5 x 2cm (2 x 1\") rectangles (approximately).","images":[],"step":4},{"description":"Mix the ingredients together in a bowl and set aside for at least 20 minutes (up to 24 hours).","images":[],"step":5},{"title":"Batter","description":"Whisk the flour, cornflour, baking powder and salt in a bowl. Then whisk in water until smooth. Refrigerate for 30 minutes. (Note 4)","duration":30,"images":[],"step":6},{"title":"Heat oil","description":"Fill small heavy based pot or large saucepan with 4cm / 1.5\" of oil. Heat to 160°C/320°F on medium high heat. (I use a Thermapen to check the temp)","images":[],"step":7},{"description":"Give the batter a quick whisk then add all the squid in a toss to coat. (Including tentacles if using baby squid - it''s the crunchiest!)","images":[],"step":8},{"title":"Batter","description":"Cook the squid in 3 batches. Pick up some squid and let the excess batter to drip off. Careful place in the oil. Use chopsticks to seperate the pieces that stick together.","images":[],"step":9},{"description":"Fry baby squid for 2 minutes or the regular squid tubes for 3 minutes until light golden. Use a spider or slotted spoon to remove the squid on a paper towel lined tray.","duration":2,"images":[],"step":10},{"title":"Repeat","description":"Fry remaining squid, making sure the oil comes back to temperature before cooking batches 2 and 3.","images":[],"step":11},{"title":"Fry 2","description":"crisp it!","images":[],"step":12},{"title":"Increase oil temp","description":"Increase the stove to high and bring the the oil up to 200°C/390°F.","images":[],"step":13},{"title":"Bowl","description":"Line a large mixing bowl with double layer of paper towels.","images":[],"step":14},{"title":"Fry","description":"Place half of the squid in the oil (it''s ok to crowd the pot). Cook for 1 1/2 minutes, until it becomes deep golden and crispy. Remove into the bowl. Bring the oil back up to 200°C/390°F then fry the remaining squid.","images":[],"step":15},{"title":"Season","description":"Remove paper towel. Taste first then sprinkle lightly with as much salt and pepper as you want (the batter has salt in it already). Toss well.","images":[],"step":16},{"description":"Serve:","images":[],"step":17},{"description":"Pour into a serving bowl and serve with aioli! This batter is so good, it will stay crispy even once the squid has gone cold.","images":[],"step":18}]', '["egg","gluten","shellfish"]', '[]', '{"mealType":["snack","dinner"],"cuisine":["Western"],"categories":["deep-fried-recipes","finger-food","iconic-dishes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_484b53b23b59', 'en', 'US', 'Cajun Baked Salmon Bites', 'Recipe video above. Cajun Baked Salmon Bites is just a really tasty, no-fuss way to cook salmon, fast (12 minutes!). Cut into cubes so the Cajun flavour hits every bite, then bake in a hot oven so it browns without overcooking the inside. No stove splatter, yay!You''ll love the crinkled foil tray lining used here - it''s a nifty Japanese fish-baking tip. Crinkled foil = no sticking, no soggy underside on the salmon, plus less washing up (no rack). YAY!Serve with whatever your heart desires - stuffed into tacos, make rice bowls, add to salads, eat off the tray. You just can''t go wrong!', 'https://www.recipetineats.com/tachyon/2025/11/Cajun-baked-salmon_5.jpg', 7, 12, 19, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["4 salmon fillets (, skinless, cut into 2.5cm / 1\" cubes (~600 - 700g / 1.2 - 1.4lb total))"]},{"ingredients":["2 tsp paprika (regular/sweet, smoked also lovely)","3/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1 tsp onion powder","1 tsp garlic powder (don''t sub with fresh garlic, will burn)","1/4 tsp dried thyme","1/4 tsp black pepper","1/4 tsp cayenne pepper (, optional for slight spiciness)","2 1/2 tsp brown sugar (, tightly pack the teaspoons)","2 tbsp olive oil"],"purpose":"Cajun spice mix (Note 1):"}]', '[{"description":"Coat salmon with Cajun seasoning, bake on crumpled foil 12 minutes at 240°C/460°F (220°C fan-forced) until lightly browned. Enjoy!","images":[],"step":1},{"description":"Preheat the oven to 240°C/460°F (220°C fan-forced).","images":[],"step":2},{"title":"Crinkled foil trick","description":"Lightly scrunch up foil, then gently unfold it so it stays wrinkled. Lots of little pointy bits = good!.Place on the tray and fold the edges to secure, repeat with another sheet to cover the whole tray. The wrinkles lift the fish slightly, preventing sticking and soggy undersides - clever Japanese fish-cooking trick!","images":[],"step":3},{"title":"Coat salmon","description":"Put the Cajun Spice mix ingredients in a bowl and mix. Add salmon and toss to coat. Spread on the foil (the more spaced out they are, the better they colour).","images":[],"step":4},{"description":"Bake 12 minutes (don''t turn). Remove salmon from the tray (so they don''t keep cooking) then enjoy!","images":[],"step":5},{"description":"For Cajun Salmon Rice Bowls pictured:","images":[],"step":6},{"title":"Photos in post","description":"rice, lettuce, tomato, radish, avocado, Cajun salmon bites.","images":[],"step":7},{"title":"Video","description":"Rice, Cajun salmon bites, roasted corn avocado salsa - made at the same time as the salmon (Note 2).","images":[],"step":8},{"title":"Sauces and garnishes for both bowls","description":"Peri-naise or leftover pink Gyros sauce (or just kewpie/regular mayo mixed with sriracha or ketchup), chopped coriander or green onion.","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Cajun","Western"],"categories":["fish-recipes","mains","other","quick-and-easy","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b39192909dd', 'en', 'US', 'Seafood Chowder', 'Recipe video above. This is a seafood soup so good, it''s hard to believe it''s made with cheap ''n cheerful marinara mix and store-bought stock. Using chicken rather than store-bought fish stock (awful stuff!), a cheeky dash of fish sauce rather than salt and bacon are some of the flavour enhancers we deploy here!Of course, if you use homemade fish stock and a hand-picked mix of fresh seafood, it will be upmarket-restaurant-worthy. :) Also see FAQ for more vegetable options.', 'https://www.recipetineats.com/tachyon/2025/09/Seafood-chowder_9.jpg', 20, 20, 40, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.65, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_chardonnay", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_corn", "quantity": {"value": 0.5, "unit": "can of 400g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["650g/ 1.3lb seafood marinara mix or mixed fresh seafood - fish (, squid, prawns, cooked mussel meat (Note 1))","50g (3 tbsp) unsalted butter","100g/ 4oz streaky bacon (, chopped into 1.5cm / 1/2\" squares)","2 cloves garlic (, finely minced)","1/2 cup chardonnay (or other dry white wine (can skip))","1/3 cup flour (, plain/all-purpose (Note 3 for gluten-free))","1 litre (4 cups) chicken stock/broth, low sodium OR homemade fish stock (avoid store-bought fish stock) (Note 2)","2 medium carrots (, peeled, cut into 7mm / 1/3\" pieces (~1 1/2 cups))","2 large potatoes (any type fine), peeled, cut into 1cm / 0.2\" cubes (~2 1/2 cups)","1 cup thickened cream / heavy cream (sub milk for lighter option)","1 cup corn (frozen or canned, drained)","2 tsp fish sauce","Pinch white pepper (substitute black pepper)"]},{"ingredients":["3 tbsp chives or parsley (, finely chopped, for garnish)","Crusty bread ( or better yet, garlic bread!)"],"purpose":"SERVING"}]', '[{"description":"Cook bacon in butter, remove. Sauté garlic, deglaze with white wine, make roux. Add stock, simmer potato, carrots and bacon 10 min. Add cream, corn, fish sauce, pepper, raw seafood - simmer 3 min. Stir in cooked seafood, taste for salt. Serve!","images":[],"step":1},{"title":"Marinara mix","description":"Separate cooked seafood (usually mussels, sometimes prawns/shrimp) from raw seafood. We put them in at different times.","images":[],"step":2},{"description":"Cut any large pieces of fish into 2.5cm / 1\" cubes.","images":[],"step":3},{"title":"Bacon","description":"In a heavy-based pot, melt the butter over medium heat. Add bacon and cook for 3 - 4 minutes until the edges are light golden. Use a slotted spoon to remove into bowl, leaving fat in the pot.","duration":3.5,"images":[],"step":4},{"title":"Deglaze","description":"Add the garlic and cook for 10 seconds (don''t let it brown). Add the wine, simmer rapidly on high for 3 minutes, scraping the base to loosen any golden bacon bits, until the wine is mostly evaporated.","duration":0.16666666666666666,"images":[],"step":5},{"title":"Roux","description":"Reduce heat down to medium, add the flour and mix for 1 minute (\"roux\").","duration":1,"images":[],"step":6},{"title":"Broth","description":"While stirring, pour in about 1 cup of the stock and mix to dissolve the roux - it will thicken into a paste. Add the remaining stock and stir well until lump free (use a whisk if needed).","images":[],"step":7},{"title":"Simmer 10 minutes","description":"Increase heat to high, bring to the boil, add the carrots, potatoes and bacon. Lower heat to medium and simmer for 10 - 12 minutes, or until the carrots are just about done.","duration":11,"images":[],"step":8},{"title":"Simmer raw seafood 3 minutes","description":"Add the cream, fish sauce, pepper, corn and raw seafood. Simmer for 3 minutes until the fish is just cooked (test - flesh should flake).","duration":3,"images":[],"step":9},{"title":"Cooked seafood","description":"Stir in cooked seafood, taste and add more salt if needed (I don''t).","images":[],"step":10},{"title":"Serve","description":"Ladle into bowls, sprinkle with chives. Serve with warm crusty bread for dunking!","images":[],"step":11}]', '["fish","gluten","milk","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","mains","other","seafood-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_070cb433311d', 'en', 'US', 'Lemon garlic salmon tray bake - easy & healthy!', 'Recipe video above. A tasty salmon tray bake recipe that''s as simple as it is healthy. Salmon infused with an assertive lemon garlic marinade cooks in just 11 minutes alongside parmesan asparagus and blistered cherry tomatoes. No stove splatter - yay! Green beans would also work great, or thin broccolini stems (and the florets go crunchy!). Shower with parmesan and squeeze of lemon for an easy finishing touch.', 'https://www.recipetineats.com/tachyon/2024/02/Lemon-garlic-salmon-tray-bake_1.jpg', 10, 11, 21, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 200.0, "unit": "punnet of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["4 x 180g/6 oz salmon fillets (, skin on or off, doesn''t matter (Note 1))"]},{"ingredients":["1 tsp lemon zest (1 lemon)","1 tbsp lemon juice","2 tbsp extra virgin olive oil","1 tsp dijon mustard (Note 2)","2 garlic cloves (, grated using microplane (Note 3))","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Marinade slather:"},{"ingredients":["3 bunches asparagus (, woody ends snapped or trimmed off (Note 4))","200g/ 7 oz cherry tomatoes (or grape tomatoes, 1 Aussie punnet)","2 tsp extra virgin olive oil","1/4 tsp each salt and pepper"],"purpose":"Vegetables (optional):"},{"ingredients":["Olive oil spray","Parmesan (, finely grated)","Lemon wedges or slices (, optional)","Parsley (, finely chopped, optional)","Crusty bread or toast (, for serving)"],"purpose":"Cooking & serving:"}]', '[{"title":"Lemon garlic paste","description":"Mix the marinade ingredients in a small bowl. Slather onto the top and sides of the salmon. If time permits, marinade for 1 hour. Otherwise, proceed with recipe.","images":[],"step":1},{"description":"Preheat oven grill / broiler to 280°C/525°F or as high as yours goes. Place the oven shelf 20 cm /8\" from the heat source.","images":[],"step":2},{"title":"Prepare tray","description":"Toss the asparagus and cherry tomatoes with the olive oil, salt and pepper. Spread out on a large tray then clear space for the salmon. Place salmon on the tray leaving a bit of space between each. Spray surface of salmon with oil.","images":[],"step":3},{"title":"Cook","description":"Grill/broil for 11 minutes or until the salmon is done - the flesh should flake, the internal temperature should be 50°C/122°F (Note 5).","duration":11,"images":[],"step":4},{"title":"Serve","description":"Transfer salmon and vegetables to plate. Grate parmesan over the vegetables. Squeeze lemon juice over the salmon, sprinkle with parsley. Eat!","images":[],"step":5}]', '["fish","gluten","milk","mustard"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","mains","one-pot-recipes","other","quick-and-easy","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f3589a5e9ed', 'en', 'US', 'Calabrian Fish Ragu', 'Recipe video above. This is a fish pasta in a richly spiced fish ragu pasta sauce. The spice mix is based on njuda, the bold flavoured spreadable Calabrian salami paste that''s rising in popularity in the restaurant scene! It''s a great way to make fish stretch further, cooked in a unique way that''s outrageously delicious with big, bold Southern Italian flavours.No stale bread? Use panko instead. See notes. 3 servings? I know it''s a little odd, but the spice mix didn''t scale down neatly to make pasta for 2! (3/8 tsp nutmeg?!). Leftovers are always delicious. :)', 'https://www.recipetineats.com/tachyon/2023/10/Calabrian-fish-ragu-pasta_6-1.jpg', 10, 25, 35, 3, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["250g/ 8 oz firm white fish fillets (, skinless, boneless, cut into 2 cm / 0.8\" cubes (barramundi, snapper, cod - Note 1))","3/4 tsp black peppercorns (Note 2 for ground option)","1 tsp fennel seeds (Note 2 for ground option)","1 tbsp smoked paprika (sub ordinary paprika)","1/2 tsp red chilli flakes ((red pepper flakes), feel free to reduce/omit)","1/2 tsp nutmeg powder","1/2 tsp caster / superfine sugar","3/4 tsp cooking / kosher salt","3 tbsp extra virgin olive oil","2 tbsp tomato paste"],"purpose":"Calabrian spiced fish:"},{"ingredients":["250g/8 oz linguine pasta (or fettuccine, spaghetti)","1 tbsp cooking / kosher salt (, for pasta water)","1 1/2 tbsp extra virgin olive oil","3 garlic cloves (, finely minced)","3/4 cup tomato passata (US: tomato puree, Note 3)"],"purpose":"Pasta:"},{"ingredients":["1 tbsp finely chopped parsley","Parmesan cheese (, finely grated, for serving)"],"purpose":"Garnish:"},{"ingredients":["1 cup stale bread like sourdough, ciabatta (, crusts removed, torn/chopped into irregular 1cm/0.4\" pieces (Note 4))","2 tsp extra virgin olive oil","1 pinch cooking / kosher salt"],"purpose":"Pangrattato"}]', '[{"title":"Toast & grind","description":"Preheat a large deep skillet or pot over medium heat (Note 5), no oil. Toast black peppercorn and fennel for 1 1/2 to 2 minutes until it smells fragrant and the fennel is lightly browned. Transfer to a mortar and use a pestle and grind to a powder while still hot.","images":[],"step":1},{"title":"Coat fish","description":"Transfer to a medium bowl with remaining Calabrian spiced fish ingredients. Stir well with a spatula until combined. Set aside.","images":[],"step":2},{"title":"Cook pasta","description":"Boil 3 litres of water with the cooking salt. Cook pasta per packet directions minus 1 minute. Just before draining, scoop out 1 1/2 cups pasta cooking water. Then drain in a colander and leave until ready to use.","images":[],"step":3},{"title":"Calabrian fish ragu","description":"While the pasta is cooking, heat olive oil in the same skillet you used to toast the fennel on medium high. Add garlic and cook for 1 minute. Add the fish. Cook for 2 minutes, stirring regularly. Add tomato passata. Simmer for 5 minutes, stirring occasionally. Add 1 cup of the reserved pasta cooking water and simmer for 2 minutes.","duration":1,"images":[],"step":4},{"title":"Toss pasta","description":"Add pasta and 3/4 of the parsley. Toss for 1 minute to coat the pasta with the sauce. Most of the fish will break up into flakes but some will remain in larger chunks - this is good! We don''t want disintegrated mush, nor giant chunks. Once the pasta turns red and the sauce and fish bits are clinging to the pasta straws, remove from heat and divide between bowls immediately.","duration":1,"images":[],"step":5},{"title":"Serve","description":"Sprinkle with pasta, pangrattato and parmesan. Eat immediately!","images":[],"step":6},{"description":"Preheat oven to 180°C / 350°F (160°C fan-forced).","images":[],"step":7},{"description":"Toss bread, oil and salt in a small bowl. Spread on a tray and bake for 10 minutes, tossing at the 5 minute mark, or until light golden and fully crisp.","duration":10,"images":[],"step":8}]', '["fish","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque"],"categories":["fish-recipes","italian-recipes","mains","other","pasta-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b262f1b1519c', 'en', 'US', 'Creamy fish on potato gratin', 'Recipe video above. This is a one-pan meal with fish baked on top of a potato gratin in a creamy sauce with a golden crunchy topping. It''s a cross between a casserole, gratin and a pie. The idea is that the panko acts like a lid, keeping the fish succulent as it bubbles away in the cream while the gratin soaks up the tasty fish juices.This is a fabulous cosy, rustic oven baked fish recipe that''s effortless yet company worthy!', 'https://www.recipetineats.com/tachyon/2023/05/Creamy-baked-fish-on-potato-gratin_7.jpg', 10, 45, 55, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_leeks", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_bread", "quantity": {"value": 3.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["4 x 160g/5oz white fish fillets (, ~2cm / 0.8\" thick, skinless (barramundi, snapper, tilapia, cod, salmon - Note 1))","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"]},{"ingredients":["3 tbsp / 50g unsalted butter","2 large leeks (, white and pale green part only, washed, cut in half lengthways, sliced 5mm / 0.2\" thick OR 2 onions (Note 2))","3 garlic cloves (, minced)","2 medium starchy potatoes (250g / 8oz each), peeled (Note 3)","3/4 tsp cooking/kosher salt","1/2 tsp black pepper","1/2 cup dry white wine (, any type, sub more veg stock (Note 4))","1/2 cup vegetable stock/broth (, low sodium)","1 cup thickened/heavy cream"],"purpose":"Potato gratin:"},{"ingredients":["3/4 cup panko breadcrumbs","2 tbsp extra virgin olive oil","1/4 cup parmesan (, finely shredded)"],"purpose":"Crunchy topping:"}]', '[{"description":"Preheat the oven to 180°C/350°F (160°C fan) with a shelf in the middle.","images":[],"step":1},{"title":"Potatoes","description":"Cut the potatoes into quarters, then sliced 4mm / 1/6\" thick. Place cut potato in a large bowl of water (prevents from going brown, removes excess starch so it cooks quicker). Drain before use.","images":[],"step":2},{"title":"Crunchy topping","description":"Mix panko and olive oil in a bowl. Then stir in parmesan.","images":[],"step":3},{"title":"Season fish","description":"Sprinkle salt and pepper on both sides of the fish fillets. Set aside.","images":[],"step":4},{"title":"Sauté","description":"Melt butter in a large oven-proof skillet (30cm/12\") over high heat until foamy. Add leek and garlic, then cook for 3 minutes.","duration":3,"images":[],"step":5},{"title":"Sauté potatoes","description":"Add potato, salt and pepper. Cook for 6 minutes, stirring regularly. The potatoes should be half cooked at this stage.","duration":6,"images":[],"step":6},{"title":"Reduce wine and stock","description":"Pour in white wine. Simmer rapidly until it is mostly evaporated - about 1 minute. Pour in stock, then simmer for 1 1/2 minutes or until reduced by half.","images":[],"step":7},{"title":"Top with fish","description":"Turn the stove off. Place fish on top of the potatoes, presentation side up. (Note 1) Pour cream all over, aiming for full coverage. Sprinkle with panko breadcrumbs.","images":[],"step":8},{"title":"Bake for 30 minutes","description":"I know this sounds like a long time but the fish stays succulent!","duration":30,"images":[],"step":9},{"title":"Colour topping","description":"Switch to the oven grill (broiler) on high and move the skillet up to the top shelf. Grill/broil 4 minutes or until golden.","images":[],"step":10},{"title":"Rest","description":"Remove and rest for 5 minutes, then serve! Eat the fish and gratin together with each mouthful for maximum eating pleasure!!","duration":5,"images":[],"step":11}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["French-style","Western"],"categories":["fish-recipes","mains","one-pot-recipes","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a9d95f30fe20', 'en', 'US', 'Kedgeree - British curried rice and fish', 'Recipe video above. Traditional English smoked fish and rice dish - think of it as an English biryani! Smoked haddock or cod tossed through a butter spiced rice studded with eggs, this is true fusion food at its best.', 'https://www.recipetineats.com/tachyon/2023/04/Kedgeree_3.jpg', 15, 30, 45, 5, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_smoked_haddock_or_cod", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_curry_leaves", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.015, "unit": "jar of 40g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.25, "unit": "carton of 12"}}]', '[{"ingredients":["4 cups/ 1 litre chicken stock/broth (, low-sodium (Note 5))","500g/1 lb smoked haddock or cod (, skin-on (or other smoked fish, Note 1))","2 1/4 cups long grain rice (, uncooked)","75g / 5 tbsp unsalted butter","15 curry leaves (optional, Note 2)","6 green cardamom pods (, lightly crushed (Note 3))","1 brown onion (, diced)","2 garlic cloves (, finely minced)","2 tsp curry powder (anything! Use spicy if you want, I use mild)","1/2 tsp turmeric powder","1 cup frozen peas (, thawed)","1/2 cup coriander/cilantro leaves (, roughly chopped (sub green onion or parsley))","3 hard boiled eggs (, halved or quartered (9 minute cook))"]}]', '[{"title":"Poach fish","description":"Bring chicken stock to a boil in a large saucepan or small pot. Place fish in (it should all be just about submerged, Note 4) and adjust heat so the stock is barely rippling. Poach it gently for 8 minutes or until the fish flakes apart. Remove fish onto a large plate.","duration":8,"images":[],"step":1},{"title":"Flake fish","description":"When cool enough to handle, discard skin (gently scrape with a butter knife) and flake fish into large pieces, checking for any bones.","images":[],"step":2},{"title":"Reserve stock","description":"Measure out 1/2 cup of the poaching liquid and set aside for later (drizzle on at end to juice up the rice).","images":[],"step":3},{"title":"Cook rice 13 min","description":"Add rice into the poaching liquid in the saucepan. Bring to a simmer over high heat. Cover with lid then reduce heat to low. Cook for 13 minutes.","duration":13,"images":[],"step":4},{"title":"Rest rice 10 min","description":"Remove the saucepan from the stove with the lid on and rest for 10 minutes. Fluff rice using a rubber spatula.","duration":10,"images":[],"step":5},{"title":"Curried butter","description":"While the rice is resting, melt the butter in a very large (30cm/12\") non stick skillet or pot, over medium-high heat. Add the cardamom pods and curry leaves and stir for 30 seconds. Add the onions, garlic and sauté for 5 minutes until browning at the edges, stirring regularly.","duration":0.5,"images":[],"step":6},{"title":"Toss rice","description":"Lower heat to medium. Stir in the curry powder and turmeric, and then the rice. Toss the rice in the spiced butter until well coated and uniformly yellow. Pour over the reserved 1/2 cup of fish poaching stock, and toss to mix through (it moistens the rice).","images":[],"step":7},{"title":"Season with salt if required","description":"Check the rice for seasoning. If you used store-bought packet stock, you should find there''s enough natural saltiness already. Otherwise season to taste and mix rice well.","images":[],"step":8},{"title":"Peas & fish","description":"Stir through the peas and most of the coriander (hold some back for garnish). Then gently fold through the fish, taking care to keep some pieces in large chunks.","images":[],"step":9},{"title":"Serve","description":"Spoon out rice onto one large platter or individual plates to serve. Top with boiled egg halves, and garnish with the remaining coriander. EAT!","images":[],"step":10}]', '["egg","fish","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["British","English"],"categories":["fish-recipes","mains","other","quick-and-easy","rice-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a76b93cf025', 'en', 'US', 'Chilli Lime Fish', 'Recipe video above. Pan-seared chunks of white fish are coated in a syrupy, spicy lime sauce in this dish loosely based on pla tort sahm rot, a traditional Thai street stall favourite. It tastes a bit like a fish version of everybody''s favourite Chilli Garlic Prawns. Very quick to make, it''s loaded with big flavours!Spice level: fairly spicy but not blow-your-head-off. See Note 4 for how to control the spiciness.', 'https://www.recipetineats.com/tachyon/2022/10/Chilli-Lime-Fish-cookbook-reference-photo_5.jpg', 10, 8, 18, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.33, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.075, "unit": "bottle of 400ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_steamed_asian_greens", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["330g / 11 oz thin white fish fillets (~1cm / 0.4\" thick) (, skinless, cut into 6cm / 2.5\" (or so) squares pieces (Note 1))","1/4 tsp cooking/kosher salt","1/4 cup rice flour or ordinary flour (Note 2)","2 tbsp canola oil"],"purpose":"Fish:"},{"ingredients":["2 tsp sesame oil","2 garlic cloves (, finely minced with a knife (Note 3))","2 tsp ginger (, finely minced with a knife (Note 3))","1 tsp chilli flakes / red pepper flakes (Note 4)","2 tbsp sriracha (Note 4)","2 tsp light soy sauce or fish sauce (Note 5)","3 tbsp brown sugar","1/2 cup water","2 tbsp lime juice"],"purpose":"Sauce:"},{"ingredients":["2 tbsp coriander/cilantro leaves","1 tbsp large red chilli (, finely sliced)","Lime wedges"],"purpose":"Garnishes (optional):"},{"ingredients":["Rice of choice","Steamed Asian greens"],"purpose":"Serve with:"}]', '[{"title":"Dust fish","description":"Sprinkle with salt, dust with rice flour, shake off excess.","images":[],"step":1},{"title":"Cook fish","description":"In a non-stick skillet, heat oil over medium-high heat. Cook the fish until golden on each side then remove to a plate.","images":[],"step":2},{"title":"Fish cooking times","description":"Thin fillets 1 cm / 2/5\" thick: 1 1/2 minutes each side; thicker fillets 1.5 - 1.75cm / 0.6 - 0.75\" thick 2 minutes each side) or until the internal temperature is 55°C / 130°F. Remove fish to a plate and set aside.","images":[],"step":3},{"title":"Sauté aromatics","description":"In the same pan, add sesame oil on medium heat. Cook garlic, chilli and ginger until golden - about 20 seconds.","images":[],"step":4},{"title":"Sauce","description":"Add everything else except lime juice. Stir, simmer, then reduce until syrupy - about 2 minutes. Add lime juice and stir. (If sauce gets too thick, add water)","images":[],"step":5},{"title":"Coat fish","description":"Return fish into sauce, turning to coat in the sauce.","images":[],"step":6},{"description":"Serve over rice, with garnishes of choice! Pictured with steamed baby pak choy tossed with Asian Sesame Dressing.","images":[],"step":7}]', '["fish","gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Modern Asian","Thai-ish"],"categories":["fish-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9a562a1e1042', 'en', 'US', 'Italian Crusted Sardines', 'Recipe video above. Here''s the perfect recipe for the sardine-shy: coat filleted sardines with an assertive Italian crust then pan fry until crispy. It''s an explosion of flavour and texture cooked in 2 1/2 minutes flat, making it one of the fastest fish recipes around!Excellent recipe for the sardine wary or first timers - no bones to worry about, and the intense Italian flavours balance out any concerns about the fishy flavour of sardines.Serve on crostini with a fresh salad on the side.', 'https://www.recipetineats.com/tachyon/2021/09/Mediterranea-Crusted-Sardines_4-Square.jpg', 10, 5, 15, 2, '[{"id": "ing_butter", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_pinenuts", "quantity": {"value": 0.025, "unit": "jar"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_baby_capers", "quantity": {"value": 0.02, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.3, "unit": "pack of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 0.04, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["8 butterflied sardines (20g each = 160g total, Note 1)","1/4 tsp salt","1/8 tsp pepper","1/4 tsp smoked paprika (sub normal or sweet)","3 tbsp extra virgin olive oil"],"purpose":"Sardines:"},{"ingredients":["1/2 cup panko breadcrumbs (Note 2)","1 garlic clove (, finely minced)","2 tsp toasted pinenuts (, finely chopped (Note 3))","2 anchovies fillets (, finely minced (sub 3/4 tsp paste, Note 4))","1 tsp baby capers (, drained, finely chopped (Note 5))","1 tsp lemon zest","4 tbsp pecorino cheese (, finely grated (or parmesan))","2 tsp fresh oregano (, chopped (sub 1/2 tsp dried))","1 tbsp extra virgin olive oil"],"purpose":"Italian Crust:"},{"ingredients":["4 tsp red onion, finely chopped (~1/4 small onion)","1 tsp large red chilli, finely chopped (, deseeded)","2 tsp parsley (, finely chopped)"],"purpose":"Topping:"}]', '[{"title":"Mix Crust","description":"Mix the Italian Crust ingredients in a bowl. Spread on a small plate.","images":[],"step":1},{"title":"Mix Topping","description":"Mix the Topping together in another small bowl.","images":[],"step":2},{"description":"Crust sardines:","images":[],"step":3},{"title":"Prepare sardines","description":"Pat sardines dry with paper towel. Sprinkle both sides of each sardine with the salt and pepper. Sprinkle the skin side only with the paprika.","images":[],"step":4},{"title":"Crust flesh side","description":"Press flesh side only firmly into the breadcrumbs - it won''t completely cover, that''s what we want (Note 6). Place on plate, breadcrumb side up. Repeat with remaining sardines.","images":[],"step":5},{"description":"Cooking sardines:","images":[],"step":6},{"title":"Pan fry sardines","description":"Heat oil in a large non stick skillet over medium high heat. Place sardines in, skin side down. Cook for 60 seconds, then carefully turn. Cook the crust side for 90 seconds or until golden and crispy.","duration":1,"images":[],"step":7},{"title":"Topping & oil drizzle","description":"Remove sardines onto plate, crust side up. Sprinkle with Topping. Pour remaining hot oil over sardines - enjoy the sizzle!","images":[],"step":8},{"description":"Serve immediately! Ideal served with crostini for the ultimate sardines on toast. See in post for side salad pairings.","images":[],"step":9}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["dinner-tonight","fish-recipes","italian-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eff49e4638ee', 'en', 'US', 'Fish with White Wine Sauce', 'Recipe video above. This is a beautiful, elegant white wine sauce that will go with virtually any fish. The simple restaurant trick we deploy here is to mix in cold cubes of butter which makes the sauce glossy and satiny. It''s a classic French technique called monter au beurre.Don''t try this sauce with baked fish (make this Baked Fish with Lemon Cream Sauce instead). You need to pan fry because the fond left in the pan after pan frying dissolves into the sauce and adds flavour.', 'https://www.recipetineats.com/tachyon/2021/08/Fish-in-white-wine-cream-sauce_95.jpg', 5, 12, 17, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 2.0, "unit": "bottle of 750ml"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["4 x 150g / 5oz white fish fillets (, skinless, boneless (I used snapper, Note 1))","1/2 tsp salt","1/4 tsp pepper","2 tbsp extra virgin olive oil"],"purpose":"Pan seared fish:"},{"ingredients":["1 eschalot (, small, finely chopped (~1 1/2 tbs, Note 2))","1 1/4 cups white wine (, dry, not sweet or too woody (chardonnay is especially good, Note 3))","1 tsp lemon juice (sub white wine vinegar)","1 tsp white wine vinegar (sub more lemon)","1/8 tsp salt","1 pinch pepper","1 pinch white sugar","1 cup thickened/heavy cream","30g / 2 tbsp unsalted butter (, cold, cut into 1cm / 1/3\" cubes)"],"purpose":"White wine sauce:"},{"ingredients":["2 tsp finely chopped parsley (or chives)"],"purpose":"Garnish, optional:"}]', '[{"description":"Cook fish:","images":[],"step":1},{"description":"Preheat oven to 50°C/120°F. Place rack over a tray.","images":[],"step":2},{"title":"Season fish","description":"Sprinkle fish with salt and pepper.","images":[],"step":3},{"title":"Cook fish","description":"Heat oil in a large non stick skillet over medium high heat. Cook fish in two batches until golden, 2 minutes on each side, or until the internal temperature is 55°C/131°F. (Note 4)","images":[],"step":4},{"title":"Keep warm","description":"Place fish on rack, and place in the oven to keep warm.","images":[],"step":5},{"description":"White wine sauce:","images":[],"step":6},{"title":"Discard oil","description":"Tip out excess oil from the skillet but don''t wipe clean.","images":[],"step":7},{"title":"Reduce wine","description":"Add eschalot, white wine, lemon juice, vinegar, salt, pepper, sugar to the pan. Bring to simmer (still on medium high) and reduce by half (~3 minutes).","images":[],"step":8},{"title":"Simmer cream","description":"Add cream, simmer for 2 minutes.","duration":2,"images":[],"step":9},{"title":"Finish with COLD butter","description":"Turn heat to low and add cold butter one cube at a time while mixing with wooden spoon. Once all the butter is incorporated, the sauce should be thickened, satiny and beautifully glossy.","images":[],"step":10},{"title":"Optional strain","description":"Strain the sauce through a sieve (discard eschalot), then pour it back into the pan.","images":[],"step":11},{"title":"Fish in sauce","description":"Place fish back into the pan in the sauce. Spoon some sauce over the fish, leave for 30 seconds.","duration":0.5,"images":[],"step":12},{"title":"Serve","description":"Transfer fish onto serving plates. Spoon sauce over each fish, sprinkled with parsley if desired. Pictured with a side of pea puree (great colour splash!).","images":[],"step":13}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["French-ish","Western"],"categories":["dinner-tonight","fish-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0ffa15dca2f8', 'en', 'US', 'Really good Fish Cakes', 'Recipe video above. You''ll find plenty of fish cake recipes floating around. But there are good fish cakes and then there are great fish cakes! The trick is to keep the potato chunky and the fish in big flakes rather than letting it all turn into a mush. Meanwhile, adding garlic, chilli, green onion and thyme to the mix keeps these fish cakes full of flavour!Pan fry then bake for best results. Pan fry golden, then bake to heat all the way through (because I like my fish cakes chunky!) and reheat the first batch you pan fried.', 'https://www.recipetineats.com/tachyon/2021/07/Fish-Cakes_96.jpg', 30, 95, 125, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 800.0, "unit": "bag of 2kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["500g / 1 lb white fish fillets (, skinless boneless, cut into 3cm / 1.2\" pieces (Note 1))","60g / 4 tbsp unsalted butter","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Fish:"},{"ingredients":["800g / 1.6 lb potatoes ( – Sebago (Aus), Russet (US), Maris Piper / King Edwards (UK) (Note 2) (makes 500g flesh))","2 garlic cloves (, finely minced)","1/2 cup green onion (, finely sliced (~1 large stem))","2 large red chillis (, deseeded and finely chopped (can omit))","1 tbsp thyme leaves (, chopped)","1 tbsp parsley (, finely chopped)","3/4 tsp salt"],"purpose":"Fish cakes:"},{"ingredients":["1 cup flour","2 eggs (, lightly whisked)","1 1/4 cups panko breadcrumbs (sub ordinary breadcrumbs)","1 cup vegetable or canola oil (, for frying (~ 1cm / 0.4\" depth))"],"purpose":"Crumbing and cooking:"}]', '[{"description":"Bake potatoes in a 220°C / 430°F (200°C fan) oven for 75 minutes or until they can be pierced with a knife with no resistance. Cut in half and scoop flesh out into a large bowl.","duration":75,"images":[],"step":1},{"title":"Turn oven down to 200°C / 390°F (180°C fan)","description":"fish cakes are finished in the oven.","images":[],"step":2},{"description":"Cook fish (while baking potatoes):","images":[],"step":3},{"description":"Set a rack over a tray. Sprinkle fish with salt and pepper.","images":[],"step":4},{"description":"Melt butter in a large non-stick skillet over medium high heat. Add half the fish and cook, turning, for 4 minutes in total. It should be just cooked inside (ie. flakes easily) but not golden.","duration":4,"images":[],"step":5},{"description":"Transfer to rack to cool. Repeat with remaining fish.","images":[],"step":6},{"description":"Fish Cake Mixture:","images":[],"step":7},{"title":"Sauté garlic","description":"In the same skillet, add garlic, chilli ,thyme and green onion into the leftover butter. Cook for 1 minute until garlic is golden, then pour over the potato, being sure to scrape out every drop of butter!","duration":1,"images":[],"step":8},{"title":"Roughly mash potato","description":"Add parsley and salt, then use a wooden spoon to roughly mash the potato. Don''t use a potato masher, we want some chunks, not smooth mashed potato.","images":[],"step":9},{"title":"Mix in fish","description":"Add fish then gently stir through, breaking it up a bit so you have some nice flakes mixed throughout the potato. Don''t mash the fish up too enthusiastically - we want fish chunks!","images":[],"step":10},{"title":"Form fish cakes","description":"Scoop out 1/4 cup of mixture. Pack it in firmly, pop out onto hand and shape firmly into a 1.75cm / 2/3\" thick cake. The potato will make it hold together, if you press firmly. You should make 13 to 15.","images":[],"step":11},{"description":"Crumb and cook:","images":[],"step":12},{"title":"Crumb","description":"Coat in flour (shake off excess), dip in egg (let excess drip off) then coat in breadcrumbs, pressing to adhere.","images":[],"step":13},{"title":"Pan fry 3 minutes","description":"Heat oil in skillet over medium high heat. Cook fish cakes in batches for 1 1/2 minutes on each side until golden, then transfer to a paper towel-lined tray. If you''re pedantic like me, stand them on their side and roll slowly to cook and make the sides golden too.","images":[],"step":14},{"title":"Bake 10 minutes","description":"Remove paper towel from under the fish cakes. Bake for 10 minutes (this heats all the fish cakes all the way through into the middle + reheats the first batch cooked).","duration":10,"images":[],"step":15},{"description":"Serve with lemon wedges, tartare sauce, plain mayonnaise (Kewpie!), sour cream, ketchup or tomato sauce.","images":[],"step":16}]', '["egg","fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6afecd3fc001', 'en', 'US', 'Salmon with Herb & Garlic Cream Sauce', 'Recipe video above. This quick, creamy Salmon Sauce gets a fine dining touch with the addition of fresh tarragon and chervil. It''s simply an excellent, easy salmon recipe for all those times when you want a touch of luxury with minimal effort!', 'https://www.recipetineats.com/tachyon/2021/01/Salmon-in-Creamy-Herb-Garlic-Sauce_6.jpg', 5, 15, 20, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chervil", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["4 salmon fillets (, skinless (~180g/6oz each) (Note 1))","1/2 tsp black pepper","1/2 tsp salt","1 tbsp olive oil","15g / 1 tbsp butter (, unsalted)"],"purpose":"Salmon"},{"ingredients":["2 garlic cloves (, finely minced)","1/2 cup dry white wine (or more chicken stock) (Note 2)","1/2 cup chicken or vegetable stock/broth (, low sodium)","1 cup cream (, heavy/thickened )","1/2 cup parmesan (, finely grated (grate your own, Note 3))","2 tsp tarragon leaves* (, finely chopped)","2 tsp chervil* (, finely chopped)","2 tsp parsley* (, finely chopped, plus more for garnish)"],"purpose":"Creamy garlic sauce:"}]', '[{"title":"Season","description":"Pat salmon dry, then sprinkle with salt and pepper.","images":[],"step":1},{"title":"Pan-sear","description":"Heat oil in a large non stick skillet over medium high heat. Add salmon, presentation side down, and cook for 3 minutes until golden brown.","duration":3,"images":[],"step":2},{"title":"Flip","description":"Turn salmon and cook the other side for another 2 minutes, until the internal temperature registers 49°C / 120°F (for medium-rare, recommended) or until cooked to your taste (Note 5).","images":[],"step":3},{"title":"Butter baste","description":"When it''s almost cooked, add the butter. Melt, then spoon over the salmon a few times.","images":[],"step":4},{"title":"Rest","description":"Remove salmon onto plate, and cover loosely with foil to keep warm.","images":[],"step":5},{"description":"Creamy Salmon Sauce:","images":[],"step":6},{"title":"Sauté garlic","description":"Add garlic and stir for 20 seconds or until light golden.","duration":0.3333333333333333,"images":[],"step":7},{"title":"Reduce wine","description":"Add white wine, turn up heat to high. Bring to simmer while stirring base of the pan to dissolve all the golden bits into the sauce. Cook 1 minute or until it most evaporates and the wine-y smell is gone.","images":[],"step":8},{"title":"Thicken cream & stock","description":"Add cream and chicken stock, then simmer on medium heat for 2 - 3 minutes until reduced and slightly thickened.","duration":2.5,"images":[],"step":9},{"title":"Add parmesan & herbs","description":"Stir through parmesan (this will thicken sauce more), then the herbs. Taste sauce and see if more salt and pepper is needed.","images":[],"step":10},{"title":"Serve","description":"Serve salmon with Creamy Sauce, ensuring there''s something on the plate to soak up all that amazing sauce! Mashed Potato rates highly. See above video for list of suggestions (including side salads).","images":[],"step":11}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","mains","other","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f1d25fd5a17', 'en', 'US', 'Crispy Beer Battered Fish', 'Recipe video above. This makes a light, crispy fish batter like you''ve never had before! Stays crispy for a good 15 - 20 min, though my fish disappears long before that.The yeast and carbonation in beer makes the batter puffy just like you get at good fish ''n chip shops. Meanwhile the rice flour + shock of ice cold batter hitting the hot oil makes it super crispy. Normal wheat flour doesn''t cut it – the batter goes soggy within minutes!You can''t taste the beer at all, and the alcohol gets cooked out. Serve with ultra crispy French fries for the ultimate homemade Fish & Chips experience.', 'https://www.recipetineats.com/tachyon/2021/01/Beer-Battered-Fish_8.jpg', 10, 12, 22, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.003, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 1.0, "unit": "bottle of 330ml"}}, {"id": "ing_oil", "quantity": {"value": 4.5, "unit": "bottle"}}, {"id": "ing_tartare_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_homemade_crispy_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["700g/ 1.4lb white fish fillets (, like flathead, snapper, whiting, cod, tilapia, flathead (skinless, boneless, Note 1))"],"purpose":"Fish:"},{"ingredients":["¼ cup rice flour (Note 2)"],"purpose":"Dusting:"},{"ingredients":["¾ cup plain/all purpose flour","¼ cup rice flour (makes it super crispy, Note 2)","1¼ tsp baking powder","¼ tsp salt","1 cup very cold beer (, anything other than dark beers like stout, porter etc (Note 3))"],"purpose":"Crispy Fish Batter:"},{"ingredients":["4 - 5 cups peanut oil (or vegetable, canola or cottonseed oil)"],"purpose":"Cooking:"},{"ingredients":["Tartare Sauce","Lemon Wedges","Homemade Crispy French fries","Baked Potato Wedges"],"purpose":"Serving:"}]', '[{"title":"Dry & cut fish","description":"Pat fish dry using paper towels or a tea towel. Cut into 7 x 3cm / 3 x 1¼\" batons, or larger fillets if you prefer. If you have very thick fillets, cut in half horizontally (Note 1)","images":[],"step":1},{"title":"Dusting bowl","description":"Place ¼ cup rice flour in a shallow bowl.","images":[],"step":2},{"title":"Heat oil: Heat 6cm / 2\"","description":"3\" oil in a large heavy based pot over medium high heat to 190°C/375°F.","images":[],"step":3},{"title":"Salt & dust","description":"While oil is heating, sprinkle 3 or 4 pieces of fish with a pinch of salt, then coat in rice flour and shake off excess. You can leave them like this for up to 10 minutes.","images":[],"step":4},{"title":"Cold batter","description":"Just before cooking, whisk together the flour, rice flour, baking powder and salt. Add very cold beer into the batter and whisk just until incorporated evenly into the flour. Do not over-mix, do not worry about flour lumps (Note 4). It should be a fairly thin batter but fully coat the back of a spoon. If too thick, add beer 1 tsp at a time.","images":[],"step":5},{"title":"Dredge fish","description":"Dunk a piece of fish in the batter, the let the excess drip off very briefly.","images":[],"step":6},{"title":"Fry 3 minutes","description":"Carefully lower into oil, dropping it in away from you, one piece at a time. Don''t crowd the pot; fry in batches. Fry for 3 minutes, flipping after about 2 minutes, until deep golden.","duration":3,"images":[],"step":7},{"title":"Drain","description":"Drain on paper towels. Repeat with remaining fish. Serve hot! However it will stay crisp for 15 - 20 minutes. (Note 5 for larger batch cooking).","duration":17.5,"images":[],"step":8},{"description":"Serve with Tartare Sauce, lemon wedges and a leafy green salad on the side dressed with a classic vinaigrette. Serve with Crispy French Fries or oven baked wedges!","images":[],"step":9}]', '["fish","gluten","peanuts"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["deep-fried-recipes","fish-recipes","iconic-dishes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d680e7dad1cf', 'en', 'US', 'Crispy Skin Salmon', 'Recipe video above. Cooking salmon so the skin is evenly crispy from end to end is simple if you follow two key tips: Firstly, ensuring the skin is dry. Secondly, using enough oil to cover the base of the skillet so the skin fries properly and goes golden and crispy rather than just burning in patches. Easy!Pictured with a creamy Lemon & Herb Risotto (ultra easy hands-free baked method!).', 'https://www.recipetineats.com/tachyon/2020/11/Crispy-Salmon-in-skillet.jpg', 3, 10, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["4 salmon fillets (, skin-on (Note 1))","1 tsp olive oil (or other cooking oil)","1 tsp salt (, cooking/kosher (3/4 tsp table salt, Note 2))","1/2 tsp black pepper"]},{"ingredients":["2 tbsp olive oil (or vegetable oil)"],"purpose":"Cooking:"},{"ingredients":["lemon wedges"],"purpose":"Serving:"}]', '[{"title":"Dry skin","description":"Pat the skin of the salmon very well with a paper towel until dry. If time permits, place the salmon skin side up in the fridge for 1 hour (uncovered,) to dry it out even more.","images":[],"step":1},{"title":"Season","description":"Drizzle flesh side with half the oil (just a tiny bit) and rub over skin. Sprinkle with half the salt and pepper. Turn fillet over and repeat. Do not do this step until just before cooking.","images":[],"step":2},{"title":"Heat oil","description":"Put enough oil in a large non stick skillet so it fully covers the base. Heat on medium high until it shimmers (but not smoking).","images":[],"step":3},{"title":"Skin side down","description":"Place salmon in the skillet skin side down, then immediately turn the head down to medium.","images":[],"step":4},{"title":"Press down","description":"Using a spatula or something similar, press down on each salmon for 10 seconds so the skin is pushed flat against the skillet and \"sets\" its form. If you can do at least two at a time that is ideal.","duration":0.16666666666666666,"images":[],"step":5},{"title":"Cook 7 minutes","description":"Cook for 7 minutes, or until the salmon is cooked 3/4 of the way through (you will see the colour changing up the side of the salmon) and the skin is crispy.","duration":7,"images":[],"step":6},{"title":"90 sec on flesh side","description":"Flip the salmon to skin side is up and cook for a further 90 seconds.","images":[],"step":7},{"description":"Final skin blast! (My secret tip) Flip the salmon again to skin side down, turn the heat up to medium high and cook the skin side again for 60 seconds, just to give it a final blast of heat to reinforce crispiness!","duration":1,"images":[],"step":8},{"description":"Serve skin side UP to protect the crispy skin. Fish skin will only stay crispy while it''s hot, so serve immediately! Pictured in post with creamy Lemon & Herb Risotto which acts as a side dish and semi-sauce (super easy no-stir recipe!).","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","mains","other","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6130927a800', 'en', 'US', 'Celebration Salmon Salad with Yoghurt Ranch Dressing', 'Recipe VIDEO above. A show off salad for gatherings! Hot smoked salmon adds a touch of special to this salad that''s loaded with fabulous flavours and textures. You''ll love the dressing! Recipe written for 5 servings, double batch pictured in post, shown as a main dish for a buffet.', 'https://www.recipetineats.com/tachyon/2019/12/Celebration-Salmon-Salad_3.jpg', 30, 5, 35, 5, '[{"id": "ing_salmon_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.8, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_chives", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_kale", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_peaches", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 10.0, "unit": "head"}}, {"id": "ing_fennel", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_snow_pea_sprouts", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 3.0, "unit": "pack of 200g"}}]', '[{"ingredients":["500g / 1 lb hot smoked salmon (, store bought, any flavour (Note 1))"]},{"ingredients":["1 small red onion (, halved then finely sliced)","1 cup (250 ml) apple cider vinegar ((enough to just cover onion), sub white wine vinegar)","1 tsp salt","2 tsp white sugar"],"purpose":"Quick Pickled Onion:"},{"ingredients":["2 cups Greek yoghurt (, full fat recommended)","3 tbsp extra virgin olive oil","1 garlic clove (, minced)","1/4 cup fresh chives, finely chopped","1/4 cup fresh dill, finely chopped","1/2 tsp EACH onion powder, garlic powder, salt, black pepper","1 1/2 tsp white sugar","3 tbsp lemon juice"],"purpose":"Yoghurt Ranch Dressing:"},{"ingredients":["4 cups (packed) kale (, torn into bite size pieces (Note 2))","2 tsp extra virgin olive oil","Pinch of salt"],"purpose":"Marinated Kale:"},{"ingredients":["2 pieces fruit - nectarines, peaches, grapefruit or blood oranges (get whatever''s ripe and juicy, or sub normal oranges)","10 cups cos lettuce / romaine (torn or cut into bite size pieces (Note 3))","1 small fennel (, shaved (0.5 mm / 1/5\" thickness) or finely sliced)","1 handful snow pea sprouts (can omit)","3/4 cup (75g) parmesan (, shredded (Note 4))"],"purpose":"Salad:"}]', '[{"title":"Flake salmon","description":"Use two forks to flake salmon into large chunks.","images":[],"step":1},{"title":"Dressing","description":"Mix the Yoghurt Ranch Dressing ingredients in a bowl. Adjust olive oil + lemon juice to taste. Leave 20 minutes.","images":[],"step":2},{"title":"Pickle Onions","description":"Place ingredients in a bowl, toss to coat. Set aside for 1 hour+ or until onion is softened (if in a rush, make sure the onion is finely sliced = faster pickle). Drain.","images":[],"step":3},{"title":"Marinated Kale","description":"Place kale in a large bowl, drizzle with oil then sprinkle with salt. Use your fingers to massage the oil onto the leaves - you want to ensure every part of the kale is coated in oil. Set aside for 30 minutes or until kale is softened.","duration":30,"images":[],"step":4},{"description":"Nectarines/peaches option- halve then finely slice.","images":[],"step":5},{"title":"Grapefruit/blood orange option","description":"segment per video. Squeeze all remaining juice out of the membrane after segmenting, mix into dressing.","images":[],"step":6},{"description":"Place lettuce, kale, fennel, 1/2 cup onion in bowl. Drizzle with about 1 cup dressing and 1/3 cup parmesan. Toss well to coat. Taste, add more parmesan or salt if you want, or more dressing.","images":[],"step":7},{"description":"Pile half dressed lettuce onto serving platter. Flake over half the salmon and half the fruit. Scatter with more red onion.","images":[],"step":8},{"description":"Top with remaining lettuce, salmon, fruit and onion (might not use all onion).","images":[],"step":9},{"description":"Drizzle with some dressing (might not use all, serve remainder on side). Scatter over snow pea sprouts, sprinkle with remaining parmesan. Place on table and let everyone help themselves!","images":[],"step":10}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","salad-recipes-main-course","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1d58f936c9a7', 'en', 'US', 'Salmon Patties', 'Recipe VIDEO above. Made with either fresh salmon OR canned salmon, these are so moreish! Golden crispy on the outside, savoury and juicy on the inside, these are baked, not fried, so they''re healthier and there''s less cleaning up. Makes 12 patties.', 'https://www.recipetineats.com/tachyon/2018/02/Salmon-Patties_8.jpg', 15, 20, 35, 4, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1 cup Panko breadcrumbs (Note 1 for subs)","1 small onion ((or 1/2 large), grated)","1 garlic clove (, finely minced)","400 g/ 14 oz cooked fresh salmon OR canned red or pink salmon (, drained (Note 2))","2 shallots / scallions / green onions (, finely sliced)","1/3 cup fresh dill (, roughly chopped (or 1 tsp dried herbs of choice))","2 eggs","1/2 cup parmesan (, grated or shredded)","1/4 tsp each salt and pepper"]},{"ingredients":["2 tbsp vegetable oil","Oil spray"],"purpose":"Cooking:"}]', '[{"description":"Preheat oven to 220C/430F standard (200C fan)","images":[],"step":1},{"description":"Place breadcrumbs in a bowl. Grate over onion, including juices. Mix onion into breadcrumbs, ensuring all breadcrumbs are soaked. (Note 3)","images":[],"step":2},{"description":"Add remaining ingredients except salmon. Mix well.","images":[],"step":3},{"description":"Add salmon. Stir through gently, leaving flakes of salmon (rather than vigorously mixing salmon into tiny pieces).","images":[],"step":4},{"description":"Scoop up 1/4 cup mixture (level, packed standard ice cream scoop, see Video). Form round patties about 1.5 cm/ 2/3\" thick and set aside.","images":[],"step":5},{"description":"Drizzle oil all over tray. Place in oven for 2 minutes until hot - oil will spread over tray. Tilt tray to spread if needed.","duration":2,"images":[],"step":6},{"title":"Place patties on tray","description":"DO NOT press down (makes them stick on tray). Spray surface with oil spray.","images":[],"step":7},{"description":"Bake 15 minutes. Flip, spray surface with oil spray, bake 5 minutes.","images":[],"step":8},{"description":"Serve with sour cream or yoghurt on the side for dipping / dolloping, and extra fresh dill if desired.","images":[],"step":9},{"description":"I served mine with cauliflower puree and Yoghurt Slaw - healthy side options! (Note 3)","images":[],"step":10}]', '["egg","fish","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","main-dishes","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_70e10b2bd897', 'en', 'US', 'Salmon Alfredo Pasta', 'A creamy Alfredo pasta tossed with flakes of hot smoked salmon (or plain cooked salmon). Make sure you follow the steps to toss the sauce and pasta with some of the pasta cooking water - it makes all the difference to create a luscious creamy sauce using only 1/2 cup of cream!', 'https://www.recipetineats.com/tachyon/2016/01/Salmon-Alfredo_7.jpg', 10, 15, 25, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 8.0, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 6.5, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}]', '[{"ingredients":["8 oz / 250g dried fettuccine","3 tbsp / 50g unsalted butter","1 small shallot (US) / eschallot (Australia), very finely minced (Note 1)","½ cup / 125 ml heavy cream (Note 2)","¾ cup / 185 ml freshly grated Parmigiano Reggiano or parmesan (Notes 3 and 4)","¼ teaspoon salt","Good grind of black pepper","6-7 oz / 180 - 200g hot smoked salmon fillet (, flaked (Note 5))"]},{"ingredients":["Fresh parsley (optional)","Extra Parmigiano Reggiano"],"purpose":"Garnish"}]', '[{"description":"Bring a large pot of salted water to boil. Add the fettuccine and cook until al dente (still firm but just cooked through). (Note 6)","images":[],"step":1},{"description":"Meanwhile, melt the butter in a deep fry pan over medium high heat. (Note 7)","images":[],"step":2},{"description":"Add the shallots and sauté for 2 minutes or until tender.","duration":2,"images":[],"step":3},{"description":"Add the cream and bring to boil. Turn heat down to medium low and simmer for 3 minutes.","duration":3,"images":[],"step":4},{"description":"Remove the fry pan from the heat and stir through the Parmigiano Reggiano, salt and pepper until the sauce is smooth.","images":[],"step":5},{"description":"TAKE OUT 1/2 cup of pasta water PLUS scoop out an extra mug (extra, just in case). Then drain the pasta in a colander.","images":[],"step":6},{"description":"Transfer the pasta and 1/2 cup of reserved pasta water into the fry pan with the sauce. Add salmon. Return the fry pan to the stove over medium heat. Toss very gently to coat the pasta in the sauce and allow the sauce to emulsify (Note 6) for 1 1/2 - 2 minutes, until the sauce coats the pasta - there should be no sauce pooled at the bottom of the skillet. (Note 7)","images":[],"step":7},{"description":"Remove from the stove and serve immediately, garnished with extra Parmigiano Reggiano and fresh parsley, if using.","images":[],"step":8}]', '["fish","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["dinner-tonight","fish-recipes","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","salmon-recipes","seafood-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2b5e5e07c97', 'en', 'US', '"Sizzling Beef" Steak Fried Rice', 'Recipe video above. This is a bit special because it''s rare to see fried rice made with juicy bites of steak! With marinated, tenderised beef pieces "sizzled" until golden (aka - your favourite Chinese restaurant Sizzling Beef!), this is an excellent recipe to make with economical cuts like sizzle steak, minute steak, and pre-cut stir fry strips. The beef is caramelised on the outside, and tenderised so it doesn''t overcook. It''s so soft and velvety, you will be shocked!', 'https://www.recipetineats.com/tachyon/2024/09/Sizzling-Beef-Fried-Rice-54326a.jpg', 15, 10, 85, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.015, "unit": "tub of 200g"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_white_rice", "quantity": {"value": 0.52, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 0.4, "unit": "pack"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["300g/ 10 oz rump beef steak (US: top sirloin)"]},{"ingredients":["1/2 tsp dark soy sauce (Note 2)","2 tsp oyster sauce (Note 3)","2 tbsp water","1 garlic clove","1/4 tsp sugar (any)","3/8 tsp baking soda (bi-carbonate soda) (ie 1/4 teaspoon HEAPED, Note 4)"],"purpose":"Tenderising beef marinade:"},{"ingredients":["2 1/2 tbsp canola or peanut oil (, separated)","4 green onion stems (, cut into 1.25 cm / 1/2\" lengths, white part separated from green part)","2 garlic cloves (, finely minced)","520g/ 1 lb (4 cups) cooked, day-old long grain white rice, (or other plain rice), refrigerated overnight (Note 5)","200g/7 oz green beans (, cut into 1.25 cm pieces (~ 2 heaped cups) (Note 6))"],"purpose":"Fried rice:"},{"ingredients":["2 tbsp fish sauce (Note 7)","1 1/2 tbsp oyster sauce (Note 3)","1/2 tsp sugar (any type)"],"purpose":"Fried rice sauce:"},{"ingredients":["2 eggs","1/2 tsp sesame oil","Pinch of salt and pepper (preferably white, but black ok)"],"purpose":"Scrambled egg:"}]', '[{"description":"Marinate beef 1 hour. Cook beef in 2 tbsp oil on high in a large pan until lightly seared, add white part of green onion and beans, cook until beef is caramelised, adding garlic towards the end. Add rice and sauce, toss well. Scramble egg on side of pan, toss through green part of green onion. Eat!","images":[],"step":1},{"title":"Marinade & tenderise beef","description":"Mix the marinade ingredients in a bowl then add the beef and toss well. Set aside for 1 hour (up to 24 hours), or the time specified in Note 1.","images":[],"step":2},{"title":"Sauce","description":"Mix the Sauce ingredients. Set aside.","images":[],"step":3},{"description":"Whisk the Scrambled Egg ingredients. Set aside.","images":[],"step":4},{"title":"Sizzle beef","description":"Heat 2 tablespoons of oil in a large non-stick pan over high heat (mine is 30cm/12\", see Note 8 for why no wok). Add the beef and cook for 2 minutes until the surface is sealed. Add the garlic, white part of the green onion and beans. Cook for another 1 minute until the beef is caramelised, stirring constantly so it doesn''t catch and burn.","duration":2,"images":[],"step":5},{"title":"Rice and sauce","description":"Add the rice and sauce. Toss for a good 1 1/2 - 2 minutes to give the rice a chance to get toasty.","images":[],"step":6},{"title":"Scramble egg","description":"shove all the rice to one side and shif the pan so the empty space is set over the flame. Add the remaining 1/2 tablespoon oil and spread. Pour the egg, swirl, give it 10 seconds to partially set then do lazy swirls with your spatula to scramble it softly. Once mostly cooked, quickly (but gently!) toss it though the rice.","images":[],"step":7},{"title":"Serve","description":"Add the green part of the green onion and toss through. Divide between bowls and enjoy!","images":[],"step":8}]', '["egg","fish","gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese","Thai-ish"],"categories":["fried-rice","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0263f552bf04', 'en', 'US', 'German Pork Knuckle (Schweinshaxe) - Slow Roasted with Crispy crackling!', 'Recipe video above. Realistically, one knuckle will serve 2. But for wow factor, serve one per person!!!While producing tender Pork Knuckle flesh is straightforward enough, very few recipes truly nail the crispy crackling. So here is a recipe that finally does! The skin is crispy all over and fabulously bubbly, shattering into a thousand porky shards when you bite instead of breaking your teeth on hard, leathery patches!Meanwhile, the flesh is seasoned with traditional flavourings and the Pork Knuckle is served with an authentic, dark and malty German beer gravy. It''s every carnivore''s dream come true!', 'https://www.recipetineats.com/tachyon/2021/05/German-Pork-Knuckle_7-main-1.jpg', 20, 180, 200, 2, '[{"id": "ing_pork", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_juniper_berries", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_beer", "quantity": {"value": 2.0, "unit": "bottle of 330ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 x 1.25kg / 2.5lb pork knuckle (Note 1)","2 tbsp white vinegar (Note 2)","3 garlic cloves (, cut into 4 - 6 slivers (Note 3))"]},{"ingredients":["2 tsp salt (, kosher / cooking salt NOT table salt (Note 4))","1 tsp black pepper","1 tsp juniper berries (Note 5)","1 tsp caraway seeds","1 tsp fennel seeds"],"purpose":"Marinade Rub:"},{"ingredients":["2 cups dark German beer (Note 6)","2 cups chicken stock / broth (, low sodium)","1 carrot (, unpeeled, sliced 2cm / 0.8\" thick)","1 onion (, unpeeled, halved, cut into 1.25cm / 1/2\" thick slices)","1 head garlic (, cut in two halves horizontally)","5 juniper berries (Note 5)","2 bay leaves (, preferably fresh otherwise dried)"],"purpose":"Beer Gravy:"},{"ingredients":["2 tsp cornflour/cornstarch","1/2 cup water","1 tsp white sugar","1/4 - 1/2 tsp salt (, kosher / cooking salt NOT table salt (Note 4))"],"purpose":"Gravy thickening and seasoning:"}]', '[{"description":"Preparation and seasoning:","images":[],"step":1},{"title":"Prick skin","description":"Poke lots of small holes all over the pork knuckle’s skin, using a small sharp knife or even a pin (eg. safety pin, sewing pin). Take care not to pierce through the fat into the flesh (Note 7).","images":[],"step":2},{"title":"Vinegar","description":"Brush (or rub) 1 tbsp of the vinegar on the pork flesh only, including inside cracks / crevices and meat under the skin where it meets the flesh (but do not peel skin back). Avoid getting vinegar on the skin.","images":[],"step":3},{"title":"Stud with garlic","description":"Make shallow incisions in the pork flesh (only) with a small knife then stuff with the garlic slivers.","images":[],"step":4},{"title":"Seasoning rub","description":"Pound the rub ingredients in a mortar and pestle until it''s a coarse powder (or use a Nutribullet, spice grinder or similar).","images":[],"step":5},{"title":"Rub seasoning on pork","description":"Rub pork skin with olive oil. Then rub the seasoning mix all over the pork – on the flesh, skin, and getting into all the cracks and crevices.","images":[],"step":6},{"title":"Skewer skin (secret for crispy skin! Note 8)","description":"Pull the skin down to stretch it tight so there''s no creases. Then thread through 2 metal skewers in a \"X\" formation near the base of the knuckle. Pierce through skin 2cm / 0.8\" from the base of the pork knuckle to hold the stretched skin in place.","images":[],"step":7},{"title":"\"Marinate\" overnight","description":"Place pork standing on a plate, then leave uncovered in the fridge overnight (Note 9).","images":[],"step":8},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":9},{"title":"Beer gravy","description":"Put all beer gravy ingredients in a roasting pan (deep enough to hold all liquids and vegetables).","images":[],"step":10},{"title":"Rack on pan","description":"Place a rack over the pan. Place pork knuckle on rack, sitting upright. (Note 10)","images":[],"step":11},{"title":"Slow roast","description":"Roast for 2 hours 10 minutes, rotating tray half way. (If the liquid in the pan is getting too low and in danger of drying out, top with 1/2 cup of water at a time.) Roast until the internal temperature in the thickest part of meat reaches 85°C / 185°F.","images":[],"step":12},{"description":"Make crispy Pork Knuckle crackling!","images":[],"step":13},{"description":"Remove knuckle from oven, transfer knuckle to a tray.","images":[],"step":14},{"title":"Increase oven","description":"Increase oven to 260°C / 500°F (240°C fan) (Note 11)","images":[],"step":15},{"title":"Brush skin with vinegar","description":"Brush skin with 1/2 the remaining 1 tbsp of vinegar. Place in oven for 30 minutes, rotating tray halfway and brushing with remaining vinegar.","duration":30,"images":[],"step":16},{"description":"Skin should be crispy, dip golden and mostly bubbly.","images":[],"step":17},{"title":"Rest","description":"Rest 15 minutes before serving with German Beer Gravy!","images":[],"step":18},{"description":"German beer gravy:","images":[],"step":19},{"title":"Strain liquid","description":"Strain roasting pan juices into a saucepan. Ideally you should have around 1.5 - 2 cups.","images":[],"step":20},{"title":"Thicken","description":"Bring liquid to a simmer. Mix cornflour and water, then pour into liquid while stirring. Add sugar and salt to taste.","images":[],"step":21},{"title":"Simmer","description":"Simmer for 2 minutes or until it becomes a thin syrup consistency (German beer gravy should not be as thick as normal gravy, but quite runny). If it''s too thick, add a touch of water. Too thin, simmer to reduce - it will thicken. Serve with pork knuckle!","duration":2,"images":[],"step":22}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Bavarian","German"],"categories":["german-food","iconic-dishes","mains","pork","pork-recipes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_220052dbd26b', 'en', 'US', 'Pizza Dough recipe', 'Recipe video above. This pizza dough can be made by hand with 5 minutes of kneading, or in 40 seconds flat using a food processor (see 2nd recipe card below). It makes a pizza crust like you get at Italian wood fired pizzerias - puffy edges with a chewy crumb, enough structure so you can pick up slices rather than being a sloppy mess. But not dry and stiff like a thin cracker! Best to use weights provided, if you can. Makes 3 pizzas.', 'https://www.recipetineats.com/tachyon/2020/05/Ball-of-pizza-dough.jpg', 30, 30, 60, 3, '[{"id": "ing_bread", "quantity": {"value": 600.0, "unit": "loaf"}}, {"id": "ing_yeast", "quantity": {"value": 0.02, "unit": "pack of 5 sachets"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.33, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.04, "unit": "pack of 125g"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_topping_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}]', '[]', '[{"title":"Mix dry","description":"Place flour, yeast, sugar and salt in a large bowl. Mix with a wooden spoon.","images":[],"step":1},{"title":"Add wet","description":"Make a well in the centre. Pour in oil and water. Mix to bring together so it comes away from the side of the bowl.","images":[],"step":2},{"title":"Knead 5 minutes","description":"Sprinkle work surface with 1/2 the Extra Flour. Scrape dough out of bowl. Bring together into a ball then knead for 5 minutes until pretty smooth (see video for Before v After, Note 5). Shape dough into a ball.","duration":5,"images":[],"step":3},{"description":"Drizzle large bowl with Extra Olive Oil (can use same bowl).","images":[],"step":4},{"description":"Place dough in, turn over and rub top with oil.","images":[],"step":5},{"description":"Cover with cling wrap, then put in a warm place for 1 - 2 hours until it doubles in size. (Rise #1)","images":[],"step":6},{"title":"Optional fridge","description":"flavour development:","images":[],"step":7},{"description":"After rising, refrigerate bowl with dough for up to 5 days (do not punch down). Flavour gets better with time. (Note 7)","images":[],"step":8},{"description":"Form small balls, Rise #2:","images":[],"step":9},{"description":"Scrape dough out of bowl on work surface lightly dusted with flour. Shape into log, fully deflating dough in the process.","images":[],"step":10},{"title":"Cut into 3 equal portions (330g / 11.6 oz each)","description":"one for each pizza base.","images":[],"step":11},{"description":"For each dough portion, shape into a ball, tuck the sides under, money-bag style, so you have a smooth surface.","images":[],"step":12},{"title":"Place balls, smooth side up, on a large tray","description":"5cm / 2\" from edge of tray, 10cm / 4\" from each other.","images":[],"step":13},{"description":"Sprinkle balls with a touch of flour and lightly rub to coat surface (so they don''t stick to tea towel). Cover balls with lightly damp tea towel. Alternatively, cover loosely with a sheet of baking paper then seal tray with cling wrap, ensuring the dough balls have plenty of space to rise under the cling wrap.","images":[],"step":14},{"description":"Leave in warm place 1 hour until almost double in size. (If fridge-cold, this will take 3 - 4 hours).","images":[],"step":15},{"description":"Stretch pizza base:","images":[],"step":16},{"description":"Preheat oven to 275°C / 530°F, or as high as it will go. Put shelf in top third of oven.","images":[],"step":17},{"description":"Sprinkle work surface with 1/2 tbsp flour. Place one dough ball on top.","images":[],"step":18},{"description":"Without touching the edges, use finger tips and back of fingers to deflate dough gently and spread out into a 20cm/8\" round. Then use your fingers and palms to stretch the dough, working around the circle, until it''s almost the size of a 30cm / 12\" pizza pan.","images":[],"step":19},{"description":"Drag onto the pizza pan (or paddle if cooking on pizza stone, Note 8). Then finish stretching it to fill the pan. Neaten up the shape so it''s as perfectly round and uniform as possible – the shape you have now is the shape it will bake to! Leave 1 cm / 1/3\" of the edge untouched as much as possible (for puffy crusts!).","images":[],"step":20},{"description":"Topping / Cooking (work quickly!):","images":[],"step":21},{"description":"Spread with 1/4 cup pizza sauce, 130g / 1 1/3 cups freshly grated mozzarella, then toppings of choice (see Topping recipes here).","images":[],"step":22},{"description":"Bake 10 minutes, rotating at 4 minutes and checking at 8 minutes, until cheese is melted and has some golden spots.","images":[],"step":23},{"description":"Cut into wedges, serve immediately!!","images":[],"step":24},{"description":"Repeat process for remaining balls to make two more pizzas.","images":[],"step":25}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["good-to-know","main-dishes","pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38fba5c4f685', 'en', 'US', 'Pizza toppings', 'Here are our top 12 favourite pizza toppings! This list will continue to grow, at which point I''ll start creating separate recipes for each pizza. For now, enjoy this handy 12-in-1 list! Also see - homemade pizza dough (dough and cooking) and pizza sauce recipe. No yeast? No worries! Make this Magic No Yeast Pizza Dough.', 'https://www.recipetineats.com/tachyon/2020/05/Pizza-Toppings.jpg', 10, 10, 20, 1, '[{"id": "ing_pizza_base", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_mozzarella", "quantity": {"value": 16.0, "unit": "pack of 125g"}}, {"id": "ing_black_pepper", "quantity": {"value": 32.0, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_olives", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_ham_batons", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_barbecue_sauce", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 10.0, "unit": "jar of 50g"}}, {"id": "ing_cabanossi_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 25.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.03, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_baby_rocket", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 3.0, "unit": "pack of 500g"}}, {"id": "ing_kale", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.0, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_capricciosa_recipe", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.0, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.225, "unit": "pack of 200g"}}, {"id": "ing_prosciutto", "quantity": {"value": 9.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 pizza base (28cm / 11\" base, see separate recipe)","1/4 cup pizza sauce (see separate recipe)"]},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","20 slices pepperoni (, cut 3mm / 1/8” thick)"],"purpose":"Pepperoni"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","1/3 cup onion (, cut 0.5cm (1/4”) thick)","1/3 cup bacon (, cut into 1 x 3cm (1/2 x 2”) pieces)","1/2 cup capsicum (, sliced 0.5cm (1/4”) thick)","12 slices pepperoni (, cut 3mm / 1/8” thick)","1/3 cup beef mince (ground beef) (, formed into 1cm (1/2”) balls)","1/3 cup button mushrooms (, cut 3mm (1/8”) thick)","1/4 cup black olives (, sliced)"],"purpose":"Supreme"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","2/3 cup ham (, cut into 2 x 0.5cm (1 x 1/4\") batons)","1/2 cup pineapple (, cut into small chunks)"],"purpose":"Ham & Pineapple"},{"ingredients":["3 tbsp barbecue sauce (instead of pizza sauce)","1 1/4 cups mozzarella cheese (, freshly grated)","10 slices pepperoni (, cut 3mm (1/8”) thick)","1/3 cup bacon (, cut into 1 x 3cm (1/2 x 2”) pieces)","1/3 cup cabanossi (, cut into 5mm (1/4”) pieces)","1/3 cup beef mince (ground beef) (, formed into 1cm (1/2”) balls)","1/3 cup ham (, cut into 2 x 0.5cm (1 x 1/4\") batons)"],"purpose":"BBQ Meatlovers"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","12 medium raw prawns/shrimp (, shelled and deveined)","25g / 1 1/2 tbsp butter (, unsalted)","1/4 tsp salt","1 tbsp garlic (, chopped)","1/2 cup capsicum (, sliced 0.5cm (1/4”) thick)","1/2 cup onion (, sliced 0.5cm (1/4”) thick)","2 tsp long red chillis (, sliced finely)","1 cup baby rocket (, loosely packed)"],"purpose":"Garlic Butter Prawns & Chilli"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","3/4 cup pork sausage (, skin removed, torn into 12 or so little balls (raw))","1 1/2 cups kale (, stems removed, torn into pieces (raw))","2 tsp olive oil"],"purpose":"Sausage & Kale"},{"ingredients":["125g / 4.4oz fresh buffalo mozzarella (, very well drained)","2 tbsp extra virgin olive oil","12 basil leaves"],"purpose":"Margherita"},{"ingredients":["Capricciosa recipe (separate recipe with video tutorial)"],"purpose":"Capricciosa"},{"ingredients":["1 heaped cup mozzarella cheese (, freshly grated)","1/2 cup sliced provolone cheese (, torn into pieces)","1/3 cup blue cheese (, broken into 1.5cm (1/2”) pieces)","3 tbsp parmesan cheese (, grated)"],"purpose":"Quattro Formaggio (Four Cheese Pizza)"},{"ingredients":["1 1/3 cup mozzarella cheese (, freshly grated)","1 tbsp olive oil (, plus extra for drizzling)","8 - 10 slices prosciutto","1 cup baby rocket (, loosely packed)"],"purpose":"Prosciutto & Rocket"},{"ingredients":["Cheese and garlic pizza (separate recipe)"],"purpose":"Cheese garlic pizza"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","1 1/4 cups potato (waxy variety) (, 2mm (1/12\") slices)","1 tbsp fresh rosemary leaves (picked, loosely packed)","1/4 tsp salt","1 1/2 tbsp extra virgin olive oil"],"purpose":"Potato & Rosemary"}]', '[{"description":"Preheat oven to 275°C/530°F, or as high as it will go. Place oven shelf in top third of oven.","images":[],"step":1},{"description":"Stretch dough to form pizza base and slide onto baking pan.","images":[],"step":2},{"description":"Follow topping directions below, then place in oven.","images":[],"step":3},{"description":"Turn pizza at 4 minutes so it cooks evenly, and check at 8 minutes (even if recipe says 10 minutes). Take out early if cheese gets too brown.","images":[],"step":4},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":5},{"description":"Distribute pepperoni over pizza, and bake.","images":[],"step":6},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":7},{"description":"Scatter remaining ingredients over pizza, and bake.","images":[],"step":8},{"description":"Ham & Pineapple","images":[],"step":9},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":10},{"description":"Scatter remaining ingredients over pizza, and bake.","images":[],"step":11},{"description":"Spread barbecue sauce over base, followed by cheese.","images":[],"step":12},{"description":"Scatter remaining ingredients over pizza, and bake.","images":[],"step":13},{"description":"Garlic Butter Prawns & Chilli","images":[],"step":14},{"description":"Toss prawns/shrimp with salt.","images":[],"step":15},{"description":"Heat butter over medium heat in a skillet or heavy frying pan until frothing. Add garlic and cook for another 30 seconds.","images":[],"step":16},{"description":"Cook prawns for 1 minute on one side until just starting to brown. Flip prawns, cook 1 minute more and remove. Reserve garlic butter.","duration":1,"images":[],"step":17},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":18},{"description":"Scatter remaining ingredients except rocket over pizza, top with prawns. Bake until done.","images":[],"step":19},{"description":"Drizzle reserved garlic butter over prawns and scatter with rocket.","images":[],"step":20},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":21},{"description":"Scatter remaining ingredients over pizza, and bake. (Note 2)","images":[],"step":22},{"description":"Spread pizza sauce over base. Drizzle 1 tbsp of oil over base, and bake.","images":[],"step":23},{"description":"After 5 minutes, remove pizza from oven. Tear buffalo mozzarella into 10 pieces and distribute over pizza. Continue baking until pizza is done.","images":[],"step":24},{"description":"Drizzle with remaining olive oil, and scatter with basil leaves.","images":[],"step":25},{"description":"See recipe directions in the separate recipe here.","images":[],"step":26},{"description":"Quattro Formaggio (Four Cheese Pizza)","images":[],"step":27},{"description":"Spread mozzarella cheese over base. Scatter provolone, parmesan and finally blue cheese over pizza. Bake.","images":[],"step":28},{"description":"Prosciutto & Rocket","images":[],"step":29},{"description":"Spread pizza sauce over base, followed by cheese. Drizzle 1 tbsp oil over pizza and bake.","images":[],"step":30},{"description":"2 minutes before the pizza is done, remove from oven. Drape prosciutto casually around the pizza.","images":[],"step":31},{"description":"Continue baking until done. Scatter rocket over pizza and drizzle with a little more olive oil.","images":[],"step":32},{"description":"Cheese & Garlic","images":[],"step":33},{"description":"See recipe directions in the separate recipe here.","images":[],"step":34},{"description":"Potato & Rosemary","images":[],"step":35},{"description":"Spread mozzarella cheese over base.","images":[],"step":36},{"description":"Arrange potato slices over pizza, each slice overlapping no more than 1/3 so it will cook through properly.","images":[],"step":37},{"description":"Sprinkle over the rosemary and salt, and drizzle with the olive oil. Bake for the standard cooking time given. Check with a fork or skewer that the potato is tender. If not fully cooked, cook another 2 minutes.","images":[],"step":38}]', '["milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["good-to-know","leftover-ham-recipes","pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0bea77e2f7c6', 'en', 'US', 'Pizza Sauces', 'Pick the one that suits your needs to make homemade pizza! (No Yeast pizza dough here)Instant Pizza Sauce - An intense flavour with the signature tang of tomato paste which compliments rich / intense flavoured pizza toppings. Tastes like Leggos pizza sauce sold at the stores. I use this the most often - personal taste and sheer convenience.Fresh and Bright - A lighter, fresher pizza sauce thanks to the addition of passata. Ideal for more delicate toppings like margherita, vegetable pizzas and most classic Italian pizzas.New York Pizza Sauce - A richly flavoured New York-style pizza sauce. Based on this recipe from Serious Eats.', 'https://www.recipetineats.com/tachyon/2020/05/Spreading-pizza-sauce-on-homemade-pizza-crust.jpg', 5, 0, 5, 4, '[{"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.02, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 cup tomato paste (, unsalted (Note 1))","1 tsp salt (Note 1)","2 tsp white sugar","2 tsp olive oil","2 tsp garlic (, finely minced (optional))","2 tbsp water","1/2 tsp EACH dried parsley (, basil and oregano (optional))"],"purpose":"Instant Pizza Sauce:"},{"ingredients":["1 cup tomato passata (Note 2)","1 tbsp tomato paste","1/2 tsp salt","1 tsp sugar","1 tbsp olive oil"],"purpose":"Fresh and Bright Pizza Sauce:"},{"ingredients":["2 tbsp olive oil","1 onion ((small), finely chopped)","2 cloves garlic grated or finely chopped","800g / 28 oz canned crushed tomatoes","1 tsp dried oregano","3/4 tsp salt","1 tsp sugar"],"purpose":"New York Pizza Sauce:"}]', '[{"description":"Instant Pizza Sauce:","images":[],"step":1},{"description":"Combine ingredients and mix well.","images":[],"step":2},{"description":"Fresh and Bright Pizza Sauce:","images":[],"step":3},{"description":"Combine ingredients and mix well","images":[],"step":4},{"description":"New York Pizza Sauce:","images":[],"step":5},{"description":"Heat oil in a heavy-based, medium saucepan over medium heat. Add onion and garlic, and sautee until onions are soft but not coloured.","images":[],"step":6},{"description":"Add tomatoes, oregano, salt and sugar. Bring to a simmer. Reduce heat to low, and cook, stirring occasionally, until reduced by half (about 1 hour). You will need to stir more frequently towards the end to stop the sauce catching","images":[],"step":7},{"description":"Leave to cool before using.","images":[],"step":8},{"description":"Using pizza sauce:","images":[],"step":9},{"description":"Use 1/4 cup of pizza sauce for each pizza (30cm/12\" wide).","images":[],"step":10},{"description":"Place raw pizza crust on a pizza pan (preferably with holes). Spread sauce evenly using the back of a spoon, leaving a 1cm / 1/2\" border for the crust.","images":[],"step":11},{"description":"Cover with toppings of choice (less is more!). Standard pizza - sprinkle with 130g / 4.5 oz freshly shredded mozzarella cheese, then 1 cup toppings such as sliced pepperoni. (See this post for pizza topping recipes)","images":[],"step":12},{"description":"Bake in preheated 275°C / 530°F oven on top shelf for 10 minutes, rotating at 4 minutes, until cheese has golden specks and crust is crisp. (See this homemade pizza recipe for full cooking directions, or this NO YEAST Pizza Dough recipe)","duration":10,"images":[],"step":13}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["good-to-know","pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_618b3c79806f', 'en', 'US', 'Greek Kofta Kebabs', 'Recipe video above. This Greek Kofta kebab features a secret spice mix from a well known Melbourne souvlaki shop called Kalimera Souvlaki Art. The owner gave me his chicken gyros recipe for a story I did for Good Food. I used the same blend for lamb mince koftas - it''s spectacular! The secret ingredient is a hint of curry powder, which adds warmth and depth without a curry taste. Genius!Served with my version of his Secret Souvlaki Sauce, crafted from clues he gave me. It''s so good, I use it to dunk crackers, veggie sticks and hot chips.', 'https://www.recipetineats.com/tachyon/2024/08/Greek-lamb-kofta-kebabs_5.jpg', 15, 10, 25, 4, '[{"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.0, "unit": "pack of 3 heads"}}, {"id": "ing_paprika", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 5.0, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}, {"id": "ing_yogurt", "quantity": {"value": 0.006, "unit": "tub of 500g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}]', '[{"ingredients":["500g/ 1 lb lamb mince (or beef, or 50/50 beef/lamb, Note 1)","3 large garlic cloves (, crushed using garlic press or finely grated)","2 tsp paprika (regular/sweet, not smoked)","2 tsp mustard powder","4 1/2 tsp dried oregano","1 1/2 tsp curry powder (, not spicy, any brand fine (Kalimera secret ingredient! Note 2))","3/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Kofta kebab:"},{"ingredients":["1 tbsp olive oil","8 skewers (, optional (I use 18cm/7.5\"))"],"purpose":"For cooking:"},{"ingredients":["3/4 cup plain yogurt (, preferably Greek (full-fat best))","2 tbsp mayonnaise (, preferably whole-egg)","2 tbsp extra virgin olive oil","1 tbsp American yellow mustard (ie the bright yellow American stuff!)","1 1/2 tsp garlic powder","1 1/2 tsp paprika (sweet/regular, not smoked or spicy)","1/2 tsp cooking salt / kosher salt"],"purpose":"Secret Sauce (Note 3):"},{"ingredients":["4 Greek pita bread (, pockets or flatbreads, warmed (TIPS - Note 4!))","2 tomatoes (, halved and sliced)","1/2 red onion (, finely sliced or chopped)","Iceberg lettuce (, finely sliced (or other leafy greens))"],"purpose":"Serving:"}]', '[{"title":"Sauce","description":"Mix the ingredients in a bowl and set aside to let the flavours meld while you make the kofta kebabs.","images":[],"step":1},{"title":"Kofta kebabs","description":"Put all the ingredients in a bowl and mix well with your hands until the spices are mixed through. Divide into 8, shape into 13cm/5\" logs. Thread onto skewers then flatten slightly to about 1.25cm / 0.5\" thick (Note 5).","images":[],"step":2},{"title":"Cook","description":"Heat 1 tbsp oil in a large non stick pan over medium high heat. Cook half the koftas for 2 minutes on each side until golden, then about 30 seconds on each short edge (just for a bit of colour). Reduce the heat if they''re browning too fast. Transfer to a serving plate, loosely cover with foil to keep warm. Cook the remaining koftas. (Scrape out loose burnt bits, if any. You shouldn''t need extra oil.)","duration":2,"images":[],"step":3},{"description":"Serve and assemble! Pile the lettuce, tomato and onion on the plate and put the sauce in a bowl. To assemble, take a warm pita bread and smear some sauce down the middle. Top with lettuce and 1 or 2 koftas (removed from the skewers), tuck tomato down the side and sprinkle with onion. Fold and EAT!","images":[],"step":4}]', '["egg","gluten","milk","mustard"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["greek-recipes","lamb","lamb-recipes","mains","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f3c383198de', 'en', 'US', 'Porchetta - Dozer''s last recipe', 'Recipe video above. Most porchetta recipes promise epic crackling, but few deliver that properly blistered crispness all the way around. You might get bubbles on top, but the sides and underside are flat and hard skin, or worse, rubbery.This one works. It has incredible crispy crackling ALL over - top, sides and even underneath - with insanely juicy meat. See the video for proof! The keys are a 1 - 2 day fridge dry, slow roasting on low then a hot blast, salting just before roasting, and using a rack on a tray, not a roasting pan.This is the last recipe developed under Dozer''s watchful eye, so it will always hold a special place in my heart. It was a big one - but he was at my feet, cheering me on every step of the way. ❤️', 'https://www.recipetineats.com/tachyon/2026/02/Porchetta-overhead-take-2.jpg', 60, 270, 3210, 8, '[{"id": "ing_pork", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 6.0, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_pork", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2.5 kg / 5lb pork belly with skin on (, NOT SCORED (Note 1))"]},{"ingredients":["2 tbsp fennel seeds (Note 1)","2 tsp black peppercorns (Note 1)","2 1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","3 tbsp finely chopped rosemary leaves - about 1/4 cup leaves (Note 3 for dried)","2 tsp red chilli flakes (red pepper flakes)","6 large garlic cloves (, finely grated with a microplane or garlic crusher)"],"purpose":"Rub:"},{"ingredients":["2 1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","2 tbsp olive oil (, divided)"],"purpose":"For skin:"},{"ingredients":["3 tbsp pork belly fat (reserved from roasting)","1/4 cup plain flour / all-purpose flour","2 cups water","1/4 tsp freshly ground black pepper","Salt (, if needed (I usually don''t need))"],"purpose":"Gravy:"}]', '[{"title":"Score pork, rub, roll, tie, fridge dry on rack 24","description":"48 hours. Oil and salt skin, slow roast 110°C /215°F for 3 1/2 hours, transfer to new rack, drizzle with oil, crackle at 240°C//465°F for 30 - 40 minutes. Make gravy using tray drippings.","duration":35,"images":[],"step":1},{"title":"Marinate 1","description":"2 days","images":[],"step":2},{"title":"Toast spices","description":"Preheat a small pan over medium heat (no oil). Toast fennel seeds and black peppercorns, tossing regularly, for 1 1/2 to 2 minutes until the fennel seeds are lightly browned.","images":[],"step":3},{"title":"Porchetta rub","description":"Crush fennel and peppercorns into a coarse powder using a mortar and pestle, or spice grinder. Add remaining Rub ingredients and mix with a spoon - it will be like a thick wet paste.","images":[],"step":4},{"title":"Trim excess meat","description":"Pat the pork skin dry with paper towels. Cut off about ~3cm / 2.2\" meat along one long edge (leave the skin) so the pork rolls neatly. Do a mock roll-up to see how much to cut off - it''s ideal if the skin fully encloses the meat, but usually this isn''t possible. (Note 4 for tips). Reserve the trimmed meat - we be rolling it up insi","images":[],"step":5},{"description":"Score 3cm / 1.2\" diamonds into the flesh, taking care not to cut through the meat (~1 cm/0.4\" deep).","images":[],"step":6},{"title":"Rub","description":"Use your hands to spread the Rub into the flesh side, being sure to get into the cuts you made. Also rub the extra piece of pork you trimmed off.","images":[],"step":7},{"title":"Tie","description":"Place the trimmed piece of pork in the middle. Roll firmly then tie at 2.5cm/1\" intervals, starting at the centre then the ends, then working in towards. I do 8 equidistant ties on the skin (26cm / 10.5\" log, one end has meat oozing out so can’t be tied).","images":[],"step":8},{"title":"Fridge 1","description":"2 days - Place on a rack on a tray and refrigerate uncovered for 48 hours (24 hours is ok) to let the rub infuse the flesh and the skin dry so it crackles really well. 12 hours is my bare minimum!","images":[],"step":9},{"description":"Preheat oven to 130°C/265°F (120°C fan-forced) with the shelf in the middle. (Note 5)","images":[],"step":10},{"title":"Oil and salt skin","description":"Remove the rack from under the pork and wipe the tray clean. Working on the tray, rub the pork skin with 1 tablespoon of the oil, then sprinkle and rub the salt in. Salt will catch on the ties - try to spread it out evenly all over the skin, and roll the pork on the salt that falls on the tray. No need to bring pork to room temp before roasting, it can go in the oven cold.","images":[],"step":11},{"title":"Slow roast","description":"Put the pork on the rack again on a clean tray. Slow roast for 3 1/2 hours. The flesh should be pretty tender (use 2 forks to check ends) but not “fall apart” (not our goal). The skin should still be soft - this is what we want at this stage.","images":[],"step":12},{"title":"Oil and increase heat","description":"Remove the pork from the oven and turn it up to 240°C/465°F. Working quickly, transfer the pork still on the rack to a clean tray. (Keep the used tray for gravy drippings). Drizzle with the remaining 1 tablespoon of oil (don’t rub with fingers) then put it back in the oven - you want it in there as it is heating up.","images":[],"step":13},{"title":"Crackle skin","description":"Roast for 30 to 40 minutes, rotating at the 15 - 20 minute mark, until the skin is all puffy and crispy all over (top and sides).","duration":35,"images":[],"step":14},{"title":"Rest and carve","description":"Remove from the oven and leave it to rest for at least 30 minutes (up to 1 hour) before cutting the strings and slicing with a serrated knife. To keep it warm for longer, put it in a low 50°C/125°F oven after resting. Serve with gravy!","images":[],"step":15},{"title":"Reserve fat","description":"Pour all the fat off the slow-roasting tray from step 4 into a jug (don’t scrape, just pour).","images":[],"step":16},{"title":"Deglaze tray","description":"Pour 1/2 cup of water onto the tray set on a stove on medium. When the water starts simmering, use a rubber spatula to loosen all the bits stuck on the tray. (If you have an induction stove, use boiling water - that should be enough to delegate, or if needed, pop the tray in the oven).","images":[],"step":17},{"title":"Make gravy","description":"Measure out 3 tablespoons fat (from step 1) and put into a large saucepan. Heat on medium high, then add flour and stir for 1 minute. Whisk in water from deglazing tray, remains water and pepper. Simmer for 2 minutes or until it thickens. Taste, add salt if needed (I don’t). Serve with pork.","duration":1,"images":[],"step":18}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["iconic-dishes","italian-recipes","mains","pork","pork-recipes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
